\section{Upper bounds for MLP approximations with nonlinearities of seminorm-type}
In this section we consider nonlinearities which are of seminorm-type.
By this we mean functions $f\colon\R^d\to\R$ such that $|f|$
satisfies condition \eqref{p01}.
Under this condition we derive upper bounds for second moments of our
MLP approximations using repeated applications of the triangle-type inequality \eqref{p01}.
%
%Throughout this paper we repeatedly refer to the following setting
%which introduces our MLP approximations.
The following setting introduces MLP approximations.
\begin{setting}\label{s01}
Let $d\in\N$, 
$\Theta=\bigcup_{n\in\N}\Z^n$,
$f,g\in C(\R^d,\R)$,
let $\varrho \colon  [0,1]^2\to \R$ satisfy for all
$t\in[0,1)$, 
$s\in (t,1]$ that $\varrho (t,s)= \frac{1}{2\sqrt{1-t}\sqrt{s-t}}$,
let $(\Omega, \mathcal{F},\P,(\F_t)_{t\in[0,1]})$ be a filtered probability space satisfying the usual conditions,
let $\unif^\theta\colon \Omega\to (0,1] $, $\theta\in\Theta$, be i.i.d.\ random variables which satisfy for all $b\in [0,1] $ that 
$\P(\unif^0\leq b)=\int_{0}^{b}\varrho (0,s)\,ds$, 
for every $\theta\in \Theta$
let 
$\uniform^\theta=(\uniform^\theta_t)_{t\in[0,1]}\colon [0,1]\times\Omega\to [0,1] $ satisfy for all  $t\in [0,1]$ that
$\uniform^\theta_t=t+(1-t)\unif^\theta$,
%
let $W^\theta\colon [0,1]\times \Omega \to\R^d$, $\theta\in\Theta$, be independent standard 
$(\F_t)_{t\in[0,1]}$-Brownian motions with continuous sample paths,
assume that
$(W^\theta)_{\theta\in\Theta}$ and
$(\unif^\theta)_{\theta\in\Theta}$ are independent,
and
let
$ 
  {\bf U}_{ n,m}^{\theta }=
({U}_{ n,m}^{\theta},{V}_{ n,m}^{\theta})
  \colon[0,1)\times\R^d\times\Omega\to\R^{1}\times\R^d
$,
$n,m\in\Z$, $\theta\in\Theta$, satisfy
for all 
$
  n,m \in \N
$,
$ \theta \in \Theta $,
$ t\in [0,1)$,
$x \in \R^d$
that $
{\bf U}_{-1,m}^{\theta}(t,x)={\bf U}_{0,m}^{\theta}(t,x)=0$ and 
\begin{equation}  \begin{split}
  &{\bf U}_{n,m}^{\theta}(t,x) 
  =  (g(x),0)+
  \sum_{i=1}^{m^n}\tfrac{g\bigl(x+W^{(\theta,0,-i)}_1-W^{(\theta,0,-i)}_t\bigr)-g(x)}{m^n}
  \left(
  1 ,
  \tfrac{ 
  W^{(\theta, 0, -i)}_{1}- W^{(\theta, 0, -i)}_{t}
  }{ 1 - t }
  \right)
  \\
  &+\sum_{\ell =0}^{n-1}\sum_{i=1}^{m^{n-\ell }}
  \tfrac{
\left((f\circ 
  {V}_{\ell ,m}^{(\theta,\ell ,i)})-\1_{\N}(\ell ) (f\circ {V}_{\ell -1,m}^{(\theta,-\ell ,i)})\right)
\!
  \left(\mathcal{R}^{(\theta, \ell ,i)}_t,x+W_{\mathcal{R}^{(\theta, \ell ,i)}_t}^{(\theta,\ell ,i)}-W_t^{(\theta,\ell ,i)}\right)
  }
  {m^{n-\ell }\varrho(t,\mathcal{R}^{(\theta, \ell ,i)}_t)}
  \left(
  1 ,
  \tfrac{ 
  W_{\mathcal{R}^{(\theta, \ell ,i)}_t}^{(\theta,\ell ,i)}- W^{(\theta, \ell , i)}_{t}
  }{ \mathcal{R}^{(\theta, \ell ,i)}_t-t}
  \right).
\end{split}  \label{c10}   \end{equation}
\end{setting}
\begin{remark}[Densities of $\uniform^0_t$, $t\in[0,1)$]\label{d14}  Assume \cref{s01}. 
Then
the fact that
$\forall\,t \in [0,1]\colon \uniform_t^0=t+(1-t)\unif^0$,
the fact that
$\forall\, b\in [0,1] \colon \P(\unif^0\leq b)=\int_{0}^{b}\varrho (0,r)\,dr=\int_{0}^{b}
\frac{dr}{2\sqrt{r}}$, and
the substitution rule 
%$s=t+(1-t)r$, $r= \frac{s-t}{1-t}$
show for all $t\in [0,1)$, $h\in C([t,1],[0,\infty))$ that
\begin{align}\begin{split}
&
\E \!\left[h(\uniform_t^0)\right]
= \E \!\left[h (t+(1-t)\unif^0)\right]
=
\int_{0}^{1}
\frac{h (t+(1-t)r)}{2\sqrt{r}}\,dr=\int_{t}^{1} \frac{h(s)}{2\sqrt{\frac{s-t}{1-t}}}\frac{ds}{1-t}
= \int_{t}^{1}h(s)\varrho(t,s)\,ds. 
\end{split}\end{align}
\end{remark}
%the fact that $\forall\,t\in [0,1), h\in C([t,1],[0,\infty))\colon \E \!\left[h(\uniform_t^0)\right]=\int_{t}^{1}\varrho(t,s)\,ds.  $
\begin{lemma}\label{c02}
It holds for all $t_0\in [0,1)$, $k\in\N$ that
\begin{align}
\int_{t_0}^1\int_{t_1}^{1}\ldots\int_{t_{k-1}}^{1}
\prod_{j=1}^{k}
\frac{\sqrt{1-t_{j-1}}}{\sqrt{t_j-t_{j-1}}}
dt_{k}dt_{k-1}\cdots dt_{1}\leq 2^k.
\end{align}
\end{lemma}
\begin{proof}[Proof of \cref{c02}]
First, observe for all $t\in[0,1)$ that
\begin{align}
\int_{t}^{1}\frac{\sqrt{1-t}}{\sqrt{s-t}}\,ds= 2\sqrt{1-t}\sqrt{s-t}\bigr|_{s=t}^1=2(1-t)\leq 2 .\label{t23} 
\end{align}
This shows 
 for all $k\in\N$, $t_0\in [0,1)$  that
\begin{align}\begin{split}
&
\int_{t_0}^1\int_{t_1}^{1}\ldots\int_{t_{k-1}}^{1}\int_{t_k}^{1}
\prod_{j=1}^{k+1}
\frac{\sqrt{1-t_{j-1}}}{\sqrt{t_j-t_{j-1}}}\,
dt_{k+1}dt_{k}dt_{k-1}\cdots dt_{1}\\
&
= 
\int_{t_0}^1\int_{t_1}^{1}\ldots\int_{t_{k-1}}^{1}\left[\int_{t_k}^{1}
\frac{\sqrt{1-t_{k}}}{\sqrt{t_{k+1}-t_{k}}}\,
dt_{k+1}\right]
\prod_{j=1}^{k}
\frac{\sqrt{1-t_{j-1}}}{\sqrt{t_j-t_{j-1}}}\,
dt_{k}dt_{k-1}\cdots dt_{1}\\
&
\leq 
\int_{t_0}^1\int_{t_1}^{1}\ldots\int_{t_{k-1}}^{1}2
\prod_{j=1}^{k}
\frac{\sqrt{1-t_{j-1}}}{\sqrt{t_j-t_{j-1}}}\,
dt_{k}dt_{k-1}\cdots dt_{1}.
\end{split}\end{align}
This, \eqref{t23}, and induction complete the proof of \cref{c02}.
\end{proof}


Under the triangle-type inequality \eqref{p01} below we now derive
upper bounds for second moments.
\begin{proposition}\label{m01}
Assume \cref{s01},
let $\lVert\cdot\rVert\colon\R^d\to[0,\infty)$ be the standard norm, let
$\gamma,f,g\in C(\R^d,\R)$ 
satisfy
for all $\lambda\in\R $, 
$v_1,v_2\in \R^d$ that 
\begin{align}\label{c01}
\lvert g(v_1)-g(v_2)\rvert
\leq  \gamma (v_1-v_2) ,
\quad \gamma(v_1+v_2)\leq \gamma (v_1)+\gamma(v_2),\quad \gamma(\lambda v_1)\leq  \lvert \lambda \rvert\gamma (v_1),
\end{align}
\begin{align}
\lvert f(v_1+v_2)\rvert\leq \lvert  f(v_1)\rvert+\lvert f(v_2)\rvert, \quad\text{and}\quad  \lvert f(\lambda v_1)\rvert\leq \lvert\lambda f(v_1)\rvert.\label{p01}
\end{align}
Then \begin{enumerate}[i)]
\item \label{c17}it holds for all 
$n,m\in\N$, $\theta\in\Theta$ that
$\mathbf{U}_{n,m}^\theta$ is measurable,
\item\label{c13}  it holds for all
$n,m\in\N$,
$t\in[0,1)$, $\xi\in\R^d$  that
\begin{align}\begin{split}
&
\left(\E\!\left[
\left\lvert
\left(f
\circ 
V_{n,m}^0\right)(t,\xi)
\right\rvert^2\right]
\right)^{1/2}\leq \left(\E\!\left[\lvert \gamma( W^0_1) \rvert^4\right]\right)^{1/4}
 \max\left\{\left(\E\!\left[\lvert f( W^0_1)\rvert^4\right]\right)^{n/4},1\right\}6^{n-1}<\infty,
\end{split}\end{align}
and
\item \label{c14}it holds for all 
$n,m\in\N$ that
\begin{align}\begin{split}
&
\left(
\E\!\left[
\left\lvert{U}_{n,m}^{0}(0,0)\right \rvert^2\right]+
\E\!\left[
\left\lVert{V}_{n,m}^{0}(0,0)\right \rVert^2\right]\right)^{1/2}
\\
&
\leq \lvert g(0)\rvert+
\left(\E\!\left[\lvert \gamma( W^0_1) \rvert^4\right]\right)^{1/4}
 \max\left\{\left(\E\!\left[\lvert f( W^0_1)\rvert^4\right]\right)^{n/4},1\right\}6^n\sqrt{d}<\infty
.
\end{split}\end{align}
\end{enumerate}
\end{proposition}


\begin{proof}[Proof of \cref{m01}]
