\prod_{j=1}^{k}
\tfrac{f(W_{t_j}^0-W^0_{t_{j-1}})}{\sqrt{\varrho(t_{j-1},t_j)}(t_{j}-t_{j-1})}
\right\rvert^2\right]\right)^{1/2}\nonumber
\\
&\leq  \sum_{i=1}^{m^n}\left(\E\!\left[
\left\lvert
 \tfrac{ \gamma\left( W^{(0,0,-i)}_1-W^{(0,0,-i)}_{t_k}\right)}{m^n}
   \tfrac{ f\!\left(
  W^{(0, 0, -i)}_{1}- W^{(0, 0, -i)}_{t_k}\right)
  }{ 1 - {t_k} }
\prod_{j=1}^{k}
\tfrac{f(W_{t_j}^0-W^0_{t_{j-1}})}{\sqrt{\varrho(t_{j-1},t_j)}(t_{j}-t_{j-1})}
\right\rvert^2\right]\right)^{1/2}\nonumber
\\
&+\sum_{\ell=1}^{n-1}\sum_{i=1}^{m^{n-\ell }}\left(\E\!\left[
\left\lvert
   \tfrac{
\left[ f\circ
  {V}_{\ell ,m}^{(0,\ell ,i)}\right]\!
