\right\rvert^2\right]\right)^{1/2}\nonumber
\\
&+\sum_{\ell=1}^{n-1}\sum_{i=1}^{m^{n-\ell }}\left(\E\!\left[
\left\lvert
   \tfrac{
\left[f\circ {V}_{\ell -1,m}^{(0,-\ell ,i)}\right]\!
  \bigl(\mathcal{R}^{(0, \ell ,i)}_{t_k},\xi +W_{\mathcal{R}^{(0, \ell ,i)}_{t_k}}^{(0,\ell ,i)}-W_{t_k}^{(0,\ell ,i)}\bigr)
  }
  {m^{n-\ell }\varrho({t_k},\mathcal{R}^{(0, \ell ,i)}_{t_k})}
   \tfrac{ f\bigl(
  W_{\mathcal{R}^{(0, \ell ,i)}_{t_k}}^{(0,\ell ,i)}- W^{(0, \ell , i)}_{t_k}\bigr)
  }{ \mathcal{R}^{(0, \ell ,i)}_{t_k}-{t_k}}
\prod_{j=1}^{k}
