\section{Lower bounds for MLP approximations for our counterexample}
A difficulty in the derivation of lower bounds for MLP approximations
are the sums on the right-hand side of the MLP recursion \eqref{c10}.
Using symmetry we show that the summand on the right-hand side of \eqref{c10}
are centered in our case.
Thus second moments are equal to variances.
The following lemma then estimates the variance of the sum over independent random fields
evaluated at the same random and independent vector from below by the sum of the variances. 

\begin{lemma}\label{t01}Let $(\Omega, \mathcal{F},\P)$ be a  probability space,
let
$m,n\in\N$, 
let
$F_1,F_2,\ldots,F_n\colon \R^m\times \Omega\to\R $, be 
i.i.d.\ random fields, let 
$X\colon\Omega\to \R^m $ be a
random variable, 
assume that $\{F_1,F_2,\ldots,F_n\} $ and $X$ are independent,
and
assume 
that
$\E[\lvert F_1(X)\rvert^2]<\infty$.
Then 
$
\var \bigl[\sum_{i=1}^{n} F_i(X)\bigr] \geq n
\var \!\left( F_1(X)\right).$
\end{lemma}
\begin{proof}[Proof of \cref{t01}]
Throughout the proof let $A\subseteq \R^m$ satisfy that
$A=\{x\in\R^m\colon \E [\lvert F_1(x)\rvert^2]<\infty\}$.
Then the disintegration theorem (see, e.g., \cite[Lemma 2.2]{hutzenthaler2020overcoming}) 
and the fact that
$\E[\lvert F_1(X)\rvert^2]<\infty$
 show that
$
\infty\cdot \P(X\notin A)\leq \E \Bigl[\E [\lvert F_1(x)\rvert^2]\bigr|_{x=X}\1_{X\notin A}\Bigr]\leq \E \Bigl[\E [\lvert F_1(x)\rvert^2]\bigr|_{x=X}\Bigr]= \E \bigl[\lvert F_1(X)\rvert^2\bigr]<\infty.
$
Hence, $\P(X\notin A)=0$ and $\P(X\in A)=1$.
This, the disintegration theorem (see, e.g., \cite[Lemma 2.2]{hutzenthaler2020overcoming}),  the assumptions, and Jensen's inequality show that for all
$i,j\in \{1,2,\ldots,n\}$ with $i\neq j$ it holds that
\begin{align}\begin{split}
&
\var [F_i(X)]
=\E \!\left[\1_{X\in A}\lvert F_i(X)\rvert^2\right]
-\left\lvert\E [\1_{X\in A} F_i(X)]\right\rvert^2\\
&
=\E \!\left[\1_{X\in A}
\E\!\left[\lvert  F_i(x)\rvert^2 \right]\Bigr|_{x=X}\right]
-\left\lvert \E \!\left[ \1_{X\in A}\E\! \left[  F_i(x)\right]\Bigr|_{x=X}\right] \right\rvert^2
= \var[F_1(X)] \\
\end{split}\end{align}
and
\begin{align}\begin{split}
&
\E\!\left[F_i(X)F_j(X) \right]= \E\!\left[\1_{X\in A}\E\!\left[
 F_i(x)F_j(x)\right]\Bigr|_{x=X}\right]
=
\E\!\left[\1_{X\in A}
\E\!\left[
F_i(x)\right]\E\!\left[
F_j(x)\right]\Bigr|_{x=X}\right]\\
&
=
\E\!\left[\1_{X\in A} \Bigl\lvert\E\!\left[F_1(x)\right]\Bigr \rvert^2\Bigr|_{x=X}\right]\geq 
\left\lvert\E\!\left[\1_{X\in A} \E\!\left[F_1(x)\right]\Bigr|_{x=X}\right]\right\rvert^2\\
&
=
\E\!\left[ \1_{X\in A}\E\!\left[F_i(x)\right]\Bigr|_{x=X}\right]
\E\!\left[\1_{X\in A} \E\!\left[F_j(x)\right]\Bigr|_{x=X}\right]= \E\!\left[ F_i(X)\right]
\E\!\left[ F_j(X)\right].
\end{split}\end{align}
Therefore, it holds that
\begin{align}\small\begin{split}
\var \!\left(\sum_{i=1}^{n} F_i(X)\right) &= 
\sum_{i=1}^{n}
\var \!\left( F_i(X)\right) + \sum_{\substack{i,j=1\\i\neq j}}^{n}
\Bigl(
\E\!\left[F_i(X)F_j(X)\right]-\E\!\left[F_i(X)\right]\E\!\left[F_j(X)\right]
\Bigr)\geq n
\var \!\left( F_1(X)\right).
\end{split}\end{align}The proof of \cref{t01} is thus completed.
\end{proof}
