&=\sum_{\nu=2}^{d}
\var\!\left[
\sum_{i=1}^{m} \tfrac{\left[g\bigl(W_{t_k}^0+W^{(0,0,-i)}_1-W^{(0,0,-i)}_{t_k}\bigr)-g(W_{t_k}^0)\right]}{m}  
   \tfrac{ W^{(0, 0, -i)}_{\nu,1}- W^{(0, 0, -i)}_{\nu,t_k}  }{ 1 - t_k }
\prod_{j=1}^{k}
\tfrac{f(W_{t_j}^0-W^0_{t_{j-1}})}{\sqrt{\varrho(t_{j-1},t_j)}(t_{j}-t_{j-1})}
\right]\nonumber\\
&\geq 
\frac{m}{m^2}\sum_{\nu=2}^{d}
\var\!\left[
\left[g\bigl(W_{t_k}^0+W^{(0,0,-1)}_1-W^{(0,0,-1)}_{t_k}\bigr)-g(W_{t_k}^0)\right]
   \tfrac{ W^{(0, 0, -1)}_{\nu,1}- W^{(0, 0, -1)}_{\nu,t_k}  }{ 1 - t_k }
\prod_{j=1}^{k}
\tfrac{f(W_{t_j}^0-W^0_{t_{j-1}})}{\sqrt{\varrho(t_{j-1},t_j)}(t_{j}-t_{j-1})}
\right]\nonumber
\\
&= \frac{1}{m}\sum_{\nu=2}^{d}
\E\!\left[
\left\lvert \left[g\bigl(W_{t_k}^0+W^{(0,0,-1)}_1-W^{(0,0,-1)}_{t_k}\bigr)-g(W_{t_k}^0)\right]
   \tfrac{ 
  W^{(0, 0, -1)}_{\nu,1}- W^{(0, 0, -1)}_{\nu,t_k}
  }{ 1 - t_k }\right\rvert^2
\prod_{j=1}^{k}\left\lvert
\tfrac{f(W_{t_j}^0-W^0_{t_{j-1}})}{\sqrt{\varrho(t_{j-1},t_j)}(t_{j}-t_{j-1})}
\right\rvert^2\right]\nonumber\\
&= \frac{1}{m}
\E\!\left[
\left\lvert \left[g\bigl(W_{t_k}^0+W^{(0,0,-1)}_1-W^{(0,0,-1)}_{t_k}\bigr)-g(W_{t_k}^0)\right]
   \tfrac{ f\bigl(
  W^{(0, 0, -1)}_{1}- W^{(0, 0, -1)}_{t_k}\bigr)
  }{ 1 - t_k }\right\rvert^2
\prod_{j=1}^{k}\left\lvert
\tfrac{f(W_{t_j}^0-W^0_{t_{j-1}})}{\sqrt{\varrho(t_{j-1},t_j)}(t_{j}-t_{j-1})}
\right\rvert^2\right]\nonumber\\
&\geq\frac{1}{m}(d-1)^{1+k} 2^{k-1}.
\end{align}
This, \eqref{c06d}, \eqref{c06c}, and the fact that
$\forall\,t_0\in\{0\},\delta\in [0,1],k\in\N\colon \int_{t_0}^\delta\int_{t_1}^{\delta}\ldots\int_{t_{k-1}}^{\delta}
dt_{k}dt_{k-1}\cdots dt_{1}=\frac{\delta^k}{k!}$ show for all
$t_0\in \{0\}$, $k,m\in\N$, $ \delta\in (0,\frac{1}{17}]$ 
that
$\epsDown_{0,m}(1)\geq [\frac{1}{m}(d-1)\frac{1}{2}]^{1/2}$
and
\begin{align}\label{t13}
&
\epsDown_{k,m}(1)\geq 
\left(\int_{t_0}^\delta\int_{t_1}^{\delta}\ldots\int_{t_{k-1}}^{\delta}
\E\!\left[
\left\lvert
\left(f
\circ 
V_{1,m}^0\right)(t_k, W^0_{t_k})
\prod_{j=1}^{k}
\tfrac{f(W_{t_j}^0-W^0_{t_{j-1}})}{\sqrt{\varrho(t_{j-1},t_j)}(t_{j}-t_{j-1})}
\right\rvert^2\right]
dt_{k}dt_{k-1}\cdots dt_{1}
\right)^{1/2}\nonumber\\
&\geq\left[ \frac{(d-1)^{1+k} 2^{k-1}}{m}\frac{\delta^k}{k!}\right]^{1/2}
=\frac{1}{2\sqrt{m}}(2(d-1))^{\frac{1+k}{2}}\frac{\delta^{k/2}}{\sqrt{k!}}
\geq 
\frac{1}{2\sqrt{m}}d^{\frac{1+k}{2}}\frac{\delta^{k/2}}{\sqrt{k!}}
\1_{[2,\infty)}(d)
.
\end{align}
This, \eqref{c06d}, and \eqref{t31b} show for all
$m,n\in\N$,
$ \delta\in (0,\frac{1}{17}]$ that
\begin{align}\begin{split}
&\left(
\E\!\left[
\left\lvert
\left(f
\circ 
V_{n,m}^0\right)(0, 0)
\right\rvert^2
\right]
\right)^{1/2}=\epsDown_{0,m}(n)
\geq 
\left(\tfrac{1}{\sqrt{2m}}\right)^{n-1}\epsDown_{n-1,m}(1)-d^{\frac{n-1}{2}}6^n
\\
&\geq \tfrac{1}{\sqrt{2}}
\left(\tfrac{1}{\sqrt{2m}}\right)^{n}d^{\frac{n}{2}}
\tfrac{\delta^{\frac{n-1}{2}}}{\sqrt{(n-1)!}}
1_{[2,\infty)}(d)
-d^{\frac{n-1}{2}}6^n.
\end{split}\label{t26}\end{align}
Furthermore, observe that for all 
$n,m\in\N$ with
$d\geq 8(2m)^n 17^{n-1} (n-1)!\cdot 36^n$ it holds that
\begin{align}
d^{1/2}\geq 2\sqrt{2}(\sqrt{2m})^n 17^{\frac{n-1}{2}}\sqrt{(n-1)!}\cdot  6^n
\end{align} and
hence
\begin{align}
\tfrac{1}{2\sqrt{2}}
\left(\tfrac{1}{\sqrt{2m}}\right)^{n}d^{\frac{n}{2}}
\tfrac{\left(\frac{1}{17}\right)^{\frac{n-1}{2}}}{\sqrt{(n-1)!}}
\geq d^{\frac{n-1}{2}}6^n
.
\end{align}
This and \eqref{t26} show that  for all 
$n,m\in\N$ with
$d\geq (1224m)^n n!$ it holds that
\begin{align}
&\left(
\E\!\left[
\left\lvert
\left(f
\circ 
V_{n,m}^0\right)(0, 0)
\right\rvert^2
\right]
\right)^{1/2}\geq
\tfrac{1}{\sqrt{8}}
\left(\tfrac{1}{\sqrt{2m}}\right)^{n}d^{\frac{n}{2}}
\tfrac{\left(\frac{1}{17}\right)^{\frac{n-1}{2}}}{\sqrt{(n-1)!}}
\geq
\tfrac{
\left(
\frac{1}{2m}\right)^{\frac{n}{2}}
d^{\frac{n}{2}}
\left(\frac{1}{17}\right)^{\frac{n}{2}}}{\sqrt{n!}}=
\tfrac{d^{n/2}}{(34m)^{n/2}  \sqrt{n!}}
.
\end{align}%%%%%%
This completes the proof of \cref{d01}.
\end{proof}

Finally, since our nonlinearity is bounded by the squared Euclidean norm,
\cref{d01} immediately implies a lower bound for the approixmation errors of
MLP approximations.
\begin{corollary}\label{c12}
Assume \cref{s01}, 
let $\lVert\cdot \rVert\colon\R^d\to[0,\infty)$ be the standard norm,
let
$u \colon  [0,1] \times \R^d \to\R $, and
assume
for all $t\in[0,1]$, $x=(x_1,x_2,\ldots,x_d)\in\R^d$ that
\begin{align}
g(x)=\lvert x_1\rvert, \quad f(x)=\bigl({\textstyle\sum_{j=2}^{d}}\lvert x_j\rvert^2\bigr)^{1/2},\quad\text{and}\quad 
u(t,x)= \frac{1}{(2\pi )^{d/2}}
\int_{\R^d}g\bigl(x+z\sqrt{1-t}\bigr)e^{- \frac{\lVert z \rVert^2}{2}}\,dz.\label{k05}
\end{align}
Then 
\begin{enumerate}[i)]
\item\label{c12a} it holds for all $t\in[0,1)$, $x=(x_1,x_2,\ldots, x_d)\in\R^d$ that
$u|_{[0,1)\times \R^d}\in C^{1,2}([0,1)\times \R^d,\R)$,
$
\bigl( \tfrac{ \partial }{ \partial t } u \bigr)( t, x ) + \tfrac{ 1 }{ 2 } ( \Delta_x u )( t, x ) + (f\circ \nabla_x u)  (t, x)  = 0$, and
$
u(1,x)=g(x)
$, and
\item it holds 
for all 
$n,m\in\N$
 with
$d\geq (1224m)^n n!$ it holds that
\begin{align}\begin{split}
&
\tfrac{d^{n/2}}{(34m)^{n/2}  \sqrt{n!}}-1\\
&
\leq 
\left(
\E\!\left[
\left\lvert{U}_{n,m}^{0}(0,0)-u(0,0)\right \rvert^2\right]+
\E\!\left[
\left\lVert{V}_{n,m}^{0}(0,0)-(\nabla_x u)(0,0)\right \rVert^2\right]\right)^{1/2}\leq d^{\frac{n+1}{2}}6^{n+1}.
\end{split}\end{align}\end{enumerate}
\end{corollary}
\begin{proof}[Proof of \cref{c12}]Throughout the proof 
for every $i\in [1,d]\cap\N$ let $ W_{i,1}^0$ be the $i$-th coordinate of $W^0_1$.
First, \eqref{k05} and a standard result on (time reverse) linear heat equations show for all $t\in[0,1)$, $x\in\R^d$ that
\begin{align}\label{k14}
u|_{[0,1)\times \R^d}\in C^{1,2}([0,1)\times \R^d,\R),\quad
\bigl( \tfrac{ \partial }{ \partial t } u \bigr)( t, x ) + \tfrac{ 1 }{ 2 } ( \Delta_x u )( t, x ) =0,\quad\text{and}\quad u(1,x)=g(x).
\end{align} 
Furthermore, \eqref{k05}  
 implies
 for all 
 $t\in[0,1]$, $x=(x_1,x_2,\ldots,x_d),
y=(y_1,y_2,\ldots,y_d)
\in\R^d$ that 
$\lvert u(t,x)-u(t,y)\rvert\leq 
\frac{1}{(2\pi )^{d/2}}
\int_{\R^d}\lvert g(x+z\sqrt{t})- g(y+z\sqrt{t})\rvert e^{- \frac{\lVert z \rVert^2}{2}}\,dz\leq 
\lvert x_1-y_1\rvert$.
This shows for all $t\in[0,1]$, $x\in\R^d$, $i\in [2,d]\cap\N$
that $ \lvert (\tfrac{\partial}{\partial x_1}u)(t,x)\rvert\leq 1$ and 
$  (\tfrac{\partial}{\partial x_i}u)(t,x)=0$.
 This and \eqref{k14}
establish
\eqref{c12a}.

Next, \eqref{c12a},
 the triangle inequality, 
\cref{d01},
and \eqref{k05}
imply for all $m,n\in\N$ with $d\geq (1224m)^n n!$ that
\begin{align}\label{k04}\begin{split}
&\left(
\E\!\left[
\lVert
V_{n,m}^0(0, 0)
-(\nabla_x u)(0,0)
\rVert^2
\right]
\right)^{1/2}\geq \left(
\E\!\left[
\lVert
V_{n,m}^0(0, 0)
\rVert^2
\right]
\right)^{1/2}-1
\geq 
\tfrac{d^{n/2}}{(34m)^{n/2}  \sqrt{n!}}-1
.
\end{split}\end{align}
Next, 
\eqref{k05} shows that
$\lvert f(W_1^0)\rvert^2= \sum_{j=2}^{d}\lvert W_{j,1}^0\rvert^2$ is chi-square distributed with $(d-1)$ degrees of freedom. Hence, 
$\E [\lvert f(W_1^0) \rvert^4]= (d-1)(d+1)\leq d^2 $. This, \cref{m01} (applied with
 $\gamma \gets (\R^d\ni (x_1,\ldots,x_d)\mapsto \lvert x_1\rvert\in\R)$  in the notation of \cref{m01}), and the fact that
$\E[\lvert W_{1,1}^0\rvert^4 ]=3 $ show that
\begin{align}\begin{split}
&
\left(
\E\!\left[
\left\lvert{U}_{n,m}^{0}(0,0)\right \rvert^2\right]+
\E\!\left[
\left\lVert{V}_{n,m}^{0}(0,0)\right \rVert^2\right]\right)^{1/2}
\leq 
\left(\E\!\left[\lvert  W^0_{1,1} \rvert^4\right]\right)^{1/4}
 \max\left\{\left(\E\!\left[\lvert f( W^0_1)\rvert^4\right]\right)^{n/4},1\right\}6^n\sqrt{d}\\
&=3^{1/4}d^{n/2}6^n \sqrt{d}= 3^{1/4}d^{\frac{n+1}{2}}6^n
.
\end{split}\end{align}
This, the triangle inequality, the fact that
$ \forall\, t\in[0,1], x\in\R^d\colon  \lvert (\tfrac{\partial}{\partial x_1}u)(t,x)\rvert\leq 1$,  the fact that
$\forall\,i\in[2,d]\cap\N \colon  (\tfrac{\partial}{\partial x_i}u)(t,x)=0$,
 and \eqref{k05}
show for all
$m,n\in\N$ that
\begin{align}\begin{split}
&
\left(
\E\!\left[
\left\lvert{U}_{n,m}^{0}(0,0)-u(0,0)\right \rvert^2\right]+
\E\!\left[
\left\lVert{V}_{n,m}^{0}(0,0)-(\nabla_x u)(0,0)\right \rVert^2\right]\right)^{1/2}\\
&\leq \left(
\E\!\left[
\left\lvert{U}_{n,m}^{0}(0,0)\right \rvert^2\right]+
\E\!\left[
\left\lVert{V}_{n,m}^{0}(0,0)\right \rVert^2\right]\right)^{1/2}
+\left(
\lvert u(0,0)\rvert^2
+
\lVert(\nabla_x u)(0,0)\rVert^2\right)^{1/2}\\
&\leq  3^{1/4}d^{\frac{n+1}{2}}6^n+\sqrt{1+1}\leq d^{\frac{n+1}{2}}6^{n+1} .
\end{split}\end{align}
This and \eqref{k04} complete the proof of \cref{c12}.
\end{proof}


