\subsection{Discretization}

The state derivative can be approximated using the Euler method as 

\begin{equation}
\begin{aligned}
    \dot{\alpha}_{t} &\approx \frac{\alpha_{t+1}-\alpha_{t}}{T}\\
    \dot{q}_{t} &\approx \frac{q_{t+1}-q_{t}}{T}
\end{aligned}    
\end{equation}\\
where $t$ is the index of discrete time steps, $T$ is the time step size.

Therefore, Equations \ref{aerialvehiclemodel} are approximately written as

\begin{equation}\label{discrete_aerial_vehicle_model}
\begin{aligned}
   \frac{\alpha_{t+1}-\alpha_{t}}{T} &= f_{1}(\alpha_{t})+d(\alpha_{t},\delta_{t})+q_{t}\\
   \frac{q_{t+1}-q_{t}}{T} &= f_{2}(\alpha_{t})+g\delta_{t} 
\end{aligned}
\end{equation}\\
where
\begin{equation}
\begin{aligned}
    &f_{1}(x_{1})=(\frac{fgQS}{WV})\cos(x_{1})\phi_{z}(x_{1})\\
    &d(x_{1},u) = (\frac{fgQS}{WV})\cos(x_{1})b_{z}u\\
    &f_{2}(x_{1})=(\frac{fgQS}{WV})\phi_{m}(x_{1})\\
    &g = (\frac{fgQS}{WV})b_{m}
\end{aligned}
\end{equation}

Rewrite Equation \ref{discrete_aerial_vehicle_model} as:
\begin{equation}\label{discrete_aerial_vehicle_model}
\begin{aligned}
   \alpha_{t+1} &= h_{1}(\alpha_{t},q_{t},\delta_{t})\\
   q_{t+1} &= h_{2}(q_{t},\alpha_{t},\delta_{t}) 
\end{aligned}
\end{equation}\\
where
\begin{equation} 
\begin{aligned}
   h_{1}(\alpha_{t},\delta_{t},q_{t})&= \alpha_{t} + T\big(f_{1}(\alpha_{t})+d(\alpha_{t},\delta_{t})+q_{t}\big)\\
   h_{2}(\alpha_{t},\delta_{t},q_{t}) &= q_{t} + T(f_{2}\big(\alpha_{t})+g\delta_{t}\big) 
\end{aligned}
\end{equation}

\section{Optimization-based control design}\label{section_optimization_based_control}

Define the tracking errors as $e_{\alpha(t)} = \alpha_{t}-\alpha_{\text{ref}(t)}, e_{q} = q_{t}-q_{\text{ref}(t)}$. The $e_{\alpha(t+1)}$ is computed as
\begin{equation}\label{e_1_dynamics}
\begin{aligned}
    e_{\alpha(t+1)}=&\alpha_{t+1}-\alpha_{\text{ref}(t+1)}\\  =&\alpha_{t}+T\big(f_{1}(\alpha_{t})+d(\alpha_{t},\delta_{t})+q_{t}\big)-\alpha_{\text{ref}(t+1)}\\  =&\alpha_{t}+T\big(f_{1}(\alpha_{t})+d(\alpha_{t},\delta_{t})+q_{t}-q_{\text{ref}(t)}+q_{\text{ref}(t)}\big)\\
    &-\alpha_{\text{ref}(t+1)}\\  =&\alpha_{t}+T\big(f_{1}(\alpha_{t})+d(\alpha_{t},\delta_{t})+e_{q(t)}+q_{\text{ref}(t)}\big)\\
    &-\alpha_{\text{ref}(t+1)}\\
\end{aligned}
\end{equation}

Define a virtual control $q_{\text{ref}(t)}=v(e_{\alpha(t)},\alpha_{t})$, which is associated with $e_{\alpha},\alpha$ to provide error-feedback control for stabilizing $e_{\alpha(t)}$ and compensate for the system dynamics associated with $\alpha_{t}$. However, when the system dynamics  are unknown, an analytical design of the virtual control law $v(e_{\alpha(t)},\alpha_{t})$ is infeasible. In such cases, $v(e_{\alpha(t)},\alpha_{t})$ can be parameterized by a neural network as $v(e_{\alpha(t)},\alpha_{t}) = W^{\vartheta_{1}}(e_{\alpha(t)},\alpha_{t})$ and optimized with samples. $\vartheta_{1}$ denotes the parameter set of neural network.   

The value function is defined as a quadratic function of the tracking error and the virtual control:

\begin{equation}
    V_{1}(t) = \sum^{\infty}_{i=t}(e_{\alpha(i+1)}^{2}+av^{2}(e_{\alpha(i)},\alpha_{i}))
\end{equation}\\
where $a>0$ is a weighting parameter that balances the trade-off between the quadratic state term and the quadratic control term.

Then the virtual control law is defined as

\begin{equation}\label{vitual_pitch_rate}
    v^{*}(e_{\alpha(t)},\alpha_{t},\delta_{t}) = \arg \min_{v_{t}} V_{1}(t) 
\end{equation}

The $e_{q(t+1)}$ is computed as
\begin{equation}\label{e_2_dynamics}
\begin{aligned}
    e_{q(t+1)} & = q_{t+1}- q_{\text{ref}(t+1)}\\
    & = q_{t} + T(f_{2}\big(\alpha_{t})+g\delta_{t}\big) - q_{\text{ref}(t+1)}\\
\end{aligned}    
\end{equation}

The control surface deflection $\delta_{t}=u(e_{q(t)},q_{(t)})$ is designed as a function of $e_{q(t)}$ and $q_{t}$ to provide error-feedback for stabilizing $e_{q(t)}$ and compensate for the system dynamics associated with $q_{t}$. However, since the system dynamics $f_{2}(\cdot), g$ and $q_{\text{ref}(t+1)}$ are unknown, the control law $u(e_{q(t)},q_{t})$ cannot be explicitly designed. Instead, $u(e_{q(t)},q_{t})$ is parameterized by a network as $u(e_{q(t)},q_{t})=W^{\vartheta_{2}}(e_{q(t)},q_{t})$, where $\vartheta_{2}$ denotes the parameter set. 

The value function is defined as:

\begin{equation}
    V_{2}(t) = \sum^{\infty}_{i=t}(e_{q(i+1)}^{2}+bu^{2}(e_{q(i)},q_{i},\alpha_{i}))
\end{equation}\\
where $b>0$ is a weighting parameter.

The control law is designed as

\begin{equation}
    u^{*}(e_{q(t)},q_{t},\alpha_{t}) = \arg \min_{u_{t}} V_{2}(t) 
\end{equation}


