%    L^{\text{batch}}_{t} = \sum^{n}_{i=1}\left| \pi(x^{\prime}_{i})-\pi(x_{i})\right| \quad (i=1,2,\cdots,n)
%\end{equation}\\
%where $\vert \cdot \vert$ is the absolute value function, $i$ is the index of a sample of one-step state transition $(x,x^{\prime})$, $n$ is the batchsize. This loss has shown effectiveness to learn a flat policy in various offline RL algorithms.



In online learning, the actor is expected to be trained with less computation cost. To this end, only one sample is used for computing temporal smoothness loss online: 

%and further

%, making it  does not require samples of biased states from a selected probability distribution. For ADP or IADP, a system model is able to predict one-step state transition and the predicted state $\hat{x}_{t+1}$ can be used as a temporal state sample. The temporal smoothness loss is written as 

\begin{equation} \label{onlineTS}
\begin{aligned}
    L^{\text{online}}_{\alpha(t)} &= \big|v(\hat{e}_{\alpha(t+1)},\hat{\alpha}_{t+1})-v(e_{\alpha(t)},\alpha_{t})\big|\\
    L^{\text{online}}_{q(t)} &= \big|\delta(\hat{e}_{q(t+1)},\hat{q}_{t+1})-\delta(e_{q(t)},q_{t})\big|
\end{aligned}
\end{equation}\\
where $\hat{x}_{t+1}$ is one-step prediction of state by a system model. In the case of IHDP, the incremental model is used to generate $\hat{x}_{t+1}$. Therefore, $L^{\text{online}}_{t}$ can be efficiently computed in online learning with only a single forward propagation of model and actor.

Then the online temporal smoothness losses can be integrated into policy optimization through Lagrangian method:

\begin{equation}\label{policy_optimization}
\begin{aligned}
    v^{*}(e_{\alpha(t)},\alpha_{t},\delta_{t}) =& \arg \min_{v_{t}}\Big(c_{1}(\hat{e}_{\alpha(t+1)},q_{t})\\
    &+ \gamma \hat{V}_{1\text{target}}(\hat{e}_{\alpha(t+1)},\hat{\alpha}_{t+1}) + \lambda_{1} L_{\alpha(t)}^{\text{online}}\Big)\\
    \delta^{*}(e_{q(t)},q_{t},\alpha_{t}) =& \arg \min_{\delta_{t}}\Big(c_{2}(\hat{e}_{q(t+1)},\delta_{t}) \\
    &+\gamma \hat{V}_{2\text{target}}(\hat{e}_{q(t+1)},\hat{q}_{t+1}) + \lambda_{2} L_{q(t)}^{\text{online}}\Big)\\
\end{aligned}
\end{equation}\\
where $\lambda_{1},\lambda_{2}$ are the weights of loss terms $L^{\text{online}}_{\alpha(t)},L^{\text{online}}_{q(t)}$.\\
\textit{Remark 1.} The temporal smoothness loss can be efficiently computed within a model-based online learning framework. The model can be used to predict one-step state transitions, which serve as the bias in a temporal smoothness loss.\\
\textit{Remark 2.} Compared to the batch temporal smoothness loss in Reference \cite{bib29}, the online temporal smoothness loss uses a single sample so that the computation cost is reduced..
%The actions are constrained to change for neighboring states.


\subsection{Low-pass filter}
A low-pass filter is used to smoothen the pitch rate reference $q_{\text{ref}}$, which is formulated as a second-order dynamics as \cite{bib30}

\begin{equation}\label{low_pass_filter}
\begin{aligned}
    \dot{d}_{1} &= d_{2}\\
    \dot{d}_{2}&= -2\zeta\omega^{2}_{n} d_{2}-\omega^{2}_{n}(d_{1}-q_{\text{ref}})
\end{aligned}
\end{equation}\\
where $d_{1},d_{2}$ are filtered signal and its differentiation, $\omega_{n}$ is the natural frequency, $\zeta$ is the damping factor.

%natural frequency and damping factor are adopted as $\omega_{n} = 20$ rad/s, $\zeta = 0.7$.


