\subsection{Derivation of incremental model}\label{appendix_A}

Taking the Taylor expansion of systems \ref{discrete_aerial_vehicle_model}:

\begin{equation}\label{taylor_expanded_model}
\begin{aligned}
    \alpha_{t+1} =& \alpha_{t} + F^{1}_{t-1}(\alpha_{t}-\alpha_{t-1}) + G^{1}_{t-1}(q_{t}-q_{t-1})\\
    &+O\left[(\alpha_{t}-\alpha_{t-1})^{2},(q_{t}-q_{t-1})^{2}\right]\\
    q_{t+1} =& q_{t} + F^{2}_{t-1}(q_{t}-q_{t-1}) + G^{2}_{t-1}(\delta_{t}-\delta_{t-1})\\
    &+O\left[(q_{t}-q_{t-1})^{2},(\delta_{t}-\delta_{t-1})^{2}\right]\\
\end{aligned}
\end{equation}\\
where

\begin{equation}
\begin{aligned}
    &F^{1}_{t-1} = \frac{\partial h_{1} [\alpha_{t},\delta_{t},q_{t}]}{\partial \alpha_{t}}|_{\alpha_{t-1},\delta_{t-1},q_{t-1}}\\
    &G^{1}_{t-1} = \frac{\partial h_{1} [\alpha_{t},\delta_{t},q_{t}]}{\partial q_{t}}|_{\alpha_{t-1},\delta_{t-1},q_{t-1}}\\
    &F^{2}_{t-1} = \frac{\partial h_{2} [\alpha_{t},\delta_{t},q_{t}]}{\partial q_{t}}|_{\alpha_{t-1},\delta_{t-1},q_{t-1}}\\
    &G^{2}_{t-1} = \frac{\partial h_{2} [\alpha_{t},\delta_{t},q_{t}]}{\partial q_{t}}|_{\alpha_{t-1},\delta_{t-1},q_{t-1}}\\
\end{aligned}    
\end{equation}\\
and $O(\cdot)$ represents higher-order terms that can be ignored if the time step $t$ is sufficiently small.


Define state increments and control increment as
\begin{equation}
\begin{aligned}
    \Delta \alpha_{t} &= \alpha_{t}-\alpha_{t-1}\\ \Delta q_{t} &= q_{t} -q_{t-1}\\
    \Delta \delta_{t}&=\delta_{t}-\delta_{t-1}
\end{aligned}    
\end{equation}

Therefore, the incremental model can be formulated as
\begin{equation}
\begin{aligned}
    &\Delta \alpha_{t+1} = F^{1}_{t-1}\Delta\alpha_{t}+G^{1}_{t-1}\Delta q_{t}\\
    &\Delta q_{t+1} = F^{2}_{t-1}\Delta q_{t}+G^{2}_{t-1}\Delta \delta_{t}
\end{aligned}
\end{equation}

\subsection{Higher-level agent's critic and actor update}\label{appendix_B}

\subsubsection{Critic}
The gradient of $L^{C_{1}}_{t}$ with respect to $\psi_{1}$ is
%The critic parameter set is updated by gradient descent method with a learning rate $\eta$:
\begin{equation}
\begin{aligned}
     \frac{\partial L^{C_{1}}_{t}}{\partial \psi_{1(t)}} &= \frac{\partial L^{C_{1}}_{t}}{\partial \delta_{1(t)}} \frac{\partial \delta_{1(t)}}{\partial \psi_{1(t)}}\\
     &=-\delta_{1(t)} \frac{\partial \hat{V}_{1}(\alpha_{t},e_{\alpha(t)})}{\partial \psi_{1(t)}}
\end{aligned}
\end{equation}

The parameter set $\psi_{1}$ is updated as

\begin{equation}
        \psi_{1(t+1)} = \psi_{1(t)} - \eta_{C_{1}}\frac{\partial L^{C_{1}}_{t}}{\partial \psi_{1(t)}}
\end{equation}\\
where $\eta_{C_{1}}$ is the learning rate.

\subsubsection{Target Critic}
The target critic network is used to stabilize learning by delaying the updates:

\begin{equation}\label{target_critic_1_update}
    \psi^{\prime}_{1(t+1)} = \tau \psi_{1(t+1)} + (1-\tau)\psi^{\prime}_{1(t)}
\end{equation}\\
where $\tau$ is delay factor $\tau$, $\psi^{\prime}_{1}$ is the parameter set of target critic.

\subsubsection{Actor}
The gradient of $L^{A_{1}}_{t}$ with respect to $\vartheta_{1}$ is


\begin{equation}\label{loss_actor_1_gradient}
\begin{aligned}
    \frac{\partial L^{A_{1}}_{t}}{\partial \vartheta_{1(t)}} 
     =& \frac{\partial \left[c_{1}(\hat{e}_{\alpha(t+1)},q_{t})+\gamma \hat{V}_{1}(\hat{\alpha}_{t+1},\hat{e}_{\alpha(t+1)})\right]}{\partial  \vartheta_{1(t)}}\\ 
    = &\left[\frac{\partial c_{1}(\hat{e}_{\alpha(t+1)},q_{t})}{\partial \hat{\alpha}_{t+1}} + \gamma\frac{\hat{V}_{1}(\hat{\alpha}_{t+1},\hat{e}_{\alpha(t+1)})}{\partial \hat{\alpha}_{t+1}}\right]\\
    &\;\; \frac{\partial \hat{\alpha}_{t+1}}{\partial q_{\text{ref}}(t)} \frac{\partial q_{\text{ref}}(t)}{\partial  \vartheta_{1(t)}}\\
    =& \left[\frac{\partial c_{1}(\hat{e}_{\alpha(t+1)},q_{t})}{\partial \hat{\alpha}_{t+1}} + \gamma\frac{\hat{V}_{1}(\hat{\alpha}_{t+1},\hat{e}_{\alpha(t+1)})}{\partial \hat{\alpha}_{t+1}}\right]\\
    &\;\; \hat{G}^{1}_{t-1} \frac{\partial q_{\text{ref}}(t)}{\partial  \vartheta_{1(t)}}
\end{aligned}
\end{equation}

The parameter set $\vartheta_{1}$ is updated as

\begin{equation}
    \vartheta_{1(t+1)} = \vartheta_{1(t)} -\eta_{A_{1}} \frac{\partial L^{A1}_{t}}{\partial \vartheta_{1(t)}} 
\end{equation}\\
where $\eta_{A_{1}}$ is the learning rate.

From an algorithmic perspective, the update of $\psi_{t}$ to $\psi_{t+1}$ can be performed multiple times until the critic loss $L_{\text{critic}}$ falls below a specified threshold. Subsequently, the update of $\vartheta_{t}$ to $\vartheta_{t+1}$ can also be repeated until the actor loss $L_{\text{actor}}$ begins to reverse direction, indicating that $\vartheta_{t}$ is near a local optimum. These steps constitute one iteration of approximate value iteration. The approximate value iteration can be executed for multiple times at time step $t$.

\subsection{Lower-level agent's critic and actor update}\label{appendix_C}

\subsubsection{Critic}

The gradient of $L^{C_{2}}_{t}$ with respect to $\psi_{2}$ is
\begin{equation}
\begin{aligned}
    \frac{\partial L^{C_{2}}_{t}}{\partial \psi_{2}(t)}=& \frac{\partial L^{C_{2}}_{t}}{\partial \delta_{2(t)}} \frac{\partial \delta_{2(t)}}{\partial \psi_{2}(t)}\\
    =&-\delta_{2(t)} \frac{\partial \hat{V}(q_{t},e_{q(t)})}{\partial \psi_{2}(t)}
\end{aligned}
\end{equation}

The parameter set $\psi_{2}$ is updated as
\begin{equation}
    \psi_{2}(t+1) = \psi_{2}(t) - \eta_{C_{2}}\frac{\partial L^{C_{2}}_{t}}{\partial \psi_{2}(t)}
\end{equation}\\
where $\eta_{C_{2}}$ is the learning rate.

\subsubsection{Target Critic}
Target critic is used to stabilize the learning by slowing down the network update.
\begin{equation}
    \psi^{\prime}_{2(t+1)} = \tau \psi_{2(t+1)} + (1-\tau)\psi^{\prime}_{2(t)}
\end{equation}\\
where $\tau$ is delay factor, $\psi^{\prime}_{2}$ is parameter set of target critic.

\subsubsection{Actor}

The gradient of $L^{A2}_{t}$ with respect to $\vartheta_{2}$ is

\begin{equation}
\begin{aligned}
    \frac{\partial L^{A2}_{t}}{\partial \vartheta_{2(t)}} 
    =& \frac{\partial \left[c_{2}(\hat{e}_{q(t+1)},\delta_{t})+\gamma \hat{V}_{2\text{target}}(\hat{q}_{t+1},\hat{e}_{q(t+1)})\right]}{\partial  \vartheta_{2(t)}}\\ 
    %& = \frac{\partial \left[c_{2}(q_{t},e_{q(t+1)}+\gamma \hat{V}_{2\text{target}}(\hat{q}_{t+1},\hat{e}_{q(t+1)})\right]}{\partial q_{t}}\frac{\partial q_{t}}{\partial  \vartheta_{2(t)}}\\
    =& \left[\frac{\partial c_{2}(\hat{e}_{q(t+1)},\delta_{t})}{\partial \hat{q}_{t+1}} + \gamma\frac{\hat{V}_{2\text{target}}(\hat{q}_{t+1},\hat{e}_{q(t+1)})}{\partial \hat{q}_{t+1}}\right]\\
    &\;\;\frac{\partial \hat{q}_{t+1}}{\partial \delta_{e(t)}} \frac{\partial \delta_{e(t)} }{\partial  \vartheta_{2(t)}}\\
    =& \left[\frac{\partial c_{2}(\hat{e}_{q(t+1)},\delta_{t})}{\partial \hat{q}_{t+1}} + \gamma\frac{\hat{V}_{2\text{target}}(\hat{q}_{t+1},\hat{e}_{q(t+1)})}{\partial \hat{q}_{t+1}}\right]
    \\
    &\;\;\;\hat{G}^{2}_{t-1} \frac{\partial \delta_{e(t)} }{\partial  \vartheta_{2(t)}}\\
\end{aligned}
\end{equation}

The parameter set $\vartheta_{2}$ is updated as

\begin{equation}
    \vartheta_{2(t+1)} = \vartheta_{2(t)} -\eta_{A_{2}} \frac{\partial L^{A2}_{t}}{\partial \vartheta_{2(t)}} 
\end{equation}\\
where $\eta_{A_{2}}$ is the learning rate.





