\appendix                          % chuyển sang phần appendices
\section*{VSG parameters calculation}
\begin{itemize}
  \item Active power control loop:  
    The closed-loop transfer function of the active power control loop is presented as follows:
    \begin{equation}
      G^P_{cl}(s) = \frac{K_{ip}A}{s^2 + D_p K_{ip} s + K_{ip} A},
    \end{equation}
    which is a second-order transfer function with natural frequency $\omega_n = \sqrt{K_{ip}A}$, damping factor $\xi = \frac{D_p K_{ip}}{2\sqrt{K_{ip}A}}$, and settling time $T_s = \frac{4}{\xi \omega_n}$. Based on the desired characteristics (1 s settling time and no overshoot), let $\xi = 1$ and thus $\omega_n = 4$. The updated equations for $D_p$ and $K_{ip}$ are then
    \begin{equation}
      D_p = \frac{A}{2}, 
      \quad
      K_{ip} = \frac{16}{A}.
    \end{equation}

  \item Reactive power control loop:  
    The closed-loop transfer function of the reactive power control loop is presented as follows:
    \begin{equation}
      G^Q_{cl}(s) = \frac{K_{iq} D}{s + D_q K_{iq} + D K_{iq}}.
    \end{equation}
    Using the final value theorem, the steady-state value is 
    \[
      y_\infty = G^Q_{cl}(0) = \frac{D}{D_q + D}.
    \]
    For a unit step reference, the steady-state error is
    \begin{equation}
      e_\infty = 1 - y_\infty = \frac{D_q}{D_q + D}.
    \end{equation}
    To make the steady-state error negligible, choose 
    \[
      D_q = \frac{D}{100}.
    \]
    The settling time is $T_s = 4\tau$, where $\tau = \frac{1}{K_{iq}(D + D_q)}$. Setting $T_s = 1$ s gives
    \begin{equation}
      K_{iq} = \frac{4}{D + D_q}.
    \end{equation}
\end{itemize}




