\textbf{Proof for Theorem} \ref{thm:convolution_theorem}
We begin by simplifying the right hand side. 
\begin{equation}
    \sum_{i=1}^{L} z_i^{l+1} = \sum_{i=1}^{L} (\gamma \cdot \frac{ (z_i^l * W + \frac{b}{L} - \frac{\mu}{L})}{\sqrt{\sigma^2 + \epsilon}} + \frac{\beta}{L})  
    \end{equation}
    \begin{equation}
        = \sum_{i=1}^{L} \gamma \cdot \frac{z_i^l * W}{\sqrt{\sigma^2 + \epsilon}} + \frac{1}{\sqrt{\sigma^2 + \epsilon}} \sum_{i=1}^{L}  \frac{b-\mu}{L} + \sum_{i=1}^L \frac{\beta}{L}
    \end{equation}
    \begin{equation}
        = S_1 + S_2 + S_3
    \end{equation}
    Here, 
    \begin{equation}
        S_1 = \frac{\gamma}{\sqrt{\sigma^2+\epsilon}} \cdot (\sum_{i=1}^L z_i^l) * W
    \end{equation} 
    \begin{equation}
        = \frac{\gamma}{\sqrt{\sigma^2+\epsilon}} \cdot z^l*W 
    \end{equation}
    \begin{equation}
        = \frac{\gamma}{\sqrt{\sigma^2+\epsilon}}
    \cdot (z^{l+1} - \beta) \cdot \frac{\sqrt{\sigma^2+\epsilon}}{\gamma} -b+\mu 
    \end{equation}
    \begin{equation}
        = z^{l+1} - \beta -b + \mu
    \end{equation}
    Also, 
    \begin{equation}
        S_2 = \sum_{i=1}^L\frac{b}{L} = b - \mu
    \end{equation}
    \begin{equation}
        S_3 = \sum_{i=1}^L \frac{\beta}{L} = \beta
    \end{equation} 
    Therefore
    \begin{equation}
        S_1 + S_2 + S_3 = z^{l+1} - \beta -b + \mu + b - \mu + \beta 
    \end{equation}
    \begin{equation}
         = z^{l+1}
    \end{equation}
\qed

\textbf{Proof for Theorem} \ref{thm:overall_thm}


Consider an input $z$ to models $\mathcal{M}$ and $\mathcal{N}$. We invoke Theorems \ref{thm:input_layer_correctness}, \ref{thm:maintheorem} and \ref{thm:convolution_theorem} to show that the invariant \ref{eqn:invariant} holds after the final input layer. In other words, after the final layer, $z^l = \sum_{i=1}^{L} z_i^l$, where $L$ is the quantization step of the final layer $l$. In an SNN, the output probabilities are derived by taking the mean over time-steps after the final layer. Therefore, the tensor used for classification in the PASC formulation is $z^* = \frac{1}{L} \cdot \sum_{i=1}^{L} z_i^l = \frac{1}{L} \cdot z^l$. Therefore, 
\begin{equation}
    f_{\mathcal{M}}^z (c) = \frac{z^*[c]}{\sum_c z^*[c]} 
\end{equation}
\begin{equation}
    = \frac{\frac{z^l[c]}{L}}{\frac{\sum_c z^l[c]}{L}} 
\end{equation}
\begin{equation}
    = \frac{z^l[c]}{\sum_c z^l[c]}
\end{equation} 
\begin{equation}
    = f_{\mathcal{N}}^z(c)
\end{equation} 
$\forall c \in \mathbf{C}$. Thus, $\mathcal{M}$ and $\mathcal{N}$ are mathematically equivalent. 
\qed

