PREFIX gptkbp: <https://gptkb.org/prop/>

SELECT ?o (COUNT(*) AS ?ofreq)
WHERE {
  ?s gptkbp:instanceOf ?o.
} 
GROUP BY ?o
ORDER BY DESC(?ofreq)
LIMIT 100
\end{lstlisting}
