\begin{dfn}[backbone rigid invariant $\bri(S)$ of a protein backbone $S$]
\label{dfn:bri}
In the notations of Definition~\ref{dfn:trin}, 
%for every residue of $S$, 
define the orthonormal basis vectors 
$\vb*{u}_i=\dfrac{\ve{A_i N_i}}{|\ve{A_i N_i}|}$, 
$\vb*{v}_i=\dfrac{\vb*{h}_i}{|\vb*{h}_i|}$ for $\vb*{h}_i=\ve{A_i C_i}-b_i\ve{A_i N_i}$, 
$b_i=\dfrac{\ve{A_i C_i}\cdot\ve{A_i N_i}}{|\ve{A_i N_i}|^2}$, and $\vb*{w}_i=\vb*{u}_i\times\vb*{v}_i$.
The \emph{backbone rigid invariant} $\bri(S)$ is the $m\times 9$ matrix whose $i$-th row for $i=2,\dots,m$ contains the coefficients $x,y,z$ of the vectors $\ve{C_{i-1}N_i}$, $\ve{N_i A_i}$, $\ve{A_i C_i}$ in the basis $\vb*{u}_{i-1},\vb*{v}_{i-1},\vb*{w}_{i-1}$.
So the nine columns of $\bri(S)$ contain the coordinates $x(N_i),y(N_i),z(N_i)$ of %the vector 
$\ve{C_{i-1}N_i}$, % with the head $N_i$, 
followed by the six coordinates $x(A_i),\dots,z(C_i)$. 
For $i=1$, the first row of $\bri(S)$ has only three non-zero coordinates $x(N_1)=x(A_1 N_1)$, $x(C_1)=x(A_1 C_1)$, $y(C_1)=y(A_1 C_1)$ from the first row of 
%the triangular invariant 
$\trin(S)$ in Definition~\ref{dfn:trin}. 
\end{dfn}

Fig.~\ref{fig:PDB707K_BRI_heatmaps_log} shows heatmaps of the PDB cleaned by Protocol~\ref{prot:cleanPDB}.
We mapped each of 110+ million residues across all 707+ thousand chains to a pair of coordinates $(x,y)$ from the invariants $\trin$ and $\bri$.
When many points $(x,y)$ were discretized to a single pixel, its color reflects the number of such points on a logarithmic scale in the color bars of all heatmaps.
\medskip

For a backbone of $m$ residues, the first row of the $m\times 9$ matrix $\bri(S)$ contains only three non-zero coordinates.
Hence the matrix $\bri(S)$ can be considered a vector of length $9(m-1)+3=9m-6$.
The simplest metric on backbone rigid invariants as vectors in $\R^{9m-6}$ is $L_\infty$ equal to the maximum absolute difference between all corresponding coordinates.
\medskip

A small value $\de$ of $L_\infty(\bri(S),\bri(Q))$ guarantees by Theorem~\ref{thm:inverse} that backbones $S,Q$ are closely matched by rigid motion.
Another metric such as Euclidean distance or its normalization by the chain length has no such guarantees and can be small even for a few outliers that can affect the rigid shape and hence functional properties of a protein. 
%\smallskip
Theorem~\ref{thm:motion} proves conditions~\ref{pro:map}(a,b,c,e,f) in Problem~\ref{pro:map} for the invariant $\bri(S)$.
%\smallskip

\begin{thm}[completeness, reconstruction, and subchains]
\label{thm:motion}
\textbf{(a)}
Under any rigid motion in $\R^3$, the matrix $\trin(S)$ in Definition~\ref{dfn:trin} is invariant, $\bri(S)$ in Definition~\ref{dfn:bri} is a complete invariant, so any backbones $S,Q\subset\R^3$ are matched by rigid motion if and only if $\bri(S)=\bri(Q)$.
\medskip

\noindent
\textbf{(b)}
%For any backbone $S$ of $m$ residues, 
The invariant $\bri(S)$, metric $L_\infty$ between invariants, and a reconstruction of $S\subset\R^3$ from $\bri(S)$ can be computed in time $O(m)$. 
\medskip

\noindent
\textbf{(c)}
Let $Q$ be a subchain of $j$ consecutive residues in a backbone $S\subset\R^3$.
If $Q$ includes the first residue of $S$, then $\bri(Q)$ consists of the first $j$ rows of $\bri(S)$.
If $Q$ starts from the $i$-th residue of $S$ for $i>1$, the rows $2,\dots,j$ of $\bri(Q)$ coincide with the rows $i+1,\dots,i+j-1$ of $\bri(S)$, and the 1st row of $\bri(Q)$ is computed from the $i$-th row of $\bri(S)$ in a constant time.
Hence $\bri(Q)$ is computed from $\bri(S)$ in time $O(j)$. 
\end{thm}
\begin{proof}[Proof of Theorem~\ref{thm:motion}]
\textbf{(a,b)}
The formulae of the basis vectors in Definition~\ref{dfn:bri}
guarantee that all vectors have unit length $|\vb*{u}_i|=|\vb*{v}_i|=|\vb*{w}_i|=1$ and are orthogonal to each other due to $\vb*{u}_i\cdot\vb*{v}_i=\vb*{v}_i\cdot\vb*{w}_i=\vb*{w}_i\cdot\vb*{u}_i=0$.
Any rigid motion $f$ acting on a backbone $S\subset\R^3$ has the form $f(p)=\vec v+R(\vec p)$ for a fixed vector $\vec v\in\R^n$, an orthogonal map $R\in\Or(\R^3)$, and any $p\in\R^3$.
Then $f$ maps every orthonormal basis $\vb*{u}_i,\vb*{v}_i,\vb*{w}_i$ with the origin at a point $A_i\in\R^3$ to another orthonormal basis $R(\vb*{u}_i)$, $R(\vb*{v}_i)$, $R(\vb*{w}_i)$ at the new origin $f(A_i)$.
Hence the image of any vector $\ve{A_i P_i}=x\vb*{u}_i +y\vb*{v}_i +z\vb*{w}_i$ under $f$ has the same coordinates in the rigidly transformed basis: $f(\ve{A_i P_i})=R(\ve{A_i P_i})= xR(\vb*{u}_i) +yR(\vb*{v}_i) +zR(\vb*{w}_i)$, so $\bri(S)=\bri(f(S))$.
\medskip

For any residue having a fixed index $i$, Definition~\ref{dfn:bri} needs only a constant time $O(1)$ to compute the basis vectors and coordinates of $\ve{C_{i-1}N_i}$ in the basis of the previous residue.
The total time for computing the $m\times 9$ matrix $\bri(S)$ is $O(m)$.
The metric $L_\infty$ has a linear time in the size $9m$. % of the matrix $\bri(S)$.
\medskip

The completeness will follow by showing that any backbone $S\subset\R^3$ can be efficiently reconstructed from $\bri(S)$, uniquely after fixing the first residue whose shape is determined by the three non-zero values in the first row of $\bri(S)$.
In the first residue, the $\al$-carbon $A_1$ can be moved to the origin $0\in\R^3$ by translation. 
Using $x(N_1)=|\ve{A_1 N_1}|$, the $N$-terminal atom $N_1$ can be fixed in the positive $x$-axis by an orthogonal map from $\SO(3)$. 
A suitable rotation around the $x$-axis can move $C_1$ to the upper $xy$-plane.
All these transformations preserve the lengths and scalar products.
The final position of $C_1$ is uniquely determined by $x(C_1),y(C_1)$ in Definition~\ref{dfn:bri}.
\medskip

After fixing $\triangle N_1,A_1,C_1$, it remains to prove that any other atom of $S$ is uniquely determined by its $x,y,z$ coordinates in $\bri(S)$.
Indeed, $N_2$ is obtained from $C_1$ by adding $\ve{C_1N_2}$, whose coordinates are the first three elements in the 2nd row of $\bri(S)$.
Then $A_2$ is obtained from $N_1$ by adding $\ve{N_2A_2}$,
whose coordinates are the next three elements in the 2nd row of $\bri(S)$.
Then $C_2$ is obtained from $A_2$ by adding $\ve{A_2C_2}$ and so on.
\medskip

\noindent
\textbf{(c)}
Since the complete invariant $\bri(S)$ of a backbone $S$ is locally defined by determining any $i$-th residue triangle $\triangle N_i A_i C_i$ in the basis of the previous $(i-1)$-st triangle, all rows of the matrix $\bri(Q)$ for any subchain $Q$ in the full backbone $S$ coincide with the corresponding rows of $\bri(S)$.
\medskip

The only exception is the first row if $Q$ starts from the $i$-th residue of $S$ for $i>1$.
In this case, the three non-zero invariants in the first row of $Q$ can be obtained from the $i$-th row of $\trin(S)$ whose values are expressed in terms of the vectors $\ve{N_i A_i}$ and $\ve{A_i C_i}$ in Definition~\ref{dfn:trin}.
This computation needs only a constant time independent of $j$ because the coordinates of the vectors $\ve{A_i N_i}$ and $\ve{A_i C_i}$ are given in the $i$-th row of $\bri(S)$.
\end{proof}

\begin{cor}[completeness under isometry]
\label{cor:isometry}
Any mirror image $\bar S$ of a backbone $S\subset\R^3$ has the invariant $\ov{\bri}(S):=\bri(\bar S)$ obtained by reversing the signs in all $z$-columns of $\bri(S)$.
The unordered pair of $\bri(S)$ and $\ov{\bri}(S)$ is complete under isometry.
\end{cor}

\begin{proof}[Proof of Corollary~\ref{cor:isometry}]
To prove that $\ov{\bri}(S):=\bri(\bar S)$ is obtained from $\bri(S)$ by reversing the signs in all $z$-columns of $\bri(S)$, consider the main atoms $N_i,A_i,C_i$ in the $i$-th residue of $S$ for any $i=2,\dots,m$.
The mirror image $\bar S$ has the corresponding atoms $\bar N_i,\bar A_i,\bar C_i$.
There is a rigid motion $f$ in $\R^3$ that matches these atoms so that $N_i=f(\bar N_i)$, $A_i=f(\bar A_i)$, $C_i=f(\bar C_i)$, and $f(\bar S)$ is obtained from $S$ by the reflection $g$ in the plane of the residue triangle $\triangle N_i A_i C_i$.
This reflection $g$ preserves the basis vectors $\vb*{u}_i,\vb*{v}_i,\vb*{w}_i$ from Definition~\ref{dfn:bri} of the $i$-th residue of the backbone $S$.
\medskip

In the orthonormal basis of $u_i,v_i$, $w_i=u_i\times v_i$, the coordinates of the vector $\ve{C_i N_{i+1}}=x(N_{i+1})\vb*{u}_i + y(N_{i+1})\vb*{v}_i + z(N_{i+1})\vb*{w}_i$ 
determine the coordinates of the mirror image
$f(\ve{\bar C_i \bar N_{i+1})}=x(N_{i+1})\vb*{u}_i + y(N_{i+1})\vb*{v}_i - z(N_{i+1})\vb*{w}_i$, where only the sign of the coefficient of $\vb*{w}_i$ is reversed as required.
Since the index $i=2,\dots,m$ was arbitrarily chosen, it remains to notice that the first residue triangles $\triangle N_1 A_1 C_1$ and $\triangle \bar N_1 \bar A_1 \bar C_1$ can be matched by rigid motion, so all 3 non-zero invariants in the first rows of $\bri(S)$ and $\bri(\bar S)$ coincide, while all $z$-coordinates are zeros.
Finally, the unordered pair of $\bri(S)$ and $\ov{\bri}(S)$ is invariant under any rigid motion by Theorem~\ref{thm:motion}(a) and under reflection, which swaps the invariants in this pair.
By Theorem~\ref{thm:motion}(b), any of $\bri(S)$ and $\ov{\bri}(S)$ suffices to reconstruct $S$ or $\bar S$ up to rigid motion, hence $S$ up to isometry in $\R^3$.
\end{proof}

