\section{Lipschitz bi-continuity of the invariant $\bri$}
\label{sec:continuity}

Theorem~\ref{thm:continuity} will prove the Lipschitz continuity of $\bri$ in condition~\ref{pro:map}(c).
For a given backbone $S$ and its perturbation $Q$, let $l_{N,A}$ and $L_{N,A}$ denote the minimum and maximum bond length between any $\al$-carbon $A_i$ and nitrogen $N_i$ in $S,Q$, respectively.
The maximum bond lengths $L_{A,C},L_{C,N}$ are similarly defined for other types of bonds.

\begin{thm}[Lipschitz continuity of $\bri$]
\label{thm:continuity}
For any $\ep>0$, let $Q$ be obtained from a backbone $S\subset\R^3$ by perturbing every atom of $S$ up to Euclidean distance $\ep$.
Let $h=\min_i|y(A_i C_i)|$ be the minimum height in triangles $\triangle N_i A_i C_i$ at $C_{i}$ for all residues in the backbones $S,Q$. 
Set $L=\max\{L_{C,N},L_{N,A},L_{A,C}\}$, $K=\dfrac{1}{l_{N,A}}+\dfrac{2}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big)$, and $\la=2(1+2LK)$.
Then $L_\infty(\bri(S),\bri(Q))\leq \la\ep$. 
\end{thm}
\smallskip

%The proof of 
Theorem~\ref{thm:continuity} needs Lemmas~\ref{lem:length_difference}, \ref{lem:vec_perturbation}, \ref{lem:norm_vectors}, \ref{lem:products}, and Proposition~\ref{prop:basis}.

\begin{lem}[length difference]
\label{lem:length_difference}
Any %vectors 
$\vb*{u},\vb*{v}\in\R^n$ satisfy
$|\,|\vb*{u}|-|\vb*{v}|\,|\leq |\vb*{u}-\vb*{v}|$.
\end{lem}
\begin{proof}
The triangle inequality for the Euclidean distance implies that
$|\vb*{u}|\leq |\vb*{u}-\vb*{v}|+|\vb*{v}|$, so 
$|\vb*{u}|-|\vb*{v}|\leq |\vb*{u}-\vb*{v}|$.
Swapping the vectors, we get
$|\vb*{v}|-|\vb*{u}|\leq |\vb*{u}-\vb*{v}|$.
Combining the inequalities $\pm(|\vb*{u}|-|\vb*{v}|)\leq |\vb*{u}-\vb*{v}|$, we conclude that $|\,|\vb*{u}|-|\vb*{v}|\,|\leq |\vb*{u}-\vb*{v}|$ as required.
\end{proof}

\begin{lem}[perturbation of a vector]
\label{lem:vec_perturbation}
Let $A',B'$ be any $\ep$-perturbations of points $A,B\in\R^n$, respectively, i.e. $|A-A'|\leq\ep$, $|B-B'|\leq\ep$.
Then $|\ve{A'B'}-\ve{AB}|\leq 2\ep$.
\end{lem}
\begin{proof}
Apply the triangle inequality: \\
$|\ve{A'B'}-\ve{AB}|=|\ve{A'A}+\ve{BB'}|\leq |\ve{A'A}|+|\ve{BB'}|\leq 2\ep$.
\end{proof}

\begin{lem}[a normalized vector]
\label{lem:norm_vectors}
Let $\vb*{u}$ be a $\de$-perturbation of a vector $\vb*{v}\in\R^n$, i.e. $|\vb*{u} -\vb*{v}|\leq\de$.
Then $\left|\dfrac{\vb*{u}}{|\vb*{u}|}-\dfrac{\vb*{v}}{|\vb*{v}|}\right|\leq \dfrac{2\de}{l}$, where $l=\max\{|\vb*{u}|,|\vb*{v}|\}$.
Hence if $\vb*{u}=\ve{A N}$ and $\vb*{u}'=\ve{A' N'}$ are vectors between atoms $A_i,N_i$ and their $\ep$-perturbations, then 
$\left|\dfrac{\vb*{u}}{|\vb*{u}|}-\dfrac{\vb*{v}}{|\vb*{v}|}\right|\leq \dfrac{4\ep}{l_{N,A}}$, where $l_{N,A}$ is the minimum bond length between $N_i,A_i$.
\end{lem}
\begin{proof}
%Without loss of generality 
Assume that $\max\{|\vb*{u}|,|\vb*{v}|\}=|\vb*{v}|$, which we denote by $l$. 
Then
\begin{align*}
& \left|\dfrac{\vb*{u}}{|\vb*{u}|}-\dfrac{\vb*{v}}{|\vb*{v}|}\right|
=\left|\dfrac{|\vb*{v}|\vb*{u}-|\vb*{u}|\vb*{v}}{|\vb*{u}|\cdot |\vb*{v}|}\right|=
\dfrac{|\,(|\vb*{v}|-|\vb*{u}|)\vb*{u}+|\vb*{u}|(\vb*{u}-\vb*{v})\,|}{|\vb*{u}|\cdot |\vb*{v}|}\leq \\
& \dfrac{|\, |\vb*{u}|-|\vb*{v}|\,|\cdot |\vb*{u}| + |\vb*{u}|\cdot |\vb*{u}-\vb*{v}|}{|\vb*{u}|\cdot|\vb*{v}|}
=\dfrac{|\,|\vb*{u}|-|\vb*{v}|\,|+|\vb*{u}-\vb*{v}|}{|\vb*{v}|}
\leq \dfrac{2|\vb*{u}-\vb*{v}|}{|\vb*{v}|}
\leq %\dfrac{2\de}{|\vb*{v}|}=
\dfrac{2\de}{l},
\end{align*} 
where we used the triangle inequality, Lemma~\ref{lem:length_difference}, and $|\vb*{u} -\vb*{v}|\leq\de$.
The second inequality follows for $\de=2\ep$ from Lemma~\ref{lem:vec_perturbation} and $l_{N,C}\leq\max\{|\vb*{u}|,|\vb*{v}|\}$.
\end{proof}

\begin{lem}[products] % perturbations]
\label{lem:products}
For any %vectors 
$\vb*{u},\vb*{u}',\vb*{v},\vb*{v}'\in\R^n$, 
if $|\vb*{v}'|=|\vb*{v}|=1$, 
then 
\smallskip

\noindent
\textbf{(a)} 
$|(\vb*{u}'\cdot \vb*{v}') - (\vb*{u}\cdot\vb*{v})|\leq
|\vb*{u}' - \vb*{u}|+|\vb*{u}|\cdot|\vb*{v}' - \vb*{v}|$, 
\smallskip

\noindent
\textbf{(b)} 
$|(\vb*{u}'\times \vb*{v}') - (\vb*{u}\times\vb*{v})|\leq
|\vb*{u}' - \vb*{u}|+|\vb*{u}|\cdot|\vb*{v}' - \vb*{v}|$,
\smallskip

\noindent
\textbf{(c)} 
$|(\vb*{u}'\cdot \vb*{v}')\vb*{v}' - (\vb*{u}\cdot\vb*{v})\vb*{v}|\leq
|\vb*{u}' - \vb*{u}|+2|\vb*{u}|\cdot|\vb*{v}' - \vb*{v}|$.
\end{lem}
\begin{proof}
\textbf{(a)} 
Any scalar and vector product has the upper bound
$|\vb*{u}|\cdot|\vb*{v}|$. %, which we use below to prove (a):  
\begin{align*}
& |(\vb*{u}'\cdot \vb*{v}') - (\vb*{u}\cdot \vb*{v})|
=|(\vb*{u}'-\vb*{u})\cdot \vb*{v}' +\vb*{u}\cdot(\vb*{v}' -\vb*{v})| \leq \\
& \leq |(\vb*{u}'-\vb*{u})\cdot \vb*{v}'| +|\vb*{u}\cdot(\vb*{v}' -\vb*{v})|\leq 
\leq |\vb*{u}'-\vb*{u}|\cdot|\vb*{v}'|+|\vb*{u}|\cdot|\vb*{v}' -\vb*{v}| = \\
& =|\vb*{u}' - \vb*{u}|+|\vb*{u}|\cdot|\vb*{v}' - \vb*{v}| \text{ due to } |\vb*{v}'|=1.
\end{align*}

\noindent
\textbf{(b)} 
Prove as (a) with the vector product instead of the scalar product.
\medskip

\noindent
\textbf{(c)} 
It follows by using $|\vb*{v}|=1$ and part (a):
\begin{align*}
& |(\vb*{u}'\cdot \vb*{v}')\vb*{v}' - (\vb*{u}\cdot\vb*{v})\vb*{v}|
=|(\vb*{u}'\cdot \vb*{v}'-\vb*{u}\cdot\vb*{v})\vb*{v}' + (\vb*{u}\cdot\vb*{v})(\vb*{v}'-\vb*{v})| \leq \\
& \leq  |\vb*{u}'\cdot \vb*{v}'-\vb*{u}\cdot\vb*{v}|\cdot |\vb*{v}'|
+|\vb*{u}\cdot\vb*{v}|\cdot |\vb*{v}'-\vb*{v}|\leq \\
& \leq |\vb*{u}'\cdot \vb*{v}'-\vb*{u}\cdot\vb*{v}|+|\vb*{u}|\cdot|\vb*{v}|\cdot|\vb*{v}'-\vb*{v}|
\leq |\vb*{u}' - \vb*{u}|+2|\vb*{u}|\cdot|\vb*{v}' - \vb*{v}|
\end{align*}
as required.
\end{proof}

Recall that $l_{N,A}$ denotes the minimum bond length between $N_i$ and $A_i$, and $L_{A,C}$ is the maximum distance between $A_i$ and $C_i$, while
$h$ is the minimum height in $\triangle N_i A_i C_i$ at $C_i$ for all residues in given backbones.

\begin{prop}[perturbations of a basis]
\label{prop:basis}
In the conditions of Theorem~\ref{thm:continuity},
if any atom is perturbed up to $\ep$, the basis vectors from Definition~\ref{dfn:bri} are perturbed as follows:
\smallskip

\noindent
\textbf{(a)} 
$|\vb*{u}'_i-\vb*{u}_i|\leq\dfrac{4\ep}{l_{N,A}}$;
\smallskip

\noindent
\textbf{(b)} 
$|\vb*{v}'_i-\vb*{v}_i|\leq\dfrac{8\ep}{h}(1+2\dfrac{L_{A,C}}{l_{N,A}})$; \smallskip

\noindent
\textbf{(c)} 
$|\vb*{w}'_i-\vb*{w}_i|\leq
4\ep K$, where $K=\dfrac{1}{l_{N,A}}+\dfrac{2}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big)$ for all $i=1,\dots,m$.
\end{prop}
\begin{proof}
\textbf{(a)} 
In Definition~\ref{dfn:bri} the vector $\vb*{u}_i=\dfrac{\ve{A_i N_i}}{|\ve{A_i N_i}|}$ satisfies the inequality $|\vb*{u}'_i-\vb*{u}_i|\leq\dfrac{4\ep}{l_{N,A}}$ by Lemma~\ref{lem:norm_vectors}.
\medskip

\noindent
\textbf{(b)} 
The second vector is $\vb*{v}_i=\dfrac{\vb*{h}_i}{|\vb*{h}_i|}$ for $\vb*{h}_i=\ve{A_i C_i}-b_i\ve{A_i N_i}$ and $b_i=\dfrac{\ve{A_i C_i}\cdot\ve{A_i N_i}}{|\ve{A_i N_i}|^2}$.
Set $\vb*{p}_i=\ve{A_i C_i}$, $\vb*{q}_i=\dfrac{\ve{A_i N_i}}{|\ve{A_i N_i}|}$, so $|\vb*{q}_i|=|\vb*{q}'_i|=1$, where any dash denotes a perturbation of a point or a vector.
Also, $|\vb*{p}_i|=|\ve{A_i C_i}|$ has the upper bound $L_{A,C}$. 
By Lemma~\ref{lem:products}(c): 
\begin{align*}
& |b'_i\ve{A'_i N'_i}-b_i\ve{A_i N_i}|=
|(\vb*{p}'_i\cdot \vb*{q}'_i)\vb*{q}'_i - (\vb*{p}_i\cdot \vb*{q}_i)\vb*{q}_i|
\leq \\
& |\vb*{p}'_i - \vb*{p}_i|+2|\vb*{p}_i|\cdot|\vb*{q}'_i - \vb*{q}_i|
\leq 2\ep+2L_{A,C}\dfrac{4\ep}{l_{N,A}},
\end{align*}
where we used $|\vb*{p_i}|\leq L_{A,C}$ and 
$|\vb*{q}'_i - \vb*{q}_i|\leq \dfrac{4\ep}{l_{N,A}}$ by Lemma~\ref{lem:norm_vectors}.
Then 
\begin{align*}
& |\vb*{h}'_i-\vb*{h}_i|=|\vb*{p}'_i-b'_i\ve{A'_i N'_i}-(\vb*{p}_i-b_i\ve{A_i N_i})| \leq \\
& \leq |\vb*{p}'_i-\vb*{p}_i|+|b'_i\ve{A'_i N'_i}-b_i\ve{A_i N_i}|\leq  2\ep+2\ep+\ep\dfrac{L_{A,C}}{l_{N,A}}=4\ep(1+2\dfrac{L_{A,C}}{l_{N,A}}).
\end{align*}
The vectors $\vb*{h}_i$, $\vb*{p}_i$, and $b_i\ve{A_i N_i}=(\vb*{p}_i\cdot\vb*{q}_i)\vb*{q}_i$ form a right-angled triangle with the hypotenuse $|\vb*{p}_i|$.
%Then $(\vb*{p}_i\cdot\vb*{q}_i)\vb*{q}_i=|\vb*{p}_i|\cos\angle N_iA_iC_i$and $|\vec r_i|=|\vb*{p}_i|\sin\angle N_iA_iC_i$.
The length $|\vb*{h}_i|=|\ve{A_iC_i}|\sin\angle N_i A_i C_i$ is the height in $\triangle N_i A_i C_i$ at the atom $C_i$.
Using the given minimum height $h\leq |\vb*{h}_i|$, Lemma~\ref{lem:norm_vectors} for $\de=4\ep(1+2\dfrac{L_{A,C}}{l_{N,A}})$ implies that
$$|\vb*{v}'_i-\vb*{v}_i|
=\left| \dfrac{\vb*{h}'_i}{|\vb*{h}'_i|} - \dfrac{\vb*{h}_i}{|\vb*{h}_i|} \right|
\leq \dfrac{2\de}{h}\leq \dfrac{8\ep}{h}(1+2\dfrac{L_{A,C}}{l_{N,A}}).$$
%\medskip

\noindent
\textbf{(c)} 
The perturbation of  $\vb*{w}_i=\vb*{u}_i\times\vb*{v}_i$ is estimated by
Lemma~\ref{lem:products}(b):
\begin{align*}
& |\vb*{w}'_i-\vb*{w}_i|
=|(\vb*{u}'_i\times \vb*{v}'_i) - (\vb*{u}_i\times\vb*{v}_i)|\leq
|\vb*{u}'_i - \vb*{u}_i|+|\vb*{u}_i|\cdot|\vb*{v}'_i - \vb*{v}_i|\leq \\
& \leq\dfrac{4\ep}{l_{N,A}}+\dfrac{8\ep}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big) =4\ep K,
\text{ where }K=\dfrac{1}{l_{N,A}}+\dfrac{2}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big)
\end{align*}
as required.
\end{proof}
\smallskip

\begin{proof}[Proof of Theorem~\ref{thm:continuity}]
In the perturbed backbone $Q$, let $N'_i,A'_i,C'_i$ denote $\ep$-perturbations of atoms $N_,A_i,C_i$ from the backbone $S$ for $i=1,\dots,m$.
We prove that any coordinate of $\bri(S)$ changes by at most $\la\ep$ for the given Lipschitz constant $\la$.
The first coordinate $x(N_1)$ changes by at most $2\ep$ because $|x(N'_1)-x(N_1)|=\big|\, |\ve{A'_1N'_1}|-|\ve{A_1 N_1}|\,\big|\leq 2\ep$ by Lemma~\ref{lem:length_difference}.
For the coordinate $x(C_1)=\dfrac{\ve{A_1 C_1}\cdot\ve{A_1N_1}}{|\ve{A_1N_1}|}$, set $\vb*{u}=\ve{A_1 C_1}$ and $\vb*{v}=\dfrac{\ve{A_1N_1}}{|\ve{A_1N_1}|}$, so $|\vb*{v}|=1$.
We write the perturbed versions of all vectors with a dash.
\medskip

Then $|x(C'_1)-x(C_1)|=|\vb*{u}'\cdot\vb*{v}'-\vb*{u}\cdot\vb*{v}|\leq 
|\vb*{u}' - \vb*{u}|+|\vb*{u}|\cdot|\vb*{v}' - \vb*{v}|$ by Lemma~\ref{lem:products}(a).
Lemma~\ref{lem:vec_perturbation} implies that $|\vb*{u}' - \vb*{u}|\leq 2\ep$.
Lemma~\ref{lem:norm_vectors} for $u=\ve{A'_1N'_1}$ and $v=\ve{A_1N_1}$ implies that $|\vb*{v}' - \vb*{v}|\leq \dfrac{4\ep}{l_{N,A}}$, where $l_{N,A}$ is the minimum length of the bond between an $\al$-carbon $A_i$ and $N_i$ across all backbones.
Also, the Euclidean length $|\vb*{u}|=|\ve{A_1 C_1}|$ has the upper bound $L_{A,C}$ equal to the maximum length of the bond between $A_i$ and $C_i$ across all backbones.
Then $|x(C'_1)-x(C_1)|\leq 2\ep\Big(1+ 2\dfrac{L_{A,C}}{l_{N,A}}\Big)$.
\medskip

In the notations above, the last non-zero coordinate in the first row of $\bri(A)$ is
 $y(C_1)=|\ve{A_1 C_1} - x(C_1)\dfrac{\ve{A_1N_1}}{|\ve{A_1N_1}|}|=|\vb*{u}-x(C_1)\vb*{v}|$.
We estimate the perturbation first by Lemma~\ref{lem:length_difference}:  
\begin{align*}
& |y(C'_1)-y(C_1)|=|\,|\vb*{u}'-x(C'_1)\vb*{v}'| - |\vb*{u}-x(C_1)\vb*{v}| \,|
\leq \\
& \leq |\vb*{u}'-x(C'_1)\vb*{v}' - (\vb*{u}-x(C_1)\vb*{v})|
 \leq |\vb*{u}'-\vb*{u}|+|x(C'_1)\vb*{v}'-x(C_1)\vb*{v}| \leq \\
& \leq 2\ep+|(x(C'_1)-x(C_1))\vb*{v}'+x(C_1)(\vb*{v}'-\vb*{v})| \leq \\
& \leq 2\ep+|x(C'_1)-x(C_1)|+|x(C_1)|\cdot|\vb*{v}'-\vb*{v}| \leq \\
& \leq 2\ep+2\ep\Big(1+ 2\dfrac{L_{A,C}}{l_{N,A}}\Big)+|\ve{A_1 C_1}|\dfrac{4\ep}{l_{N,A}} 
\leq 4\ep \Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big),
\end{align*}
where we substituted %the bounds
$|x(C'_1)-x(C_1)|\leq 2\ep(1+ 2\dfrac{L_{A,C}}{l_{N,A}})$ and
$|\vb*{v}'-\vb*{v}|\leq \dfrac{4\ep}{l_{N,A}}$. 
\smallskip

In any $i$-th row for $i=2,\dots,m$, we estimate %perturbations 
by Proposition~\ref{prop:basis}(a):
\begin{align*}
& |x(N'_i)-x(N_i)|=|\ve{C'_{i-1}N'_i}\cdot \vb*{u}'_i - \ve{C_{i-1} N_i}\cdot \vb*{u}_i| \leq 
|\ve{C'_{i-1}N'_i} - \ve{C_{i-1} N_i}|+ \\
& + |\ve{C_{i-1} N_i}|\cdot |\vb*{u}'_i - \vb*{u}_i|
\leq 2\ep+L_{C,N}\dfrac{4\ep}{l_{N,A}}=2\ep(1+2\dfrac{L_{C,N}}{l_{N,A}})
\end{align*}
due to the upper bound $|\ve{C_{i-1} N_i}|\leq L_{C,N}$.
For the other coordinates $y,z$, similarly use Proposition~\ref{prop:basis}(b,c): %, respectively, as follows:
\begin{align*}
& |y(N'_i)-y(N_i)=|\ve{C'_{i-1}N'_i}\cdot \vb*{v}'_i - \ve{C_{i-1} N_i}\cdot \vb*{v}_i| \leq \\
& \leq |\ve{C'_{i-1}N'_i} - \ve{C_{i-1} N_i}|+|\ve{C_{i-1} N_i}|\cdot |\vb*{v}'_i - \vb*{v}_i|\leq \\
& \leq 2\ep+L_{C,N}\cdot \dfrac{8\ep}{h}(1+2\dfrac{L_{A,C}}{l_{N,A}})=2\ep\Big(1+4\dfrac{L_{C,N}}{h} (1+2\dfrac{L_{A,C}}{l_{N,A}}\Big). \\
& |z(N'_i)-z(N_i)|
=|\ve{C'_{i-1}N'_i}\cdot \vb*{w}'_i - \ve{C_{i-1} N_i}\cdot \vb*{w}_i|
\leq \\
& \leq  |\ve{C'_{i-1}N'_i} - \ve{C_{i-1} N_i}|+|\ve{C_{i-1} N_i}|\cdot |\vb*{w}'_i - \vb*{w}_i|\leq \\
& \leq 2\ep+L_{C,N}\cdot 4\ep K =2\ep(1+2L_{C,N}K),
\text{ for } K=\dfrac{1}{l_{N,A}}+\dfrac{2}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big).
\end{align*}

For the atoms $A_i,C_i$, we get similar upper bounds by replacing the factor $L_{C,N}$ with $L_{N,A}$, $L_{A,C}$, respectively.
Taking into account all upper bounds above, the overall upper bound for the $L_\infty$ metric on invariants is
$L_\infty(\bri(S),\bri(Q))\leq \la\ep$, where
$\la=2(1+2LK)$ for $L=\max\{L_{C,N},L_{N,A},L_{A,C}\}$ and
$K=\dfrac{1}{l_{N,A}}+\dfrac{2}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big)$ as required. 
\end{proof}

\begin{exa}[continuity in practice]
\label{exa:continuity}
For all 707K+ cleaned chains, the median upper bound for $\la$ is about 34.5 but the real values are smaller as in the example below.
Consider the backbone $S$ of the chain A (141 residues) from the standard hemoglobin 2hhb in the PDB.
\medskip

We perturb $S$ to $Q$ by adding to each coordinate $x,y,z$ of all atoms in $S$ some uniform noise up to various thresholds $\ep=0.01,0.02,\dots,0.1\angstrom$.
Fig.~\ref{fig:hemoglobins}~(top left) shows how the distance $L_\infty(\bri(S),\bri(Q))$ averaged over 20 perturbations depends on $\ep$
As expected by Theorem~\ref{thm:continuity}, the metric $L_\infty$ is perturbed linearly up to $\la\ep$, where $\la\approx 4$.
\end{exa}

Because the metric $L_\infty$ between invariants $\bri$ ($m\times 9$ matrices) can be computed in linear time $O(m)$, Theorem~\ref{thm:continuity} also completes condition (\ref{pro:map}f) in Problem~\ref{pro:map}.
Theorem~\ref{thm:inverse} will prove %the atom matching 
condition in \ref{pro:map}(d).

\begin{thm}[inverse continuity of $\bri$]
\label{thm:inverse}
For any $\de>0$ and backbones $S,Q\subset\R^3$ with $L_\infty(\bri(S),\bri(Q))<\de$, there is a rigid motion $f$ of $\R^3$ such that any atom of $S$ is $\mu\de$-close to the corresponding atom of $f(Q)$ for $\mu=\sqrt{3}\dfrac{(8LK)^{m-1}-1}{8LK-1}$.
Let $\widehat{\bri}(S)$ be $\bri(S)$ after multiplying the $i$-th row by $\dfrac{(8LK)^{i-1}-1}{8LK-1}$ for $i=2,\dots,m$.
Then $L_\infty(\widehat{\bri}(S),\widehat{\bri}(Q))<\de$ guarantees a rigid motion $f$ of $\R^3$ such that any atom of the backbone $S$ is $\sqrt{3}\de$-close to the corresponding atom of $f(Q)$.
\end{thm}
\begin{proof}[Proof of Theorem~\ref{thm:inverse}]
Choose the origin of $\R^3$ at the first alpha-carbon atom $A_1$ of the backbone $S$, the positive $x$-axis through the vector $\ve{A_1N_1}$, and the $y$-axis so that the triangle $N_1 A_1 C_1$ belongs to the upper half of the $xy$-plane.
Shift another backbone $Q$ so that its first alpha-carbon atom $A'_1$ coincides with the origin $A_1$. 
Rotate the image of $Q$ so that its first nitrogen atom $N_1$ is in the $x$-axis through the atoms $A_1,N_1$ of $S$ and the next carbon $C'_1$ of $Q$ is in the upper $xy$-plane.
\medskip

For the resulting motion $f$, we will prove that the atoms of $S$ are $\mu\de$-close to the corresponding atoms of the image of $Q$, which we still denote by $N'_i,A'_i,C'_i$ for simplicity.
Because the atom $N'_1$ is in the $x$-axis through $\ve{A_1N_1}$, the first basis vectors of length 1 coincide ($\vb*{u}'_1=\vb*{u}_1$) and hence also uniquely define the other basis vectors ($\vb*{v}'_1=\vb*{v}_1$, $\vb*{w}'_1=\vb*{w}_1$).
\medskip

Then $|x(N'_1)-x(N_1)|\leq\de$ implies that the atom $N'_1$ is $\de$-close to $N_1$ in the $x$-axis.
The atoms $C_1,C'_1$ are $\de\sqrt{2}$-close due to
$$|C'_1-C_1|=\sqrt{|x(C'_1)-x(C_1)|^2+|y(C'_1)-y(C_1)|^2}\leq\sqrt{\de^2+\de^2}=\de\sqrt{2}.$$ 
%\smallskip

Because the first bases coincide, we consider the second residue:
\begin{align*}
& |N'_2-N_2|= \\
& =|x(N'_2)\vb*{u}_1 + y(N'_2)\vb*{v}_1 + z(N'_2)\vb*{w}_1 - 
x(N_2)\vb*{u}_1 - y(N_2)\vb*{v}_1 - z(N_2)\vb*{w}_1|
= \\
& =\sqrt{|x(N'_2)-x(N_2)|^2+|y(N'_2)-y(N_2)|^2+|z(N'_2)-z(N_2)|^2}\leq \\
& \leq\sqrt{\de^2+\de^2+\de^2}=\de\sqrt{3}.
\end{align*}

Similarly, we get the upper bound $\ep=\de\sqrt{3}$ for the deviations $|A'_2-A_2|$ and $|C'_2-C_2|$.
We will prove the following upper bound on deviations of atoms by induction on 
the number $m\geq 2$ of residues.   
$$\max\{|N'_m-N_m|,|A'_m-A_m|,|C'_m-C_m|\}\leq 
\sqrt{3}(1+8LK+\dots+8 (LK)^{m-2})\de, $$
$$\text{ where } 
L=\max\{L_{C,N},L_{N,A},L_{A,C}\},\quad 
K=\dfrac{1}{l_{N,A}}+\dfrac{2}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big).$$
The base $m=2$ was completed above.
The inductive assumption says that the upper bound $\ep=\sqrt{3}(1+8LK+\dots+(8 LK)^{i-2})\de$ holds for a single value of $i\geq 2$.
The inductive step below is for the next value $i+1$.
\medskip

Proposition~\ref{prop:basis} estimates deviations of vectors in the second basis:
$$|\vb*{u}'_2-\vb*{u}_2|\leq\dfrac{4\ep}{l_{N,A}},\quad
|\vb*{v}'_2-\vb*{v}_2|\leq\dfrac{8\ep}{h}\big(1+2\dfrac{L_{A,C}}{l_{N,A}}\big), \quad
|\vb*{w}'_2-\vb*{w}_2|\leq
4\ep K.$$ 
For nitrogens, we split the deviations in the $(i+1)$-st residue into the deviations proportional to the differences in coordinates and the deviations proportional to the differences in basis vectors as follows:
\begin{align*}
& |N'_{i+1}-N_{i+1}| =  |x(N'_{i+1})\vb*{u}'_i 
+y(N'_{i+1})\vb*{v}'_i + z(N'_{i+1})\vb*{w}'_i - \\
& - x(N_{i+1})\vb*{u}_i 
-y(N_{i+1})\vb*{v}_i - z(N_{i+1})\vb*{w}_i| = 
|(x(N'_{i+1})\vb*{u}'_i - x(N_{i+1})\vb*{u}_i) + \\
& +(y(N'_{i+1})\vb*{v}'_i - y(N_{i+1})\vb*{v}_i)
+(z(N'_{i+1})\vb*{w}'_i - z(N_{i+1})\vb*{w}_i)|= \\
& =\Big|
\big(x(N'_{i+1})- x(N_{i+1})\big)\vb*{u}'_i + x(N_{i+1})(\vb*{u}'_i-\vb*{u}_i)
+\big(y(N'_{i+1})- y(N_{i+1})\big)\vb*{v}'_i +\\ 
& + y(N_{i+1})(\vb*{v}'_i-\vb*{v}_i)
+\big(z(N'_{i+1})- z(N_{i+1})\big)\vb*{w}'_i + z(N_{i+1})(\vb*{w}'_i-\vb*{w}_i)\Big|\leq \\
& \leq \Big| \big(x(N'_{i+1})- x(N_{i+1})\big)\vb*{u}'_i+ \big(y(N'_{i+1})- y(N_{i+1})\big)\vb*{v}'_i+ \\
& + \big(z(N'_{i+1})- z(N_{i+1})\big)\vb*{w}'_i \Big| +\Big| x(N_{i+1})(\vb*{u}'_i-\vb*{u}_i)\Big| + \\
& + \Big| y(N_{i+1})(\vb*{v}'_i-\vb*{v}_i)\Big|
+ \Big| z(N_{i+1})(\vb*{w}'_i-\vb*{w}_i)\Big|.
\end{align*}

In the last upper bound, the first big modulus is the Euclidean length of a vector written in the orthonormal basis $\vb*{u}'_i, \vb*{v}'_i, \vb*{w}'_i$.
Since the coordinates of this vector have absolute values at most $\de$, this length has the upper bound $\de\sqrt{3}$.
In the second row of the matrix $\bri$, we estimate each term by replacing absolute values of coordinates with the maximum bond lengths and by using
$|x(N_{i+1})|\leq L_{C,N}$ and Proposition~\ref{prop:basis} as follows: 
\begin{align*}
& |x(N_{i+1})|\cdot |\vb*{u}'_i-\vb*{u}_i|\leq 
 L_{C,N}\dfrac{4\ep}{l_{N,A}}, \\
& |y(N_{i+1})|\cdot |\vb*{v}'_i-\vb*{v}_i|\leq 
 L_{C,N}\dfrac{8\ep}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big), \\
& |z(N_{i+1})|\cdot |\vb*{w}'_i-\vb*{w}_i|\leq 
 L_{C,N}\cdot 4\ep K, \text{ where }
 K=\dfrac{1}{l_{N,A}}+\dfrac{2}{h}\Big(1+2\dfrac{L_{A,C}}{l_{N,A}}\Big).
\end{align*}

Taking the sum of these estimates,  the final deviation %of nitrogens 
is
\begin{align*}
& |N'_{i+1}-N_{i+1}|\leq \\
& \sqrt{3}\de+ 4\ep L_{C,N}\Big(\dfrac{1}{l_{N,A}}
 +\dfrac{2}{h}\big(1+2\dfrac{L_{A,C}}{l_{N,A}}\big)
 +\dfrac{1}{l_{N,A}}+\dfrac{2}{h}\big(1+2\dfrac{L_{A,C}}{l_{N,A}}\big)
 \Big)= \\
& =\sqrt{3}\de+8L_{C,N}\ep K\leq \sqrt{3}(1+ 8LK(1+\dots+(8LK)^{i-2})\de
 = \\
& =\sqrt{3}(1+\dots+(8LK)^{i-1})\de.
\end{align*}

For the atoms $A_{i+1},C_{i+1}$ in the $(i+1)$-st residue, we get the same bound by replacing $L_{C,N}$ with $L_{N,A},L_{A,C}\leq L$.
The bound for $i=m$ is 
$\sqrt{3}(1+\dots+(8LK)^{m-2}))\de=\sqrt{3}\dfrac{(8LK)^{m-1}-1}{8LK-1}\de$.
\medskip

Now consider the modified invariant $\widehat{\bri}(S)$ obtained by multiplying the $i$-th row of $\bri(S)$ by $\dfrac{(8LK)^{i-1}-1}{8LK-1}$ for $i=2,\dots,m$.
Then the $\de$-closeness of the corresponding invariant components in the metric $L_\infty$ means smaller deviations $|x(N'_i)-x(N_i)|\leq\de\dfrac{8LK-1}{(8LK)^{i-1}-1}$, similarly for other components.
This extra multiplicative factor gives the upper bound 
$|N'_{i+1}-N_{i+1}|\leq\sqrt{3}\de$, similarly for all other atoms.
\end{proof}

A Lipschitz constant $\mu$ plays no significant role because any metric on invariant values can be divided by $\mu$, which makes this constant 1.  
The second part of Theorem~\ref{thm:inverse} offers a smarter adjustment of $\bri(S)$ to the modified invariant $\widehat{\bri}(S)$ depending on a row index of $\bri(S)$ to guarantee the smaller Lipschitz constant $\sqrt{3}$.

