\section{Theoretical considerations}%
\label{sec:theorConsiderations}

In this section, we consider theoretical implications of the
\soQuadbt{} framework including the preservation of asymptotic stability and
the error between the data-driven terms and their intrusive counterparts.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Stability preservation}%
\label{sec:stability}

For the present discussion, we allow the matrices in~\cref{eqn:soSys} to be
complex valued.
In the intrusive setting, \sopvBt{} preserves asymptotic stability when the
underlying full-order model~\cref{eqn:soSys} is \emph{Hermitian}, i.e.,
\begin{equation} \label{eqn:soSymmReal}
  \BM = \BM^{\herm}, \quad
  \BD = \BD^{\herm}, \quad
  \BK = \BK^{\herm}, \quad
  \BBu = \BCp^{\herm} \quad\text{and}\quad
  \BCv = \Bzero,
\end{equation}
and the system matrices $\BM, \BD, \BK$ are Hermitian positive definite
(\HPD{}).
Obviously, a special case of~\cref{eqn:soSymmReal} is the
system~\cref{eqn:soSys} being state-space symmetric when the corresponding
matrices are real valued.
Interestingly, \soQuadbt{} will preserve asymptotic stability if the data are
generated by a Rayleigh-damped system that is Hermitian with \HPD{} mass,
damping and stiffness matrices, and if the left and right quadrature
nodes---those used to implicitly approximate $\BQv$ and $\BPp$,
respectively---are complex conjugate pairs of each other, i.e.,
$\i \zeta_{i} = \i s_{i}$ and $\i \vartheta_{i} = -\i s_{i}$.
If the $s_{i}$'s are not all strictly positive or negative, then at least some
of the nodes will be equivalent, i.e.,
$\zeta_{j} = s_{j} = - s_{k} = \vartheta_{k}$ for some $j, k$, which is not
allowed under~\Cref{thm:sobtFromData}.
To prove the stability result, we first derive formulae for the data
matrices~\cref{eqn:soDataMatrices} in this special case when the quadrature
nodes underlying the approximations to $\BQv$ and $\BPp$ come in complex
conjugate pairs and may overlap, with $\BCv = \Bzero$. 

\begin{theorem} \label{thm:sobtFromData_Hermite} \allowdisplaybreaks
  Let the functions $d \colon \C \to \C$, $n \colon \C \to \C$ and
  $h \colon \C \to \C$ be defined as in~\cref{eqn:auxFunctions}.
  Suppose the left and right quadrature rules
  in~\cref{eqn:soQuadContFactor,eqn:soQuadObsvFactor} are complex conjugate
  pairs, i.e., $\zeta_{i} = s_{i}$, $\vartheta_{i} = -s_{i}$ and
  $\eta_{i} = \varrho_{i} = \vartheta_{i}$ for $i = 1, \ldots, N$ and
  $N = J = K$, and the quadrature rules are such that $d(\i s_i)\neq 0$ and $\Bvarphi(\i s_{j})$ is nonsingular for all $i = 1, \ldots, N$.
  Let the quadrature-based factors $\BRcheckp$ and $\BLcheckv$ be given as
  in~\cref{eqn:soQuadContFactor,eqn:soQuadObsvFactor} and let the matrices
  $\bbLM, \bbLK \in \C^{pK \times mJ}$, $\bbBu\in\C^{pK \times m}$ and $\bbCp\in\C^{p \times mJ}$ be as in~\cref{eqn:soDataMatrices}.
  Then, the matrices $\bbLM$, $\bbLK$, $\bbBu$ and $\bbCp$ are given
  block-entrywise by
  \begin{subequations} \label{eqn:dataFormulas_Hermite}
  \begin{align}
    \label{eqn:MfromData_Hermite}
    \bbLM_{\Bk, \Bj} & =
      \begin{cases}
        \displaystyle -\frac{\eta_{k} \eta_{j}}{d(\i s_{j})^2}
          \frac{\ds}{\ds s} \Big( d(s) \BG(s) \Big) \bigg|_{s = \i s_{j}}
          \left( \frac{\ds}{\ds s} h(s) \bigg|_{s = \i s_{j}} \right)^{-1} &
          \text{if} \quad \i s_{j} = -\i s_{k}, \\[5mm]
        \displaystyle -\frac{\eta_{k} \eta_{j}}{d(-\i s_{k}) d(\i s_{j})}
          \frac{d(-\i s_{k})\BG(-\i s_{k}) - d(\i s_{j}) \BG(\i s_{j})}%
          {h(-\i s_{k}) - h(\i s_{j})} & \text{if} \quad \i s_{j} \neq -\i s_{k},
      \end{cases}\\[2ex]
    \label{eqn:KfromData_Hermite}
    \bbLK_{\Bk, \Bj} & =
      \begin{cases}
        \displaystyle \frac{\eta_{k} \eta_{j}}{d(\i s_{j})^2}
          \frac{\ds}{\ds s} \Big( n(s) \BG(s) \Big) \bigg|_{s = \i s_{j}} 
          \left( \frac{\ds}{\ds s} h(s) \bigg|_{s = \i s_{j}} \right)^{-1} &
          \text{if} \quad \i s_{j} = -\i s_{k}, \\[5mm]
    \displaystyle \frac{\eta_{k} \eta_{j}}{d(-\i s_{k}) d(\i s_{j})}
      \frac{n(-\i s_{k}) \BG(-\i s_{k}) - n(\i s_{j}) \BG(\i s_{j})}%
      {h(-\i s_{k}) - h(\i s_{j})} & \text{if} \quad \i s_{j} \neq -\i s_{k},
      \end{cases}\\[2ex]
    \label{eqn:BCpCvfromData_Hermite}
    \big( \bbBu \big)_{\Bk, :} & = \eta \BG(-\i s_{k})
    \quad\text{and}\quad
    \big( \bbCp \big)_{:, \Bj} = \eta \BG(\i s_{j}),
  \end{align}
  \end{subequations}
  where $\BG$ is the second-order transfer function~\cref{eqn:soTf}.
\end{theorem}
\begin{proof}  \allowdisplaybreaks
  The claims in~\cref{eqn:BCpCvfromData_Hermite}, as well
  as~\cref{eqn:MfromData_Hermite,eqn:KfromData_Hermite} for the case of
  $\i s_{j} \neq -\i s_{k}$ follow directly from \Cref{thm:sobtFromData} under the stated
  assumptions since $\zeta_{j} = s_{j}$ and $\vartheta_{k} = -s_{k}$.
  To prove~\cref{eqn:MfromData_Hermite} in the $\i s_{j} = -\i s_{k}$ case, we observe that
  \begin{equation*}
    \bbLM_{\Bk, \Bj} = \BI_{k, p}^{\trans} \left( \BLcheckv^{\herm}
      \BM \BRcheckp \right) \BI_{j, m} =
      \eta_{k} \eta_{j} \BCp \Bvarphi(\i s_{j})^{-1} \BM \Bvarphi(\i s_{j})^{-1} \BBu
  \end{equation*}
  holds.
  Let $\varepsilon > 0$; using the same logic as in the proof of
  \Cref{thm:sobtFromData}, we have that
  \begin{align*}
    & \BCp \Bvarphi(\i s_{j})^{-1} \BM \Bvarphi(\i s_{j})^{-1} \BBu \\
    & = \lim\limits_{\varepsilon \to 0} \BCp
      \Bvarphi \big( \i (s_{j} + \varepsilon) \big)^{-1} \BM
      \Bvarphi(\i s_{j})^{-1} \\
    & = -\lim\limits_{\varepsilon \to 0}
      \frac{1}{d \big(\i (s_{j} + \varepsilon) \big) d(\i s_{j})}
      \frac{d \big( \i(s_{j} + \varepsilon) \big) \BG
      \big( \i (s_{j} + \varepsilon) \big) - d(\i s_{j}) \BG(\i s_{j})}%
      {h \big(\i (s_{j} + \varepsilon) \big) - h(\i s_{j})} \\
    & = -\frac{1}{d(\i s_{j})^{2}} \lim\limits_{\varepsilon \to 0}
      \frac{d \big( \i(s_{j} + \varepsilon) \big) \BG
      \big(\i (s_{j} + \varepsilon) \big) - d(\i s_{j}) \BG(\i s_{j})}%
      {\i (s_{j} + \varepsilon) - \i s_{j}}
      \frac{\i (s_{j} + \varepsilon) - \i s_{j}}%
      {h \big(\i (s_{j} +\varepsilon) \big) - h(\i s_{j})}\\
    & = -\frac{1}{d(\i s_{j})^{2}} \frac{\ds}{\ds s}
      \Big( d(s) \BG(s) \Big) \bigg|_{s = \i s_{j}}
      \left( \frac{\ds}{\ds s} h(s) \bigg|_{s = \i s_{j}} \right)^{-1},
  \end{align*}
  by the limit definition of the derivative.
  This proves~\cref{eqn:MfromData_Hermite} when $\i s_{j} = -\i s_{k}$ by
  multiplication with $\eta_{k} \eta_{j}$.
  Using the same arguments, the other remaining
  formula~\cref{eqn:KfromData_Hermite} can be shown for $\i s_{j} = -\i s_{k}$, which
  concludes the proof.
\end{proof}

\Cref{alg:soQuadBT} can be used with the setup and assumptions outlined in
\Cref{thm:sobtFromData_Hermite} to compute reduced-order models via \soQuadbt{}.
The substantial difference to using \Cref{thm:sobtFromData} is that
the data matrices in~\cref{eqn:soDataMatrices} are constructed according to the
formulae in~\cref{eqn:dataFormulas_Hermite} instead of~\cref{eqn:dataFormulas}. 
In this case, the matrices in~\cref{eqn:soDataMatrices} may require information
about the derivative of $\BG$ in the off-diagonal entries if the chosen
quadrature nodes are such that $\i s_{j} = -\i s_{k}$.
This will indeed be the case for the realification procedure that we describe
in \Cref{sec:realmodel}.

Suppose the assumptions of \Cref{thm:sobtFromData_Hermite} are satisfied and
that the transfer function data $\BG(\i s_{j})$ are generated by a Hermitian
system~\cref{eqn:soSymmReal} with \HPD{} mass, damping and stiffness matrices. 
Because the underlying system is Hermitian, it follows that the
quadrature-based factors~\cref{eqn:soQuadContFactor,eqn:soQuadObsvFactor}
satisfy $\BRcheckp = \BLcheckv$ since $\i \zeta_{j} = \i s_{j}$ and
$\i \vartheta_{k} = -\i s_{k}$.
Thus, the matrices $\bbLM$ and $\bbLK$ constructed according to
\Cref{thm:sobtFromData_Hermite} satisfy
\begin{equation*}
  \bbLM = \BRcheckp^{\herm}\BM\BRcheckp = \bbLM^{\herm} \quad\text{and}\quad
  \bbLK = \BRcheckp^{\herm}\BK\BRcheckp = \bbLK^{\herm}
\end{equation*}
by the property~\cref{eqn:soSymmReal} of the underlying system.
Moreover, $\bbBu = \bbCp^{\herm}$ holds by construction.
We claim that a reduced-order model~\cref{eqn:soSysRed} computed via
\Cref{alg:soQuadBT} using these Hermitian data matrices has a similar symmetry
structure as the original underlying system with \HPD{} mass, damping and
stiffness matrices.
Obviously $\BMr = \BI_r$ is \HPD{} by construction.
Because $\bbLM$ is Hermitian, its singular value decomposition is so that the
singular vectors satisfy $\BUcheck = \BYcheck$. 
Then, for any $\Bz\in\C^{Nm}$, it holds that
\begin{equation*}
  \Bz^{\herm} \BKr \Bz = \Bz^{\herm}\BSigmacheck_{1}^{-1/2} \BUcheck_{1}^{\herm}
    \bbLK \BUcheck_{1} \BSigmacheck_{1}^{-1/2} \Bz =
    \Bw^{\herm} \BK \Bw > 0,
\end{equation*}
with $\Bw = \BRcheckp \BUcheck_{1} \BSigmacheck_{1}^{-1/2} \Bz$, and the fact that
$\Bw^{\herm} \BK \Bw > 0$ follows from the assumption that $\BK$ is \HPD{}.
Therefore, we have that $\BKr$ is \HPD{}.
Finally, if the system is Rayleigh damped, then trivially $\BDr$ is \HPD{}
because it is a nonnegative linear combination of two \HPD{} matrices and
$\alpha, \beta \geq 0$ by assumption.
Because Hermitian second-order systems~\cref{eqn:soSys} with positive definite
mass, damping, and stiffness matrices are asymptotically stable,
this argument directly implies the following stability result.

\begin{theorem} \label{thm:stability}
  Assume the system $\Sys$ in~\cref{eqn:soSys} used to generate the data
  $\BG(\i s_j)$ is Hermitian~\cref{eqn:soSymmReal} with positive definite mass,
  damping and stiffness matrices, assume that $\Sys$ has Rayleigh
  damping~\cref{eqn:Rayleigh}, and assume that the data $\BG(\i s_j)$
  satisfy the assumptions of \Cref{thm:sobtFromData_Hermite}.
  Then, the reduced-order system computed by \soQuadbt{} using the data
  matrices from \Cref{thm:sobtFromData_Hermite} is asymptotically stable. 
\end{theorem}

\Cref{thm:stability} may also be used conversely to check the assumptions
placed on the underlying system that provides the data.
If a reduced-order model~\cref{eqn:soSysRed} is computed by \Cref{alg:soQuadBT}
using the data matrices~\cref{eqn:dataFormulas_Hermite} is not asymptotically
stable, then the transfer function data $\BG(\i s_{j})$ were not generated by a
symmetric system with \HPD{} mass, damping and stiffness matrices.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Error control}%
\label{sec:error}

The result~\cite[Prop.~3.2]{GosGB22} provides error control on the data
matrices that appear in \foQuadbt{} in terms of their intrusive counterparts. 
By recognizing that the proof of~\cite[Prop.~3.2]{GosGB22} makes no assumption
on the underlying system structure, this result can be extended directly to our
setting to derive error bounds on the matrices in \Cref{thm:sobtFromData}.

\begin{theorem} \label{thm:error} \allowdisplaybreaks
  Assume that the quadrature rules used to
  derive~\cref{eqn:soQuadContFactor,eqn:soQuadObsvFactor} are such that the
  quadrature-based approximations to $\BPp$ and $\BQv$ satisfy
  \begin{equation} \label{eqn:quadControl}
    \lVert \BPp - \BRcheckp \BRcheckp^{\herm} \rVert_{\frob} \leq
      \frac{\delta}{1 + \delta} \sigma_{\min} \left( \BPp \right)
    \quad\text{and}\quad
    \lVert \BQv - \BLcheckv \BLcheckv^{\herm} \rVert_{\frob} \leq
      \frac{\delta}{1 + \delta} \sigma_{\min} \left( \BQv \right),
  \end{equation}
  for some $\delta \in (0, 1)$, where $\sigma_{\min}(\cdot)$ denotes the minimum
  singular value of a matrix.
  Then, there exist partial isometries $\leftIso \in \C^{pK \times n}$ and
  $\rightIso \in \C^{mJ \times n}$ so that
  \begin{subequations} \label{eqn:romBounds}
  \begin{align}
    \lVert \BLcheckv^{\herm} \BM \BRcheckp - \leftIso \big( \BLv^{\herm}
      \BM \BRp \big) \rightIso^{\herm} \rVert_{\frob} & \leq 2 \delta
      \lVert \BLv \rVert_{2} \lVert \BM \rVert_{2} \lVert \BRp \rVert_{2}, \\
    \lVert \BLcheckv^{\herm} \BK \BRcheckp - \leftIso \big( \BLv^{\herm}
      \BK \BRp \big) \rightIso^{\herm} \rVert_{\frob} & \leq 2 \delta
      \lVert \BLv \rVert_{2} \lVert \BK \rVert_{2} \lVert \BRp \rVert_{2}, \\
    \lVert \BLcheckv^{\herm} \BB - \leftIso \big( \BLv^{\herm} \BB \big)
      \rVert_{\frob} & \leq 2 \delta \lVert \BLv \rVert_{2}
      \lVert \BB \rVert_{2}, \\
    \lVert \BCp \BRcheckp - \big( \BCp \BRp \big) \rightIso^{\herm}
      \rVert_{\frob} & \leq 2 \delta \lVert \BCp \rVert_{2}
      \lVert \BRp \rVert_{2}, \\
    \lVert \BCv \BRcheckp - \big( \BCv \BRp \big) \rightIso^{\herm}
      \rVert_{\frob} & \leq 2 \delta \lVert \BCv \rVert_{2}
      \lVert \BRp \rVert_{2}.
  \end{align}
  \end{subequations}
\end{theorem}
\begin{proof}
  The result follows by carefully following the proof
  of~\cite[Prop.~3.2]{GosGB22} in the context of \Cref{thm:sobtFromData}.
\end{proof}

In general, \Cref{thm:error} can be applied to any low-rank implementation of
\sopvBt{} for which the approximate factors satisfy~\cref{eqn:quadControl}.
For our setting, this allows us to control the error in the reduced-order model
matrices via the error in the corresponding quadrature rules. 
Thus, for a sufficiently fine resolved quadrature rule, one can recover nearly
exact \sopvBt{}-based reduced-order models solely from data. 


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% PRACTICE PART.                                                               %
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\section{Practical considerations}%
\label{sec:pracConsiderations}

In this section, we discuss practical considerations for the implementation of
\Cref{alg:soQuadBT}.
First, we provide formulas for the \soQuadbt{} method to construct real-valued
reduced-order models, and then we discuss how to infer suitable damping
parameters for the proportional damping model from data.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Enforcing real-valued models from complex-valued data}%
\label{sec:realmodel}

In the context of systems used in  time-domain simulations, the underlying
system~\cref{eqn:soSys} is typically presumed to be real in the sense that the
inputs, state variables, and outputs evolve in a real-dimensional vector space. 
Thus, there exists a state-space realization of~\cref{eqn:soSys} given by
\emph{real-valued} matrices $\BM$, $\BD$, $\BK$, $\BBu$, $\BCp$ and $\BCv$. 
When such a real system generates the transfer function data used in
\Cref{alg:soQuadBT}, it is possible to modify \soQuadbt{} to produce a
real-valued realization of the reduced-order model.
In the subsequent discussion, we describe how to achieve the construction of
such real-valued realizations.
To this end, we require that the frequency-dependent damping coefficients $f$
and $g$ in~\cref{eqn:dampingModel} to satisfy
\begin{subequations} \label{eqn:conjAssumption}
\begin{align}
  \overline{f(s)} & = f(\overline{s}), \quad
  \overline{g(s)} = g(\overline{s}) 
  \quad\text{so that}\quad \\
  \overline{n(s)} & = n(\overline{s}), \quad
  \overline{d(s)} = d(\overline{s}), \quad
  \overline{h(s)} = h(\overline{s}),
\end{align}
\end{subequations}
for all $s\in \C$, where $n$, $d$ and $h$ are defined as
in~\cref{eqn:auxFunctions}. 
The assumption~\cref{eqn:conjAssumption} is trivially satisfied for Rayleigh
damping~\cref{eqn:Rayleigh} because $\alpha, \beta \in \R$, and notably
not satisfied for structural damping~\cref{eqn:structural} because
$\overline{g(s)} = -\i \tfrac{\overline{\eta}}{\overline{s}} \neq \i
\tfrac{\overline{\eta}}{\overline{s}} = g(\overline{s})$.
Although this is expected; indeed, a structurally-damped system can always be
expressed by a realization with zero damping and complex-valued stiffness
$\left(1 + \i \eta \right) \BK$.

For simplicity of presentation, we assume that both quadrature rules use an
equal number of nodes, $N = J = K$, and that $\BCv = \Bzero$;
the construction that we describe in the following also applies to the general case.
Suppose that a \emph{symmetric} quadrature rule is used to generate the
approximate factors~\cref{eqn:soQuadContFactor,eqn:soQuadObsvFactor}, i.e.,
the nodes are symmetrically distributed according to
\begin{subequations} \label{eqn:symmNodes}
\begin{align}
  \vartheta_{1} & < \vartheta_{3} < \ldots < \vartheta_{N - 1} < 0 <
    \vartheta_{2} < \vartheta_{4} < \ldots < \vartheta_{N}, \\
  \zeta_{1} & < \zeta_{3} < \ldots < \zeta_{N-1} < 0 <
    \zeta_{2} < \zeta_{4} < \ldots < \zeta_{N},
\end{align}
\end{subequations}
and satisfy $\vartheta_{i} = -\vartheta_{i+1}$ and $\zeta_{i} = -\zeta_{i+1}$,
for $i = 1, 3, \ldots, N-1$.
We assume additionally that the corresponding quadrature weights are computed
such that $\varrho_{i} = \varrho_{i + 1}$ and $\varphi_{i} = \varphi_{i + 1}$
for all $i = 1, 3, \ldots, N-1$.
This symmetric ordering scheme ensures that the transfer function evaluations
at these nodes come in complex conjugate pairs, that is,
$\overline{\BG(\i \vartheta_i)}=\BG(\i\vartheta_{i + 1})$ and
$\overline{\BG(\i \zeta_{i})} = \BG(\i \zeta_{i + 1})$,
for $i = 1, 3\ldots, N - 1$.
From this conjugate symmetry and the assumption~\cref{eqn:conjAssumption}, the
$2p \times 2m$-block entries of $\bbLM$ corresponding to the nodes
$(\i\vartheta_{k}, -\i \vartheta_{k})$ and $(\i \zeta_{j}, -\i\zeta_{j})$
satisfy
\begin{align*}
  & \begin{bmatrix} \bbLM_{\Bk, \Bj} & \bbLM_{\Bk, \Bj + \Bone} \\
    \bbLM_{\Bk + \Bone, \Bj} & \bbLM_{\Bk + \Bone, \Bj + \Bone} \end{bmatrix} \\
  & = -\varphi_{k} \varrho_{j}
    \begin{bmatrix}
    \displaystyle
    \frac{d(\i \vartheta_{k}) \BG(\i \vartheta_{k}) -
    d(\i \zeta_{j}) \BG(\i \zeta_{j})}%
    {d(\i \vartheta_{k}) d(\i \zeta_{j}) \left( h(\i \vartheta_{k}) -
    h(\i \zeta_{j}) \right)} &
    %
    \displaystyle
    \frac{d(\i \vartheta_{k}) \BG(\i \vartheta_{k}) -
    \overline{d(\i \zeta_{j}) \BG(\i \zeta_{j})}}%
    {d(\i \vartheta_{k}) \overline{d(\i \zeta_{j})} \left( h(\i \vartheta_{k}) -
    \overline{h(\i \zeta_{j})} \right)} \\[3pt]
    %
    \displaystyle
    \frac{\overline{d(\i \vartheta_{k}) \BG(\i \vartheta_{k})} -
    d(\i \zeta_{j}) \BG(\i \zeta_{j})}%
    {\overline{d(\i \vartheta_{k})} d(\i \zeta_{j}) \left(
    \overline{h(\i \vartheta_{k})} - h(\i \zeta_{j}) \right)} & 
    %
    \displaystyle 
    \frac{\overline{d(\i \vartheta_{k})} \overline{\BG(\i \vartheta_{k})} -
    \overline{d(\i \zeta_{j})} \overline{\BG(\i \zeta_{j})}}%
    {\overline{d(\i \vartheta_{k})} \overline{d(\i \zeta_{j})}
    \left( \overline{h(\i \vartheta_{k})} - \overline{h(\i \zeta_{j})} \right)}
    \end{bmatrix},
\end{align*}
where $\Bk$ and $\Bk + \Bone$ refer to the indices $(k - 1) p + 1 : k p$ and
$k p + 1 : (k + 1) p$ and similarly for $\Bj$ and $\Bj + \Bone$.
From the above, we observe that
$\overline{\bbLM_{\Bk, \Bj}} = \bbLM_{\Bk + \Bone, \Bj + \Bone}$ and
$\overline{\bbLM_{\Bk, \Bj + \Bone}} = \bbLM_{\Bk + \Bone, \Bj}$.
Define the unitary matrix $\BJ_{\ell} \defeq \frac{1}{\sqrt{2}}
\begin{bmatrix} \BI_{\ell} & -\i \BI_{\ell} \\ \BI_{\ell} &  \hphantom{-}\i
\BI_{\ell} \end{bmatrix} \in \C^{2 \ell \times 2 \ell}$ for some positive
integer $\ell \in \N$.
One can readily verify that
\begin{equation*}
  \BJ_{p}^{\herm} \begin{bmatrix} \bbLM_{\Bk, \Bj} & \bbLM_{\Bk, \Bj + \Bone} \\
    \bbLM_{\Bk + \Bone, \Bj} & \bbLM_{\Bk + \Bone, \Bj + \Bone} \end{bmatrix}
    \BJ_{m} = \begin{bmatrix} \hphantom{-}\real(\bbLM_{\Bk, \Bj} +
    \bbLM_{\Bk, \Bj + \Bone}) & \imag(\bbLM_{\Bk, \Bj} -
    \bbLM_{\Bk, \Bj + \Bone}) \\ 
    -\imag(\bbLM_{\Bk, \Bj} + \bbLM_{\Bk, \Bj + \Bone}) &
    \real(\bbLM_{\Bk, \Bj} - \bbLM_{\Bk, \Bj + \Bone} ) \end{bmatrix},
\end{equation*}
which is real valued. 
Thus, the matrix $\bbLM$ in~\cref{eqn:MfromData} is unitarily equivalent to a
real-valued matrix $\widetilde{\bbLM} \defeq (\BI_{N/2} \otimes
\BJ_{p}^{\herm}) \bbLM (\BI_{N/2}\otimes \BJ_{m}) \in \R^{p K \times m J}$,
where $\otimes$ denotes the matrix Kronecker product~\cite[Chap.~12.3]{GolV13}.
Similarly, the matrices $\bbLK$, $\bbBu$ and $\bbCp$
in~\cref{eqn:KfromData,eqn:BCpCvfromData} are unitarily equivalent to
real-valued matrices as well.
Namely, one can verify that
\begin{equation*}
  \widetilde{\bbLK} \defeq (\BI_{N/2} \otimes \BJ_{p}^{\herm}) \bbLK
    (\BI_{N/2} \otimes \BJ_{m}),\quad
  \widetilde{\mathbb{B}}_{\inp} \defeq (\BI_{N/2} \otimes \BJ_{p}^{\herm}\big)
    \bbBu \quad\mbox{and}\quad
  \widetilde{\mathbb{C}}_{\pos} = \bbCp (\BI_{N/2} \otimes \BJ_{m})
\end{equation*}
are all real valued by construction.
Therefore, we may use these unitary transformations to obtain real-valued data
matrices in \Cref{alg:soQuadBT} and, consequently, a real-valued realizations
of the reduced-order models.
Lastly, we mention that this realification procedure can also be applied to
the second-order Hermite Loewner matrices derived in \Cref{thm:sobtFromData_Hermite}. 
If the underlying system is real valued and the data satisfy the hypotheses 
of~\Cref{thm:stability}, 
then this allows one to obtain a real-valued realization of an asymptotically stable system.
In this setting, it will be the case that $\zeta_{i+1} = s_{i+1} = - s_{i} = \vartheta_{i}$
and $\zeta_{i} = s_{i} = - s_{i+1} = \vartheta_{i+1}$
due to~\cref{eqn:symmNodes}, and so evaluations of the
derivative of $\BG$ will appear in the sub- and super-diagonals of $\bbLM$ and $\bbLK$.

