\subsection{Optimal choice of damping parameters}%
\label{ss:optDamping}

Thus far, we have assumed that the coefficient functions $f(s)$ and $g(s)$ in
the generalized proportional damping model~\cref{eqn:dampingModel} are given and
can be freely evaluated.
However, in a truly data-driven regime, these would be unknown. 
We discuss how these coefficients can be inferred from data in the simplified
cases of Rayleigh damping~\cref{eqn:Rayleigh} and
structural damping~\cref{eqn:structural};
this corresponds to inferring the parameters $\alpha, \beta \in \R$ or
$\eta \in \R$, respectively.
In either case, we assume the data $\Bg_{k} = \BG(s_{k})$ to be prescribed at a
fixed number of points $s_{k} \in \C$, for $k = 1, \ldots, N$; we do not assume
this data to have any particular structure other than that it is generated by
the true underlying system's transfer function $\BG$.
The reduced-order matrices are computed according to \Cref{alg:soQuadBT}, and
the goal is then to optimize the damping parameters in the \soQuadbt{} reduced
model to best fit the given data.
A similar idea has been employed in the previously mentioned second-order
Loewner framework~\cite{PonGB22}, as well as in the data-driven modeling of
time-delay systems~\cite{SchU16}.
In contrast to these works, we explicitly derive gradients of the relevant cost
function with respect to the damping parameters.

To streamline the subsequent presentation, we introduce the following notation
\begin{alignat*}{3}
  \BvarphiRayleigh & \colon \C \to \Cnn & \quad\text{with}\quad &&
    \BvarphiRayleigh(s, \alpha, \beta) & \defeq
    (s^{2} + s \alpha) \BMr + (1 + s\beta) \BKr, \\
  \BvarphiStruct & \colon \C \to \Cnn & \quad\text{with}\quad &&
    \BvarphiStruct(s, \eta) & \defeq s^{2} \BMr + (1 + \i \eta ) \BKr, \\
  \CC & \colon \C \to \Cpn & \quad\text{with} \quad &&
    \CC(s) & \defeq \BCpr + s\BCvr.
\end{alignat*}
Even though \soQuadbt{} constructs reduced models with $\BMr = \BI_{r}$, this
is not enforced in the subsequent results to make the presentation as general
as possible. 
Thus, the minimization procedure we describe can be applied to any data-driven
reduced model~\cref{eqn:soSysRed} with unknown damping parameters; e.g.,
it can be applied to those computed by the second-order Loewner
framework~\cite{PonGB22}.
For the Rayleigh damped case, the optimization problem is formulated as
\begin{align}
\begin{split}
\label{eqn:rayleighOpt}
  (\alphaStar, \betaStar) & = \argmin\limits_{(\alpha, \beta) \in \R^{2}}
    \sum\limits_{k = 1}^{N} \objRayleigh(\alpha, \beta), \quad\text{with}\\\objRayleigh(\alpha, \beta) & \defeq \left\lVert \Bg_{k} - \CC (s_{k})
    \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BBur \right\rVert_{\frob}^{2},
\end{split}
\end{align}
and for the structurally damped case, we have
\begin{equation} \label{eqn:structOpt}
  \etaStar = \argmin\limits_{\eta \in \R} \sum\limits_{k = 1}^{N}
    \objStruct(\eta), \quad\text{with}\quad
    \objStruct(\eta) \defeq \left\lVert \Bg_{k} -\CC (s_{k})
    \BvarphiStruct(s_{k}, \eta)^{-1} \BBur \right\rVert_{\frob}^{2}.
\end{equation}
The gradients of the objective functions~\cref{eqn:rayleighOpt,eqn:structOpt}
are presented below. 

\begin{theorem} \label{thm:grads} \allowdisplaybreaks
  Consider a reduced-order model of the form~\cref{eqn:soSysRed}.
  For the minimization problem~\cref{eqn:rayleighOpt}, the gradients with
  respect to the optimization parameters are
  \begin{subequations}
  \begin{align} \label{eqn:alphaDeriv}
    \frac{\partial}{\partial{\alpha}} \objRayleigh(\alpha, \beta) &
    = 2 \real \bigg( s_{k} \trace \bigg( \BMr \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BBur\Big(\Bg_{k} 
      \\ \nonumber
    & \quad{}-{}
      \CC(s_{k})
      \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BBur
      \Big)^{\herm} \CC(s_{k}) \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1}
      \bigg) \bigg), \\
    \label{eqn:betaDeriv}
    \frac{\partial}{\partial{\beta}} \objRayleigh(\alpha, \beta) &
      = 2 \real \bigg( s_{k} \trace \bigg( \BKr \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BBur \Big( \Bg_{k} 
      \\ \nonumber
    & \quad{}-{}
      \CC(s_{k})
      \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BBu
      \Big)^{\herm} \CC(s_{k}) \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1}
      \bigg) \bigg).
  \end{align}
  \end{subequations}
  For the minimization problem~\cref{eqn:structOpt}, the gradient is given by
  \begin{align} \label{eqn:etaDeriv}
  \frac{\partial}{\partial{\eta}} \objStruct(\eta) &
    = 2 \real \bigg( \trace \bigg( \BKr \BvarphiStruct(s_{k}, \eta)^{-1} \\ \nonumber
  & \quad{}\times{}
    \BBur \Big(\Bg_{k} - \CC(s_{k}) \BvarphiStruct(s_{k}, \eta)^{-1} \BBur
    \Big)^{\herm} \CC(s_{k}) \BvarphiStruct(s_{k}, \eta)^{-1} \bigg) \bigg).
  \end{align}
\end{theorem}
\begin{proof} \allowdisplaybreaks
  It suffices to show~\cref{eqn:betaDeriv} since the proofs
  of~\cref{eqn:alphaDeriv,eqn:etaDeriv} follow analogously.
  Define $\CE_{k} \defeq \Bg_{k} - \CC(s_{k}) \BvarphiRayleigh(s_{k}, \alpha,
  \beta)^{-1} \BBur \in \C^{p\times m}$ so that
  $\objRayleigh(\alpha, \beta) = \lVert \CE_{k} \rVert_{\frob}^{2} =
  \trace(\CE_{k}^{\herm} \CE_{k})$.
  Now, we consider an arbitrary perturbation $\pertBeta \in \R$, and expand
  the helper function $\BvarphiRayleigh(s_{k}, \alpha, \beta + \pertBeta)$ as
  \begin{align*}
    \BvarphiRayleigh(s_{k}, \alpha, \beta + \pertBeta) &
      = \Big( (s_{k}^{2} + s_{k} \alpha) \BMr +
      (1 + s_{k} \beta + s_{k} \pertBeta) \BKr \Big) \\
    & = \BvarphiRayleigh(s_{k}, \alpha, \beta) + s_{k} \pertBeta \BKr.
  \end{align*}
  By choosing $\pertBeta$ to be small enough such that
  $\lVert \BvarphiRayleigh(s_{k}, \alpha_{k}, \beta_{k}) s_{k} \pertBeta
  \BKr \rVert_{2} < 1$, we may expand
  $\BvarphiRayleigh(s_{k}, \alpha, \beta + \pertBeta)^{-1}$ as a Neumann series
  into
    \begin{align*}
      \BvarphiRayleigh(s_{k}, \alpha, \beta + \pertBeta)^{-1}
      & = \Big(\BvarphiRayleigh(s_{k}, \alpha, \beta) -
        (-s_{k} \pertBeta \BKr) \Big)^{-1} \\
      & = \sum\limits_{j = 0}^{\infty}
        \Big( \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1}
        (-s_{k} \pertBeta\BKr) \Big)^{j}
        \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \\
      & = \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} - s_{k} \pertBeta
        \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BKr
        \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} + \mathcal{O}(\lVert \pertBeta \rVert_{\frob}^{2}).
    \end{align*}
    Using this expression, the objective function can be written as
    \begin{align*}
      & \objRayleigh(\alpha, \beta +\pertBeta) \\
      & = \lVert \CE_{k} + s_{k} \pertBeta \CC(s_{k})
        \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BKr
        \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BBur \rVert_{\frob}^{2}
        + \mathcal{O}(\lVert \pertBeta \rVert_{\frob}^{2}) \\
      & = \trace(\CE_{k}^{\herm} \CE_{k}) + 2 \real \Big( s_{k} \trace \Big(
        \CE_{k}^{\herm} \CC(s_{k}) \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1}
        \BKr \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1} \BBur \Big) \Big) \pertBeta + \mathcal{O}(\lVert \pertBeta \rVert_{\frob}^{2})\\
      & = \objRayleigh(\alpha, \beta) + 2 \real \Big( s_{k} \trace \Big( \BKr
        \BvarphiRayleigh(s_{k}, \alpha,\beta)^{-1} \BBur \CE_{k}^{\herm}
        \CC(s_{k}) \BvarphiRayleigh(s_{k}, \alpha, \beta)^{-1}
        \Big) \Big) \pertBeta + \mathcal{O}(\lVert \pertBeta \rVert_{\frob}^{2}),
    \end{align*}
    which proves~\cref{eqn:betaDeriv}.
\end{proof}

In a setting where the damping coefficients are unknown, the gradients in
\Cref{thm:grads} can be used in any off-the-shelf optimization algorithm to
minimize the cost function~\cref{eqn:rayleighOpt} over possible values of
$\alpha$ and $\beta$ simultaneously if the system is Rayleigh damped,
or in the case of structural damping, to minimize~\cref{eqn:structOpt} over
$\eta$.
This minimization routine adds one additional step at the end of
\Cref{alg:soQuadBT}.
We emphasize that the reduced-order model matrices do not need to be recomputed
after the optimization step; the computed parameters are only used to form the
reduced-order damping term from the already computed mass and
stiffness matrices.


