\section{Preliminaries} % NOTATION ----------------------------------------------------------------------------------------------------
\label{Preliminaries}
This section introduces the fundamental concepts, notations, and definitions essential for understanding our proposed methodology.
\subsection{Markov Decision Process}
\label{sec:MDP}
  The proposed system considers an infinite-horizon discrete-time MDP, defined by the tuple ($\mathcal{X}$, $U$, $f$, $r$), with state space $\mathcal{X}$ and action space $U$ where $f(x_{t+1} \mid x_t,u_t)$ at time $t \in T$ denotes the stochastic transition dynamics from the current state $x_t \in \mathcal{X}$ to $x_{t+1} \in \mathcal{X}$ under a policy $\pi_\phi$ parameterized by $\phi$, from which actions $u_t$ are sampled $u_t\sim\pi_\phi(\cdot \mid x_t)$.

  Building upon the standard MDP framework, the notation is extended to accommodate \emph{goal-conditioned RL} \cite{liu2022gc_rlsurvey}. In this setting, a goal set $\mathcal{G} \subset \mathcal{X}$ is introduced, where each goal $g_t \in \mathcal{G}$ specifies a desired state that the agent aims to reach. Consequently, the reward function $r(x_t, g_t)$ and the policy $\pi_\phi(u_t \mid x_t, g_t)$ become dependent on the current goal $g_t$, allowing for more flexible and directed learning objectives.

The WM, denoted by $\tilde{f}_\xi$, is parameterized by $\xi$, and serves as an approximation of the true transition dynamics $f$. Specifically, the WM predicts the distribution of the next state $\tilde{x}_{t+1}$ given the current state $x_t$ and action $u_t$, i.e., $\tilde{f}_\xi(\tilde{x}_{t+1} \mid x_t, u_t) \approx f(x_{t+1} \mid x_t, u_t)$.

\subsection{Lyapunov Stability and Lie derivatives}

The Lie derivative $\textsf{L}_f V(x_t)$ measures the rate of change of a differentiable Lyapunov function $V: \mathcal{X} \rightarrow \mathbb{R}_{\geq 0}$ along the trajectories of the system dynamics $f$. In experiments, the Lie derivative are approximated using the WM as follows:
\begin{equation}
        \textsf{L}_{\tilde{f}}V(x_t) = \mathbb{E}_{\tilde{x}_{t+1}\sim \tilde{f}(\cdot\mid x_t,u_t)}[V(\tilde{x}_{t+1}) - V(x_t)]
\label{eq:Lie_derivative}
\end{equation}

Here, $\tilde{x}_{t+1}$ is the predicted next state generated by the WM. This approximation facilitates the computation of the Lie derivatives through sampled transitions from the replay buffer.

An investigation into the Lyapunov stability requires a formal definition of system stability around the goal point, which is given as:
% {\color{red}\bf B: Is this really correct? $ V$ should be positive, i.e., $ V(x)>0$ for all $ x\neq 0$, and you need to have a unique equilibrium ... }

\begin{definition}[$\epsilon$-stability]
    \label{def:stability}

    Consider a goal state $g_t \in \mathcal{G} \subset \mathcal{X}$. Define the region around $g_t$ as a ball $\mathcal{B}(g_t,\epsilon) = \{ x_t \in \mathcal{X} \mid ||x_t - g_t||_{\infty} < \epsilon \}$, where $\epsilon > 0$ denotes the radius of interest. A pair $(V, \pi_\phi)$, consisting of a Lyapunov function $V$ and a policy $\pi_\phi$, is said to be $\epsilon$-stable about $g_t$ if: (a) The Lie derivative satisfies $\textsf{L}_f V(x_t) < 0$ for all $x_t \in \mathcal{B}(g_t, \epsilon) \setminus \{g_t\}$ (b) $V(x_t) > 0$ for all $x_t \in \mathcal{B}(g_t, \epsilon) \setminus \{g_t\}$ (c) $V(g_t)=0$     
\end{definition}

% {\color{red} This condition ensures that the system's trajectories converge to the equilibrium point $g_t$ (see Equation \eqref{eq:Lie_derivative})}

% \end{definition}
% We define our NLF as an MLP parameterized by $\psi$. 
\begin{definition}[Lyapunov Risk] Consider the Lyapunov function, parameterized by $\psi$ for a controlled dynamic system. In order to quantify the extent to which the Lyapunov conditions are being violated, we define an objective function for the NLF based on the Lyapunov risk \cite{chang2019neural} as:

\begin{equation} 
    \label{eq:lyap_risk}
    J_V(\psi) = \mathbb{E}_{x_t,u_t \sim \pi_\phi(\cdot \mid x_t)} \bigg( -\bigg[ \max(0,\textsf{L}_{\tilde{f}}V_{\psi}(x_t)) + V^2_{\psi}(g_t) \bigg] \bigg)
\end{equation}

 The goal $g_t$ represents the equilibrium point. The $V^2_{\psi}(g_t)$ loss term encourages $V_{\psi}(g_t)=0$,  penalizing non-zero values at the goal state such that $g_t$ becomes the global minima. Secondly, the $\max(0,\textsf{L}_{\tilde{f}}V_{\psi}(x_t))$ term penalizes positive Lie derivatives. The positive definiteness of $V_\psi$ is enforced by designing the network architecture to output strictly positive values. This is achieved by taking the absolute value of the networks outputs and adding a small constant \cite{gaby2022lyapunov}. 
\end{definition}

Differentiating $J_V(\psi)$ with respect to the network parameters $\psi$ yields an unbiased estimator suitable for optimizing the NLF to better satisfy the Lyapunov conditions:

\begin{multline}
\label{eq:derivative_obj}
\nabla_{\psi} J_V(\psi) = \mathbb{E}_{x_t, u_t \sim \pi_\phi(\cdot \mid x_t)} \bigg( - \bigg[\\ \mathbf{1}(\textsf{L}_{\tilde{f}} V_{\psi}(x_t) > 0) \nabla_{\psi} (\textsf{L}_{\tilde{f}} V_{\psi}(x_t)) + 2 V_{\psi}(g_t) \nabla_{\psi} V_{\psi}(g_t) \bigg] \bigg)
\end{multline}

where $\mathbf{1}(\cdot)$ is the indicator function that equals 1 when $\textsf{L}_f V_\psi(x_t) > 0$ and 0 otherwise. This gradient facilitates the training of the NLF to minimize violations of the Lyapunov conditions.
\subsection{Probabilistic World Model}% PROBABALISTIC WM ----------------------------------------------------------------------------------------------------------------------
% See williams and Rasmussan 1996 and  https://proceedings.neurips.cc/paper_files/paper/2003/file/7993e11204b215b27694b6f139e34ce8-Paper.pdf
% !!Simplify like this paper: https://arxiv.org/pdf/2309.05582
WM's enable RL agents to anticipate and manage the inherent uncertainties of their environments. In this work, the WM learns a probability distribution over possible subsequent future states which we utilize for resampling off-policy transitions to calculate on-policy Lie derivatives (Equation ~\eqref{eq:Lie_derivative}). Thereby, reducing the variance in NLF training caused by the dynamics $f(x_{t+1} \mid x_t,u_t)$ depending on the current behavior policy $\pi_\phi$ and not the previous policies used to collect training data. The WM enhances the proposed approaches NLF approximation accuracy and provides valuable uncertainty estimates, which are crucial for robust decision-making under stochasticity, exemplified in Section \ref{sec:stab-analysis}. 

 The WM learns from transition data in the form of $\mathcal{D}=\{(x_t,u_t),x_{t+1}\}^T_{t=0}$ and is updated through minimizing the negative log likelihood loss function: 
\begin{equation}
     \mathrm{Loss}_\xi(x_t)=-\sum^T_{t=1}\log\tilde{f}_{\xi}(\Tilde{x}_{t+1} \mid x_t,u_t)
\end{equation}

The WM conditioned on $x_t$ and $u_t$, outputs a Gaussian distribution with a mean $\mu_\xi(x_t, u_t)$ and diagonal covariance matrix $\sigma_\xi(x_t, u_t)$. This implies that each element of $x_t$ is modeled independently and is uncorrelated with the rest of the state information. Such an assumption is commonly made in probabilistic models to simplify the modeling process \cite{chua2018PATS}.

\begin{equation}
    \tilde{f}_\xi(\tilde{x}_{t+1} \mid x_t, u_t) = \prod_{i=1}^n \mathcal{N}(\tilde{x}_{t+1,i}; \mu_{\xi,i}(x_t, u_t), \sigma^2_{\xi,i}(x_t, u_t))
    \label{eq:prob_dist_diag}
\end{equation}

Therefore, the loss is:
\begin{multline}
\label{eq:loss} % Not sure where to put the \\ here
\mathrm{Loss}_{\xi}(x_t) = \sum_{t=1}^T \left[ (\mu_{\xi}(x_t, u_t) - x_{t+1})^T \sigma^{-1}_{\xi}(x_t, u_t) \right. \\
\left. (\mu_{\xi}(x_t, u_t) - x_{t+1}) + \log \det \sigma_{\xi}(x_t, u_t) \right].
\end{multline}

\section{Policy Optimization and Lyapunov Approximation}
% Should be last section I write since it's dependant on results

In standard RL, the policy $\pi_\phi$ aims to maximize the expected $\gamma$-discounted cumulative return:
\begin{equation}
    \label{eq:classic-rl}
    J(\pi_\phi)=\mathbb{E}_{\pi_\phi, f}[\sum^\infty_{t=0}\gamma^tr(x_t,u_t)]
\end{equation} 


This typical RL objective aims to maximize task-specific rewards, often without considering the system's stability. To promote system stability, we modify the policy objective by adding a regularization term that encourages exploration in regions where the Lyapunov function is poorly defined, thereby incentivizing exploration in unstable regions.

\begin{equation}
    \label{eq:mixed_obj}
    J(\pi_\phi) = \mathbb{E}_{\pi_\phi, f} \left[ \sum_{t=0}^{\infty} \left( (1 - \beta) \gamma^t r(x_t, g_t) + \beta \cdot \mathrm{Loss}_\psi(x_t) \right) \right]
\end{equation}

Here, $\beta \in [0,1]$ is a hyperparameter that balances the trade-off between reward and Lyapunov risk. In practice (See Figure \ref{fig:ip_grid}) we find $\beta=0.5$ to be work best. The Lyapunov loss, given as $\text{Loss}_\psi(x_t)$, is defined as:

\begin{equation}
    \mathrm{Loss}_{\psi}(x_t) = \max(0,\textsf{L}_{\tilde{f}}V_{\psi}(x_t)) + V^2_{\psi}(g_t) 
\end{equation}

This objective, is used by our Soft Actor-Critic Lyapunov Approximation (SACLA) method and incentivizes the agent to explore regions where the Lyapunov function is poorly defined, thereby enhancing the robustness and stability of the learned NLF.

We implement the SACLA algorithm, which leverages the Soft Actor-Critic (SAC) framework \cite{haarnoja2018soft} for online data generation and NLF learning. The algorithm integrates the following components:

\begin{itemize}
    \item \textbf{Policy Update:} Optimizes the policy $\pi_\phi$ to maximize the combined objective of reward and Lyapunov loss.
    \item \textbf{NLF Update:} Minimizes the Lyapunov risk $J_V(\psi)$ to improve the accuracy of the Lyapunov function.
    \item \textbf{WM Update:} Trains the WM $\tilde{f}_\xi$ to better predict state transitions, thereby reducing variance in Lie derivative estimates.
\end{itemize}

The detailed algorithm is presented in Algorithm \ref{alg:algorithm}.

\begin{algorithm}
\caption{Soft Actor-Critic Lyapunov Approximation}
\label{alg:algorithm}
\begin{algorithmic}
\LeftComment{Initial parameters}
\State \textbf{Input:} $\psi, \theta_1, \theta_2, \phi, \xi$ 
\begin{algorithmic}[1]

\State $\bar{\theta}_1 \leftarrow \theta_1, \bar{\theta}_2 \leftarrow \theta_2$ \LeftComment{Initialize target network weights}
\State $\mathcal{D} \leftarrow \emptyset$ \LeftComment{Initialize an empty replay pool}
\For{\texttt{each iteration}}
    \For{\texttt{each environment step}}
        \LeftComment{Sample action from the policy}
        \State $u_t \sim \pi_\phi(u_t \mid x_t)$ 
        \LeftComment{Sample transition from the environment}
        \State $x_{t+1} \sim f(x_{t+1} \mid x_t, u_t)$ 
        \LeftComment{Store the transition in the replay pool}
        \State $\mathcal{D} \leftarrow \mathcal{D} \cup \{(x_t, u_t, r(x_t, u_t), x_{t+1})\}$ 
    \EndFor
    \For{\texttt{each gradient step}}
    \LeftComment{Update NLF parameters using Equation \eqref{eq:derivative_obj}}
        \State $\psi \leftarrow \psi_V - \psi_V \hat{\nabla}_\psi J_V(\psi)$ 
        % \State $\xi \leftarrow \xi_f - \hat{\nabla}_\xi \arg\min_{\xi} \mathbb{E}_{\mathcal{D}}[-\log f_{\xi}(x_{t+1} |x_t, u_t)]$ \Comment{Update WM parameters}
        \LeftComment{Update WM parameters using Equation \eqref{eq:loss}}
        \State $\xi \leftarrow \xi - \lambda_\xi \nabla_\xi \mathrm{Loss}_{f_{\xi}}(\xi)$ 
        \LeftComment{Update the Q-function parameters}
        \State $\theta_i \leftarrow \theta_i - \lambda_Q \hat{\nabla}_{\theta_i} J_Q(\theta_i)$ for $i \in \{1, 2\}$ 
        \LeftComment{Update policy weights}
        \State $\phi \leftarrow \phi - \lambda_\pi \hat{\nabla}_\phi J_\pi(\phi)$ 
        \LeftComment{Adjust temperature}
        \State $\alpha \leftarrow \alpha - \lambda_\alpha \hat{\nabla}_\alpha J(\alpha)$ 
        \LeftComment{Update target network weights}
        \State $\bar{\theta}_i \leftarrow \tau \theta_i + (1 - \tau) \bar{\theta}_i$ for $i \in \{1, 2\}$ 
    \EndFor
\EndFor
\State \textbf{Output:} $\psi, \theta_1, \theta_2, \phi$
\end{algorithmic}
\end{algorithmic}
\end{algorithm}

