        \centering %lbtr
        \includegraphics[trim=60 40 30 60,clip,width=\textwidth]{images/wm_plot_3D_working_traj2.png}
        \caption{Side view}
        \label{fig:image1}
    \end{subfigure}
    \hfill
    \begin{subfigure}[b]{0.24 \textwidth}
        \centering
