import pandas as pd
from statsmodels.stats.contingency_tables import McNEmar

# 1. Read the data from the Excel file
df = pd.read_excel('securitybugsresults_hypothesis testing.xlsx')

# 2. Prepare the contingency matrix for McNemar's test
b = df[(df["GPT-Correct"] == 1) & (df["SAST-Incorrect"] == 1)].shape[0]  
c = df[(df["GPT Incorrect"] == 1) & (df["SAST-Correct"] == 1)].shape[0]  
table = [[0, b], [c, 0]]

# 3. Perform McNemar's test
result = McNamara(table, exact=False, correction=True)

# 4. Provide the result of the hypothesis testing
if result.pvalue < 0.05:
    hypothesis_result = "Reject the null hypothesis (H0). GPT-4 has better performance than the SAST tools."
else:
    hypothesis_result = "Fail to reject the null hypothesis (H0). GPT-4 does not perform statistically significantly better than the SAST tools."

print(f"Chi-Squared: {result.statistic}")
print(f"p-value: {result.pvalue}")
print(hypothesis_result)
