%%\| F_u(G_t,\Delta) \|_{[0, T]} := \sup_{\substack{\Delta \in IQC(\Psi, M)}} \norm{F_u(G_t, \Delta)}_{2[0, T]}
%\end{gathered}
%\end{equation}

The input/output behavior of $\Delta$ is bounded via time-domain IQCs.
Time-domain IQCs are defined by a filter $\Psi \in \RH^{n_z \times (n_v + n_w)}$ with input $[v^T, w^T]^T$ and output $z$, and a $n_z \times n_z$ real, symmetric matrix $M$, see, e.g., \cite{Seiler2015}. 
%The filter $\Psi$ and the matrix $M$ result from a (non-unique) factorization  $\Pi = \Psi^\sim M \Psi$ \cite{Scherer2004} of the classical frequency-domain IQC multipliers $\Pi$ proposed by Megretski and Rantzer \cite{Megretski1997}. Hence, $\Psi$ can be interpreted as a $D$-scale common in robust control literature\cite{Packard1993}.
The uncertainty $\Delta$ satisfies the time domain IQC defined by $M$ and $\Psi$ if the filter output $z$ fulfills $\int_0^T z(t)^T M z(t) \, dt \ge 0 $
%\begin{equation}
%    \label{eq:iqctd1}
%    \int_0^T z(t)^T M z(t) \, dt \ge 0
%\end{equation}
for all $v \in L_2[0,T]$, $w=\Delta(v)$ over the interval $[0,T]$ for zero initial conditions.
In this case, the short notation $\Delta \in IQC(\Psi,M)$ is used.
An example for feasible parameterization and factorization of a time-varying parametric uncertainty is given below.
\begin{ex}
  \label{ex1}
  Let $\mathcal{S}$ denote the set of nonlinear, time-varying,
  uncertainties with a given norm-bound $b$, i.e.
  $\Delta \in \mathcal{S}$ if
  $ \|\Delta\|_{2\rightarrow 2,[0,T]} \leq b$. If
  $\Delta \in \mathcal{S}$, then for any constant $\lambda\ge 0$ it
  satisfies the IQC defined by the static filter $\Psi =I_{n_v + n_w}$ and constant matrix:
  \begin{align*}
    M := \bsmtx b^2 \lambda \, I_{n_v} & 0\\0 & -\lambda \, I_{n_w}\esmtx	
  \end{align*}
\end{ex}

