\section{Problem Formulation}\label{sec:Problem}
\vspace{-10.5pt}
%
%\begin{itemize}
%	%\item Story comparable to IFAC paper
%	\item Nonlinear system along trajectory NOT LTV system
%	\item Linearization full including parameter $\rho_\Delta$
%	\item Controller is for the nonlinear system as we cover "all" effects% regler fuer das nichtlineare system da wir alle effekte it dabei haben
%	\item can be easily extended to include different types of uncertainties, non linearities, saturations or infinite dimensional systems such as time delays
%\end{itemize}
%


Consider a nonlinear system $\tilde{N}$ whose dynamics are defined by the nonlinear ordinary differential equations (ODEs)
\begin{equation}\label{eq:NonLin}
	\begin{split}
		\dot{x}(t) &= f(x(t), d(t), u(t),\rho(t)) \\
		e(t) &= h(x(t), d(t), u(t), \rho(t))\\
		y(t) &= g(x(t), d(t), u(t), \rho(t)).\\
	\end{split}
\end{equation}
% the vectors $x(t)\in \R^{n_x}$, $d(t)\in \R^{n_d}$, and $e(t)\in \R^{n_e}$ describe the state variable, the  input, and the output at time $t$, respectively. 
In (\ref{eq:NonLin}), the vector $\rho(t)\in \R^{n_\rho}$ denotes a time-varying parameter vector at time $t$. A pre-defined trajectory is defined as a unique solution of (\ref{eq:NonLin}) satisfying
\begin{equation}\label{eq:NonLinRef}
	\begin{split}
		\dot{x}_\mathcal{T}(t) &= f(x_\mathcal{T}(t), d_\mathcal{T}(t), u_\mathcal{T}(t), \rho_\mathcal{T}(t)) \\
		e_\mathcal{T}(t) &= h(x_\mathcal{T}(t), d_\mathcal{T}(t), u_\mathcal{T}(t), \rho_\mathcal{T}(t)) \\
y_\mathcal{T}(t) &= g(x_\mathcal{T}(t), d_\mathcal{T}(t), u_\mathcal{T}(t), \rho_\mathcal{T}(t)) \quad \forall t\in [0,T].
	\end{split}
\end{equation}
The subscript $\mathcal{T}$ will be used to denote a specific trajectory, $(x_\mathcal{T}, \, d_\mathcal{T}, \, u_\mathcal{T},\, \rho_\mathcal{T} )$ satisfying \eqref{eq:NonLinRef}. The objective of the paper is to design a controller $K$, which in feedback interconnection with the system $\tilde{N}$ (\ref{eq:NonLin}) satisfies given performance requirements along a prescribed trajectory over the finite time horizon $[0,T]$. The resulting closed loop system denoted by $\mathcal{F}_l(\tilde{N},K)$ shall be robust against perturbations in both the input signal $d_\Delta$ and parameter signal $\rho_\Delta$:
\begin{equation}
d_\Delta  := d -d_\mathcal{T}, \quad \rho_\Delta := \rho -\rho_\mathcal{T}.
\end{equation}
\vspace{-2.0pt}The parameter perturbation $\rho_\Delta$ is confined, at each point in time, to a set $\mathcal{P} \subseteq \R^{n_\rho}$.

