A user-defined amount of iterations $i_\text{max}$ is provided to the algorithm together with
the system $\hat{N}$ \eqref{eq:uLTVext}, with the additional input $u$ and output $y$. The uncertainty covering the parameter variation $\Delta:=\text{diag}(\rho_\Delta)$ is described by $\mathcal{S}$ with its input/output behavior bounded by the IQC in Example \ref{ex1}. Its norm bound is denoted $b_\rho$. Initial values of the scalings $M_{v}^{(0)}:=I_{n_v}$, $M_{w}^{(0)}:=I_{n_w}$, 
and $\gamma_\text{IQC}^{(0)}:= 1$ are also provided.

Each iteration starts with the construction of the scaled plant $N_\text{s}$, as described in section \ref{ss:RobSyn}.
For the first iteration $N_\text{s} = \hat{N}$ given the initialization choices.

The next step is a nominal finite horizon synthesis for the scaled plant $G_\text{s}$ under non-zero initial conditions. Here, the parameter variation $\rho_\Delta$ is treated as constant vector, with its entries chosen to the corresponding values of the uncertainty norm-bond $b_\rho$.
%Note that the synthesis accounts for the driving term, but does not cover any time-variation in the parameter perturbation.
Reference \cite{khargonekar1991h_} provides
necessary and sufficient conditions for the existence of a
$\gamma$-suboptimal controller for non-zero initial conditions. Theorem \ref{thm2} below is a special case of the results in \cite{khargonekar1991h_}.
%\textcolor{blue}{FB: do you think we need the theorem? I mean especially this one doesn't add much... it is basically just
%the one from [5] sin terminal penalty and in our notation (additional matrices, missing atm). However, a paper without theorems probably has a hard time to get through the review. If we add it I think I need to define the nonlinear system already with $u$ and $y$... otherwise it becomes untraceable}
\begin{mytheo} 
  \label{thm2}	 
  Consider an LTV system $\hat{N}$ \eqref{eq:uLTVext} with a fixed value of $\rho_\Delta$, and  $\gamma > 0$ given. Let $Q$ be a given positive definite diagonal matrix. Let $B$, $\hat{C}$, $\bar{R}$ and $\hat{R}$ be defined as follows.
  \begin{align*}
    \begin{split}
      \hat{A}&:= \bsmtx A \,\,&\,\, 0 \\ 0 \,\,&\,\, 0\esmtx \hspace{0.2in} \hat{B} := \bsmtx Eb_\rho & B_d  \esmtx  \\
      B&:= \bsmtx Eb_\rho & B_d & B_u\esmtx \hspace{0.2in} \bar{R}:=\text{diag}\{-\gamma^{2}I_{n_w+n_d}, I_{n_u}\}\\
      \hat{C}&:= \bsmtx 0 & C_e^T & C_y^T \\ 1^T & 0 & 0\esmtx^T \hspace{0.05in} \hat{R}:=\text{diag}\{-\gamma^{2}I_{n_v+n_e}, I_{n_y}\}
    \end{split}
  \end{align*}
  \begin{enumerate}		
  \item There exists an admissible output feedback controller $K$ such that $\|\mathcal{F}_l(\hat{N},K)\|_{2[0,T]}<\gamma$ if and only if the following three conditions hold:
    \begin{enumerate}			
    \item There exists a differentiable function
      $X:[0,T] \rightarrow \Sm^n$ such that $X(T) = 0$,	
      \begin{align*}
        \dot{X} + \hat{A}^{T}X + X\hat{A} - XB\bar{R}^{-1}B^TX + \hat{C}^T\hat{C} = 0
      \end{align*}
	and $X(0) < \gamma^2 Q$.
    \item There exists a differentiable function
      $Y:[0,T] \rightarrow \Sm^n$ such that $Y(0) = Q^{-1}$,		
      \begin{align*}
        -\dot{Y} + \hat{A}Y + Y\hat{A}^{T} - Y\hat{C}^T\hat{R}^{-1}\hat{C}Y + \hat{B}\hat{B}^T= 0
      \end{align*}
    \item $X(t)$ and $Y(t)$ satisfy the following point-wise in time spectral radius condition,
      \begin{equation}
        \label{ccond}
        \rho(X(t)Y(t))<\gamma^2 \text{, } \forall t \in [0,T]
      \end{equation}
    \end{enumerate}
  \item If the conditions above are met, then the closed loop performance
    $\|\mathcal{F}_l(\hat{N},K)\|_{[0,T]}<\gamma$ is achieved by the
    central controller constructed from $X$ and $Y$.
