\section{The Lagrangian Method}
\subsection{Algorithmic framework}
% (SD: Provide scope here)
 \begin{assumption}\label{asmp_oracle}
     Agents have access to an oracle that yields policies in the stationary NE of an unconstrained Markov game $\ccalG$. We use $NE(\ccalG)$ to represent the set of stationary NE policies for $\ccalG$.
 \end{assumption}
 We begin by stating that agents have a mechanism to access the stationary NE policies for a stochastic game that is unconstrained. Note that for a Markov game with finite number of actions and states, a stationary NE always exists. Methods such as value iteration, policy iteration and it's variants (such as natural policy gradient, actor-critic methods, etc.), and linear programming can be effective as methods for agents to compute/learn NE. Arguments related to time complexity of the various methods is not the current focus. Instead, given any approach to solve for NE for a unconstrained Markov game, we want to build on existing designs by satisfying system level constraints. 
 % (SD: Talk more about how to find NE, and that the scope of the paper is not to provide a new way to solve Markov unconstrained games, but to build on existing designs by accommodating system level constraints.)
Let us now define the important notion of the Lagrangian game. 
\begin{definition} (Lagrangian game) \label{def_lagrangainGame}
    Given the constrained Markov game $\ccalG$, the Lagrangian game $\ccalG(\lambda)$ is given by the tuple  $(\ccalS,\ccalN,\{\ccalA_i,r_i\}_{i\in \ccalN}, P, \{c_{j},b_j\}_{j=1}^{m}, \lambda)$, where $\lambda\in \mbR^{m}$ and the  value function $\ccalL_i: \Pi^{\tau} \times \mbR^{m}$ of agent $i\in \ccalN$ given by 
    \begin{align}
        \ccalL_i(\pi, \lambda):= V_i^{s}(\pi) + \lambda^{T}(U^{s}(\pi)-b). 
    \end{align}
\end{definition}
The algorithmic framework proceeds as follows.
Each episode of the repeated game play is divided into epochs of size $T_0$ time steps.
 Given constrained Markov game $\ccalG$, agents construct the Lagrangian game $\ccalG(\lambda_k)$ for epoch number $k \in \mbN_0$ (see algorithm \ref{alg:gamedyn}). 
 % Let $NE(\ccalG(\lambda_k)) \in \Pi$ represent the set of NE stochastic stationary policies for game $\ccalG(\lambda_k)$. 
 % Each epoch consists of repeated game play for $T_0$ time-steps.
 % \begin{assumption}\label{asmp_oracle}
 %     Agents have access to an Oracle that they use to solve an unconstrained Markov game to Nash Equilibrium.
 % \end{assumption}
 At epoch $k$, the agents access the oracle to solve $\ccalG(\lambda_k)$ and receive stationary NE policy $\pi^{k} \in NE(\ccalG(\lambda_k))$, following which they use $\pi^{k}$ to play the game $\ccalG(\lambda_k)$ (choose actions) for a horizon length of $T_0 \in \mbN$, the length of the epoch. Agents receive the roll-out rewards, which they use to construct $\lambda_{k+1}$ for the succeeding epoch as follows.
\begin{align} \label{eq_lambdaupdate}
    \lambda_{j,k+1}=\bigg[\lambda_{j,k}-\frac{\eta}{T_0}\sum_{t=kT_0}^{(k+1)T_{0}-1} (c_{j}(s^t,a^t)-b_j)\bigg]_{+}
\end{align}
for all $j\in [m]$. We refer to this as the dual descent update (see Algorithm \ref{alg:dualdes}). Here, $\lambda_k=(\lambda_{j,k})_{j\in [m]}$, and $\eta\in \mbR$ is the step-size of the update rule. At epoch $k+1$, agents construct Lagrangian game $\ccalG(\lambda_{k+1})$, and the process repeats itself. The successive updates to the Lagrange multiplier $\lambda_k$ lead to epoch dependent nonstationary policy $\pi^{\lambda} \in \Pi^{\tau}$, where $\pi^{\lambda}(s,t)=\pi^{k}(s)$ for $t\in [kT_0,(k+1)T_0)$, and all states $s\in \ccalS$. We shall abuse notation slightly to write $\pi^{\lambda}=\{\pi^{k}\}_{k\geq 0}$. The process is depicted in Algorithms \ref{alg:dualdes} and \ref{alg:gamedyn}.

% (SD: Fill in a detailed algorithm here)  
\begin{algorithm} 
\caption{Dual Descent}
\label{alg:dualdes}
\begin{algorithmic}[1] 

\Require Constrained Markov game $\ccalG$, $\pi^{k} \in NE(\ccalG(\lambda_k))$, $\lambda_k \in \mbR^{m}_{+}$, $s^{kT_0} \in \ccalS$, $T_0 \in \mbN$, $\eta \in \mbR_{+}$.

\Function{dual-des} {$\pi^{k},s^{kT_0},\lambda_k$}
\State \textbf{Rollout} $T_0$ steps with actions $a^t \sim \pi^{k}(s^t)$ for $t\in [kT_0, (k+1)T_0-1]$
\ForAll{$j\in [m]$}
    \State $\lambda_{j,k+1}\gets\bigg[\lambda_{j,k}-\frac{\eta}{T_0}\sum\limits_{t=kT_0}^{(k+1)T_{0}-1} (c_{j}(s^t,a^t)-b_j)\bigg]_{+}$ 
\EndFor
\State \textbf{return} $(\lambda_{k+1}, s^{(k+1)T_0})$

\EndFunction
\end{algorithmic}
\end{algorithm}

