\subsection{Main result and implications}
\noindent To make claims for this algorithmic framework, we shall need the following assumptions.
\begin{assumption} \label{asmp_superfeasible}
    (Slater condition) For each $\pi\in\Pi$ and any player $i\in \ccalN$, there exists a $\pi^{\dagger}_i\in \Pi_i$ such that $U(\pi^{\dagger}_i,\pi_{-i})> b$. 
\end{assumption}
% Thus whatever policies players use, player $i$ can find a policy to satisfy the constraints.
\begin{assumption} \label{asmp_boundedreward}
    (Bounded rewards) There exists $B$ such that $|c_{j}(s,a)-b_j|\leq B$ for all states $s\in \ccalS$, actions $a\in \ccalA$ and constraint $j\in [m]$. Moreover the reward functions $|r_{i}(s,a)|\leq R<\infty$ for all agents $i\in\ccalN$, for all states $s$ and actions $a$.
\end{assumption}
% This ensures that the value functions are always finite.
\begin{assumption} \label{asmp_unbiasedestimate}
    (Unbiased rollout) The accumulated reward that agents receive from the roll-out of stationary policy $\pi\in \Pi$ at any epoch $k$ is an unbiased estimate of $U_{j}(\pi)$, i.e.
    \begin{align}
        \mbE_{\pi} \left[ \frac{1}{T_0} \sum_{t=kT_0}^{(k+1)T_0-1} c_{j}(s^t,a^t)  \right] = U_{j}(\pi) 
        % \nonumber \\
        % =\lim_{T\rightarrow \infty}\frac{1}{T}\mbE \left[\sum_{t=0}^T c_{j}(s^t,a^t)\right].
    \end{align}
    for any constraint $j\in [m]$ and initial state. Similarly, we assume that 
    \begin{align}
        \mbE_{\pi} \left[ \frac{1}{T_0} \sum_{t=kT_0}^{(k+1)T_0-1} r_{i}(s^t,a^t)  \right] = V_i(\pi)
    \end{align}
    for all $i\in \ccalN$.
\end{assumption}
Assumption \ref{asmp_superfeasible} ensures that whatever policies other players use, a player $i\in \ccalN$ can find a policy to satisfy the constraints. This assumption is common in the constrained Markov game literature, see \cite{dufour2022stationary} for example.
Assumption \ref{asmp_boundedreward} ensures that the value functions are always finite.
In assumption \ref{asmp_unbiasedestimate}, we assume that the rollout reward at any epoch is an unbiased estimate of the value function under the executed policy at that epoch. This is a standard assumption in reinforcement learning, and we assume that $T_0$ is picked large enough for this assumption to be satisfied.
