\subsection{Proof of tightness}
In this section, we establish the tightness of the sequence of measures defined in \eqref{eq_lambdaupdate}, which forms the foundation for the results in the next subsections, which in turn enable Theorem \ref{thm_main}. 

\begin{definition}\label{def_gendual}
     We define the generalized dual $d_i: \mbR^{m}_{+} \times \Pi_{-i} \rightarrow \mbR$  for agent $i$ in constrained Markov game $\ccalG$ as follows
    \begin{align} \label{eq_dik1}
        d_i(\lambda,\pi_{-i})= \sup_{z_i \in \Pi_i} [V_i(z_i,\pi_{-i}) + \lambda^{T}(U(z_i,\pi_{-i})-b)]
    \end{align}
\end{definition}
The generalized dual represents the best that agent $i$ can achieve with respect to its Lagrangian value function, when the considered Lagrange multiplier is $\lambda\in\mbR^{m}_{+}$ and the policies of the other agents are fixed to the stationary policy $\pi_{-i}\in\Pi_{-i}$.
The two arguments for the generalized dual are the Lagrange multiplier and the stationary policy $\pi_{-i}$.

The following Lemma regarding generalized duals will be useful in establishing tightness. Variations of this result are often referred to as Danskin's Theorem in the literature. 

\begin{lemma} (Danskin's Theorem) \label{lem_danskin}
    For epoch $k$ in the execution of Algorithm \ref{alg:gamedyn}, with $\pi^k \in NE(\ccalG(\lambda_k))$ we have
    \begin{align}
        d_i(\lambda^{+},\pi^{k}_{-i})-d_i(\lambda_k,\pi^{k}_{-i}) \geq (\lambda^{+}-\lambda_k)^{T}(U(\pi^k)-b)\nonumber
    \end{align}
    where $\lambda^{+} \in \mbR^{m}_{+}$ is some reference Lagrange multiplier, and $i\in \ccalN$.
\end{lemma}
\begin{proof}
    At epoch $k$, agents other than $i\in \ccalN$ play policy $\pi^k_{-i}$. Define $L:\Pi_i\times \mbR^{m}_{+}\rightarrow \mbR$ as $L(z_i,\lambda)=V_i(z_i,\pi^{k}_{-i})+\lambda^{T}(U(z_i,\pi^{k}_{-i})-b)$. Then, using Def. \ref{def_gendual}, we have $d_i(\lambda,\pi^{k}_{-i})=\sup_{z_i \in \Pi_i} L(z_i,\lambda)$. Since $\pi^k\in NE(\ccalG(\lambda_k))$, $\pi^{k}_{i}$ lies in the best-response strategy set of agent $i$ against $\pi^{k}_{-i}$ for optimizing objective $L(\cdot,\lambda_k)$. Thus, 
    \begin{align}\label{eq_L1}        L(\pi^{k}_{i},\lambda_k)&=d_i(\lambda_k,\pi^{k}_{-i}) \nonumber \\
        \textrm{or, } d_i(\lambda^{+},\pi^{k}_{-i})&=d_i(\lambda^{+},\pi^{k}_{-i})+d_i(\lambda_k,\pi^{k}_{-i})-L(\pi^{k}_{i},\lambda_k)
    \end{align}
    where we add $d_i(\lambda^{+},\pi^{k}_{-i})$ to both sides on the second line in \eqref{eq_L1}. Also note that 
    \begin{align} \label{eq_L2}
        d_i(\lambda^{+},\pi^{k}_{-i}) \geq L(\pi^{k}_{i}, \lambda^{+})
    \end{align}
    as $\pi^{k}_i$ is a potentially suboptimal response for agent $i$ against objective $L(\cdot,\lambda^{+})$. As a result, plugging in \eqref{eq_L2} into \eqref{eq_L1}, we have,
    \begin{align}\label{eq_L3}
        d_i(\lambda^{+},\pi^{k}_{-i}) \geq L(\pi^k_{i},\lambda^{+}) + d_i(\lambda_k,\pi^{k}_{-i}) - L(\pi^k_{i},\lambda_k)
    \end{align}
    Then, rearranging terms and substituting for $L(\cdot,\cdot)$ we get the desired result.
\end{proof}

