\end{lemma}
\begin{proof}
    By Slater's conditions (assumption \ref{asmp_superfeasible}), there exists feasible  policy $\pi^{\dagger}_i$ with respect to $\pi^{k}_{-i}$, which leads to
    \begin{align}
        d_i(\lambda,\pi^{k}_{-i}) \geq V_i (\pi^{\dagger}_i,\pi^{k}_{-i}) + \lambda^{T} (U(\pi^{\dagger}_i,\pi^{k}_{-i})-b) 
    \end{align}
    This implies, using $U(\pi^{\dagger}_i,\pi^{k}_{-i})-b\geq C>0$,
    \begin{align}
       d_i(\lambda,\pi^{k}_{-i})-d_i(\lambda^{+},\pi^{k}_{-i}) \\ \nonumber \geq  V_i (\pi^{\dagger}_i,\pi^{k}_{-i})+ \lambda^{T}C - d_i(\lambda^{+},\pi^{k}_{-i})
    \end{align}
    Now, for all $\lambda\in \ccalD^{k}_{i}$, we have $d_i(\lambda,\pi^{k}_{-i})-d_i(\lambda^{+},\pi^{k}_{-i})\leq \eta B^2/2$. Thus, we get that 
    \begin{align} \label{eq_Dkbound1}
    V_i(\pi^{\dagger}_i,\pi^{k}_{-i})+ \lambda^{T}C - d_i(\lambda^{+},\pi^{k}_{-i}) \leq \eta B^2/2.    
    \end{align}
    Let $C_{\star}=\min_{j\in [m]}C_j$, where $C=(C_j)_{j\in [m]}$. Since $\lambda\in \mbR^{m}_{+}$, and $C>0$, we have $\|\lambda\|_{1} C_{\star} \leq \lambda^{T}C$, where $\|\lambda\|_{1}=\sum_{j=1}^{m} \lambda_j$. Thus, using \eqref{eq_Dkbound1}, we get,
    \begin{align}
        \|\lambda\|_{1} C_{\star} \leq \eta B^2/2 + d_i(\lambda^{+},\pi^{k}_{-i}) -V_i(\pi^{\dagger}_i,\pi^{k}_{-i})
    \end{align}
    Since the reward functions $r_i$ are finite, we get that $\|\lambda\|_1$ is bounded, for all $\lambda\in \ccalD^{k}_{i}$. Then, $\ccalD_{i}^{k}$ is contained in the ball $\ccalD$ defined as follows.
    \begin{align}
        \ccalD=\{\lambda\in \mbR^{m}_{+}: \|\lambda\|_1 \leq \frac{\eta B^2/2+d_i(\lambda^{+},\pi^{k}_{-i})-V_i(\pi^{\dagger}_{i},\pi^{k}_{-i})}{C_{\star}}\}
    \end{align}
    Since the closed ball is compact, we have our desired result.
\end{proof}
\begin{lemma} \label{lem_tightness}
    Under the assumptions of Theorem \ref{thm_main}, the sequence of probability measures $\{p(\lambda_k|\lambda_0)\}_{k\geq 0}$ is tight according to definition \ref{def_tightness}.
\end{lemma}
\begin{proof}
    Let $\ccalD^{k}_{i}$ be the set previously defined, and $\bar\ccalD^{k}_{i}$ it's complement. By virtue of the previous Lemma, the set $\ccalD^{k}_{i}$ is contained in a compact set. Define $\ccalD^k:=\cup_{i\in \ccalN}\ccalD_i^{k}$. Then $\ccalD^k$ is also contained in a compact set.
    % Hence, to prove the result, it is enough to show that the sequence of probabilities $\{p(\lambda_l|\lambda_0)\}$ is tight in $\bar\ccalD^{k}_{i}$. 
    Let us denote by $\ccalB_{\eta B}$ a closed ball centered at $0$ and radius $\eta B$ and by $\oplus$ the Minkowski addition. 
    Given knowledge of sigma algebra $\ccalF_k$, consider the sequence of sets $(\ccalD^q)_{q\leq k}$. If $\lambda^k \in \ccalD^{k}$, then $\lambda_{k+1} \in \ccalD^{k} \oplus \ccalB_{\eta B}$, because the estimate of the gradient in \eqref{eq_lambdaupdate} is bounded by $B$. Since $\ccalB_{\eta B}$ is compact, we have that 
     $\ccalD^k \oplus \ccalB_{\eta B}$ is contained in a compact set. This means that the first iterate of the sequence $\{\lambda_k\}_{k\geq 0}$, say $\lambda_l$, that is in the set $\ccalD^l$, has bounded norm with probability $1$.

    Without loss of generality, assume that the sequence $\{\lambda_k\}_{k\geq 0}$ is such that $\lambda_0 \in \bar\ccalD^0$. Let us define the following stopping time $K_0=\min_{k\geq 0}\{\lambda_k \in \ccalD^k\}$. We define the sequence $\{\lambda_{k\wedge K_0}\}$, where $\wedge$ denotes the minimum between $k$ and $K_0$. Note that the previous discussion allows us to exclusively consider indices $k\leq K_0$. That is, $\lambda_k \in \ccalC$ for all $k\geq K_0$, where $\ccalC$ is some compact set.

    We denote by $\|\lambda-\lambda^{+}\|^{2}$ the distance from $\lambda$ to the reference $\lambda^{+}$, where $\|\cdot\|$ is the norm induced by the inner product. Using the nonexpansiveness of the norm, and substituting $\lambda_{(k+1)\wedge K_0}$ by its dynamics in \eqref{eq_lambdaupdate}, it follows that 
    \begin{align} \label{eq_tight1}
        \|\lambda_{(k+1)\wedge K_0} - \lambda^{+}\|^2 \leq \|\lambda_{k\wedge K_0}-\eta g_k -\lambda^{+}\|^{2} \nonumber \\
        = \|\lambda_{k\wedge K_0}-\lambda^{+}\|^{2} - 2\eta (\lambda_{k\wedge K_0}-\lambda^{+})^{T}g_k + \eta^2\|g_k\|^{2}
    \end{align}
    where the vector $g_k=\sum_{t=kT_0}^{(k+1)T_0-1} (c(s^t,a^t)-b)/T_0 $ is the time average of the difference between the constraint payoff rollout and the constraint right hand side. Next, consider the conditional expectation of \eqref{eq_tight1} with respect to the sigma algebra $\ccalF_k$.
    \begin{align} \label{eq_tight2}
        \mbE\left[ \|\lambda_{(k+1)\wedge K_0} - \lambda^{+}\|^2 | \ccalF_k \right] \leq \|\lambda_{k\wedge K_0} - \lambda^{+}\|^2 \nonumber \\ -2\eta (\lambda_{k\wedge K_0}-\lambda^{+})^{T}\mbE \left[g_k|\ccalF_k\right] +\eta^2 \mbE\left[\|g_k\|^2\right | \ccalF_k] .
    \end{align}
    Here we utilize the fact that $\lambda_{(k\wedge K_0)}$ is $\ccalF_k$-measurable. Using assumption \ref{asmp_boundedreward}, it follows that $\mbE\left[\|g_k\|^2\right | \ccalF_k] \leq B^2$. Plugging into \eqref{eq_tight2}, we get
    \begin{align}\label{eq_tight3}
        \mbE\left[ \|\lambda_{(k+1)\wedge K_0} - \lambda^{+}\|^2 | \ccalF_k \right] \leq \|\lambda_{k\wedge K_0} - \lambda^{+}\|^2 \nonumber \\ -2\eta (\lambda_{k\wedge K_0}-\lambda^{+})^{T}\mbE \left[g_k|\ccalF_k\right] +\eta^2 B^2.
    \end{align}
    Using assumption \ref{asmp_unbiasedestimate}, we have that $\mbE \left[g_k|\ccalF_k\right]=U(\pi^{k})-b$ for all $\pi^{k} \in NE(\ccalG(\lambda_k))$. 
    % The conditional expectation on the sigma algebra $\ccalF_k$ for the previous expression means calculating the expectation of the stochastic rollout rewards at epoch $k$, using the Nash policy $\pi^{k} \in NE(\ccalG(\lambda_k))$. 
    Therefore the second term on the RHS of \eqref{eq_tight3} is equivalent to $-2\eta(\lambda_{k\wedge K_0}-\lambda^{+})^{T}(U(\pi^{k})-b)$. By Danskin's Theorem (Lemma \ref{lem_danskin}), it follows that 
    $(\lambda^{+}-\lambda_{k\wedge K_0})^{T}\mbE\left[g_k|\ccalF_k\right] \leq d_i(\lambda^{+},\pi^{k}_{-i})-d_i(\lambda_{k\wedge K_0},\pi^{k}_{-i})$. Substituting in the previous inequality, we get
    \begin{align} \label{eq_tight4}
       \mbE\left[ \|\lambda_{(k+1)\wedge K_0} - \lambda^{+}\|^2 | \ccalF_k \right] \leq \|\lambda_{k\wedge K_0} - \lambda^{+}\|^2 \nonumber \\ -2\eta (d_i(\lambda_{k\wedge K_0},\pi^{k}_{-i}) - d_i(\lambda^{+},\pi^{k}_{-i})) +\eta^2 B^2. 
    \end{align}
    Since $\lambda_{k\wedge K_0}$ is outside $\ccalD^k$, it is outside $\ccalD_i^k$ for all agents $i\in \ccalN$. So we have that $(d_i(\lambda_{k\wedge K_0},\pi^{k}_{-i}) - d_i(\lambda^{+},\pi^{k}_{-i})) > \eta B^2 / 2$, which further implies that $-2\eta (d_i(\lambda_{k\wedge K_0},\pi^{k}_{-i}) - d_i(\lambda^{+},\pi^{k}_{-i})) +\eta^2 B^2 < 0$ in \eqref{eq_tight4}. Thus, we get that 
    \begin{align} \label{eq_tight5}
        \mbE\left[ \|\lambda_{(k+1)\wedge K_0} - \lambda^{+}\|^2 | \ccalF_k \right] \leq \|\lambda_{k\wedge K_0} - \lambda^{+}\|^2.
    \end{align}
    Applying this equation recursively and taking expectation, we get that 
    \begin{align} \label{eq_tight5B}
        \mbE\left[ \|\lambda_{(k+1)\wedge K_0} - \lambda^{+}\|^2 \right] \leq \|\lambda_{0} - \lambda^{+}\|^2.
    \end{align}

    Having established \eqref{eq_tight5B}, we construct set $\ccalK_\epsilon$, for any $\epsilon>0$ as follows
    \begin{align}
        \ccalK_\epsilon =\{\lambda \in \mbR^{m}_{+}: \|\lambda-\lambda^{+}\|^{2} \leq \|\lambda_0-\lambda^{+}\|^{2}/\epsilon\}.
    \end{align}
    The ball $\ccalK_\epsilon$ is closed by definition. Moreover, since $\lambda^{+}$ and $\lambda_0$ have finite norm, and the set $\ccalK_\epsilon$ consists of such $\lambda$ which are at most a fixed distance away from $\lambda^{+}$, $\ccalK_\epsilon$ is bounded. Thus $\ccalK_\epsilon$ is compact. Hence, using Markov inequality, we get that 
    \begin{align} \label{eq_tight6}
        \mbP\left[\lambda_{k\wedge K_0} \in \ccalK_\epsilon\right] = \mbP\left[ \|\lambda_{k\wedge K_0}-\lambda^{+}\|^{2} \leq \|\lambda_0-\lambda^{+}\|^{2}/\epsilon\right] \nonumber \\
        > 1-\epsilon \frac{\mbE\left[\|\lambda_{k\wedge K_0}-\lambda^{+}\|^{2}\right]}{\|\lambda_0-\lambda^{+}\|^{2}} \geq 1-\epsilon
    \end{align}
    where the last inequality follows from \eqref{eq_tight5B}. Thus, our proof is complete.
\end{proof}
