\subsection{Feasibility guarantees assuming tightness}
\begin{proposition} \label{prop_feasibility1}
    If the sequence $\{p(\lambda_k|\lambda_0)\}_{k\geq 0}$ is tight, the state-action trajectories are feasible with probability 1, i.e.,
    \begin{align}
        \liminf_{T\rightarrow \infty}\frac{1}{T}\bigg[\sum_{t=0}^T c_{j}(s^t,a^t)|s^{0}=s\bigg] \geq b_j
    \end{align}
    holds almost surely for all $j\in [m]$ and for any arbitrary initial state $s$.
\end{proposition}
\begin{proof}
    For the sake of contradiction, assume there exists $\beta \in (0,1]$ and $\epsilon>0$ such that for some $j\in [m]$ we have 
    \begin{align} \label{eq_feasible1}
        \mbP\left[ \liminf\limits_{T\rightarrow \infty} \frac{1}{T} \sum_{t=0}^{T-1} c_{j}(s^t,a^t) \leq b_j -\epsilon\right]= \beta.
    \end{align}
    We first lower bound the norm of the $k+1$ iterate of the dual multiplier $\lambda_{j,k+1}$ whose evolution happens according to \eqref{eq_lambdaupdate}, as follows. See that by virtue of the projection onto the positive orthant in \eqref{eq_lambdaupdate}, we get 
    \begin{align} \label{eq_feasible2}
        \lambda_{j,k+1} \geq \lambda_{j,k} - \frac{\eta}{T_0}\sum_{t=kT_0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right).
    \end{align}
    Applying \eqref{eq_feasible2} recursively, we get 
    \begin{align}\label{eq_feasible2-1}
        \lambda_{j,k+1} \geq \lambda_{j,0} - \frac{\eta}{T_0}\sum_{t=0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right).
    \end{align}
    By the definition of the $l_1$ norm, one has that $\|\lambda_0\|_1 \geq \lambda_j$ for all $j\in [m]$ and $\lambda\in \mbR^{m}_{+}$. Hence, it holds that 
    \begin{align} \label{eq_feasible3}
        \limsup\limits_{k\rightarrow \infty} \|\lambda_{k+1}\|_1 \geq \limsup\limits_{k\rightarrow \infty} \lambda_{j,k+1}.
    \end{align}
    Using \eqref{eq_feasible2-1}, we obtain
    \begin{align} \label{eq_feasible3-1}
        &\limsup_{k\rightarrow \infty} \|\lambda_{k+1}\|_1 \\ \nonumber &\geq \lambda_{j,0} + \limsup\limits_{k\rightarrow \infty} \left[- \frac{\eta}{T_0}\sum_{t=0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right)\right].
    \end{align}
    Now, 
    \begin{align}
        &\limsup\limits_{k\rightarrow \infty} \left[- \frac{\eta}{T_0}\sum_{t=0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right)\right] \nonumber \\ &= -\eta\liminf\limits_{k\rightarrow \infty}(k+1)\frac{1}{(k+1)T_0}\left[\sum_{t=0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right)\right].
    \end{align}
    % $\limsup\limits_{k\rightarrow \infty} \left[- \frac{\eta}{T_0}\sum_{t=0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right)\right] = -\eta\liminf\limits_{k\rightarrow \infty}(k+1)\frac{1}{(k+1)T_0}\left[- \frac{1}{T_0}\sum_{t=0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right)\right]$. 
    Using \eqref{eq_feasible1}, we have that with probability $\beta$, 
    \begin{align}
        \liminf\limits_{k\rightarrow \infty}\frac{1}{(k+1)T_0}\left[\sum_{t=0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right)\right] \leq -\epsilon,
    \end{align} 
    which would imply 
    \begin{align}
       \limsup\limits_{k\rightarrow \infty} \left[- \frac{\eta}{T_0}\sum_{t=0}^{(k+1)T_0-1}\left(c_{j}(s^t,a^t) -b_j\right)\right] \nonumber \\ \geq \eta \liminf\limits_{k\rightarrow \infty} (k+1)\epsilon = \infty. 
    \end{align}
    Thus we have shown that with probability $\beta$, the norm of the $(k+1)$ iterate of the Lagrange multiplier $\lambda_{k+1}$ is lower-bounded at infinity. Hence for any compact set $\ccalK$, there exists a constant $l_\ccalK\geq 0$ and a subsequence $\{k_l\}$ such that $\mbP(\lambda_{k_l}\in \ccalK)=1-\beta$ for all $l>l_\ccalK$. This further implies that for $\delta\in(0,\beta]$, there does not exist a compact set $\ccalK_\delta$ for which $\mbP(\lambda_k \in \ccalK_\delta) > 1-\delta$ for all iterates $k$, which contradicts our assumption that the sequence of probability measures $\{p(\lambda_k|\lambda_0)\}_{k\geq 0}$ is tight. This completes the proof. 
\end{proof}
\subsection{Optimality guarantees assuming tightness}
% \lipsum[1-2]
\begin{lemma} \label{lem_optimality1}
    Under the assumptions of Theorem \ref{thm_main}, when agents execute policy sequence  $\{\pi^{k}\}_{k\geq 0}$, ergodic complementary slackness holds, i.e.
    \begin{align}
        \limsup\limits_{K\rightarrow \infty} \frac{1}{KT_0} \sum_{k=0}^{K-1} \mbE \left[\lambda_k^{T} \sum_{t=kT_0}^{(k+1)T_0-1}(c(s^t,a^t)-b)\right] \leq \eta B^2 / 2
    \end{align}
    where as defined in assumption \ref{asmp_boundedreward}, there exists $B$ such that $|c_{j}(s,a)-b_j|\leq B$ for all states $s$, actions $a$, and constraints $j \in [m]$.
\end{lemma}
\begin{proof}
    Define once again the vector $g_k := \frac{1}{T_0}\sum_{t=kT_0}^{(k+1)T_0-1} c(s^t,a^t)-b$ as the rollout at epoch $k$, when agents execute $\pi^{k}$. Here $g_k \in \mbR^{m}$, where $m$ is the number of constraints on the system. Then, write the square of the dual iterates' norm at time $k+1$. 
    % To recall, the dual update is given by 
    % \begin{align} \label{eq_slackness1}
    %     \lambda_{j,k+1}=\left[\lambda_{j,k}-\frac{\eta}{T_0}\sum_{t=kT_0}^{(k+1)T_{0}-1} (c_{j}(s^t,a^t)-b_j)\right]_{+}
    % \end{align}
    % where $\lambda_k=(\lambda_{j,k})_{j\in[m]}$.
    Using \eqref{eq_lambdaupdate} and the non-expansiveness property of the projection, we get 
    \begin{align} \label{eq_slackness2}
        \|\lambda_{k+1}\|^{2} \leq \|\lambda_k - \eta g_k\|^{2} = \|\lambda_k\|^{2} + \eta^{2} \|g_k\|^{2} - 2\eta g_k^{T}\lambda_k.
    \end{align}
    Using the fact that the difference $|c_{i}(s,a)-b_i| \leq B$, we get 
    \begin{align} \label{eq_slackness3}
        \|\lambda_{k+1}\|^{2} \leq \|\lambda_k\|^{2} + \eta^{2} B^{2} - 2\eta g_k^{T}\lambda_k.
    \end{align}
    Taking conditional expectation with respect to $\sigma$-algebra $\ccalF_k$, and using the fact that $\lambda_k$ is $\ccalF_k$ measurable, we get that 
    \begin{align} \label{eq_slackness4}
        \mbE(\|\lambda_{k+1}\|^{2}|\ccalF_k) \leq \|\lambda_k\|^2 +\eta^2 B^2 -2\eta \mbE(g_k^{T}\lambda_k | \ccalF_k).
    \end{align}
    Now, we shall use \eqref{eq_slackness4} recursively. 
    See that, if we take conditional expectation on both sides with respect to $\ccalF_{k-1}$ for the previous inequality, we get 
    \begin{align} \label{eq_slackness4B}
        \mbE(\|\lambda_{k+1}\|^{2}|\ccalF_{k-1}) \leq \mbE(\|\lambda_k\|^2|\ccalF_{k-1}) +\eta^2 B^2 \nonumber \\ -2\eta \mbE(g_k^{T}\lambda_k | \ccalF_{k-1}).
    \end{align}
    Applying \eqref{eq_slackness4} at epoch $k-1$, we get that $\mbE(\|\lambda_{k}\|^{2}|\ccalF_{k-1}) \leq \|\lambda_{k-1}\|^2 +\eta^2 B^2 -2\eta \mbE(g_{k-1}^{T}\lambda_{k-1} | \ccalF_{k-1})$. Plugging this inequality into \eqref{eq_slackness4B}, we get
    \begin{align} \label{eq_slackness4C}
        \mbE(\|\lambda_{k+1}\|^{2}|\ccalF_{k-1}) \leq \|\lambda_{k-1}\|^2 +2\eta^2 B^2 -2\eta (\mbE(g_k^{T}\lambda_k | \ccalF_{k-1}) \nonumber \\ + \mbE(g_{k-1}^{T}\lambda_{k-1} | \ccalF_{k-1})).
    \end{align}
    Thus, applying \eqref{eq_slackness4} in a recursive fashion, we get that 
    \begin{align} \label{eq_slackness5}
        \mbE(\|\lambda_{k+1}\|^{2}|\ccalF_0) \leq \|\lambda_{0}\|^2 + (k+1)\eta^2 B^2 -2\eta \sum_{l=0}^{k} \mbE(\lambda_l^{T}g_l | \ccalF_0).
    \end{align}
    Thus, using the fact that $\|\lambda_k\| \geq 0$ for all $k$, and rearranging terms in \eqref{eq_slackness5}, we get
    \begin{align}
        \frac{1}{k+1} \sum_{l=0}^{k} \mbE [\lambda_l^T g_l] \leq \frac{\|\lambda_0\|^{2}}{2\eta(k+1)} + \eta \frac{B^2}{2}.
    \end{align}
    Taking limit superior on both sides, we get our final result.
\end{proof}

We now define some terms which will be used to represent the optimal value function for agents against a nonstationary environment comprised of other agents. For every sequence $\{\pi^{k}\}_{k\geq 0}$, we define
\begin{align} \label{def_P_i}
    \ccalP_{i}^{\star} (\pi^{k}_{-i})  :=\sup\limits_{\zeta^{k} \in \Pi^{c}_{i}(\pi^{k}_{-i})} \mbE_{(\zeta^{k},\pi^{k}_{-i})}\left[\sum_{t=kT_0}^{(k+1)T_0-1} r_{i}(s^t,a^t)/T_0\right]
\end{align}
as the optimal value (best-response) for agent $i \in \ccalN$, for epoch $k$, when other agents play $\pi^{k}_{-i}$. 
Further, we define 
\begin{align}
\ccalP_{i}^{\star}:= \liminf_{K\rightarrow \infty} \frac{1}{K} \sum_{k=0}^{K} \ccalP_{i}^{*} (\pi^{k}_{-i}).    
