\begin{lemma}
    Let assumptions \ref{asmp_superfeasible}, \ref{asmp_boundedreward}, \ref{asmp_unbiasedestimate} hold. In addition, assume that the sequence $\{p(\lambda_k | \lambda_0)\}_{k\geq 0}$ is tight, when agents execute the policy sequence  $\{\pi^{k}\}_{k\geq 0}$. Then the sequence of policies forms a constrained nonstationary $\eta\frac{B^2}{2}$-NE for the game $\ccalG$.
\end{lemma}

\begin{proof}
    Let agents follow policy sequence $\{\pi^{k}\}_{k\geq 0}$. Let the policy sequence be realized until epoch $K$. Recall that the generalized dual function for an agent $i\in \ccalN$, Lagrange multiplier $\lambda_k$, and policies of other agents $\pi^{k}_{-i}$, for $k\leq K$ is given by
    \begin{align} \label{eq_optimality1}
        d_i(\lambda_k,\pi^{k}_{-i})= \max_{z_i \in \Pi_i} \left[V_i(z_i,\pi^{k}_{-i}) + \lambda_{k}^{T}(U(z_i,\pi_{-i}^{\lambda_k})-b)\right]
    \end{align}
    Since $\pi^{k}$ is in $NE(\ccalG(\lambda_k))$, we have that $\pi^{k}_i$ is a best-response to $\pi^{k}_{-i}$, which implies that the resultant maximization in \eqref{eq_optimality1} results in
    \begin{align} \label{eq_optimality2}
        d_i(\lambda_k,\pi^{k}_{-i}) = V_i(\pi^{k}) +\lambda_{k}^{T}(U(\pi^{k})-b).
    \end{align}

    \noindent \textit{Claim:} We claim that $\ccalP^{\star}_{i}(\pi^{k}_{-i}) \leq d_i(\lambda_k,\pi^{k}_{-i})$. For the sake of contradiction, assume that $\ccalP^{\star}_{i}(\pi^{k}_{-i})> d_i(\lambda_k,\pi^{k}_{-i})$. Using assumption \ref{asmp_unbiasedestimate} (unbiased rollout), we have that  
    \begin{align} \label{eq_optimality2-1}
        \mbE_{(\zeta^{k},\pi^{k}_{-i})}\left[\sum_{t=kT_0}^{(k+1)T_0-1} r_{i}(s^t,a^t)/T_0\right] = V_{i}(\zeta_i, \pi^{k}_{-i})
    \end{align}
    Plugging \eqref{eq_optimality2-1} into \eqref{def_P_i}, we write 
    \begin{align}
        \ccalP^{\star}_{i}(\pi^{k}_{-i})=\sup_{\zeta_i \in \Pi^{c}_{i}(\pi^{k}_{-i})}  V_{i}(\zeta_i, \pi^{k}_{-i}).
    \end{align}
    Since $\ccalP^{\star}_{i}(\pi^{k}_{-i})$ is the maximum value for the constrained problem, the policy $\zeta^{\star}_i=\argmax_{\zeta_i \in \Pi^{c}_{i}(\pi^{k}_{-i})} V_{i}(\zeta_i, \pi^{k}_{-i})$ satisfies 
    $U(\zeta^{\star}_{i}, \pi^{k}_{-i}))-b \geq 0$. Moreover, due to the update dynamics for the Lagrange multiplier in \eqref{eq_lambdaupdate}, $\lambda_k \geq 0$. So, $\lambda_{k}^{T}(U(\zeta^{\star}_{i}, \pi^{k}_{-i}))-b)\geq 0$, which implies that 
    \begin{align}\label{eq_optimality3}
        V_i(\zeta^{\star}_{i},  \pi^{k}_{-i}) + \lambda_{k}^{T}(U(\zeta^{\star}_{i}, \pi^{k}_{-i}))-b) \geq V_i(\zeta^{\star}_{i},  \pi^{k}_{-i})=\ccalP^{\star}_{i}(\pi^{k}_{-i})
    \end{align}
    % $V_i(\zeta^{*}_{i},  \pi^{k}_{-i}) + \lambda_{k}^{T}(U(\zeta^{*}_{i}, \pi^{k}_{-i}))-b) \geq V_i(\zeta^{*}_{i},  \pi^{k}_{-i})=\ccalP^{*}_{i}(\pi^{k}_{-i})$. 
    But, by definition of the generalized dual, $d_i(\lambda_k, \pi^{k}_{-i})\geq V_i(\zeta^{\star}_{i},  \pi^{k}_{-i}) + \lambda_{k}^{T}(U(\zeta^{\star}_{i}, \pi^{k}_{-i}))-b)$, which when reconciled with \eqref{eq_optimality3} creates the contradiction. 

    Thus, from the previous claim, we have $\ccalP^{\star}_{i}(\pi^{k}_{-i}) \leq d_i(\lambda_k,\pi^{k}_{-i})$. Taking average over $K$ epochs, and using \eqref{eq_optimality2}, we have 
    \begin{align} \label{eq_optimality4}
        \frac{1}{K}\sum_{k=0}^{K-1} \left(V_i(\pi^{k}) +\lambda_{k}^{T}(U(\pi^{k})-b)\right) \geq \frac{1}{K}\sum_{k=0}^{K-1} \ccalP^{\star}_{i}(\pi^{k}_{-i}) . 
    \end{align}
    where $\pi_k\in NE(\ccalG(\lambda_k))$.
    Substituting $V_i(\pi^{k})= \mbE \left[ \frac{1}{T_0} \sum_{t=kT_0}^{(k+1)T_0-1} r_{i}(s^t,a^t) \left. \right| \lambda_k  \right]$ and rearranging terms we get 
    \begin{align} \label{eq_optimality5}
        \frac{1}{K} \sum_{k=0}^{K-1} \mbE \left[ \frac{1}{T_0} \sum_{t=kT_0}^{(k+1)T_0-1} r_{i}(s^t,a^t) \left. \right| \lambda_k  \right] \nonumber \\ \geq \frac{1}{K}\sum_{k=0}^{K-1} \ccalP^{\star}_{i}(\pi^{k}_{-i}) - \frac{1}{K} \sum_{k=0}^{K-1} \lambda_{k}^{T}(U(\pi^{k})-b)
    \end{align}
    Now, we take limit on both sides for $K\rightarrow \infty$. We use the result from Lemma \ref{lem_optimality1} to bound $\liminf_{K\rightarrow \infty} \frac{1}{K} \sum_{k=0}^{K-1} \lambda_{k}^{T}(U(\pi^{k})-b) \leq \eta B^2/2$. Recall that $\liminf_{K\rightarrow \infty} \frac{1}{K}\sum_{k=0}^{K-1} \ccalP^{\star}_{i}(\pi^{k}_{-i})= \ccalP^{\star}_i$. Further substituting for $T=KT_0$ on the LHS of \eqref{eq_optimality5}, we get
    \begin{align}
        \liminf_{T\rightarrow \infty} \frac{1}{T} \mbE \sum_{t=0}^{T-1} r_i(s^t, a^t) \geq \ccalP^{\star}_i - \eta B^2 / 2.
    \end{align}
    Since agent $i$ is arbitrary, this shows that the sequence of policies $\{\pi^{k}\}_{k\geq 0}$ comprises a nonstationary $\eta \frac{B^2}{2}$-NE for constrained Markov game $\ccalG$. Moreover, feasibility is guaranteed from proposition \ref{prop_feasibility1}, which in turn implies our desired result.
\end{proof}


