	\subsection{Fundamental Properties of $\sim_{\varepsilon, \delta}$}\label{sec:fundamental-properties}
	We now establish some fundamental properties of $\sim_{\varepsilon, \delta}$ that are generally desirable for approximate probabilistic bisimulations \cite{AAPP,SAPB}. 
	\begin{restatable}{theorem}{ThmFundamentalProperties}\label{thm:fundamental-properties}
		Let $\mathcal{M}$ be a CTMC and $s, s', s'' \in \stateSpace$.
		\begin{enumerate}
			\item ${\sim_{\varepsilon, \delta}}$ is the largest $(\varepsilon, \delta)$-bisimulation on $\mathcal{M}$.
			\item If $s \sim_{\varepsilon_1, \delta_1} s'$ and $s' \sim_{\varepsilon_2, \delta_2} s''$ then $s \sim_{\varepsilon_1 + \varepsilon_2, \delta_1 + \delta_2} s''$. 
			\item $s \sim s'$ iff $s \sim_{0,0} s'$.
		\end{enumerate}
	\end{restatable}

	\Cref{thm:fundamental-properties} shows that $\sim_{\varepsilon, \delta}$ is itself an $(\varepsilon, \delta)$-bisimulation, and that it is the largest such relation (item 1). Furthermore $\sim_{\varepsilon, \delta}$ is additive in both $\varepsilon$ and $\delta$ \mbox{(item 2)} and coincides with strong bisimilarity $\sim$ iff $\varepsilon = \delta = 0$ (item 3).

	By slightly adjusting a procedure proposed in \cite{AAPP} that constructs $\sim_\varepsilon$ for DTMCs by solving flow networks á la \cite{PTATPBS,PSfPP}, $\sim_{\varepsilon, \delta}$ can be computed in time polynomial in the number of states of $\mathcal{M}$. 

	\begin{restatable}{corollary}{CorAlgorithmicComplexity}\label{cor:algorithmic-complexity-sim-epsilon-delta}
		For a given CTMC $\mathcal{M}$, $\sim_{\varepsilon, \delta}$ can be computed in time $\mathcal{O}(\vert \stateSpace \vert^7)$.
	\end{restatable}

	Furthermore, $(\varepsilon, \delta)$-bisimilarity in $\mathcal{M}$ implies $\tau$-bisimilarity (for a $\tau \geq 0$ that depends on $\varepsilon$ and $\delta$) in the uniformization $\uniformization{\mathcal{M}}{\uniformizationRate}$ of $\mathcal{M}$ for $q \geq \max_{s \in \stateSpace} \rate(s)$. \unskip
	\begin{restatable}{lemma}{LemApproximatBisimulationInUniformization}\label{lem:approximate-bisimulation-in-uniformization}
		$s \sim_{\varepsilon, \delta}^\mathcal{M} s'$ implies $s \sim_\tau^{\uniformization{\mathcal{M}}{\uniformizationRate}} s'$, where $\tau = e^\delta \cdot(1 + \varepsilon) - 1$.
	\end{restatable}

	A notion from the literature related to $(\varepsilon, \delta)$-bisimulations is that of $\tau$-quasi-lumpability, which is also known as $\tau$- or near-lumpability \cite{EOLFMC,BQLMC,CBPIQLSWFN}. It is defined for partitions $\Omega = \{\Omega_1, \ldots, \Omega_m\}$ of the state space $\stateSpace$ of $\mathcal{M}$. More precisely, $\Omega$ is a $\tau$-quasi-lumpability for some $\tau \geq 0$ if for all $1 \leq i,j \leq m$ and all $s, s' \in \Omega_i$ it holds that $\vert \prob(s, \Omega_j) \cdot \rate(s) - \prob(s', \Omega_j) \cdot \rate(s')\vert \leq \tau$ \cite{PL}. The partitions of the state space induced by \emph{transitive} $(\varepsilon, \delta)$-bisimulations are quasi-lumpabilities. 	\begin{restatable}{proposition}{PropConnectionTauLump}
		Let $R$ be a transitive $(\varepsilon, \delta)$-bisimulation and $\uniformizationRate \geq \max_{s \in \stateSpace} \rate(s)$. The partition induced by $R$, i.e., the set $\xfrac{\stateSpace}{R}$, is a $q \cdot (e^{\delta} \cdot(1 + \varepsilon) - 1)$-lumpability.
	\end{restatable}

	On the other hand, states related by a $\tau$-lumpability might require large values of $\varepsilon, \delta$ to be able to relate them by an $(\varepsilon, \delta)$-bisimulation.
	\begin{restatable}{proposition}{PropTauLumpDoesNotImplyEpsilonDelta}\label{prop:quasi-lumpability-does-not-imply-epsilon-delta}
		For any given $\varepsilon \in (0,1), \delta > 0$ and $\tau > 0$ there is a CTMC $\mathcal{M} = \mathcal{M}(\varepsilon, \delta, \tau)$ with states $s,s'$ such that $\{s,s'\}$ is a block of a $\tau$-quasi lumpability on $\mathcal{M}$ but the pair $(s,s')$ does neither satisfy the $\varepsilon$- nor the $\delta$-condition.
	\end{restatable}
	\Cref{prop:quasi-lumpability-does-not-imply-epsilon-delta} illustrates the advantage of considering differences in the exit rates and transition probabilities of states separately when arguing about the similarity of their behavior, instead of considering the transition rates, i.e., the product of these two values, as is usually done in the literature \cite{EOLFMC,BQLMC,PL}.

	We finish the section by showing how to ``split'' $(\varepsilon,\delta)$-bisimilarity into $(\varepsilon, 0)$- and $(0, \delta)$-bisimilarity. More precisely, given $\mathcal{M} \sim_{\varepsilon, \delta} \mathcal{N}$ we construct CTMCs $\mathcal{M}', \mathcal{N}'$ with the same graph structure and such that \mbox{$\mathcal{M} \sim_{\varepsilon, 0} \mathcal{M}' \sim_{0, \delta} \mathcal{N}' \sim \mathcal{N}$}. This decomposition makes it possible to treat the two parameters individually and, together with the additivity of $\sim_{\varepsilon, \delta}$, allows us to extend results shown for $(\varepsilon,0)$- and $(0, \delta)$-bisimilar states or chains to $(\varepsilon, \delta)$-bisimilar ones. 
	\begin{restatable}{theorem}{ThmSameStructureConstruction}\label{thm:same-structure-no-additional-tolerance}
		Let $\mathcal{M} \sim_{\varepsilon, \delta} \mathcal{N}$. Then there are CTMCs $\mathcal{M}'$ and $\mathcal{N}'$ with the same graph structure and such that
$			\mathcal{M} \sim_{\varepsilon, 0} \mathcal{M}' \sim_{0, \delta} \mathcal{N}' \sim \mathcal{N}.$
	\end{restatable}
	\paragraph{Proof sketch.}
		We describe how to construct $\mathcal{M}'$ and $\mathcal{N}'$. The models share the state space $\stateSpace' = \stateSpace^\mathcal{M} \times \stateSpace^\mathcal{N}$, with initial state $(\initialState^\mathcal{M}, \initialState^\mathcal{N})$. The label function $\labelFunction'$ of both models is $\labelFunction'((s,t)) = \labelFunction^\mathcal{N}(t)$, and the exit rate functions are defined via 
		\begin{center}
			${\rate^\mathcal{M}}'((s,t)) = \begin{cases}
				\rate^\mathcal{M}(s), &\text{if } s \sim_{\varepsilon, \delta} \! \! t \\
				\rate^\mathcal{N}(t), &\text{if} s \nsim_{\varepsilon, \delta} t
			\end{cases} \qquad \text{and} \qquad
			{\rate^\mathcal{N}}'((s,t)) = \rate^\mathcal{N}(t).$
		\end{center}
		Furthermore, the common transition probability function of $\mathcal{M}'$ and $\mathcal{N}'$ is 
		\begin{align*}
			\prob'((s,t), (s',t')) &= \begin{cases}
				\Delta_{s,t}(s',t') \prob^\mathcal{M}(s,s'), &\text{if } s \sim_{\varepsilon, \delta} t, s' \in \Succ(s), t' \in \Succ(t) \\
				\prob^\mathcal{M}(s,s')  \prob^\mathcal{N}(t,t'), &\text{if } s \nsim_{\varepsilon, \delta} t \\
				0, &\text{otherwise}
			\end{cases}
		\end{align*}
		where, for a given pair of $(\varepsilon, \delta)$-bisimilar states $(s,t) \in \stateSpace^\mathcal{M} \times \stateSpace^\mathcal{N}$, the function $\Delta_{s,t} \colon \Succ(s) \to \Distr(\Succ(t))$ is a weight function as in \Cref{lem:characterization-weight-functions-concur}, which exists for all such $(s,t)$ since $s \sim_{\varepsilon} t$ in the underlying DTMCs of $\mathcal{M}$ and $\mathcal{N}$. The proof proceeds by showing the desired relations between the models.  \qed
