	$\erlang_4$ is illustrated in \Cref{fig:erlang-4}. Given $\mathcal{M}$ and $c \in \mathbb{R}_{> 0}$, let $c \cdot \mathcal{M}$ be the CTMC obtained from $\mathcal{M}$ by multiplying all rates with $c$. Then $\mathcal{M} \sim_{0, \delta} c \cdot \mathcal{M}$ for $\delta \geq \ln(c)$. For an absorbing, uniform CTMC $\mathcal{M}$ it is clear that an acceleration $c \cdot \mathcal{M}$ with $c = e^{\delta} \geq 1$ or a deceleration  $1/c\cdot \mathcal{M}$ induces the maximal possible difference in timed reachability probabilities compared to $\mathcal{M}$ among all $\mathcal{M}'$ with \mbox{$\mathcal{M} \sim_{0, \delta} \mathcal{M}'$}. 
	In the sequel, results are formulated for the comparison of $\mathcal{M}$ with $c\cdot \mathcal{M}$. By switching the roles of $\mathcal{M}$ and $c\cdot \mathcal{M}$, we obtain symmetric results for the deceleration.
	\begin{restatable}{proposition}{PropErrorErlangCTMC}\label{prop:error-erlang-ctmc}
		Let $n \in \mathbb{N}$, $t \geq 0$, and $\erlang'_n = c \cdot \erlang_n$ for some $c \geq 1$. Then 
		\begin{center}
			$\Diff_t(\erlang_n) \coloneqq \vert \probMeasure^{\erlang_n}(\lozenge^{\leq t} g) - \probMeasure^{\erlang'_n}(\lozenge^{\leq t} g) \vert = \sum\limits_{k = 0}^{n-1} \frac{t^k}{k!} \cdot \left(e^{-t} - c^ke^{-ct} \right)$.
		\end{center}
		If $c > 1$, $\Diff_t(\erlang_n)$ has a local maximum at $t = \frac{n \cdot \ln(c)}{c - 1}$ that is global on $[0, \infty)$. 
	\end{restatable}

	\begin{remark}\label{rem:arbitrary-rate}
		We could have also allowed arbitrary (but uniform) rates for $\erlang_n$ in \Cref{def:erlang-ctmc}, i.e., $\rate(s) = r$ for all $s \in \stateSpace$ and some $r > 0$. In this case,
		\begin{center}
			$\Diff_t(\erlang_n) = \sum\limits_{k=0}^{n-1} \frac{(r\cdot t)^k}{k!} \cdot \left(e^{-r\cdot t} - c^{k}e^{-c \cdot r\cdot t}\right)$, 
		\end{center}
		with a (local) maximum at $t^* = \frac{n \cdot \ln(c)}{r \cdot (c-1)}$ for $c > 1$. Note that $\Diff_{t^*}(\erlang_n)$ does not depend on $r$. Moreover, the assumption that $r = 1$ can be made w.l.o.g., as in the case of $r \neq 1$ the time-bounded reachability probabilities until $t$ are the same as those of the corresponding CTMC with uniform exit rate $1$ until $r \cdot t$. 
	\end{remark}

	\Cref{prop:error-erlang-ctmc} induces a way to exactly compute the absolute difference in timed reachability probabilities of a CTMC $\mathcal{M}$ and its acceleration $c \cdot \mathcal{M}$. 
	\begin{restatable}{theorem}{ThmExactBoundZeroDelta}\label{thm:exact-computation-error-0-delta}
		Let $\mathcal{M}$ be a CTMC with $\rate(s) = 1$ for all $s \in \stateSpace$, and let $g$ be a unique absorbing goal state. Let $\delta > 0$, $c = e^\delta > 1$, and $\mathcal{M}' = c \cdot \mathcal{M}$. Then \begin{center}
			$\Diff_t(\mathcal{M}) = \vert \probMeasure^{\mathcal{M}'}(\lozenge^{\leq t} g) - \probMeasure^{\mathcal{M}}(\lozenge^{\leq t}g) \vert = \sum\limits_{n=1}^{\infty} p_n \cdot \Diff_t(\erlang_n), $
		\end{center}
		where $p_n$ denotes the probability to reach $g$ after exactly $n$ (discrete) steps. 
	\end{restatable}
	\paragraph{Proof sketch.} Let $\Pi_n$ contain all finite paths entering $g$ after exactly $n$ steps, and let $\mathrm{Traj}^*(\pi)$ contain all timed versions of $\pi \in \Pi_n$ that enter $g$ in $(t, c \cdot t]$. Then $\Diff_t(\mathcal{M}) = \sum_{n=0}^{\infty} \sum_{\pi \in \Pi_n} \probMeasure^\mathcal{M}(\mathrm{Traj}^*(\pi)) = \sum_{n=0}^{\infty} \sum_{\pi \in \Pi_n} \mathrm{Pr}^\mathcal{M}(\mathrm{Traj}^*(\pi) \mid \pi) \cdot \mathrm{Pr}^\mathcal{M}(\pi)$ by Bayes' rule. As $\probMeasure^\mathcal{M}(\mathrm{Traj}^*(\pi) \mid \pi) = \Diff_t(\erlang_n)$ for all $\pi \in \Pi_n$, $\Diff_t(\erlang_0) = 0$ for all $t$, and $\sum_{\pi \in \Pi_n} \probMeasure^\mathcal{M}(\pi) = p_n$, the claim follows. \qed

	\medskip 

	In \Cref{thm:exact-computation-error-0-delta} (and all other results in this section) we could have also used any (uniform) exit rate $r > 0$ for the states of $\mathcal{M}$ since, as described in \Cref{rem:arbitrary-rate}, we can model different rates by scaling the time bound $t$.

	Next we show how to obtain, for given $t$ and $\delta$, a maximal $N$ (that depends on $t, \delta$) such that $\Diff_t(\mathcal{M}) \leq \Diff_t(\erlang_N)$. Using the explicit form of $\Diff_t(\erlang_N)$ from \Cref{prop:error-erlang-ctmc}, this yields an easy-to-compute upper bound for $\Diff_t(\mathcal{M})$. 
	\begin{restatable}{proposition}{PropImproveBoundZeroDeltaViaMaxErlang}\label{prop:erlang-bound-0-delta}
		Let $N = \left \lceil \frac{(e^{\delta} - 1) \cdot t}{\delta} \right \rceil$. Under the conditions of \Cref{thm:exact-computation-error-0-delta},
		\begin{center}
			$\Diff_t(\mathcal{M}) \leq \Diff_t(\erlang_N) = \sum\limits_{k=0}^{N-1} \frac{t^k}{k!} \cdot \left(e^{-t} - c^ke^{-ct} \right).$
		\end{center}
	\end{restatable}

	The bound of \Cref{prop:erlang-bound-0-delta} is usually tighter than that for $(0, \delta)$-bisimilar states in \Cref{cor:transient-prob-bounds-epsilon-or-delta-0}, since it does not converge to $1$ exponentially fast for increasing $t$. See \Cref{fig:4-state-chain,fig:example-bounds-diag-queue} for some examples of the behavior of the bound. 

	\begin{remark}\label{rem:adjustment-of-bound-via-Markov-inequality}
		Let $\mathcal{M}$ be as in \Cref{thm:exact-computation-error-0-delta} and let $X$ be the random variable that describes the probability to reach $g$ for the first time after exactly $n$ steps. Then $p_n \leq \probMeasure(X \leq n)$, so the Markov inequality implies $p_n \leq \frac{\mathbb{E}(X)}{n}$ for every $n$, where $\mathbb{E}(X)$ is the expected value of $X$. Together with \Cref{thm:exact-computation-error-0-delta} this yields
		\begin{center}
			$\Diff_t(\mathcal{M}) = \sum\limits_{n=1}^{\infty} p_n \cdot \Diff_t(\erlang_n) \leq 
			\mathbb{E}(X) \cdot \sum\limits_{n=1}^{\infty} \frac{1}{n} \cdot \Diff_t(\erlang_n).$ 		\end{center}
		This bound heavily depends on $\mathbb{E}(X)$, i.e., on the expected number of steps until reaching $g$. If $\mathbb{E}(X)$ is small the bound can be tighter than those of \Cref{prop:transient-prob-bounds-epsilon-delta-greater-0,prop:erlang-bound-0-delta}, while it can quickly become trivial if $\mathbb{E}(X)$ is large. 
	\end{remark}

	Next, we present  a way to compute the values of $p_n$ based on a spectral decomposition of the transition probability matrix $\probMatrix$ of CTMC $\mathcal{M}$. We start with the case of a  diagonalizable $\probMatrix$, and afterwards deal with arbitrary $\probMatrix$ by using the Jordan canonical form \cite{MAALA}. Moreover, we use the so obtained explicit formulas for $p_n$ to obtain upper bounds for $\Diff_t(\mathcal{M})$. In contrast to the results so far, these bounds converge to $0$ for $t \to \infty$, just like the actual difference does. 

	The transition probability matrix $\probMatrix$ of $\mathcal{M}$ is diagonalizable if there is a diagonal matrix $\diagonalMatrix$, with diagonal elements corresponding to the eigenvalues of $\probMatrix$ (repeated according to their multiplicities), and a regular matrix $\symmetryMatrix$ such that $\probMatrix = \symmetryMatrix \diagonalMatrix \symmetryMatrix^{-1}$ \cite{MAALA}. It is well-known that every eigenvalue $\lambda_i$ of a stochastic matrix satisfies $\vert \lambda_i \vert \leq 1$, and that $\lambda_1 = 1$ is an eigenvalue of any such matrix. 
%
	As we assume that an absorbing state is reached almost surely, $1$ is the only eigenvalue of modulus $1$, and it has a multiplicity $a_\probMatrix$ of at most $2$ (as there are at most two absorbing states in $\mathcal{M}$).
	Hence, we can w.l.o.g. assume that for the $m$ distinct eigenvalues of $\probMatrix$ we have $\lambda_1 = 1 > \vert \lambda_2 \vert \geq \ldots \geq \vert \lambda_m \vert$, and that the diagonal of $\diagonalMatrix$ is in descending order w.r.t. the absolute values of these eigenvalues. From now on we denote the second largest (absolute value wise) eigenvalue of $\probMatrix$ by $\lambda$. 


	\begin{restatable}[\cite{MCASAGE}]{proposition}{PropExactComputationPnDiag}\label{prop:exact-computation-pn-diag}
		Let $\mathcal{M}$ be a CTMC such that $\probMatrix = \symmetryMatrix \diagonalMatrix\symmetryMatrix^{-1}$ is diagonalizable. Let $k \in \mathbb{N}$ and $n = \vert \stateSpace \vert$. Then $p_{k+1} = \sum_{j=a_\probMatrix+1}^{n} \symmetryMatrix_{1, j} \cdot \symmetryMatrix^{-1}_{j, n} \cdot (\lambda_j -1) \cdot \lambda_j^k.$
	\end{restatable}

	Combining \Cref{thm:exact-computation-error-0-delta} and \Cref{prop:exact-computation-pn-diag} yields a new bound for $\Diff_t(\mathcal{M})$. \unskip
	\begin{restatable}{proposition}{BoundPnDiag}\label{prop:improved-bounds-0delta-with-ev-diagonalizable}
		Under the conditions of \Cref{thm:exact-computation-error-0-delta} we have 
		\begin{center}
			$\Diff_t(\mathcal{M}) \leq (n-a_\probMatrix) \cdot C \cdot \sum_{k=1}^{\infty} \vert \lambda \vert^{k-1} \cdot \Diff_t(\erlang_k),$
		\end{center}
		where $n = \vert \stateSpace \vert$ and $C =  \max_{i = a_\probMatrix+1, \ldots, n} \vert \symmetryMatrix_{1,i} \cdot \symmetryMatrix^{-1}_{i,n} \cdot (\lambda_i - 1) \vert$. 
	\end{restatable}
	\paragraph{Proof sketch.} By \Cref{prop:exact-computation-pn-diag}, $p_{k+1} = \sum_{j=a_\probMatrix+1}^{n} \symmetryMatrix_{1, j} \cdot \symmetryMatrix^{-1}_{j, n} \cdot (\lambda_j -1) \cdot \lambda_j^k$, so by the triangle inequality $p_{k+1} \leq \sum_{j=a_\probMatrix+1}^{n} \vert \symmetryMatrix_{1, j} \cdot \symmetryMatrix^{-1}_{j, n} \cdot (\lambda_j -1) \vert \cdot \vert \lambda_j \vert^k $. Because $\vert \lambda_j \vert \leq \vert \lambda \vert$ for all $j > a_\probMatrix$ we get $p_{k+1} \leq \vert \lambda \vert^{k} \cdot \sum_{j=a_\probMatrix+1}^{n} C = \vert \lambda \vert^{k} \cdot (n-a_\probMatrix) \cdot C$ for $C = \max_{i = a_\probMatrix+1, \ldots, n} \vert \symmetryMatrix_{1,i} \cdot \symmetryMatrix^{-1}_{i,n} \cdot (\lambda_i - 1) \vert$. The claim follows from \Cref{thm:exact-computation-error-0-delta}.  \qed

	\medskip

	The bound obtained in \Cref{prop:improved-bounds-0delta-with-ev-diagonalizable} is tight: Consider a CTMC $\mathcal{M}$ with two states $s$ and $g$, such that $\rate(s) = \rate(g) = 1$ and $\prob(s, s) = p, \prob(s,g) = 1-p$ for a $p \in (0,1)$. Let $\mathcal{M}' = e^{\delta} \cdot \mathcal{M}$, so $\mathcal{M} \sim_{0, \delta} \mathcal{M}'$. The probability matrix $\probMatrix$ of $\mathcal{M}$ is diagonalizable with eigenvalues $\lambda_1= 1$ and $\lambda_2 = \lambda = p$. Then $p_k =\vert \sum_{j=2}^{2} \symmetryMatrix_{1, j} \cdot \symmetryMatrix^{-1}_{j, 2} \cdot (\lambda_j -1) \cdot \lambda_j^{k-1} \vert = (1-p) \cdot p^{k-1} = (n-1) \cdot C \cdot \lambda^{k-1}$, so here the inequalities in the proof  of \Cref{prop:improved-bounds-0delta-with-ev-diagonalizable} are  equalities. 
	%
	Furthermore, since always $\vert \lambda \vert < 1$, the bounds converge to $0$ for $t \to \infty$, just like $\Diff_t(\mathcal{M})$.

