	\section{Proofs of \Cref{sec:definition-fundamental-properties}}
	\begin{restatable}{lemma}{LemCharacterizationTransitive}\label{lem:characterization-transitive}
		Let $R \subseteq \stateSpace \times \stateSpace$ be an equivalence. $R$ satisfies the $\varepsilon$-condition of  \Cref{def:epsilon-delta-bisimulation} iff for every $R$-closed set $A \subseteq \stateSpace$: $\vert \prob(s, A) - \prob(s', A) \vert \leq \varepsilon.$
	\end{restatable}
	\begin{proof}
		Let $(s,s') \in R$. For the direction from left to right, let $A \subseteq \stateSpace$ be $R$-closed. Then $R(A) = A$, so by the $\varepsilon$-condition of \Cref{def:epsilon-delta-bisimulation} we have 
		\begin{align*}
			\prob(s, A) \leq \prob(s', A) + \varepsilon \qquad \text{ and } \qquad \prob(s', A) \leq \prob(s, A) + \varepsilon,
		\end{align*}
		and it follows that $\vert \prob(s, A) - \prob(s', A) \vert \leq \varepsilon.$

		For the reverse direction let $A \subseteq \stateSpace$ (not necessarily $R$-closed). Because $R$ is an equivalence $R(A)$ is the union of all equivalence classes containing any element of a $A$, and hence $R$-closed. Thus, we have $\vert \prob(s, R(A)) - \prob(s', R(A)) \vert \leq \varepsilon$, so in particular $\prob(s, R(A)) \leq \prob(s', R(A)) + \varepsilon$. Since $A \subseteq R(A)$ it follows that 
		\begin{align*}
			\prob(s, A) \leq \prob(s, R(A)) \leq \prob(s', R(A)) + \varepsilon.
		\end{align*}
	\end{proof}

	\ThmFundamentalProperties*
	\begin{proof}
		\begin{enumerate}
			\item We start by showing that $\sim_{\varepsilon, \delta}$ is itself an $(\varepsilon, \delta)$-bisimulation. To this end we first observe that, as a countable union of symmetric and reflexive relations, $\sim_{\varepsilon, \delta}$ is itself both reflexive and symmetric. Now let $(s,t) \in {\sim_{\varepsilon, \delta}}$. Then there is some $(\varepsilon, \delta)$-bisimulation $R$ such that $(s,t) \in R$. It follows that $\labelFunction(s) = \labelFunction(t)$ and $\vert \ln(\rate(s)) - \ln(\rate(t)) \vert \leq \delta$ (both of these implications are independent of the choice of $R$). 

			\quad We now show that for all $A \subseteq \stateSpace$, it holds that $\prob(s, A) \leq \prob(t, {\sim_{\varepsilon, \delta}}(A)) + \varepsilon$. To this end observe that, for any two relations $R_1, R_2 \subseteq \stateSpace \times \stateSpace$ with $R_1 \subseteq R_2$ and all $A \subseteq \stateSpace$ it holds that $R_1(A) \subseteq R_2(A)$. 
			Because $R$ is an $(\varepsilon, \delta)$-bisimulation, $R \subseteq {\sim_{\varepsilon, \delta}}$, and since $(s,t) \in R$ it follows that 
			\begin{align*}
				\prob(s, A) \overset{(s,t) \in R}{\leq} \prob(t, R(A)) + \varepsilon \overset{R(A) \, \subseteq \, {\sim_{\varepsilon, \delta}(A)}}{\leq} \prob(t, {\sim_{\varepsilon, \delta}}(A)) + \varepsilon
			\end{align*}
			for every $A \subseteq \stateSpace$, so $\sim_{\varepsilon, \delta}$ is indeed an $(\varepsilon, \delta)$-bisimulation. 

			\quad Now assume that there is a larger $(\varepsilon, \delta)$-bisimulation $R^*$ on $\mathcal{M}$, i.e., an $(\varepsilon, \delta)$-bisimulation $R^*$ such that ${\sim_{\varepsilon, \delta}} \subsetneq R^*$. Then there is some $(s,t) \in R^* \setminus {\sim_{\varepsilon, \delta}}$. However, as $R^*$ is an $(\varepsilon, \delta)$-bisimulation on $\mathcal{M}$, $R^* \subseteq {\sim_{\varepsilon, \delta}}$, and so $R^* \setminus {\sim_{\varepsilon, \delta}} = \emptyset$. Contradiction.
			\item 	It is clear that $\labelFunction(s) = \labelFunction(s') = \labelFunction(s'')$. Define 
			\begin{align*}
				R = \{(x, z) \in \stateSpace \times \stateSpace \mid \exists \, y \in \stateSpace \colon x \sim_{\varepsilon_1, \delta_1} y \text{ and } y \sim_{\varepsilon_2, \delta_2} z\}.
			\end{align*}
			Then it follows from the respective properties of $\sim_{\varepsilon_1, \delta_1}$ and $\sim_{\varepsilon_2, \delta_2}$ that $R$ is a symmetric and reflexive relation, and it holds that $(s,s'') \in R$. Moreover, for every pair of states $(x,z) \in R$, for which $y \in \stateSpace$ is a state satisfying the defining conditions of $R$ w.r.t. $x$ and $z$, we have that 
			\begin{align*}
				\vert \ln(\rate(x)) - \ln(\rate(z)) \vert &= \vert \ln(\rate(x)) - \ln(\rate(y)) + \ln(\rate(y)) - \ln(\rate(z)) \vert \\& \leq \vert \ln(\rate(x)) - \ln(\rate(y)) \vert + \vert \ln(\rate(y)) - \ln(\rate(z)) \vert \\&\leq \delta_1 + \delta_2.
			\end{align*}
			Now let $A \subseteq \stateSpace$. We first observe that ${\sim_{\varepsilon_2, \delta_2}}({\sim_{\varepsilon_1, \delta_1}}(A)) \subseteq R(A)$, since 
			\begin{align*}
				{\sim_{\varepsilon_2, \delta_2}}({\sim_{\varepsilon_1, \delta_1}}(A)) &= \{z \in \stateSpace \mid \exists \, y \in {\sim_{\varepsilon_1, \delta_1}}(A) \colon y \sim_{\varepsilon_2, \delta_2} z\} \\
				&= \{z \in S \mid \exists \, y \in \{x \in \stateSpace \mid \exists \, a \in A \colon a \sim_{\varepsilon_1, \delta_1} x \} \colon y \sim_{\varepsilon_2, \delta_2} z\} \\
				&= \{z \in S \mid \exists \, y \in \stateSpace \colon \exists \, a \in A \colon \underbrace{a \sim_{\varepsilon_1, \delta_1} y \text{ and } y \sim_{\varepsilon_2, \delta_2} z}_{(a, z) \in R}\} \\
				&\subseteq \{z \in S \mid \exists \, a \in A\colon (a, z) \in R \} = R(A).
			\end{align*}
			Hence, we get for all $(x, z) \in R$ and $y$ as above that
			\begin{align*}
				\prob(x, A)& \leq \prob(y, {\sim_{\varepsilon_1, \delta_1}}(A)) + \varepsilon_1 \\&\leq \prob(z, {\sim_{\varepsilon_2, \delta_2}}({\sim_{\varepsilon_1, \delta_1}}(A))) + \varepsilon_1 + \varepsilon_2 \\&\leq \prob(z, R(A)) + \varepsilon_1 + \varepsilon_2,
			\end{align*}
			so $R$ is a $(\varepsilon_1 + \varepsilon_2, \delta_1+ \delta_2)$-bisimulation. As $(s, s'') \in R$, the claim follows.
			\item We first observe that $\sim_{0, 0}$ is an equivalence. To see this, let $s \sim_{0,0} s'$ and $s' \sim_{0,0} s''$. By the additivity of $(\varepsilon, \delta)$-bisimulations proved in item 2 it follows that $s \sim_{0 + 0, 0 + 0} s''$, i.e., $s \sim_{0, 0} s''$, so $\sim_{0, 0}$ is transitive. As any $(\varepsilon, \delta)$-bisimulation is reflexive and symmetric by definition, and because $\sim_{\varepsilon, \delta}$ is itself an $(\varepsilon, \delta)$-bisimulation for any $\varepsilon, \delta \geq 0$ by item 1, $\sim_{0, 0}$ is an equivalence. 

			\quad Now let $s \sim_{0, 0} s'$. Then $\labelFunction(s) = \labelFunction(s')$ because $(\varepsilon, \delta)$-bisimulations only relate states with the same label. Furthermore, $\vert \ln(\rate(s)) - \ln(\rate(s')) \vert \leq 0$, so $\ln(\rate(s)) = \ln(\rate(s'))$ which, because of the strong monotonicity of $x \mapsto \ln(x)$ on $\mathbb{R}_{>0}$, is equivalent to $\rate(s) = \rate(s')$. By \Cref{lem:characterization-transitive}, the $\varepsilon$-condition for $\sim_{0,0}$ holds iff $\vert \prob(s, A) - \prob(s', A) \vert \leq 0$ iff $\prob(x, A) = \prob(y, A)$ for every $\sim_{0,0}$-closed set $A$ and any two states $(s,s') \in {\sim_{0,0}}$. As $s \sim_{0,0} s'$ and any equivalence class $C$ of $\sim_{0,0}$ is $\sim_{0, 0}$-closed it follows that for all these $C$, $\prob(s, C) = \prob(s', C)$. Thus, $\sim_{0, 0}$ is a strong bisimulation and hence $s \sim_{0,0} s'$ implies $s \sim s'$. 

			\quad In the other direction, let $s \sim s'$. The validity of the labeling- and the $\delta$-condition (for $\delta = 0$) follows as in the previous case. Again by \Cref{lem:characterization-transitive}, the only thing left to prove is that for every $\sim$-closed set $A$ we have $\prob(s, A) = \prob(s', A)$. As $\sim$ is an equivalence, the $\sim$-closed sets are precisely the (unions of) equivalence classes of $\sim$ \cite{RBBTEAPC}. Let $C = \bigcup_{i \in I} C_i$ be such a union for some countable index set $I \subseteq \mathbb{N}$ and equivalence classes $C_i \in \xfrac{\stateSpace}{\sim}$. Then 
			\begin{align*}
				\prob(s, C) = \sum_{i \in I} \prob(s, C_i) \overset{s \sim s'}{=} \sum_{i \in I} \prob(s', C_i) = \prob(s', C). 
			\end{align*}
			Hence, $\sim$ is a $(0, 0)$-bisimulation, and thus $s \sim s'$ implies $s \sim_{0, 0} s'$. 
		\end{enumerate}
	\end{proof}


	\CorAlgorithmicComplexity*
	\begin{proof}
		We adjust the algorithm proposed in \cite{AAPP} for computing $\sim_\varepsilon$ on DTMC in $\mathcal{O}(\vert \stateSpace \vert^7)$. To this end, we first observe that the $\varepsilon$-condition of $(\varepsilon, \delta)$-bisimulation is as for $\varepsilon$-bisimulations on DTMC (see \Cref{def:epsilon-bisimulation,def:epsilon-delta-bisimulation}). The $\varepsilon$-condition can hence be checked by solving specific maximum flow problems, just like in the algorithm of \cite{AAPP}. Furthermore, the $\delta$-condition is a purely state based property, and can hence be checked before considering the $\varepsilon$-condition at all. Thus, altering the algorithm of \cite{AAPP} such that the initial relation $R_0$ equals 
		\begin{align*}
			R_0 = \{(s,s') \in \stateSpace \times \stateSpace \mid \labelFunction(s) = \labelFunction(s') \text{ and } \vert \ln(\rate(s)) - \ln(\rate(s')) \vert \leq \delta\}
		\end{align*}
		causes the relation returned by the algorithm to equal $\sim_{\varepsilon, \delta}$, as it only relates states that satisfy both the labeling and the $\delta$-condition, and only removes states from one of the intermediate relations $R_i$ if they do not satisfy the $\varepsilon$-condition. Since the construction of $R_0$ as above requires at most $\vert \stateSpace \vert^2$ comparisons of state labels and $\vert \stateSpace \vert^2$ comparisons of (the logarithms of)  exit rates, the dominating part of the algorithm is still the (unchanged) loop, leading to the same algorithmic complexity as that of the computation of $\sim_\varepsilon$ on DTMC.
	\end{proof}


	\LemApproximatBisimulationInUniformization*
	\begin{proof}
		Let $s \sim_{\varepsilon, \delta} s'$, and let $\uniformizationRate \geq \max_{p \in \stateSpace} \rate(p)$ be a uniformization rate of $\mathcal{M}$. Recall that the probability distribution $\unifProb$ of $\uniformization{\mathcal{M}}{q}$ is given as \cite{MCASMP}
		\begin{align*}
			\unifProb(s, t) = 
			\begin{cases}
				\frac{\prob(s,t) \cdot \rate(s)}{\uniformizationRate}, & \text{if } s \neq t\\
				1 + \frac{\prob(s,s) \cdot \rate(s)}{\uniformizationRate} - \frac{\rate(s)}{\uniformizationRate}, & \text{if} s = t
			\end{cases}.
		\end{align*}
		In particular, this definition implies $\frac{\prob(s,s) \cdot \rate(s)}{\uniformizationRate} = \unifProb(s, s) + \frac{\rate(s)}{q} - 1$.

		The goal is to prove that $\sim_{\varepsilon, \delta}$ induces a $\tau$-bisimulation on $\uniformization{\mathcal{M}}{\uniformizationRate}$ for $\tau = e^\delta \cdot (1 +\varepsilon) - 1$. By definition, $\sim_{\varepsilon, \delta}$ only relates states with the same label. Thus, what remains to be checked is condition (ii) of \Cref{def:epsilon-bisimulation}. To this end, let $A \subseteq \stateSpace$. We distinguish three cases. 

		If $s \notin A$ and $s' \notin {\sim_{\varepsilon, \delta}} (A)$ then 
		\begin{align*}
			\unifProb(s, A) &= \frac{\prob(s, A) \cdot \rate(s)}{\uniformizationRate} \\
			&\leq \frac{(\prob(s', {\sim_{\varepsilon, \delta}}(A)) + \varepsilon) \cdot \rate(s') \cdot e^{\delta}}{\uniformizationRate} \\
			&= \underbrace{\frac{\prob(s', {\sim_{\varepsilon, \delta}}(A)) \cdot \rate(s')}{\uniformizationRate}}_{= \unifProb(s', {\sim_{\varepsilon, \delta}}(A))}  \cdot e^{\delta} + \underbrace{\frac{\varepsilon \cdot e^{\delta} \cdot \rate(s')}{\uniformizationRate}}_{\leq \varepsilon \cdot e^{\delta} \text{ as } \rate(s') \leq \uniformizationRate} \\
			&\leq \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) \cdot e^{\delta} + \varepsilon \cdot e^{\delta} \\
			&= \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + (e^{\delta} - 1) \cdot \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + \varepsilon \cdot e^{\delta} \\
			&\leq \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + e^{\delta} - 1 + \varepsilon \cdot e^{\delta} \\
			&= \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + e^{\delta} \cdot (1 + \varepsilon) - 1. 
		\end{align*}
		Otherwise, if $s \notin A$ but $s' \in {\sim_{\varepsilon, \delta}}(A)$ then 
		\begin{align*}
			\unifProb(s, A) &= \frac{\prob(s, A) \cdot \rate(s)}{q} \\&\leq \frac{(\prob(s', {\sim_{\varepsilon, \delta}}(A))+ \varepsilon)\cdot \rate(s') \cdot e^{\delta}}{\uniformizationRate} \\
			&= e^{\delta} \cdot \underbrace{\frac{\prob(s', {\sim_{\varepsilon, \delta}}(A) \setminus \{s'\}) \cdot \rate(s')}{\uniformizationRate}}_{= \unifProb(s', {\sim_{\varepsilon, \delta}}(A) \setminus \{s'\})} + \ e^{\delta} \cdot \underbrace{\frac{\prob(s', s')\cdot \rate(s')}{\uniformizationRate}}_{= \unifProb(s', s') + \frac{\rate(s')}{\uniformizationRate} - 1} + \frac{\varepsilon \cdot e^{\delta} \cdot\rate(s')}{\uniformizationRate} \\
			&= e^{\delta} \cdot \unifProb(s', {\sim_{\varepsilon, \delta}}(A) \setminus \{s'\}) + e^{\delta} \left(\unifProb(s', s') + \frac{\rate(s')}{\uniformizationRate} - 1 \right) + \frac{\varepsilon \cdot e^{\delta} \cdot \rate(s')}{\uniformizationRate} \\
			&= e^{\delta} \cdot \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + (1+\varepsilon)\cdot e^{\delta} \cdot \frac{\rate(s')}{\uniformizationRate} - e^{\delta} \\
			&= \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + (e^{\delta} - 1)\cdot \underbrace{\unifProb(s', {\sim_{\varepsilon, \delta}}(A))}_{\leq 1} + (1 + \varepsilon)\cdot e^{\delta} \cdot \underbrace{\frac{\rate(s')}{\uniformizationRate}}_{\leq 1} - e^{\delta} \\
			&\leq \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + e^{\delta} - 1 + (1+\varepsilon) \cdot e^\delta - e^{\delta} \\
			&= \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + e^{\delta} \cdot (1+\varepsilon) - 1.
		\end{align*}
		Lastly, if $s \in A$ then it immediately follows that $s' \in {\sim_{\varepsilon, \delta}}(A)$ as $s \sim_{\varepsilon, \delta} s'$ and 
		\begin{align*}
			\unifProb(s, A) = \frac{\prob(s, A) \cdot \rate(s)}{\uniformizationRate} + 1 - \frac{\rate(s)}{q} = \frac{(\prob(s, A) - 1) \cdot \rate(s)}{q} + 1.
		\end{align*}
		As $\prob(s, A) - 1 \leq 0$, it follows that
		\begin{align*}
			\unifProb(s, A) &\leq \frac{(\prob(s', {\sim_{\varepsilon, \delta}}(A)) + \varepsilon - 1) \cdot e^{-\delta}\cdot \rate(s')}{\uniformizationRate} + 1 \\
			&= e^{-\delta} \cdot \underbrace{\frac{\prob(s', {\sim_{\varepsilon, \delta}}(A) \setminus \{s'\}) \cdot \rate(s')}{\uniformizationRate}}_{= \unifProb(s', {\sim_{\varepsilon, \delta}}(A) \setminus \{s'\})} + e^{-\delta} \cdot \underbrace{\frac{\prob(s', s') \cdot \rate(s')}{\uniformizationRate}}_{= \unifProb(s', s') + \frac{\rate(s')}{\uniformizationRate} - 1} \\&\qquad + (\varepsilon-1) \cdot \frac{e^{-\delta} \cdot \rate(s')}{\uniformizationRate} + 1 \\
			&= \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + (e^{-\delta} - 1) \cdot \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) \\& \qquad + e^{-\delta} \cdot \frac{\rate(s')}{\uniformizationRate} - e^{-\delta} + (\varepsilon-1) \cdot \frac{e^{-\delta} \cdot \rate(s')}{\uniformizationRate} + 1 \\
			&= \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + \underbrace{\underbrace{(e^{-\delta} - 1)}_{\leq 0} \cdot \unifProb(s', {\sim_{\varepsilon, \delta}}(A))}_{\leq 0} - e^{-\delta} + \varepsilon \cdot e^{-\delta} \cdot \underbrace{\frac{\rate(s')}{\uniformizationRate}}_{\leq 1}  + 1  \\
			&\leq \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) - e^{-\delta} + \varepsilon \cdot e^{-\delta} + 1 \\
			&= \unifProb(s', {\sim_{\varepsilon, \delta}}(A)) + e^{-\delta} \cdot ( \varepsilon - 1) + 1
		\end{align*}
		Hence, $\sim_{\varepsilon, \delta}$ induces a $\max\{1 + e^{-\delta} \cdot (\varepsilon -1), e^{\delta} \cdot (1 + \varepsilon) -1 \}$-bisimulation on the uniformized DTMC $\uniformization{\mathcal{M}}{\uniformizationRate}$. As this maximum is, for any $\varepsilon, \delta \geq 0$, attained at $e^{\delta} \cdot ( 1 + \varepsilon) - 1$, the claim follows. 
	\end{proof}

	\PropConnectionTauLump*
	\begin{proof}
		Let $C \in \xfrac{\stateSpace}{R}$ and $(s, s') \in R$. Then 
		\begin{align*}
			\prob(s,C) \cdot \rate(s) &\leq (\prob(s', C) + \varepsilon)\cdot \rate(s') \cdot e^{\delta} \\
			&= \prob(s', C) \cdot \rate(s') \cdot e^{\delta} + \varepsilon \cdot \rate(s') \cdot e^{\delta} \\
			&= \prob(s', C) \cdot \rate(s') + (e^{\delta} - 1) \cdot \prob(s', C) \cdot \rate(s') + \varepsilon \cdot \rate(s') \cdot e^{\delta} \\
			&= \prob(s', C) \cdot \rate(s') + \rate(s') \cdot ((e^{\delta} - 1)\cdot \prob(s', C) + \varepsilon \cdot e^{\delta}) \\
			&\leq \prob(s', C) \cdot \rate(s') + \rate(s') \cdot (e^{\delta} -1 + \varepsilon \cdot e^{\delta}) \\
			& \leq \prob(s', C) \cdot \rate(s') + q \cdot (e^{\delta} \cdot (1 + \varepsilon) - 1).
		\end{align*}
		With the same calculations, $\prob(s', C) \cdot \rate(s') \leq \prob(s, C) \cdot \rate(s) + q \cdot (e^{\delta} \cdot (1 + \varepsilon) -1)$, and so $\vert \rate(s, C) - \rate(s', C) \vert \leq q \cdot (e^\delta \cdot (1+\varepsilon) - 1)$ for all equivalence classes $C$ of $R$ and all $(s,s') \in R$. Thus, $\xfrac{S}{R}$ is a $q \cdot(e^{\delta} \cdot (1 + \varepsilon) - 1)$-lumpability of $\stateSpace$.
	\end{proof}

