	\PropTauLumpDoesNotImplyEpsilonDelta*
	\begin{proof}
		Let $\varepsilon \in (0, 1)$, $\delta > 0, \tau > 0$ and $n \in \mathbb{N}$ with \mbox{$n > \max\{\frac{\varepsilon\cdot(\tau + 1)}{\tau\cdot(1 - \varepsilon)}, \frac{e^{\delta}}{\tau} - 1\}$.} We consider a CTMC $\mathcal{M} = \mathcal{M}(\varepsilon, \delta, \tau)$. It has states $s, s', g, s_1, \ldots, s_n$ and transition probabilities $\prob(s, g) = 1, \prob(s', g) = \frac{1 + \tau}{1 + (n+1)\tau}, \prob(s', s_i) = \frac{\tau}{1 + (n+1)\tau}$ for all $i = 1, \ldots, n$, and self-loops in the remaining states. For our purpose, only the exit rates of states $s$ and $s'$ matter, which are $\rate(s) = 1$ and $\rate(s') = 1 + (n+1) \cdot \tau$. The labeling function $\labelFunction$ is such that $\labelFunction(s) = \labelFunction(s') = a$ and it assigns unique labels $a_x$ to all other states $x$. In particular, besides $s$ and $s'$ no two states have the same label. A depiction of $\mathcal{M}$ can be found in \Cref{fig:cex-lumpability}.

		In $\mathcal{M}$, the pair $(s,s')$ does not satisfy the $\delta$-condition since
		\begin{align*}
			\vert \rate(s) - \rate(s') \vert = \vert 1 - (1 + (n+1) \cdot \tau) \vert = (n+1) \cdot \tau > \left(\frac{e^{\delta}}{\tau} - 1 + 1 \right) \cdot \tau = e^{\delta}.
		\end{align*} 
		Moreover, the $\varepsilon$-condition is violated because 
		\begin{align*}
			\prob(s', \{g\}) + \varepsilon &= \frac{1 + \tau}{1 + (n+1)\cdot \tau} + \varepsilon 
			\\&< \frac{1 + \tau}{1 + (\frac{\varepsilon\cdot(\tau +1)}{\tau\cdot (1-\varepsilon)} + 1) \cdot \tau} + \varepsilon 
			\\&= \frac{1 + \tau}{1 + \frac{\varepsilon \cdot(\tau + 1) + \tau \cdot (1 - \varepsilon)}{1 - \varepsilon}} + \varepsilon 
			\\&= \frac{1+ \tau}{1 + \frac{\varepsilon + \tau}{1 - \varepsilon}} + \varepsilon 
			\\&= \frac{1 + \tau}{\frac{\varepsilon + \tau + 1 - \varepsilon}{1 - \varepsilon}} + \varepsilon \\&= \frac{1+\tau}{1 + \tau} \cdot (1 - \varepsilon) + \varepsilon 
			\\&= 1 = \prob(s, \{g\})
		\end{align*}
		The partition $\Omega = \{\{s, s'\}, \{g\}\} \cup \{\{s_i\} \mid i = 1, \ldots, n\}$ that relates $s$ and $s'$ is, however, a $\tau$-quasi lumpability since 
		\begin{align*}
			\vert \prob(s, \{g\})  \rate(s)- \prob(s', \{g\})  \rate(s') \vert &= \left \vert 1 - \left(\frac{1 + \tau}{1 + (n+1) \cdot \tau} \right) \cdot (1 + (n+1) \cdot \tau)  \right \vert \\&= \left \vert 1 - (1 + \tau) \right \vert = \tau
		\end{align*} 
		and, for all $i$, 
		\begin{align*}
			\vert \prob(s, \{s_i\})  \rate(s) - \prob(s', \{s_i\})  \rate(s') \vert = \left\vert \frac{\tau}{1 + (n+1)\tau} \cdot (1 + (n+1) \cdot \tau) \right \vert = \tau.
		\end{align*}
	\end{proof}

	\ThmSameStructureConstruction*
	\begin{proof}
		We start by defining the models $\mathcal{M}'$ and $\mathcal{N}'$. They both share the same state space $\stateSpace' = \stateSpace^\mathcal{M} \times \stateSpace^\mathcal{N}$, with initial state $\initialState' = (\initialState^\mathcal{M}, \initialState^\mathcal{N})$. The label function $\labelFunction'$ of both models is defined to be $\labelFunction'((s,t)) = \labelFunction^\mathcal{N}(t)$, and the exit rate functions are defined via 
		\begin{align*}
			{\rate^\mathcal{M}}'((s,t)) &= \begin{cases}
				\rate^\mathcal{M}(s), &\text{if } s \sim_{\varepsilon, \delta} \! \! t \\
				\rate^\mathcal{N}(t), &\text{if} s \nsim_{\varepsilon, \delta} t
			\end{cases} \qquad \text{and} \qquad
			{\rate^\mathcal{N}}'((s,t)) = \rate^\mathcal{N}(t).
		\end{align*}
		Lastly, the common transition probability function is defined as 
		\begin{align*}
			\prob'((s,t), (s',t')) &= \begin{cases}
				\Delta_{s,t}(s',t') \prob^\mathcal{M}(s,s'), &\text{if } s \sim_{\varepsilon, \delta} t, s' \in \Succ(s), t' \in \Succ(t) \\
				\prob^\mathcal{M}(s,s')  \prob^\mathcal{N}(t,t') &\text{if } s \nsim_{\varepsilon, \delta} t \\
				0, &\text{otherwise}
			\end{cases}
		\end{align*}
		where, for a given pair $(s,t) \in \stateSpace'$ with $s \sim_{\varepsilon, \delta} t$, $\Delta_{s,t} \colon \Succ(s) \to \Distr(\Succ(t))$ is a weight function as in \Cref{lem:characterization-weight-functions-concur}. Note that $\Delta_{s,t}$ exists for every such pair $(s,t)$ as any two $(\varepsilon, \delta)$-bisimilar states are $\varepsilon$-bisimilar in the DTMCs underlying $\mathcal{M}$ and $\mathcal{N}$ by the definition of $(\varepsilon, \delta)$-bisimulations. All in all, we thus have $\mathcal{M}' = (\stateSpace', \prob', {\rate^\mathcal{M}}', \initialState', \labelFunction')$ and $\mathcal{N}' = (\stateSpace', \prob', {\rate^\mathcal{N}}', \initialState', \labelFunction')$.

		To ensure well-definedness of $\mathcal{M}'$ and $\mathcal{N}'$, we first show that $\prob'$ is actually a probability distribution on $\stateSpace'$. To this end, let $(s,t) \in \stateSpace'$. If $s \sim_{\varepsilon, \delta} t$ then, by definition of $\prob'$, we have $\prob'((s,t), (s',t')) = 0$ if $s' \notin \Succ(s)$ or $t' \notin \Succ(t)$, i.e., $\prob'((s,t), (s',t')) = 0$ for every $(s',t') \notin (\Succ(s) \times \Succ(t))$. Hence, 
		\begin{align*}
			\prob'((s,t), \stateSpace') &= \sum_{(s', t') \in (\Succ(s) \times \Succ(t))} \prob'((s,t), (s',t')) \\
			&= \sum_{(s', t') \in (\Succ(s) \times \Succ(t))} \Delta_{s,t}(s', t') \cdot \prob^\mathcal{M}(s,s') \\
			&= \sum_{s' \in \Succ(s)} \prob^\mathcal{M}(s,s') \cdot \underbrace{\sum_{t' \in \Succ(t)} \Delta_{s,t}(s',t')}_{=1 \text{ as} \Delta_{s,t}(s', \cdot) \in \Distr(Succ(t))} \\
			&= \sum_{s' \in \Succ(s)} \prob^\mathcal{M}(s,s') = 1.  
		\end{align*}
		Otherwise, if $s \nsim_{\varepsilon, \delta} t$ then 
		\begin{align*}
			\prob'((s,t), \stateSpace') &= \sum_{(s',t') \in \stateSpace'}\prob^\mathcal{M}(s,s') \cdot \prob^\mathcal{N}(t,t') \\&= \sum_{s' \in \stateSpace^\mathcal{M}} \prob^\mathcal{M}(s,s') \cdot \sum_{t' \in \stateSpace^\mathcal{N}}  \prob^\mathcal{N}(t,t') = 1.
		\end{align*}

		We now prove that $\mathcal{M} \sim_{\varepsilon, 0} \mathcal{M}' \sim_{0, \delta} \mathcal{N}' \sim \mathcal{N}$. 

		\medskip

		\textbf{$\mathcal{M}' \sim_{0, \delta} \mathcal{N}'$: } \qquad Consider the identity relation $R_{id} = \{((s,t), (s,t)) \mid (s,t) \in \stateSpace'\}$ on $\stateSpace'$. $R_{id}$ is reflexive, symmetric and only relates states with the same label. Furthermore, since both $\mathcal{M}'$ and $\mathcal{N}'$ have the same transition probability function $\prob'$, the $\varepsilon$-condition of \Cref{def:epsilon-delta-bisimulation} is satisfied for $\varepsilon = 0$. Lastly, regarding the $\delta$-condition, we distinguish two cases. If $s \sim_{\varepsilon, \delta} t$ then 
		\begin{align*}
			\vert \ln ({\rate^\mathcal{M}}'((s,t))) - \ln({\rate^\mathcal{N}}'((s,t))) \vert = \vert \ln(\rate^\mathcal{M}(s)) - \ln(\rate^\mathcal{N}(t)) \vert \leq \delta.
		\end{align*}
		Otherwise, if $s \nsim_{\varepsilon, \delta} t$ then ${\rate^\mathcal{M}}'((s,t)) = \rate^\mathcal{N}(t) = {\rate^\mathcal{N}}'((s,t))$ and the $\delta$-condition holds trivially. Hence, $R_{id}$ is a $(0, \delta)$-bisimulation, and since it relates the initial states of both $\mathcal{M}'$ and $\mathcal{N}'$ it follows that $\mathcal{M}' \sim_{0, \delta}\mathcal{N}'$.

		\medskip 

		\textbf{$\mathcal{M} \sim_{\varepsilon, 0} \mathcal{M}'$: } \qquad Denote by $R \subseteq \stateSpace^\mathcal{M} \times \stateSpace'$ the reflexive and symmetric closure of 
		\begin{align*}
			\{(s,(s,t)) \mid s \in \stateSpace^\mathcal{M}, (s,t) \in \stateSpace' \text{ such that } s \sim_{\varepsilon, \delta} t\}.
		\end{align*}
		Note that, in particular, $(\initialState^\mathcal{M}, \initialState') \in R$ as $\initialState^\mathcal{M} \sim_{\varepsilon, \delta} \initialState^\mathcal{N}$ by assumption.

		Let $(s,(s,t)) \in R$ (the case for $((s,t), s) \in R$ works analogously, and the cases $(s,s) \in R$ resp. $((s,t), (s,t)) \in R$ are trivial). Then $\labelFunction'((s,t)) = \labelFunction^\mathcal{N}(t) = \labelFunction^\mathcal{M}(s)$ since $s \sim_{\varepsilon, \delta} t$, and 
		\begin{align*}
			\vert \ln (\rate^\mathcal{M}(s)) - \ln ({\rate^\mathcal{M}}'((s,t))) \vert = \vert \ln (\rate^\mathcal{M}(s)) - \ln (\rate^\mathcal{M}(s)) \vert = 0,
		\end{align*}
		so $R$ satisfies both the labeling- and the $\delta$-condition (for $\delta = 0$) of \Cref{def:epsilon-delta-bisimulation}. 

		The only thing left to prove for $R$ to be an $(\varepsilon, 0)$-bisimulation is thus the $\varepsilon$-condition. To see that this conditions holds, let $A \subseteq \stateSpace^\mathcal{M} \cup \stateSpace'$. Then 
		\begin{align*}
			\prob'((s,t), R(A)) = \sum_{(s', t') \in R(A)} \prob'((s,t), (s',t')) = \sum_{\substack{(s',t') \in R(A) \\ s' \in \Succ(s) \\ t' \in \Succ(t)}} \prob'((s,t), (s',t')) 
		\end{align*}
		where the second equality follows from the definition of $\prob'$ since $s \sim_{\varepsilon, \delta} t$. 

		By the definition of $R$ every $(s', t')$ with $s' \in A \cap \Succ(s)$ and $t' \in {\sim_{\varepsilon, \delta}}{\{s'\}} \cap \Succ(t)$ is contained in $R(A)$, i.e., $\{(s',t') \in R(A) \mid s' \in \Succ(s), t' \in \Succ(t)\}$ is a superset of $\{(s',t') \in \stateSpace' \mid s' \in A \cap \Succ(s), t' \in \Succ(t) \cap {\sim_{\varepsilon, \delta}}(\{s'\})\}$. Thus,
		\begin{align*}
			\prob'((s,t), R(A)) &= \sum_{\substack{(s',t') \in R(A) \\ s' \in \Succ(s) \\ t' \in \Succ(t)}} \prob'((s,t), (s',t')) \\
			&\geq \sum_{s' \in \Succ(s) \cap A} \sum_{t'\in \Succ(t) \cap {\sim_{\varepsilon,\delta}}(\{s'\})} \prob'((s,t), (s',t')) \\
			&= \sum_{s' \in \Succ(s) \cap A} \sum_{t'\in \Succ(t)\cap {\sim_{\varepsilon,\delta}}(\{s'\})} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \\
			&= \sum_{s' \in \Succ(s) \cap A} \sum_{t'\in \Succ(t)} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \\& \qquad - \sum_{s' \in \Succ(s) \cap A} \sum_{t'\in {\Succ(t) \setminus \sim_{\varepsilon,\delta}}(\{s'\})} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \\
			&= \prob^\mathcal{M}(s, A) - \sum_{s' \in \Succ(s) \cap A} \sum_{t'\in {\Succ(t) \setminus \sim_{\varepsilon,\delta}}(\{s'\})} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t')
		\end{align*}
		as $\sum_{t' \in \Succ(t)} \Delta_{s,t}(s',t') = 1$ since $\Delta_{s,t}(s', \cdot) \in \Distr(\Succ(t))$. The sum in the previous term can then be bounded from above via
		\begin{align}
			&\textcolor{white}{=} \sum_{s' \in \Succ(s) \cap A} \sum_{t'\in {\Succ(t) \setminus \sim_{\varepsilon,\delta}}(\{s'\})} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \nonumber \\&\leq \sum_{s' \in \Succ(s)} \sum_{t'\in {\Succ(t) \setminus \sim_{\varepsilon,\delta}}(\{s'\})} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \nonumber \\
			&= \sum_{s'\in \Succ(s)} \prob^\mathcal{M}(s,s') \cdot \left(1 - \sum_{t' \in \Succ(t) \cap {\sim_{\varepsilon, \delta}}(\{s'\})} \Delta_{s,t}(s',t') \right) \nonumber \\
			&= 1 - \underbrace{\sum_{s' \in \Succ(s)}\sum_{t' \in \Succ(t) \cap {\sim_{\varepsilon, \delta}}(\{s'\})} \prob^\mathcal{M}(s,s') \cdot  \Delta_{s,t}(s',t')}_{\geq 1 - \varepsilon \text{ by condition (2) of  \Cref{lem:characterization-weight-functions-concur}} } \nonumber \\
			&\leq 1 - (1-\varepsilon) = \varepsilon. \label{eq:same-structure-2}
		\end{align}
		All in all, this yields that 
		\begin{align*}
			\prob'((s,t), R(A)) &\geq  \prob^\mathcal{M}(s, A) - \underbrace{\sum_{s' \in \Succ(s) \cap A} \sum_{t'\in {\Succ(t) \setminus \sim_{\varepsilon,\delta}}(\{s'\})} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t')}_{\leq \varepsilon \text{ by \Cref{eq:same-structure-2}}} \\&\geq \prob^\mathcal{M}(s,A) - \varepsilon,
		\end{align*}
		which is equivalent to the $\varepsilon$-condition
		\begin{align*}
			\prob^\mathcal{M}(s,A) \leq \prob'((s,t), R(A)) + \varepsilon.
		\end{align*}

		To prove that $\prob'((s,t), A) \leq \prob^\mathcal{M}(s,R(A)) + \varepsilon$ for all $A \subseteq S$, we first observe that since $(s,(s,t)) \in R$ it again has to hold that $s \sim_{\varepsilon, \delta} t$, so we get 
		\begin{align}
			\prob'((s,t), A) &= \sum_{(s', t') \in A} \prob'((s,t), (s',t')) \nonumber \\
			&= \sum_{\substack{(s',t') \in A \\ s' \in \Succ(s) \\ t' \in \Succ(t)}} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \nonumber\\
			&= \sum_{\substack{(s',t') \in A \\ s' \in \Succ(s) \\ t' \in \Succ(t) \cap {\sim_{\varepsilon, \delta}}(\{s'\})}} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \nonumber\\& \qquad+ \sum_{\substack{(s',t') \in A \\ s' \in \Succ(s) \\ t' \in \Succ(t) \setminus {\sim_{\varepsilon, \delta}}(\{s'\})}} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \label{eq:same-struct-1}
		\end{align}

		As $(s', t') \in A$ with $s' \sim_{\varepsilon, \delta} t'$ implies $s' \in R(A)$ it follows that the first sum in \Cref{eq:same-struct-1} can be bounded from above via
		\begin{align*}
			&\sum_{\substack{(s',t') \in A \\ s' \in \Succ(s) \\ t' \in \Succ(t) \cap {\sim_{\varepsilon, \delta}}(\{s'\})}} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \\&\leq \sum_{s' \in \Succ(s) \cap R(A)} \sum_{t'\in \Succ(t) \cap {\sim_{\varepsilon, \delta}}(\{s'\}) }\prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \\
			&\leq \sum_{s' \in \Succ(s) \cap R(A)} \prob^\mathcal{M}(s,s') \cdot \sum_{t'\in \Succ(t)} \Delta_{s,t}(s',t') \\
			&= \prob^\mathcal{M}(s,R(A)).
		\end{align*}
		Furthermore, similar to \Cref{eq:same-structure-2}, the second sum of \Cref{eq:same-struct-1} satisfies 
		\begin{align*}
			&\sum_{\substack{(s',t') \in A \\ s' \in \Succ(s) \\ t' \in \Succ(t) \setminus {\sim_{\varepsilon, \delta}}(\{s'\})}} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \leq \varepsilon.
		\end{align*}
		Hence, \Cref{eq:same-struct-1} becomes
		\begin{align*}
			\prob'((s,t), A) &= \sum_{\substack{(s',t') \in A \\ s' \in \Succ(s) \\ t' \in \Succ(t) \cap {\sim_{\varepsilon, \delta}}(\{s'\})}} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \nonumber\\& \qquad+ \sum_{\substack{(s',t') \in A \\ s' \in \Succ(s) \\ t' \in \Succ(t) \setminus {\sim_{\varepsilon, \delta}}(\{s'\})}} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \\
			&\leq \prob^\mathcal{M}(s, R(A)) + \varepsilon.
		\end{align*}
		All in all, this proves that $R$ is an $(\varepsilon,0)$-bisimulation, and thus $\mathcal{M} \sim_{\varepsilon, 0} \mathcal{M}'$. 

		\medskip 

		\textbf{$\mathcal{N}' \sim \mathcal{N}$: } \qquad Let $R'$ be the smallest equivalence on $\stateSpace^\mathcal{N} \cup \stateSpace'$ that contains all pairs $(t, (s,t))$ with $t \in \stateSpace^\mathcal{N}$ and $s \in \stateSpace^\mathcal{M}$. It is easy to see that every equivalence class of $R'$ is of the form $C = \{t\} \cup (\stateSpace^\mathcal{M} \times \{t\})$ for some $t \in \stateSpace^\mathcal{N}$. 

		Now, let $(x,y) \in R$. In the case that $x = y = t$ or $x = y = (s,t)$ for some $t \in \stateSpace^\mathcal{N}$ resp. some $(s,t) \in \stateSpace'$ it is clear that $R'$ satisfies all conditions of a strong bisimulation w.r.t. the pair $(x,y)$. 

		Otherwise, we consider two cases. If, on the one hand, $x = t\in \stateSpace^\mathcal{N}$ and $y \in \stateSpace'$ (or the other way around, which can be proved analogously) it follows from the definition of $R'$ that $y = (s,t)$ for some $s \in \stateSpace^\mathcal{M}$, i.e., that $(x,y) = (t, (s,t))$. By definition we have $\labelFunction'((s,t)) = \labelFunction^\mathcal{N}(t)$ and ${\rate^\mathcal{N}}'((s,t)) = \rate^\mathcal{N}(t)$, so we only need to check the transition probabilities. To this end, let $C = \{t'\} \cup (\stateSpace^\mathcal{M} \times \{t'\})$ be some equivalence class of $R'$. If $s \sim_{\varepsilon, \delta} t$ in $\mathcal{M} \oplus \mathcal{N}$ then there is a weight function $\Delta_{s,t}$ as in \Cref{lem:characterization-weight-functions-concur} for the pair $(s,t)$. If additionally $t' \in \Succ(t)$ we get
		\begin{align*}
			\prob^\mathcal{N}(t,C) &= \prob^\mathcal{N}(t,t') \\
			&= \sum_{s' \in \Succ(s)} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') \\
			&= \sum_{s' \in \Succ(s)} \prob^\mathcal{M}(s,s') \cdot \Delta_{s,t}(s',t') + \underbrace{ \sum_{s' \in \stateSpace^\mathcal{M} \setminus \Succ(s)} \prob'((s,t), (s',t'))}_{= 0} \\
			&= \sum_{s' \in \Succ(s)} \prob'((s,t), (s',t')) + \sum_{s'\in \stateSpace^\mathcal{M} \setminus \Succ(s)} \prob'((s,t), (s',t')) \\
			&= \sum_{s' \in \stateSpace^\mathcal{M}} \prob'((s,t), (s', t')) \\
			&= \sum_{(s', t') \in C} \prob'((s,t), (s',t')) = \prob'((s,t), C),
		\end{align*}
		while in the case that $t' \notin \Succ(t)$ we have 
		\begin{align*}
			\prob^\mathcal{N}(t,C) &= \prob^\mathcal{N}(t,t') = 0 = \sum_{(s',t') \in C} \prob'((s,t), (s',t')).
		\end{align*}
		Moreover, if $s \nsim_{\varepsilon, \delta} t$, we get 
		\begin{align*}
			\prob^\mathcal{N}(t,C) &= \prob^\mathcal{N}(t,t') \\
			&= \prob^\mathcal{N}(t,t') \cdot \sum_{s' \in \stateSpace^\mathcal{M}}\prob^\mathcal{M}(s,s') \\
			&= \sum_{s' \in \stateSpace^\mathcal{M}} \prob^\mathcal{M}(s,s') \cdot \prob^\mathcal{N}(t,t') \\
			&= \sum_{s' \in \stateSpace^\mathcal{M}} \prob'((s,t),(s',t')) \\
			&= \sum_{(s',t') \in C} \prob'((s,t), (s',t')) = \prob'((s,t), C). 
		\end{align*}

		If, on the other hand, $x,y \in \stateSpace'$ it follows from the definition of $R'$ that there is some $t \in \stateSpace^\mathcal{N}$ such that $x = (s, t)$ and $y = (s', t)$. Let $C = \{t'\} \cup (\stateSpace^\mathcal{M} \times \{t'\})$ be an equivalence class of $R'$. 

		We again do a case distinction, depending on the $(\varepsilon, \delta)$-bisimilarity of $t$ and $s$ resp. $s'$ in $\mathcal{M} \oplus \mathcal{N}$. In the case that $s \sim_{\varepsilon, \delta} t$, $s' \sim_{\varepsilon, \delta} t$ and $t' \in \Succ(t)$ we have 
		\begin{align*}
			\prob'((s,t), C) &= \sum_{(p,t') \in C} \prob'((s,t), (p,t')) \\&= \sum_{p \in \Succ(s)} \prob^\mathcal{M}(s,p) \cdot \Delta_{s,t}(p,t') \\&= \prob^\mathcal{N}(t,t') \\
			&= \sum_{p \in \Succ(s')} \prob^\mathcal{M}(s', p) \cdot \Delta_{s', t}(p, t')\\&= \sum_{(p, t') \in C} \prob'((s', t), (p, t')) \\&= \prob'((s',t), C),
		\end{align*}
		while if $t' \notin \Succ(t)$ it holds that 
		\begin{align*}
			\prob'((s,t), C) = 0 = \prob'((s', t), C).
		\end{align*}
		Otherwise, if $s \nsim_{\varepsilon, \delta} t$ and $s' \nsim_{\varepsilon, \delta} t$ then 
		\begin{align*}
			\prob'((s,t), C) &= \sum_{(p, t') \in C} \prob^\mathcal{M}(s,p) \cdot \prob^\mathcal{N}(t,t') \\&= \sum_{p \in S^\mathcal{M}} \prob^\mathcal{M}(s,p) \cdot \prob^\mathcal{N}(t,t') \\&= \prob^\mathcal{N}(t,t') \\
			&= \sum_{p \in S^\mathcal{M}} \prob^\mathcal{M}(s',p) \cdot \prob^\mathcal{N}(t,t') \\&= \prob'((s', t), C). 
		\end{align*}

		Lastly, if $s \sim_{\varepsilon, \delta} t$ and $s' \nsim_{\varepsilon, \delta} t$ (or the other way around), we have if $t' \notin \Succ(t)$ that 
		\begin{align*}
			\prob'((s,t), C) = 0 &= \sum_{p \in S^\mathcal{M}} \prob^\mathcal{M}(s',p) \cdot \underbrace{\prob^\mathcal{N}(t,t')}_{=0} = \sum_{(p,t') \in C} \prob'((s',t),(p,t')) \\&=  \prob'((s', t), C),
		\end{align*}
		while for $t' \in \Succ(t)$ we get
		\begin{align*}
			\prob'((s,t), C) &= \sum_{(p, t') \in C} \prob'((s,t), (p, t')) \\&= \sum_{p \in \Succ(s)} \prob^\mathcal{M}(s,p) \cdot \Delta_{s,t}(p,t') \\&= \prob^\mathcal{N}(t, t') \\
			&=  \prob^\mathcal{N}(t,t') \cdot \sum_{p \in \stateSpace^\mathcal{M}}\prob^\mathcal{M}(s',p) \\&= \sum_{p \in \stateSpace^\mathcal{M}}\prob^\mathcal{M}(s',p) \cdot \prob^\mathcal{N}(t,t') \\&= \prob'((s', t), C)
		\end{align*}

		All in all, the previous calculations proved that, for every pair of states $(x,y) \in R'$ and any $R'$-equivalence class $C$ we have $\prob'(x, C) = \prob'(y, C)$, and hence $R'$ is a strong bisimulation between $\mathcal{N}$ and $\mathcal{N}'$. As $R'$ in particular relates the initial states of $\mathcal{N}$ and $\mathcal{N}'$ it follows that $\mathcal{N}' \sim \mathcal{N}$. 
	\end{proof}




