	\PropTransientBoundsEpsilonDeltaGreateZero*
	\begin{proof}
		Let $\uniformizationRate$ be a uniformization rate of $\mathcal{M}$, i.e., $\uniformizationRate \geq \max_{s \in \stateSpace} \rate(s)$. From \Cref{lem:approximate-bisimulation-in-uniformization} we know that in $\uniformization{\mathcal{M}}{\uniformizationRate}$ we have $s \sim_{e^\delta \cdot(1 + \varepsilon) - 1} s'$. 

		\Cref{thm:main-result-rbbteapc} \cite{RBBTEAPC} together with the fact that the probability to reach $g$ from $s$ resp. $s'$ after at most $k$ steps in $\uniformization{\mathcal{M}}{\uniformizationRate}$ coincides with the entries $\unifProbMatrix^k_{s,g}$ resp. $\unifProbMatrix^k_{s', g}$ at positions $[s,g]$ resp. $[s', g]$ of $\unifProbMatrix^k$ \cite{PoMC} yields the desired bound via
		\begin{align*}
			\vert \probMeasure_s(\reachability^{\leq t} g) - \probMeasure_{s'}(\reachability^{\leq t} g) 	\vert &= e^{-\uniformizationRate \cdot t} \cdot \left \vert \sum_{k = 0}^\infty \frac{(\uniformizationRate \cdot t)^k}{k!} \cdot (\unifProbMatrix^k_{s,g} - \unifProbMatrix^k_{s', g}) \right \vert \\
			&= e^{-\uniformizationRate \cdot t} \cdot \left \vert \sum_{k = 0}^\infty \frac{(\uniformizationRate \cdot t)^k}{k!} \cdot (\probMeasure_s(\reachability^{\leq k} g) - \probMeasure_{s'}(\reachability^{\leq k} g)) \right \vert \\
			&\leq e^{-\uniformizationRate \cdot t} \cdot \sum_{k=0}^\infty \frac{(\uniformizationRate \cdot  t)^k}{k!} \cdot \vert 	\probMeasure_s(\reachability^{\leq k} g) - \probMeasure_{s'}(\reachability^{\leq k} g) \vert \\
			&\leq e^{-\uniformizationRate\cdot  t} \cdot\sum_{k=0}^\infty \frac{(\uniformizationRate \cdot t)^k}{k!} \cdot (1 - 	(1-(e^\delta \cdot(1 + \varepsilon) - 1))^k) \\
			&= e^{-\uniformizationRate \cdot  t} \cdot \sum_{k=0}^\infty \frac{(\uniformizationRate \cdot  t)^k}{k!} \cdot (1 - (2- e	^\delta \cdot(1 + \varepsilon))^k) \\
			&= e^{-\uniformizationRate\cdot t} \cdot \underbrace{\sum_{k = 0}^{\infty} \frac{(q\cdot t)^k}{k!}}_{= e	^{\uniformizationRate\cdot t}} - e^{- \uniformizationRate\cdot t} \cdot \underbrace{\sum_{k=0}^{\infty} \frac{(\uniformizationRate \cdot t \cdot (2-e^{\delta} \cdot (1 + \varepsilon)))^k}{k!}}_{= e^{\uniformizationRate\cdot t \cdot (2-e^{\delta} \cdot ( 1+ \varepsilon))}} \\ 
			&= e^{-\uniformizationRate \cdot t} \cdot e^{\uniformizationRate \cdot t} - e^{-\uniformizationRate \cdot t} \cdot e^{\uniformizationRate\cdot t \cdot (2-e^{\delta} \cdot (1 + \varepsilon))} \\
			&= 1 - e^{-\uniformizationRate \cdot t + 2 \cdot \uniformizationRate \cdot t - \uniformizationRate \cdot t \cdot e^{\delta} \cdot (1 + \varepsilon)} \\
			&= 1 - e^{-\uniformizationRate \cdot t \cdot (e^\delta \cdot(1 + \varepsilon)-1)}.
		\end{align*}
	\end{proof}


	\ThmParetoCurveUnif*
	\begin{proof}
		By \Cref{prop:transient-prob-bounds-epsilon-delta-greater-0}, $\vert \probMeasure_s(\reachability^{\leq t} g) - \probMeasure_{s'}(\reachability^{\leq t} g) \vert \leq 1 - e^{- q \cdot t \cdot (e^{\delta}\cdot ( 1+ \varepsilon) - 1)}$. Hence, if $1 -e^{- q \cdot t \cdot (e^{\delta}\cdot ( 1+ \varepsilon) - 1)} \leq \theta$ it immediately follows that also the absolute difference in the probabilities to reach $g$ after at most time $t$ between $s$ and $s'$ is $\leq \theta$. It is easy to see that 
		\begin{align*}
			1 -e^{- q \cdot t \cdot (e^{\delta}\cdot ( 1+ \varepsilon) - 1)} \leq \theta \qquad \text{ iff } \qquad e^{\delta}\cdot(1+\varepsilon) \leq 1 - \frac{\ln(1 - \theta)}{q \cdot t}.
		\end{align*}
		For fixed $\delta$, this yields 
		\begin{align*}
			e^{\delta} \cdot (1 + \varepsilon) \leq 1 - \frac{\ln(1 - \theta)}{q \cdot t} \qquad \text{ iff } \qquad \varepsilon \leq \frac{1}{e^{\delta}} \cdot \left(\frac{\uniformizationRate \cdot t - \ln(1-\theta)}{q \cdot t} \right) - 1,
		\end{align*}
		while for fixed $\varepsilon$ we get 
		\begin{align*}
			e^{\delta} \cdot (1 + \varepsilon) \leq 1 - \frac{\ln(1 - \theta)}{q \cdot t} \qquad \text{ iff } \qquad \delta \leq \ln \left( \frac{q \cdot t - \ln(1 - \theta)}{(1+\varepsilon) \cdot q \cdot t} \right).
		\end{align*}
		If both inequalities hold simultaneously, i.e., if $\varepsilon \in \left[0, \frac{1}{e^{\delta}} \cdot \left(\frac{\uniformizationRate \cdot t - \ln(1-\theta)}{\uniformizationRate\cdot t} \right) - 1\right]$ and $\delta \in \left[0, \ln\left(\frac{q\cdot t - \ln(1-\theta)}{(\varepsilon + 1)\cdot q \cdot t}\right)\right]$, then $1 -e^{- q \cdot t \cdot (e^{\delta}\cdot ( 1+ \varepsilon) - 1)} \leq \theta$, and by \Cref{prop:transient-prob-bounds-epsilon-delta-greater-0} it follows that $\vert \probMeasure_s(\reachability^{\leq t} g) - \probMeasure_{s'}(\reachability^{\leq t} g) \vert \leq \theta$, too.
	\end{proof}

\section{Additional Material for \Cref{sec:errors-0-delta-states}}
	\label{app:uniformizing}




\subsection{Uniformizing $(0,\delta)$-Bisimilar CTMCs}

For transitive $(0,\delta)$-bisimulations, i.e.,  $(0,\delta)$-bisimulations that are equivalence relations, the following construction shows
that we can restrict our analysis to uniform CTMCs when comparing time-bounded reachability probabilities in related states. 

Let $\mathcal{M}=(\stateSpace^{\mathcal{M}}, \prob^{\mathcal{M}}, \rate^{\mathcal{M}}, \initialState^\mathcal{M}, \labelFunction^\mathcal{M})$ and $\mathcal{N}=(\stateSpace^{\mathcal{N}}, \prob^{\mathcal{N}}, \rate^{\mathcal{N}}, \initialState^\mathcal{N}, \labelFunction^\mathcal{N})$ be two CTMCs with goal states $g$ and $g'$, respectively, and $R$
a transitive $(0,\delta)$-bisimulation on $\mathcal{M} \oplus \mathcal{N}$ with $(\initialState^\mathcal{M},\initialState^\mathcal{N})\in R$. Further, assume that $(g,g')\in R$ and that $g$ and $g'$ are not related to any other states by $R$. (This can be achieved, e.g., by giving both states the same, fresh label.) Let $t>0$.
Assume
\[
 \probMeasure^{\mathcal{M}}(\lozenge^{\leq t} g) \leq \probMeasure^{\mathcal{N}}(\lozenge^{\leq t} g').
 \]
 \paragraph{Claim:}
There are uniform CTMCs $\mathcal{M}'=(\stateSpace^{\mathcal{M}}, \prob^{\mathcal{M}'}, \rate^{\mathcal{M}'}, \initialState^\mathcal{M}, \labelFunction^{\mathcal{M}})$ and $\mathcal{N}'=(\stateSpace^{\mathcal{N}}, \prob^{\mathcal{N}'}, \rate^{\mathcal{N}'}, \initialState^\mathcal{N}, \labelFunction^{\mathcal{N}})$ with the same state spaces as $\mathcal{M}$ and $\mathcal{N}$, such that $R$ is still a $(0,\delta)$-bisimulation on $\mathcal{M}' \oplus \mathcal{N}'$ and such that 
\[
\probMeasure^{\mathcal{M}'}(\lozenge^{\leq t} g) \leq  \probMeasure^{\mathcal{M}}(\lozenge^{\leq t} g) \leq \probMeasure^{\mathcal{N}}(\lozenge^{\leq t} g') \leq \probMeasure^{\mathcal{N}'}(\lozenge^{\leq t} g').
\]
Furthermore, for all states $p \in \stateSpace^{\mathcal{M}}$ and $p'\in  \stateSpace^{\mathcal{N}}$ with $(p,p')\in R$, 
we have $\rate^{\mathcal{N}'}(p')= \rate^{\mathcal{M}'}(p) \cdot e^\delta$.


\begin{proof}
W.l.o.g., we assume that all states in $\mathcal{M}$ and $\mathcal{N}$ are reachable.
First, observe that all (reachable) states have to be part of an $R$-equivalence class as $R$ is an exact probabilistic bisimulation on the embedded DTMCs of $\mathcal{M}$ and $\mathcal{N}$, and the initial states $\initialState^\mathcal{M}$ and $\initialState^\mathcal{N}$ are related by $R$.
Furthermore, all states in $\mathcal{M}$ have to be related by $R$ to at least one state in $\mathcal{N}$, and vice versa.

To obtain $\mathcal{M}'$ and $\mathcal{N}'$ we first construct 
$\mathcal{M}''$ and $\mathcal{N}''$  that differ from $\mathcal{M}$ and $\mathcal{N}$ only in the exit rates, given by new functions $\rate^{\mathcal{M}''}$ and $\rate^{\mathcal{N}''}$ on 
$\stateSpace^{\mathcal{M}}$ and $\stateSpace^{\mathcal{N}}$. In particular, the transition probabilities are not affected when moving from $\mathcal{M}$ (resp. $\mathcal{N}$) to $\mathcal{M}''$ (resp. $\mathcal{N}''$).

For the construction of $\mathcal{M}''$ and $\mathcal{N}''$, let $C$ be an $R$-equivalence class.
Define 
\begin{align*}
\rate_{\min}^\mathcal{M}(C) &= \min_{p\in \stateSpace^{\mathcal{M}} \cap C} \rate^{\mathcal{M}}(p) \qquad \text{ and } \qquad 
\rate_{\max}^\mathcal{N}(C) = \max_{p\in \stateSpace^{\mathcal{N}} \cap C} \rate^{\mathcal{N}}(p).
\end{align*}
As all states in $C$ are $(0,\delta)$-bisimilar, we know that $\rate_{\max}^\mathcal{N}(C) \leq  \rate_{\min}^\mathcal{M}(C) \cdot e^\delta$.
Now, let
\[
\rate^{\mathcal{M}''}(p) = \rate_{\min}^\mathcal{M}([p]_R) \leq  \rate^{\mathcal{M}}(p) 
\]
for all $p\in \stateSpace^{\mathcal{M}}$ 
and let 
\[
\rate^{\mathcal{N}''}(p') = \rate_{\min}^\mathcal{M}([p']_R) \cdot e^\delta \geq \rate_{\max}^\mathcal{N}([p']_R) \geq \rate^{\mathcal{N}}(p')
\]
for all $p'\in \stateSpace^{\mathcal{N}}$. 
As rates in $\mathcal{M}''$ are all smaller than or equal to the corresponding ones in $\mathcal{M}$ and rates in $\mathcal{N}''$ are all larger than or equal to the corresponding ones in $\mathcal{N}$, we have
\[
\probMeasure^{\mathcal{M}''}(\lozenge^{\leq t} g) \leq  \probMeasure^{\mathcal{M}}(\lozenge^{\leq t} g) \leq \probMeasure^{\mathcal{N}}(\lozenge^{\leq t} g') \leq \probMeasure^{\mathcal{N}''}(\lozenge^{\leq t} g').
\]
Furthermore, $R$ is still a $(0,\delta)$-bisimulation on $\mathcal{M}''\oplus \mathcal{N}''$ as the transition probabilities have not been changed and the rates of related states differ at most by a factor of $e^\delta$ by construction.

Now, we let $\mathcal{M}'$ be the uniformization of $\mathcal{M}''$ with uniformization rate $\uniformizationRate_{\mathcal{M}}=\max_{p\in \stateSpace^{\mathcal{M}}} \rate^{\mathcal{M}''}(p)$
and likewise $\mathcal{N}'$  the uniformization of $\mathcal{N}''$ with uniformization rate $\uniformizationRate_{\mathcal{N}}=\max_{p'\in \stateSpace^{\mathcal{N}}} \rate^{\mathcal{N}''}(p')$.
We view these uniformizations as CTMCs.
For each state $p \in \stateSpace^{\mathcal{M}}$, there is a state $p'\in \stateSpace^{\mathcal{N}}$, namely any state related to $p$ by $R$, such that 
\[
e^\delta \cdot \rate^{\mathcal{M}''}(p) = \rate^{\mathcal{N}''}(p').
\]
Analogously, for each $p'\in \stateSpace^{\mathcal{N}}$, there is a $p \in  \stateSpace^{\mathcal{M}}$ such that this equation holds.
So, $\uniformizationRate_{\mathcal{M}}\cdot e^\delta = \uniformizationRate_\mathcal{N}$.

Now, let $p \in \stateSpace^{\mathcal{M}}$ and  $p'\in \stateSpace^{\mathcal{N}}$ be such that $(p,p')\in R$.
The rates of $p$ and $p'$ in $\mathcal{M}' \oplus \mathcal{N}'$ differ by a factor of $e^\delta$, just like the uniformization rates.
So, for all states $p\not=r\in \stateSpace^{\mathcal{M}}$, the probability to move from $p$ to $r$ in the uniformization $\mathcal{M}'$
is 
\[
\prob^{\mathcal{M}'}(p,r) = \frac{ \rate^{\mathcal{M}''}(p)}{\uniformizationRate_\mathcal{M}} \cdot \prob^{\mathcal{M}}(p,r) .
\]
Likewise, for all $p',r'\in \stateSpace^{\mathcal{N}}$ with $r' \neq p'$ and $(p,p')\in R$,
\[
\prob^{\mathcal{N}'}(p',r') = \frac{ \rate^{\mathcal{N}''}(p')}{\uniformizationRate_\mathcal{N}} \cdot \prob^{\mathcal{N}}(p',r') =  \frac{ \rate^{\mathcal{M}''}(p)}{\uniformizationRate_\mathcal{M}} \cdot \prob^{\mathcal{N}}(p',r')
\]
 The probability to move from $p$ to $p$ and from $p'$ to $p'$ in the respective uniformizations increases by
\[
\frac{\uniformizationRate_\mathcal{M}-\rate^{\mathcal{M}''}(p)}{\uniformizationRate_\mathcal{M}} = \frac{\uniformizationRate_\mathcal{N}-\rate^{\mathcal{N}''}(p')}{q_\mathcal{N}} .
\]
So, in $p$ and $p'$ the outgoing transition probabilities change by the same factor in the uniformization, and the remaining probability mass is redirected to the state itself.
As this holds for all states, $R$ is still an exact bisimulation on the DTMCs embedded in $\mathcal{M}'$ and $\mathcal{N}'$, and so $R$ is a $(0,\delta)$-bisimulation on the CTMCs $\mathcal{M}'$ and $\mathcal{N}'$ 
because all states in $\mathcal{M}'$ have exit rate $q_{\mathcal{M}}$ and all states in $\mathcal{N}'$ have exit rate $q_{\mathcal{N}}=e^\delta \cdot q_{\mathcal{M}}$.
As uniformization does not affect time-bounded reachability probabilities, we also have
\[
\probMeasure^{\mathcal{M}'}(\lozenge^{\leq t} g) \leq  \probMeasure^{\mathcal{M}}(\lozenge^{\leq t} g) \leq \probMeasure^{\mathcal{N}}(\lozenge^{\leq t} g') \leq \probMeasure^{\mathcal{N}'}(\lozenge^{\leq t} g').
\]\qed
\end{proof}


\subsection{Proofs of \Cref{sec:errors-0-delta-states}}

	\begin{lemma}\label{lem:binom-coeff}
		Let $m \in \mathbb{N}_{> 0}$ and $c > 1$. Then 
		\begin{align*}
			\sum_{i=0}^{m-1} \frac{1}{i!(m-i-1)!} \cdot (c-1)^{m-i-1} = \frac{1}{(m-1)!}\cdot c^{m-1}.
		\end{align*}
	\end{lemma}
	\begin{proof}
		We start by observing that 
		\begin{align*}
			\sum_{i=0}^{m-1} \frac{1}{i!(m-i-1)!} \cdot (c-1)^{m-i-1} = \frac{1}{(m-1)!}c^{m-1}, 
		\end{align*}
		is equivalent to 
		\begin{align*}
			\sum_{i=0}^{m-1} \frac{(m-1)!}{i! (m-i-1)!} \cdot (c-1)^{-i} = \left( \frac{c}{c-1} \right)^{m-1}
		\end{align*}
		which, after rewriting, is equivalent to
		\begin{align*}
			\sum_{i=0}^{m-1} \binom{m-1}{i} \cdot (c-1)^{-i} = \left(\frac{c}{c-1} \right)^{m-1}.
		\end{align*}

		We prove the latter identity by induction on $m$, where the induction base $m = 1$ is trivial. For the induction step $m \mapsto m+1$, we make use of the well-known fact that 
		\begin{align*}
			\binom{m}{i+1} = \binom{m-1}{i} + \binom{m-1}{i+1}
		\end{align*}
		to obtain 
		\begin{align*}
			&\textcolor{white}{=} \sum_{i=0}^{m} \binom{m}{i} (c-1)^{-i} \\&= 1 + \sum_{i=1}^m \binom{m}{i} \cdot (c-1)^{-i} \\&= 1 + \sum_{i=0}^{m-1} \binom{m}{i+1} \cdot  (c-1)^{-i-1} \\&= 1 + \frac{1}{c-1} \cdot \sum_{i=0}^{m-1} \binom{m}{i+1} \cdot (c-1)^{-i}  \\
			&= 1 + \frac{1}{c-1} \cdot \sum_{i = 0}^{m-1} \left(\binom{m-1}{i} + \binom{m-1}{i+1} \right) \cdot (c-1)^{-i} \\
			&= 1 + \frac{1}{c-1} \cdot \big(\underbrace{\sum_{i = 0}^{m-1} \binom{m-1}{i} \cdot (c-1)^{-i}}_{\text{(IH): } = \left(\frac{c}{c-1}\right)^{m-1}} + \sum_{i = 0}^{m-1} \binom{m-1}{i+1} \cdot (c-1)^{-i} \big) \\
			&= 1 + \frac{c^{m-1}}{(c-1)^m} + \sum_{i = 0}^{m-1} \binom{m-1}{i+1} \cdot (c-1)^{-(i+1)} \\
			&= 1 + \frac{c^{m-1}}{(c-1)^m} + \sum_{i = 0}^{m-2} \binom{m-1}{i+1} \cdot (c-1)^{-(i+1)} + \underbrace{\binom{m-1}{m} \cdot (c-1)^{-m}}_{= 0}\\
			&= 1 + \frac{c^{m-1}}{(c-1)^m} + \sum_{i=1}^{m-1} \binom{m-1}{i} \cdot (c-1)^{-i} \\
			&= \frac{c^{m-1}}{(c-1)^m} + \underbrace{\sum_{i=0}^{m-1} \binom{m-1}{i} \cdot (c-1)^{-i}}_{\text{(IH): } = \left(\frac{c}{c-1}\right)^{m-1}} \\
			&= \frac{c^{m-1}}{(c-1)^m} + \frac{c^{m-1}}{(c-1)^{m-1}} \\
			&= \frac{c^{m-1} + c^{m-1} \cdot (c-1)}{(c-1)^{m}} \\
			&= \frac{c^m}{(c-1)^m}
		\end{align*}
		and so the claim follows by induction.
	\end{proof}

	\PropErrorErlangCTMC*
	\begin{proof}
		We start by observing that if $t = 0$ then the absolute difference in reachability probabilities of the goal state $g$ between $\erlang_n$ and $\erlang_n'$ until time $t$ equals $0$, as in this case either both have $g$ as initial state (if $n = 0$), yielding $\probMeasure^{\erlang_n} (\lozenge^{\leq 0} g) = 1 = \probMeasure^{\erlang_n'}(\lozenge^{\leq 0} g)$, or both have an initial state $s_0 \neq g$, yielding $\probMeasure^{\erlang_n} (\lozenge^{\leq 0} g) = 0 = \probMeasure^{\erlang_n'}(\lozenge^{\leq 0} g)$. Since, independent of $n$, we have 
		\begin{align*}
		\sum_{k=0}^{n-1} \frac{0^k}{k!} \cdot \left(e^{-0} - c^ke^{-c \cdot 0} \right) = \frac{0^0}{0!} \cdot (1 - c^0 \cdot 1) + \sum_{k=1}^{n-1} \frac{0^k}{k!} \cdot \left(e^{-0} - c^ke^{-c \cdot 0} \right) = 0,
		\end{align*}
		 it follows that the claim holds if $t = 0$. 

		Moreover, if $c = 1$ then $\erlang_n' = \erlang_n$ and thus
		\begin{align*}
			\vert \probMeasure^{\erlang_n}(\lozenge^{\leq t} g) - \probMeasure^{\erlang_n'}(\lozenge^{\leq t} g) \vert = 0 = \sum_{k=0}^{n-1} \frac{t^k}{k!} \left(e^{-t} - 1^ke^{-1 \cdot t} \right),
		\end{align*}
		so the claim also holds if $c = 1$, independent of $t$ and $n$. 

		Now assume that $t > 0$, $c > 1$, and denote, for a given $n$, the states of $\erlang_n$ by $s_0, \ldots, s_{n-1}, g$. As Erlang CTMC are, by definition, acyclic it is possible to compute their transient reachability probabilities explicitly by using, e.g., the ACE algorithm proposed in \cite{TAAMC}. We follow a more direct approach and prove the claim by induction on $n$. 

		\smallskip
		\noindent
		\textbf{Induction Base:} \qquad For $n = 0$, $\erlang_0$ consists of the goal state $g$ only. Hence, $\vert \probMeasure_{\erlang_0}(\lozenge^{\leq t} g) - \probMeasure_{\erlang'_0}(\lozenge^{\leq t} g) \vert = \vert 1 - 1 \vert = 0$ for any $t \geq 0$. This matches the empty sum $\sum_{k = 0}^{-1} \frac{t^k}{k!} \cdot \left(e^{-t} - c^ke^{-ct} \right)$. 

		If $n = 1$, the probability to reach $g$ in $\erlang_1'$ until at most time $t$ is
		\begin{align}
			\probMeasure_{\erlang_1'}(\lozenge^{\leq t} g) = \probMeasure_{\erlang_1}(\lozenge^{\leq t} g) + \probMeasure_{\erlang_1}(\lozenge^{= t} s_0) \cdot \probMeasure_{s_0}(\lozenge^{\leq t\cdot(c-1)} g), \label{eq:error-erlang-ctmc-eq-1}
		\end{align}
		where $\probMeasure_{\erlang_1}(\lozenge^{= t} x)$ denotes the probability to be in state $x$ of $\erlang_1$ after \emph{exactly} time $t$. 
		Intuitively, \Cref{eq:error-erlang-ctmc-eq-1} holds because accelerating $\erlang_1$ by $c$ to obtain $\erlang_1'$ yields a uniform CTMC with the same structure as $\erlang_1$ and modified rates $c$ for which, as described in \Cref{rem:arbitrary-rate}, the probability to reach the goal state $g$ until time point $t$ is the same as reaching $g$ in $\erlang_1$ until time point $c \cdot t$. This corresponds, however, to either reaching $g$ until $t$ in $\erlang_1$, or still being in $s_0$ at $t$ and reaching $g$ in the remaining time, i.e., in $[t, c \cdot t]$. Because we consider time-homogeneous CTMC, the latter probability is the same as that of reaching $g$ from $s_0$ in the interval $[0, c \cdot t - t] = [0, t \cdot(c-1)]$, i.e., the same as $\probMeasure_{s_0}(\lozenge^{\leq t\cdot(c-1)} g)$. 

		From \Cref{eq:error-erlang-ctmc-eq-1} it now follows that
		\begin{align*}
			&\textcolor{white}{=} \vert \probMeasure_{\erlang_1}(\lozenge^{\leq t} g) - \probMeasure_{\erlang'_1}(\lozenge^{\leq t} g) \vert \\&= \left \vert \probMeasure_{\erlang_1}(\lozenge^{\leq t} g) - \left( \probMeasure_{\erlang_1}(\lozenge^{\leq t} g) + \probMeasure_{\erlang_1}(\lozenge^{= t} s_0) \cdot \probMeasure_{s_0}(\lozenge^{\leq t\cdot(c-1)} g) \right) \right \vert\\
			&= \probMeasure_{\erlang_1}(\lozenge^{= t} s_0) \cdot \probMeasure_{s_0}(\lozenge^{\leq t\cdot(c-1)} g) \\
			&= (1 - (1-e^{-t}))\cdot (1-e^{-t(c-1)}) \\
			&= e^{-t} \cdot (1-e^{-t \cdot (c-1)}) \\
			&= e^{-t} - e^{-t -t \cdot (c-1)} \\
			&= \frac{t^0}{0!} \cdot \left(e^{-t} - c^0 e^{-c \cdot t} \right) \\
			&= \sum_{k=0}^{0} \frac{t^k}{k!} \left(e^{-t} - c^k e^{-c \cdot t} \right).
		\end{align*}

		The function $e^{-t} - e^{-ct}$ is differentiable in $t$ with $\frac{d}{dt} (e^{-t} - e^{-ct}) = -e^{-t} + ce^{-ct}$. By computing the roots via 
		\begin{align*}
			ce^{-ct} - e^{-t} = 0 \qquad \text{ iff } \qquad \ln(c)-ct = -t \qquad \text{ iff } \qquad t = \frac{\ln(c)}{c-1}
		\end{align*}
		and plugging into the second derivative of $e^{-t} - e^{-ct}$ we observe that the function has a local maximum at this position. Furthermore, $e^{-t} - e^{-ct} \geq 0$ for all $t \geq 0$ because $c > 1$. Since, for $t \geq 0$,  $\frac{d}{dt}(e^{-t} - e^{-ct}) > 0$ iff $ t < \frac{\ln(c)}{c-1}$, $\frac{d}{dt}(e^{-t} - e^{-ct}) < 0$ iff $t > \frac{\ln(c)}{c-1}$, $\lim_{t \to 0} e^{-t} - e^{-ct} = 0 = \lim_{t \to \infty} e^{-t} - e^{-ct}$ and $e^{-t} - e^{-ct}$ is continuous, it follows that the maximum is global on the interval $[0, \infty)$.

		\smallskip
		\noindent
		\textbf{Induction Step: } \qquad Assume that the claim holds for $n-1$. Using a similar argument as in the induction base, we can find an analogue to \Cref{eq:error-erlang-ctmc-eq-1} for $\erlang_n'$ and express the reachability probability in the accelerated chain by probabilities in the original chain $\erlang_n$ via 
		\begin{align*}
			\probMeasure_{\erlang_n'}(\lozenge^{\leq t}g) = \probMeasure_{\erlang_n}(\lozenge^{\leq t} g) + \sum_{i = 0}^{n-1} \probMeasure_{\erlang_n}(\lozenge^{= t} s_i) \cdot \probMeasure_{s_i}(\lozenge^{\leq t \cdot (c-1)} g).
		\end{align*}
		Intuitively, this identity expresses that reaching $g$ until time $t$ in $\erlang_n'$ is the same as either reaching $g$ in $\erlang_n$ until time $t$, or being in any of the remaining states of $\erlang_n$ at time point $t$ and reaching $g$ in the remaining time of $t \cdot (c-1)$. For the absolute difference of the reachability probabilities in $\erlang_n$ and $\erlang_n'$ this yields 
		\begin{align*}
			\Diff_t(\erlang_n) = \vert \probMeasure_{\erlang_n}(\lozenge^{\leq t} g) - \probMeasure_{\erlang'_n}(\lozenge^{\leq t} g) \vert = \sum_{i = 0}^{n-1} \pi_{t}(s_0, s_i) \cdot \pi_{t \cdot (c-1)}(s_i, g),
		\end{align*}
		where $\pi_x(s, s')$ denotes the transient probability to be in state $s'$ after time $x$ when starting in state $s$. 

		Because of the shape of $\erlang_n$, the probabilities $\pi_t(s_0, s_i)$ and $\pi_{t \cdot (c-1)}(s_i, g)$ for $i = 0, \ldots, n-1$ can be computed explicitly by applying the well-known Poisson distribution: $\pi_t(s_0, s_i)$ describes the probability to make exactly $i$ jumps until time $t$ and is thus given as $\pi_t(s_0, s_i) = \frac{1}{i!} \cdot t^i \cdot e^{-t}$, while $\pi_{t \cdot (c-1)} (s_i, g)$ equals the probability to make the remaining number of jumps required to get from $s_i$ to $g$ until time $t \cdot (c-1)$, so
		\begin{align*}
			\pi_{t \cdot(c-1)}(s_i, g) = 1 - \sum_{j=0}^{n-i-1} \frac{1}{j!} \cdot e^{-t\cdot(c-1)} \cdot (t \cdot(c-1))^j.
		\end{align*}
		When plugging this into the sum, we get
		\begin{align}
			&\textcolor{white}{=} \Diff_t(\erlang_n) \nonumber
			\\&= \sum_{i = 0}^{n-1} \frac{t^i}{i!} \cdot e^{-t} \cdot \left(1 - \sum_{j=0}^{n-i-1} \frac{1}{j!} \cdot e^{-t\cdot(c-1)} \cdot (t \cdot(c-1))^j\right) \label{eq:erlang-bound-eq1} \\
			&= \sum_{i=0}^{n-1}\frac{1}{i!} \cdot \left( t^i e^{-t} - \sum_{j=0}^{n-i-1} \frac{1}{j!} \cdot e^{-c t} \cdot t^{j+i} \cdot (c-1)^j \right) \nonumber \\
			&= \sum_{i=0}^{n-2}\frac{1}{i!} \cdot \left( t^i e^{-t} - \sum_{j=0}^{n-i-1} \frac{1}{j!} \cdot e^{-c t} \cdot t^{j+i} \cdot (c-1)^j \right) \nonumber \\& \qquad + \frac{1}{(n-1)!}\cdot \left (t^{n-1}e^{-t} - \sum_{j=0}^0 \frac{1}{j!} e^{-ct} \cdot t^{j + n-1} \cdot (c-1)^j \right) \nonumber \\
			&= \sum_{i=0}^{n-2}\frac{1}{i!} \cdot \left( t^i e^{-t} - \sum_{j=0}^{n-i-1} \frac{1}{j!} \cdot e^{-c t} \cdot t^{j+i} \cdot (c-1)^j \right) + \frac{t^{n-1}}{(n-1)!} \cdot (e^{-t} - e^{-ct}) \nonumber \\
			&= \sum_{i=0}^{n-2}\frac{1}{i!} \cdot \left( t^i e^{-t} - \sum_{j=0}^{n-i-2} \left(\frac{1}{j!} \cdot e^{-c t} \cdot t^{j+i} \cdot (c-1)^j \right) - \frac{1}{(n-i-1)!} \cdot e^{-ct} \cdot t^{n-1} \cdot  (c-1)^{n-i-1} \right) \nonumber  \\& \qquad + \frac{t^{n-1}}{(n-1)!} \cdot (e^{-t} - e^{-ct}) \nonumber  \\
			&= \sum_{i=0}^{n-2}\frac{1}{i!} \cdot \left( t^i e^{-t} - \sum_{j=0}^{n-i-2} \left(\frac{1}{j!} \cdot e^{-c t} \cdot t^{j+i} \cdot (c-1)^j \right) \right) \nonumber \\& \qquad- \sum_{i=0}^{n-2} \frac{1}{i!(n-i-1)!} \cdot e^{-ct} \cdot t^{n-1} \cdot (c-1)^{n-i-1} + \frac{t^{n-1}}{(n-1)!} \cdot (e^{-t} - e^{-ct}) \nonumber \\
			&= \sum_{i=0}^{n-2} \frac{t^i}{i!} \cdot e^{-t} \cdot \left(1 - \sum_{j=0}^{n-i-2} \left( \frac{1}{j!} \cdot e^{-t \cdot (c-1)} \cdot (t \cdot (c-1))^j \right) \right) + \frac{t^{n-1}}{(n-1)!} \cdot e^{-t} \nonumber \\ & \qquad - t^{n-1} \cdot \sum_{i=0}^{n-1} \frac{1}{i!(n-i-1)!}\cdot e^{-ct} \cdot  (c-1)^{n-i-1}. \nonumber
		\end{align}
		When comparing the first sum of the last term with the equality 
		\begin{align*}
			\Diff_t(\erlang_n) = \sum_{i = 0}^{n-1} \frac{t^i}{i!} \cdot e^{-t} \cdot \left(1 - \sum_{j=0}^{n-i-1} \frac{1}{j!} \cdot e^{-t\cdot(c-1)} \cdot (t \cdot(c-1))^j\right)
		\end{align*}
		from \Cref{eq:erlang-bound-eq1} it is easy to see that they almost coincide, with the only difference being that $n$ in the latter is replaced with $n-1$ in the former. Thus, 
		\begin{align*}
			\sum_{i=0}^{n-2} \frac{t^i}{i!} \cdot e^{-t} \cdot \left(1 - \sum_{j=0}^{n-i-2} \left( \frac{1}{j!} \cdot e^{-t \cdot (c-1)} \cdot (t \cdot (c-1))^j \right) \right) = \Diff_t(\erlang_{n-1})
		\end{align*}
		and so it follows by  induction hypothesis that 
		\begin{align*}
			\sum_{i=0}^{n-2} \frac{t^i}{i!} \cdot e^{-t} \cdot \left(1 - \sum_{j=0}^{n-i-2} \left( \frac{1}{j!} \cdot e^{-t \cdot (c-1)} \cdot (t \cdot (c-1))^j \right) \right) = \sum_{k=0}^{n-2} \frac{t^k}{k!} \cdot \left(e^{-t} - c^ke^{-ct} \right),
		\end{align*}
		yielding
		\begin{align*}
			\Diff_t(\erlang_n) &= \sum_{k=0}^{n-2} \frac{t^k}{k!} \cdot \left(e^{-t} - c^ke^{-ct} \right) + \frac{t^{n-1}}{(n-1)!} \cdot e^{-t} \\& \qquad - t^{n-1} \cdot \sum_{i=0}^{n-1} \frac{1}{i!(n-i-1)!}\cdot e^{-ct} \cdot (c-1)^{n-i-1} \\
			&= \sum_{k=0}^{n-2} \frac{t^k}{k!} \cdot \left(e^{-t} - c^ke^{-ct} \right) + \frac{t^{n-1}}{(n-1)!} \cdot e^{-t} \\& \qquad - t^{n-1} \cdot e^{-ct} \cdot \underbrace{\sum_{i=0}^{n-1} \frac{1}{i!(n-i-1)!} \cdot (c-1)^{n-i-1}}_{= \frac{1}{(n-1)!}\cdot c^{n-1} \text{ by \Cref{lem:binom-coeff}}} \\
			&= \sum_{k=0}^{n-2} \frac{t^k}{k!} \cdot \left(e^{-t} - c^ke^{-ct} \right) + \frac{t^{n-1}}{(n-1)!} \cdot \left( e^{-t} - c^{n-1}e^{-ct} \right) \\ 
			&= \sum_{k=0}^{n-1} \frac{t^k}{k!} \cdot \left(e^{-t} - c^ke^{-ct} \right)
		\end{align*}
		and completing the induction step. 

		As a finite sum of differentiable function we can differentiate $\Diff_t(\erlang_n)$ w.r.t. $t$ to obtain 
		\begin{align*}
			&\textcolor{white}{=}\frac{d}{dt} \Diff_t(\erlang_n) \\&= \sum_{k=1}^{n-1} \left(\frac{t^{k-1}}{(k-1)!} \cdot (e^{-t} - c^ke^{-ct}) + \frac{t^k}{k!}\cdot(-e^{-t} + c^{k+1}e^{-ct}) \right) + (ce^{-ct} - e^{-t})\\
			&= \sum_{k=1}^{n-1} \frac{t^{k-1}}{(k-1)!} \cdot (e^{-t} - c^ke^{-ct}) + \sum_{k=1}^{n-1} \frac{t^k}{k!}\cdot(c^{k+1}e^{-ct} - e^{-t}) + (ce^{-ct} - e^{-t}) \\
			&= \sum_{k=1}^{n-1} \frac{t^{k-1}}{(k-1)!} \cdot (e^{-t} - c^ke^{-ct}) + \sum_{k=0}^{n-1} \frac{t^k}{k!}\cdot(c^{k+1}e^{-ct} - e^{-t}) \\ 
			&= \sum_{k=1}^{n-1} \frac{t^{k-1}}{(k-1)!} \cdot (e^{-t} - c^ke^{-ct}) + \sum_{k=1}^{n} \frac{t^{k-1}}{(k-1)!}\cdot(c^{k}e^{-ct} - e^{-t}) \\
			&= \frac{t^{n-1}}{(n-1)!}(c^ne^{-ct} - e^{-t}).
		\end{align*}
		Now it is easy to see that $\frac{t^{n-1}}{(n-1)!} \cdot (c^ne^{-ct} - e^{-t}) = 0$ iff $t = 0$ or $c^ne^{-ct} - e^{-t}$. The former case if of no concern since $\Diff_{t}(\erlang_n) \geq 0 = \Diff_{0}(\erlang_n)$ for all $t \geq 0$. In the latter case we get
		\begin{align*}
			\frac{d}{dt} \Diff_t(\erlang_n) = 0 \qquad \text{ iff } \qquad c^ne^{-ct} - e^{-t} = 0 \qquad \text{ iff } \qquad t = \frac{n \cdot \ln(c)}{(c-1)}.
		\end{align*} 
		By computing the second derivative of $\Diff_t(\erlang_n)$ w.r.t. $t$ and plugging in $t^* = \frac{n \cdot \ln(c)}{(c-1)}$ one can observe that $\Diff_{t^*}(\erlang_n) < 0$, yielding a local maximum in $t^*$. Similar to the induction base, on the interval $[0, \infty)$ the function $\Diff_t(\erlang_n)$ is continuous and nonnegative, has a first derivative $> 0$ iff $t < t^*$ and $<0$ iff $t > t^*$, and converges to $0$ for $t \to 0$ and $t \to \infty$. All in all, this implies that the obtained maximum in $t^*$ is global on $[0, \infty)$. 
	\end{proof}


	\ThmExactBoundZeroDelta*
	\begin{proof}
		If $\initialState = g$ then $\Diff_t(\mathcal{M}) = \vert \probMeasure^{\mathcal{M}'}(\lozenge^{\leq t} g) - \probMeasure^{\mathcal{M}}(\lozenge^{\leq t}g) \vert = 0$ for any $t$. Otherwise we start by noting that, by the choice of $\mathcal{M}' = c \cdot \mathcal{M}$,
		\begin{align*}
			\Diff_t(\mathcal{M}) = \vert \probMeasure^{\mathcal{M}'}(\lozenge^{\leq t} g) - \probMeasure^{\mathcal{M}}(\lozenge^{\leq t} g) \vert = \probMeasure^\mathcal{M}(\lozenge^{(t, c \cdot t]} g), 
		\end{align*}
		where $\probMeasure^\mathcal{M}(\lozenge^{(t, c \cdot t]} g)$ denote the probability of the chain to \emph{enter}  $g$ in the interval $(t, c \cdot t]$. We introduce some notation used throughout the proof. Denote by 
		\begin{align*}
			\Pi_n = \{s_0 s_1 \ldots s_{n-1} s_n \in \stateSpace^{n} \mid s_0 = \initialState, s_n = g \text{ and} s_i \neq g \text{ for } 0 \leq i \leq n-1\}
		\end{align*}	
		the set of all finite (untimed) paths of length $n$ (i.e., with a total of $n$ transitions) from the initial state of $\mathcal{M}$ to the goal state $g$. For $\pi =  \initialState s_1\ldots s_{n-1} g \in \Pi_n$, we additionally define 
		\begin{align*}
			\mathrm{Traj}(\pi) &= \{\initialState t_0 s_1 t_1 \ldots s_{n-1}t_{n-1} g \in S \cdot (\mathbb{R}_{>0} \cdot S)^n\} \\
			\mathrm{Traj}^*(\pi) &= \{\overline{\pi} \in \mathrm{Traj}(\pi) \mid \overline{\pi} \text{ reaches} g \text{ in} (t, c\cdot t]\}.
		\end{align*}
		In words, $\mathrm{Traj}(\pi)$ is the set of all timed paths that follow $\pi$, and $\mathrm{Traj}^*(\pi)$ is the set of all timed paths of $\mathcal{M}$ that follow $\pi$ and enter $g$ in the time interval $(t, c \cdot t]$. 
		Lastly, define the probability of $\mathcal{M}$ to follow a (timed version of a) path in $\Pi_n$ as
		\begin{align*}
			p_n = \probMeasure^{\mathcal{M}}(\Pi_n) = \sum_{\pi \in \Pi_n} \probMeasure^{\mathcal{M}}(\pi).
		\end{align*}

		For two events $A, B$, denote by $\probability(A \mid B)$ the \emph{conditional probability} of $A$ given $B$ w.r.t probability measure $\probability$.
		By Bayes' rule, which states that
		\begin{align*}
			\probability(A \mid B) = \frac{\mathrm{Prob}(B \mid A) \cdot \probability(A)}{\probability(B)}
		\end{align*} 
		if $\probability(B) > 0$, it follows that
		\begin{align*}
			\Diff_t(\mathcal{M}) &=  \probMeasure^\mathcal{M}(\lozenge^{(t, c \cdot t]} g) \\
			&= \sum_{n = 0}^{\infty} \sum_{\pi \in \Pi_n} \probMeasure^\mathcal{M}(\mathrm{Traj}^*(\pi)) \\
			&= \sum_{n=0}^\infty \sum_{\pi \in \Pi_n} \frac{\probMeasure^\mathcal{M}(\mathrm{Traj}^*(\pi) \mid \pi) \cdot \probMeasure^\mathcal{M}(\pi)}{\probMeasure^\mathcal{M}(\pi \mid \mathrm{Traj}^*(\pi))} \\
			&= \sum_{n = 0}^{\infty} \sum_{\pi \in \Pi_n} \probMeasure^\mathcal{M}(\mathrm{Traj}^*(\pi) \mid \pi) \cdot \probMeasure^\mathcal{M}(\pi)
		\end{align*}
		where the last equality holds since the probability to follow (an untimed) path $\pi$ when knowing that one follows a timed version of $\pi$, i.e., the probability of $\pi$ in $\mathcal{M}$ given $\mathrm{Traj}^*(\pi)$, equals $1$.

		We observe that for any $\pi \in \Pi_n$, $ \probMeasure^\mathcal{M}(\mathrm{Traj}^*(\pi) \mid \pi)$ equals the error obtained at time point $t$ when considering, instead of $\mathcal{M}$, the Erlang-CTMCs $\erlang_n$ and $c \cdot \erlang_n$, respectively, i.e., that $ \probMeasure^\mathcal{M}(\mathrm{Traj}^*(\pi) \mid \pi) = \Diff_t(\erlang_n)$ for $\Diff_t(\erlang_n)$ as in \Cref{prop:error-erlang-ctmc}. Intuitively, this follows from the fact that conditioning on $\pi$ dictates a path through the chain that must be taken, so there are no probabilistic choices involved anymore. Hence, the only possibility in any state $s_i$, $i < n$, along $\pi = s_0 s_1 \ldots$ is to move to the next state $s_{i+1}$ with probability $1$. But this results in precisely the form of the Erlang CTMC $\erlang_n$. Because $\mathrm{Traj}^*(\pi)$ contains only those timed versions of $\pi$ that enter $g$ exactly in the time interval $(t, c\cdot t]$ we can argue as done in the proof of \Cref{prop:error-erlang-ctmc} to obtain \Cref{eq:error-erlang-ctmc-eq-1} and describe the probabilities as the difference of transient probabilities in the corresponding chains $\erlang_n$ and $\erlang_n'$. 

		Using this observation, we get the desired identity via
		\begin{align*}
			\Diff_t(\mathcal{M}) &= \sum_{n = 0}^{\infty} \sum_{\pi \in \Pi_n} \probMeasure^\mathcal{M}(\mathrm{Traj}^*(\pi) \mid \pi) \cdot \probMeasure^\mathcal{M}(\pi) \\&= \sum_{n = 0}^{\infty} \Diff_t(\erlang_n) \cdot \sum_{\pi \in \Pi_n} \probMeasure^\mathcal{M}(\pi) \\&= \sum_{n=0}^{\infty} \Diff_t(\erlang_n) \cdot p_n \\&= \sum_{n=1}^{\infty} \Diff_t(\erlang_n) \cdot p_n
		\end{align*}
		where the second to last equality follows from the definition of $p_n$, and the last one holds since $\Diff_t(\erlang_0) = 0$ for all $t$.
	\end{proof}

	\PropImproveBoundZeroDeltaViaMaxErlang*
	\begin{proof}
		From \Cref{thm:exact-computation-error-0-delta} we know that $\Diff_t(\mathcal{M}) = \sum_{n=0}^{\infty} p_n \cdot \Diff_t(\erlang_n)$, where $p_n$ is the probability of $\mathcal{M}$ to enter the goal state $g$ after \emph{exactly} $n$ discrete steps and $\Diff_t(\erlang_n)$ is as in \Cref{prop:error-erlang-ctmc}. In particular, it holds for all $n \in \mathbb{N}$ that $p_n \in [0,1]$, and additionally that $\sum_{n \in \mathbb{N}} p_n \leq 1$ since the total probability to enter $g$ is at most $1$. Thus, we can bound the value of $\Diff_t(\mathcal{M})$ for above via 
		\begin{align}\label{thm:exact-computation-error-0-delta-eq-1}
			\Diff_t(\mathcal{M}) = \sum_{n=0}^{\infty} p_n \cdot \Diff_t(\erlang_n) \leq \max_{n \in \mathbb{N}} \Diff_t(\erlang_n).
		\end{align}
		Since we know from \Cref{prop:error-erlang-ctmc} that $\Diff_t(\erlang_n) = \sum_{k=0}^{n-1} \frac{t^k}{k!} \cdot \left(e^{-t} - c^k e^{-ct} \right)$ for every $t \geq 0$ and all $n \in \mathbb{N}$ it follows that 
		\begin{align*}
			\Diff_t(\mathcal{M}) \leq \max_{n \in \mathbb{N}} \sum_{k=0}^{n-1} \frac{t^k}{k!} \cdot \left(e^{-t} - c^k e^{-ct} \right).
		\end{align*}
		We now show that for every $t \geq 0$ this maximum is attained at $N = \left \lceil \frac{(e^{\delta} - 1) \cdot t}{\delta} \right \rceil$ where, for $x \in \mathbb{R}$,  $\lceil x \rceil$ is defined to be the smallest integer $\geq x$.

		If $t = 0$ then $\Diff_t(\mathcal{M}) = 0 = \Diff_t(\erlang_n)$ for all $n$, and so in particular for $N = 0 = \left \lceil \frac{(e^{\delta}-1) \cdot 0}{\delta} \right \rceil$. Thus, the maximum is attained at $N$.

		If $t > 0$ we directly obtain from \Cref{prop:error-erlang-ctmc} that
		\begin{align*}
			\Diff_t(\erlang_{n+1}) = \Diff_t(\erlang_n) + \frac{t^n}{n!}\cdot(e^{-t} - c^ne^{-ct})
		\end{align*}
		from which, as $c = e^{\delta} > 1$, we get
		\begin{align}\label{thm:exact-computation-error-0-delta-eq-2}
			\Diff_t(\erlang_{n+1}) < \Diff_t(\erlang_n) \qquad \text{iff} \qquad e^{(c-1)t} < c^n \qquad \text{iff} \qquad \frac{(e^{\delta} - 1) \cdot t}{\delta} < n. 
		\end{align}
		Let $N = \left \lceil \frac{(e^{\delta} - 1) \cdot t}{\delta} \right \rceil$, i.e., $N$ is the smallest positive integer such that $N \geq \frac{(e^{\delta} - 1) \cdot t}{\delta}$ or equivalently (by \Cref{thm:exact-computation-error-0-delta-eq-2}) such that $e^{(c-1)\cdot N} \leq c^N$. To prove that the maximum in \Cref{thm:exact-computation-error-0-delta-eq-1} is obtained for $N$, we do a case distinction. 
		\begin{itemize}
			\item If $n > N$ then $e^{(c-1)t} \leq c^N < \ldots < c^n$, where the first inequality follows from the choice of $N$ as the smallest integer $\geq \frac{(e^\delta -1) \cdot t}{\delta}$, which is equivalent to $e^{(c-1)t}\leq c^N$ by \Cref{thm:exact-computation-error-0-delta-eq-2}, and the remaining inequalities follow by monotonicity and the fact that $c > 1$. But then $\Diff_t(\erlang_n) < \Diff_t(\erlang_N)$, as for all $n > N$ we have $\frac{(e^{\delta} -1) \cdot t}{\delta} \leq N < n$ and hence 
			\begin{align*}
				\Diff_t(\erlang_n) < \Diff_t(\erlang_{n-1}) < \ldots < \Diff_t(\erlang_{N+1}) < \Diff_t(\erlang_N).
			\end{align*}
			again by \Cref{thm:exact-computation-error-0-delta-eq-2} (applied iteratively).
			\item Otherwise, if $n < N$, then $e^{(c-1)t} > c^{N-1} > \ldots  > c^n$, where the first inequality follows from the choice of $N$ as the \emph{smallest} positive integer such that $e^{(c-1)t} \leq c^N$. Applying \Cref{thm:exact-computation-error-0-delta-eq-2} iteratively, it follows that 
			\begin{align*}
				\Diff_t(\erlang_n) < \Diff_t(\erlang_{n+1}) < \ldots < \Diff_t(\erlang_{N-1}) < \Diff_t(\erlang_N).
			\end{align*}
		\end{itemize}
		All in all this shows that indeed 
		\begin{align*}
			\Diff_t(\mathcal{M}) \overset{\text{Eq. } (\ref{thm:exact-computation-error-0-delta-eq-1})}{\leq} \max_{n \in \mathbb{N}} \Diff_t(\erlang_n) = \Diff_t(\erlang_N) = \sum_{k=0}^{N-1} \frac{t^k}{k!}\cdot \left(e^{-t} - c^ke^{-ct} \right).
		\end{align*}
	\end{proof}


	\PropExactComputationPnDiag*
	\begin{proof}
		As $\probMatrix$ is diagonalizable there are matrices $\symmetryMatrix, \diagonalMatrix \in \mathbb{C}^{n \times n}$ such that $\diagonalMatrix$ is a diagonal matrix whose diagonal contains, in descending order w.r.t. their absolute value, the eigenvalues $\lambda_1, \lambda_2, \ldots, \lambda_n$ of $\probMatrix$ (repeated according to their multiplicities), and such that $\probMatrix = \symmetryMatrix \diagonalMatrix\symmetryMatrix^{-1}$. Since $\probMatrix$ is stochastic, $\lambda_1 = 1$\cite{MAALA}. 

		The probability to move into the goal state $g = s_n$, which we w.l.o.g. associate with the last row of $\probMatrix$, after \emph{exactly} $k+1$ steps when starting in the initial state $\initialState = s_1$, which is associated with the first row of $\prob$, is given as the entry at position $[1,n]$ of $\probMatrix^{k+1} - \probMatrix^{k}$. If $a_{\probMatrix} = 1$, i.e., if $\mathcal{M}$ only has a single accepting state, we get 
		\begin{align*}
			p_{k+1} &= (\probMatrix^{k+1} - \probMatrix^{k})_{1, n} = \mathbf{\dirac}_{s_1} \cdot ((\symmetryMatrix \diagonalMatrix\symmetryMatrix^{-1})^{k+1} - (\symmetryMatrix \diagonalMatrix\symmetryMatrix^{-1})^k) \cdot \mathbf{\dirac}_{s_n}^{\top} \\
			&= \mathbf{\dirac}_{s_1} \cdot \symmetryMatrix(\diagonalMatrix^{k+1} - \diagonalMatrix^k) \symmetryMatrix^{-1} \cdot \mathbf{\dirac}_{s_n}^\top \\
			&= \begin{pmatrix}
				\symmetryMatrix_{1, 1} &\symmetryMatrix_{1, 2} &\ldots &\symmetryMatrix_{1, n}
			\end{pmatrix} \cdot \begin{pmatrix} 0 & 0 & & & \ldots \\
				0 & \lambda_2^{k} \cdot(\lambda_2 - 1) & 0 & & \ldots  \\
				0 & 0 & \lambda_3^{k} \cdot (\lambda_3 -1) & 0 & \ldots  \\
				\vdots & \vdots & & \ddots & \vdots \\
				0 & 0  & \ldots & 0 & \lambda_n^{k} \cdot (\lambda_n - 1)
			\end{pmatrix}\cdot \begin{pmatrix} \symmetryMatrix^{-1}_{1, n} \\ \symmetryMatrix^{-1}_{2, n}\\ \vdots \\ \symmetryMatrix^{-1}_{n, n}  \end{pmatrix} \\
			\\ &= \sum_{j = 2}^{n} \symmetryMatrix_{1, j} \cdot \symmetryMatrix^{-1}_{j, n} \cdot (\lambda_j - 1) \cdot \lambda_j^k.
		\end{align*}

		In the case that $a_{\probMatrix} = 2$ we have $\lambda_2 = 1$, and so the entry in the second row of $\diagonalMatrix^{k+1} - \diagonalMatrix^k$ vanishes as well. Hence, the resulting sum starts from $j = 3$, but stays the same otherwise. Combining both results we obtain the desired identity.
	\end{proof}

	\BoundPnDiag*
	\begin{proof}
		By \Cref{prop:exact-computation-pn-diag} we know that, if $\probMatrix$ is diagonalizable, i.e., if $\probMatrix = \symmetryMatrix \diagonalMatrix \symmetryMatrix^{-1}$ for a diagonal matrix $\diagonalMatrix$ and a suitable symmetry matrix $\symmetryMatrix$, 
		we have for every $k \in \mathbb{N}$ that $p_{k+1} = \sum_{j = a_{\probMatrix} + 1}^{n} \symmetryMatrix_{1, j} \cdot \symmetryMatrix^{-1}_{j, n} \cdot (\lambda_j - 1) \cdot \lambda_j^k$. 

		Let $\lambda_1', \ldots, \lambda_m'$ be the distinct eigenvalue of $\probMatrix$, given in descending order w.r.t. their absolute values, i.e., such that $1 = \lambda_1' > \vert \lambda_2' \vert > \ldots > \vert \lambda_m' \vert$. 

		We first assume that the only absorbing state of $\mathcal{M}$ is $g$, i.e., that $a_{\probMatrix} = 1$. Then the eigenvalues of $\mathcal{M}$, repeated according to their multiplicities, are $\lambda_1 = 1 > \vert \lambda_2 \vert \geq \ldots \geq \vert \lambda_n \vert$, and so $\lambda = \lambda_2$. 
		As $p_{k+1} \geq 0$ for every $k \in \mathbb{N}$ we have $p_{k+1} = \vert p_{k+1}\vert$. Therefore,
		\begin{align*}
			p_{k+1} &= \left \vert \sum_{j=2}^{n} \symmetryMatrix_{1, j} \cdot  \symmetryMatrix^{-1}_{j, n} \cdot (\lambda_j -1) \cdot \lambda_j^k \right \vert \\
			&\leq \sum_{j=2}^{n} \underbrace{\vert \symmetryMatrix_{1,j} \cdot \symmetryMatrix^{-1}_{j,n} \cdot (\lambda_j - 1) \vert}_{\leq \max_{j = 2, \ldots, n} \vert \symmetryMatrix_{1,j} \cdot \symmetryMatrix^{-1}_{j,n} \cdot (\lambda_j - 1) \vert \eqcolon C} \cdot \underbrace{\vert \lambda_j \vert^k}_{\leq \vert \lambda \vert^k} \\
			&\leq \vert \lambda \vert^k \cdot \sum_{j=2}^{n} C = \vert \lambda \vert^k \cdot (n-1) \cdot C.
		\end{align*}
		By plugging this inequality into the result of \Cref{thm:exact-computation-error-0-delta} we obtain
		\begin{align*}
			\Diff_t(\mathcal{M}) &= \sum_{k=1}^{\infty} p_k \cdot \Diff_t(\erlang_k) \\&\leq (n-1) \cdot C \cdot \sum_{k=1}^{\infty} \vert \lambda \vert^{k-1} \cdot \Diff_t(\erlang_k)
			\\&= (n-a_{\probMatrix}) \cdot C \cdot \sum_{k=1}^{\infty} \vert \lambda \vert^{k-1} \cdot \Diff_t(\erlang_k).
		\end{align*}

		Using similar calculations it is easy to show that the claim still holds if $\mathcal{M}$ has an additional absorbing fail state, i.e., if $a_{\probMatrix} = 2$.
	\end{proof}

	\ThmExactValuePnNonDiagonalizable* 
	\begin{proof}
		The proof proceeds mostly similar to that of \Cref{prop:exact-computation-pn-diag}, with the main difference being that here the JCF of $\probMatrix = \symmetryMatrix \jordanMatrix\symmetryMatrix^{-1}$ is used instead of the (probably not existing) diagonalization. Let $\tau_1, \ldots, \tau_m$ be the distinct eigenvalues of $\probMatrix$, given in descending order w.r.t. their absolute values. $\jordanMatrix$ can contain multiple blocks $\jordanMatrix_{i,1}, \ldots, \jordanMatrix_{i,q}$ that correspond to a single eigenvalue $\tau_i$. To avoid clutter in the notation we do not use double indices, but instead count the Jordan blocks individually, i.e., instead of $\jordanMatrix_{i,1}, \ldots, \jordanMatrix_{i, q}$ we write $\jordanMatrix_{i}, \jordanMatrix_{i+1}, \ldots, \jordanMatrix_{i +q}$. Let $r_{i}$ be the size (i.e., the number of rows resp. columns) of $\jordanMatrix_{i}$, and let $\lambda_i$ be the eigenvalue corresponding to $\jordanMatrix_i$.

		We assume w.l.o.g. that the initial state $\initialState$ of $\mathcal{M}$ corresponds to the first row of $\probMatrix$, and that the unique goal state $g$ corresponds to the last, i.e., the $n$-th row of $\probMatrix$. Furthermore, we assume that the Jordan blocks of $\jordanMatrix$ are ordered decreasingly w.r.t. the absolute values of the corresponding eigenvalues, starting with the blocks corresponding to eigenvalue $1$ in the top left of $\jordanMatrix$, and that if there are multiple Jordan blocks for the same eigenvalue, these occur in decreasing order w.r.t their sizes. 

		We first consider the case where $g$ is the only absorbing state in $\mathcal{M}$. 
		Since $g$ is reachable from every state in $\mathcal{M}$, the eigenvalue $\lambda_1 = 1$ has (algebraic and geometric) multiplicity $1$, i.e., $a_{\probMatrix} = 1$, and so $\jordanMatrix$ can be written as 
		\begin{align}
			\jordanMatrix = \begin{pmatrix}
				1 & 0  &\ldots & 0 \\
				0 & \jordanMatrix_{2} & \ldots & 0  \\
				\vdots  && \ddots  & \vdots \\
				0 &\ldots  & &\jordanMatrix_{q_{\jordanMatrix}} 
			\end{pmatrix}.\label{eq:jordanForm}
		\end{align}
		where $q_{\jordanMatrix}$ is the total number of Jordan blocks of $\jordanMatrix$. Each $\jordanMatrix_i$ with corresponding eigenvalue $\lambda_i$ is an $r_i \times r_i$ matrix of the form 
		\begin{align*}
			\jordanMatrix_i = \begin{pmatrix}
				\lambda_i & 1 & 0 & 0 & \ldots \\
				0 & \lambda_i & 1 & 0 & \ldots \\
				\vdots & & \ddots & \ddots & \vdots \\
				0 & \ldots & 0& \lambda_i & 1 \\
				0 & \ldots  & & 0 & \lambda_i
			\end{pmatrix}.
		\end{align*}
		The probability to reach $g$ after exactly $N+1$ discrete time steps is
		\begin{align}
			p_{N+1} &= \mathbf{\dirac}_{\initialState} \cdot (\probMatrix^{N+1} - \probMatrix^{N}) \cdot \mathbf{\dirac}_{g}^{\top}\nonumber \\
			&= \mathbf{\dirac}_{\initialState} \cdot \cdot ((\symmetryMatrix \jordanMatrix \symmetryMatrix^{-1})^{N+1} - (\symmetryMatrix \jordanMatrix \symmetryMatrix^{-1})^{N}) \cdot \mathbf{\dirac}_{g}^{\top} \nonumber \\
			&= \mathbf{\dirac}_{\initialState} \cdot \symmetryMatrix \cdot (\jordanMatrix^{N+1} - \jordanMatrix^{N}) \cdot \symmetryMatrix^{-1}  \cdot \mathbf{\dirac}_{g}^{\top} \nonumber \\
			&= \begin{pmatrix} \symmetryMatrix_{1, 1}  & \symmetryMatrix_{1, 2} & \ldots & \symmetryMatrix_{1, n} \end{pmatrix} \cdot (\jordanMatrix^{N+1} - \jordanMatrix^{N}) \cdot  \begin{pmatrix} \symmetryMatrix^{-1}_{1, n}\\ \symmetryMatrix^{-1}_{2, n}\\ \vdots \\ \symmetryMatrix^{-1}_{n, n} \end{pmatrix}. \label{eq:pN+1-written-our-via-Jordan}
		\end{align}
		We first consider the case that $\lambda_i \neq 0$ for all $i$. Then the $N$-th power of $\jordanMatrix_{i}$ has the form
		\begin{align}
			\jordanMatrix_i^N = \begin{pmatrix}
				\lambda_i^N & \binom{N}{1} \lambda_i^{N-1} & \binom{N}{2} \lambda_i^{N-2} & \ldots & \binom{N}{r_i - 1} \lambda_i^{N - r_i + 1} \\
				0 & \lambda_i^N & \binom{N}{1} \lambda_i^{N-1} & \ldots & \binom{N}{r_i - 2} \lambda_i^{N-r_i + 2} \\ \\
				\vdots & &  \ddots & &  \vdots \\ \\
				0 & \ldots & 0 & \lambda_i^N & \binom{N}{1} \lambda_i^{N-1} \\
				0 & \ldots & 0 & 0 & \lambda_i^N
			\end{pmatrix}, \label{eq:power-of-jordan}
		\end{align}
		yielding
		\begin{align*}
			&\jordanMatrix_i^{N+1} - \jordanMatrix_i^N = \jordanMatrix_i^N \cdot (\jordanMatrix_i - \mathbf{I}_{r_i}) \\&= \begin{pmatrix}
				\lambda_i^N ( \lambda_i - 1) & \lambda_i^{N-1}  (\lambda_i  \binom{N+1}{1} - \binom{N}{1}) & \lambda_i^{N-2}  (\lambda_i  \binom{N+1}{2} - \binom{N}{2})  & \ldots & \lambda_i^{N - r_i + 1}  ( \lambda_i  \binom{N+1}{r_i - 1} - \binom{N}{r_i - 1})\\
				0 & \lambda_i^N ( \lambda_i - 1) & \lambda_i^{N-1}  (\lambda_i  \binom{N+1}{1} - \binom{N}{1}) & \ldots & \lambda_i^{N - r_i + 2}  ( \lambda_i  \binom{N+1}{r_i - 2} - \binom{N}{r_i - 2}) \\ \\
				\vdots & &  \ddots & &  \vdots \\ \\
				0 & \ldots & 0 & \lambda_i^N ( \lambda_i - 1) & \lambda_i^{N-1}  (\lambda_i  \binom{N+1}{1} - \binom{N}{1}) \\
				0 & \ldots & 0 & 0 & \lambda_i^N ( \lambda_i - 1)
			\end{pmatrix}
		\end{align*}
		where $\mathbf{I}_{r_i}$ is the $r_i \times r_i$ identity matrix.
		When combining the derived form of $\jordanMatrix_i^{N+1} - \jordanMatrix_i^N$ with \Cref{eq:pN+1-written-our-via-Jordan} and carrying out the multiplication, we obtain 
		\begin{align*}
			p_{N+1} &= \sum_{l = 2}^{q_{\jordanMatrix}} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j} \symmetryMatrix_{1, k + h_l} \cdot \symmetryMatrix^{-1}_{j + h_l, n} \cdot \lambda_{l}^{N + k - j} \cdot \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right)
			\\&
			= \sum_{l = a_{\probMatrix} +1}^{q_{\jordanMatrix}} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j} \symmetryMatrix_{1, k + h_l} \cdot \symmetryMatrix^{-1}_{j + h_l, n} \cdot \lambda_{l}^{N + k - j} \cdot \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right)
		\end{align*}
		for $h_l = \sum_{i = 1}^{l-1} r_{l}$. The parameter $l$ specifies the Jordan block $\jordanMatrix_{l}$ that we are currently interested in, and the offset $h_l$ ensures that the correct entries of $\symmetryMatrix$ (for the rows) and $\symmetryMatrix^{-1}$ (for the columns) are picked. We do not have to consider $l = 1$ as $\lambda_1 = 1$ and so $\jordanMatrix_1^{N+1} - \jordanMatrix_1^{N}$ equal the (($1 \times 1$)-dimensional) matrix with all entries $0$. 

		\medskip

		We now consider the case where $\probMatrix$ is allowed to have eigenvalue $0$. We assume that the Jordan blocks $\jordanMatrix_{q_{\jordanMatrix}-z}, \ldots, \jordanMatrix_{q_{\jordanMatrix}-1}, \jordanMatrix_{q_{\jordanMatrix}}$ correspond to the eigenvalue $0$, i.e., that there are a total of $z$ such blocks for some $0 \leq z \leq q_{\jordanMatrix}-1$ (where we have $z < q_{\jordanMatrix}$ as $\lambda_1 = 1$ has a multiplicity of at least $1$). Consider again the identity in \Cref{eq:pN+1-written-our-via-Jordan}, i.e, 
		\begin{align*}
			p_{N+1} = \begin{pmatrix} \symmetryMatrix_{1, 1}  & \symmetryMatrix_{1, 2} & \ldots & \symmetryMatrix_{1, n} \end{pmatrix} \cdot (\jordanMatrix^{N+1} - \jordanMatrix^{N}) \cdot  \begin{pmatrix} \symmetryMatrix^{-1}_{1, n}\\ \symmetryMatrix^{-1}_{2, n}\\ \vdots \\ \symmetryMatrix^{-1}_{n, n} \end{pmatrix}.
		\end{align*}
		When carrying out the multiplications, nothing changes for the first $q_{\jordanMatrix} - z$ Jordan blocks that correspond to a non-zero eigenvalue. However, when considering one of the Jordan blocks $\jordanMatrix_i$ for $i \geq q_{\jordanMatrix}-z$, 
		$\jordanMatrix_i^{N}$ is not of the form described in \Cref{eq:power-of-jordan}, but instead has entries $\jordanMatrix_i^{N}[j,j+N] = 1$ for $1 \leq j \leq r_{i} - N$, and entries $0$ everywhere else. The difference $\jordanMatrix_i^{N+1} - \jordanMatrix_i^{N}$ therefore has entries 
		\begin{align*}
			(\jordanMatrix_i^{N+1} - \jordanMatrix_i^{N})[j,k] &= 
			\begin{cases}
				1, &\text{if } 1 \leq j \leq r_{i} - N - 1, k = j + N + 1 \\
				-1, &\text{if } 1 \leq j \leq r_{i} - N, k = j + N \\
				0, & \text{otherwise}
			\end{cases}.
		\end{align*}
		Thus, for the result of the product of \Cref{eq:power-of-jordan}, these blocks add summands of the form 
		\begin{align*}
			(0 - \symmetryMatrix_{1, h_l + 1} \cdot \symmetryMatrix^{-1}_{h_l + N + 1, n}) + \sum_{j = 1}^{r_{i} - N} (\symmetryMatrix_{1, h_l + h} - \symmetryMatrix_{1, h_l + j + 1}) \cdot \symmetryMatrix^{-1}_{h_l + N + j},
		\end{align*}
		where $h_l$ is, as in the first case, an offset that ensures that the entries of the correct columns resp. rows of $\symmetryMatrix_{1, *}$ resp. $\symmetryMatrix^{-1}_{*, n}$ are chosen. By setting $\symmetryMatrix_{1, h_l + j}^* = \symmetryMatrix_{1, h_l +j}$ if $j > 0$ and  $\symmetryMatrix_{1, h_l + j}^* = 0$ if $j = 0$, summing over all Jordan blocks corresponding to the eigenvalue $0$ yields a term of the form
		\begin{align*}
			R(N, z) \coloneqq \sum_{l = q_{\jordanMatrix}-z+1}^{q_{\jordanMatrix}} \sum_{j=0}^{r_{l} - N - 1} (\symmetryMatrix_{1, h_l + j}^* - \symmetryMatrix_{1, h_l + j + 1}) \cdot \symmetryMatrix^{-1}_{h_l + N + j, n}.
		\end{align*}
 		By combining this with the previous calculations regarding the non-zero eigenvalues we obtain
		\begin{align*}
			p_{N+1} = \sum_{l = a_{\probMatrix} + 1}^{q_{\jordanMatrix}-z} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j} \symmetryMatrix_{1, k + h_l} \cdot \symmetryMatrix^{-1}_{j + h_l, n} \cdot \lambda_{l}^{N + k - j} \cdot \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) + R(N, z). 
		\end{align*}

		If $\mathcal{M}$ has a an additional absorbing fail state, then $a_{\probMatrix} = 2$ and a $1 \times 1$ Jordan block for eigenvalue $1$ occurs twice in the top left of \Cref{eq:jordanForm}. However, similar to the above deductions this Jordan block is canceled out in any of the difference $\jordanMatrix^{N+1} - \jordanMatrix^N$, and so the only adjustment needed for this case is an initial value of $l = 3$, which again coincides with $a_{\probMatrix} + 1$. 
	\end{proof}


	\PropJordanBound*
	\begin{proof}
		From \Cref{thm:exact-computation-error-0-delta} we know that
		\begin{align}
			\Diff_t(\mathcal{M}) = \sum_{k = 1}^{R-1} p_k \cdot \Diff_t(\erlang_k) + \sum_{k=R}^{\infty} p_k \cdot \Diff_t(\erlang_k) \label{eq:jordan-bound}
		\end{align}
		for $R$ the maximal size of any Jordan block of $\jordanMatrix$. 

		We split the series at position $R$ since for any $k \geq R$ the term $R(k, z)$ from \Cref{thm:exact-value-pn-non-diagonalizable} vanishes, allowing us to ignore it in our subsequent calculations. 

		To obtain a bound for $p_{N+1}$  for some $N \geq R-1$ we have to consider its absolute value, as the eigenvalues $\lambda_i$ of $\probMatrix$ can be complex even for stochastic matrices $\probMatrix$. Since $p_{N+1} \in [0,1]$ is a probability it coincides with its absolute value, so
		\begin{align*}
			p_{N+1} &= \left \vert\sum_{l = a_{\probMatrix}+1}^{q_{\jordanMatrix}-z} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j} \symmetryMatrix_{1, k + h_l} \cdot \symmetryMatrix^{-1}_{j + h_l, n} \cdot \lambda_{l}^{N + k - j} \cdot \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) \right \vert
		\end{align*}
		and we want to find a bound for the right-hand side of this equation. Using the triangle inequality we get 
		\begin{align*}
			p_{N+1} &\leq  \sum_{l = a_{\probMatrix}+1}^{q_{\jordanMatrix}-z} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j}  \vert \symmetryMatrix_{1, k + h_l} \cdot  \symmetryMatrix^{-1}_{j + h_l, n} \vert \cdot \vert \lambda_{l}^{N + k - j} \vert \cdot \left \vert \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) \right \vert \\
			&\leq \sum_{l = a_{\probMatrix}+1}^{q_{\jordanMatrix}-z} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j}  \vert \symmetryMatrix_{1, k + h_l} \cdot \symmetryMatrix^{-1}_{j + h_l, n}  \vert \cdot \vert \lambda^{N + k - j} \vert \cdot \left \vert \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) \right \vert \\
			&\leq \vert \lambda \vert^{N - r + 1} \cdot \sum_{l = a_{\probMatrix}+1}^{q_{\jordanMatrix}-z} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j}  \vert \symmetryMatrix_{1, k + h_l} \cdot \symmetryMatrix^{-1}_{j + h_l, n} \vert \cdot \left \vert \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) \right \vert
		\end{align*}
		where the second inequality follows from $\vert \lambda \vert \geq \vert \lambda_i\vert$ for every $a_{\probMatrix} + 1 \leq i \leq q_{\jordanMatrix}-z$, and the last inequality holds since $N + 1 - r$ is the minimal possible exponent of $\lambda$ in any of the summands. 

		For $l = a_{\probMatrix}+1, \ldots, q_{\jordanMatrix}-z$ let $\vert \lambda_{l}^* \vert = \max\{\vert \lambda_{l} \vert, \vert 1 - \lambda_{l} \vert\}$. If $j = k = 1$, i.e., if $j - k = 0$, the right-most factor can be bounded via 
		\begin{align*}
			\left \vert \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) \right \vert &= \vert \lambda_{l} - 1 \vert \leq \lambda_{l}^* = \lambda_{l}^{*} \cdot \frac{(N+1)^{j-k}}{(j-k)!},
		\end{align*}
		while for $j -k > 0$ we obtain 
		\begin{align*}
			&\left \vert \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) \right \vert \\
			&= \left \vert \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \lambda_{l} \cdot \binom{N}{j-k} + \lambda_{l} \cdot \binom{N}{j-k} - \binom{N}{j-k} \right) \right \vert \\
			&\leq \left \vert \lambda_{l} \cdot \binom{N+1}{j-k} - \lambda_{l} \cdot \binom{N}{j-k} \right \vert + \left \vert \lambda_{l} \cdot \binom{N}{j-k} - \binom{N}{j-k}  \right \vert \\
			&= \vert \lambda_{l} \vert \cdot \left \vert \binom{N+1}{j-k} - \binom{N}{j-k} \right \vert + \binom{N}{j-k} \cdot \vert \lambda_{l} - 1 \vert \\
			&\leq \lambda_{l}^* \cdot \left( \left \vert \binom{N+1}{j-k} - \binom{N}{j-k} \right \vert + \binom{N}{j-k} \right) \\
			&= \lambda_{l}^* \cdot \left( \left \vert \binom{N}{j-k} + \binom{N}{j-k-1} - \binom{N}{j-k} \right \vert + \binom{N}{j-k} \right) \\
			&= \lambda_{l}^* \cdot \left( \binom{N}{j-k-1} + \binom{N}{j-k} \right)  \\
			&=  \lambda_{l}^*  \cdot \binom{N+1}{j-k} \\
			&\leq \vert \lambda_{l}^* \vert \cdot \frac{(N+1)^{j-k}}{(j-k)!}
		\end{align*}
		where the last inequality holds trivially if $N + 1 < j-k$, as in this case we have $\binom{N+1}{j-k} = 0$, and otherwise follows from
		\begin{align*}
			\binom{n}{k} = \frac{n!}{k! \cdot (n-k)!} = \frac{n \cdot {n-1} \cdot \ldots \cdot (n-k+1)}{k!} \leq \frac{n^{k}}{k!}
		\end{align*}
		for every $n \geq k$. As $(j-k)! \geq 1$ for every $j \geq k$, which holds by definition of the corresponding sum, and $j-k \leq r - 1$ we additionally obtain
		\begin{align*}
			\left \vert \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) \right \vert \leq \vert \lambda_{l}^* \vert \cdot (N+1)^{r-1}. 
		\end{align*}
		All in all, this yields 
		\begin{align*}
			p_{N+1} &\leq \vert \lambda \vert^{N - r + 1} \cdot \sum_{l = a_{\probMatrix}+1}^{q_{\jordanMatrix}-z} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j}  \vert \symmetryMatrix_{1, k + h_l}  \cdot \symmetryMatrix^{-1}_{j + h_l, n} \vert \cdot \left \vert \left(\lambda_{l} \cdot \binom{N+1}{j-k} - \binom{N}{j-k} \right) \right \vert \\
			& \leq \vert \lambda \vert^{N - r + 1} \cdot \sum_{l = a_{\probMatrix}+1}^{q_{\jordanMatrix}-z} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j}  \vert \symmetryMatrix_{1, k + h_l} \cdot \symmetryMatrix^{-1}_{j + h_l, n}  \vert \cdot \vert \lambda_{l}^* \vert \cdot (N+1)^{r - 1} \\
			&= \vert \lambda \vert^{N - r + 1} \cdot (N+1)^{r - 1} \cdot \underbrace{\sum_{l = a_{\probMatrix}+1}^{q_{\jordanMatrix}-z} \sum_{j = 1}^{r_{l}} \sum_{k = 1}^{j}  \vert \symmetryMatrix_{1, k + h_l} \cdot \symmetryMatrix^{-1}_{j + h_l, n} \vert \cdot \vert \lambda_{l}^* \vert}_{\eqcolon C} \\
			&= \vert \lambda \vert^{N - r + 1} \cdot (N+1)^{r - 1} \cdot C,
		\end{align*}
		where $C$ is a positive constant that is independent of $N$.

		In particular, it follows for every $k \geq R$ that
		\begin{align*}
			p_{k} \leq \vert \lambda \vert^{k - r} \cdot k^{r - 1} \cdot C
		\end{align*}
		and plugging this upper bound into \Cref{eq:jordan-bound} finishes the proof.
	\end{proof}


	\section{Additional Proofs of \Cref{sec:reward-bounds}}
	We start with a short recap on the computation of reward-bounded reachability probabilities. We follow \cite{LCPP}[Sec. 3], adjusted to our setting. For $x, y \in \mathbb{R}$, let $x \ominus y = \max\{0, x - y\}$. Further, for a given state $s$ and some reward bound $r \geq 0$, let $K = K_{s, r} = \{x \geq 0 \mid \reward(s) \cdot x \leq r \}$. Lastly, for states $s,s'$, let $R(s,s') = \rate(s) \cdot \prob(s,s')$. 

	As we are interested in reward-bounded reachability probabilities, we do not need to consider any constraint on the time up until reaching the goal state $g$ from state $s$. As the reward of $g$ does not affect the reward-bounded probability \emph{until reaching} $g$, we can w.l.o.g. assume $\reward(g) > 0$. In the notation of \cite{LCPP} we get that $\probMeasure_s(\reachability_{\leq r}g)$ for some reward bound $r$ is the least solution of the following set of equations: 
	\begin{align*}
		\probMeasure_s(\reachability_{\leq r}g) = \begin{cases}
			\int_{0}^{\sup K_{s,r}} \sum_{s' \in S} R(s,s') \cdot e^{-\rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r \ominus \rho(s) \cdot x} g) \ \mathrm{dx}, & \text{if } s \neq g  \\
			1, & \text{if } s = g
		\end{cases}.
	\end{align*}

	First, we show that removing self-loops from states with reward $0$ does not change the reward-bounded reachability probabilities of the goal state $g$. Note that in the following lemma we can exclude $\prob(s,s)= 1$, because in this case $s$ is absorbing and the probability to reach $g$ from $s$ equals $0$, independent of the reward-bound. 
	\begin{restatable}{lemma}{LemRemoveSelfLoops}\label{lem:remove-self-loops-reward-bounded-reach}
		Let $\mathcal{M}$ be a CTMC and $s \in \stateSpace$ with $\rho(s) = 0$ and $\prob(s, s) \in (0,1)$. Then $\probMeasure^\mathcal{M}_s(\reachability_{\leq r} g) = \probMeasure^{\mathcal{M}^*}_s(\reachability_{\leq r} g)$, where $\mathcal{M}^*$ is as $\mathcal{M}$, with the only difference being that $\prob^{\mathcal{M}^*}(s,s) = 0$ and $\prob^{\mathcal{M}^*}(s,s') = \frac{\prob^\mathcal{M}(s,s')}{1 - \prob^\mathcal{M}(s,s)}$ for all $s \neq s'$. 
	\end{restatable}
	\begin{proof}
		By our assumption $\rho(g) > 0$ and hence $s \neq g$. Furthermore, as $\rho(s) = 0$ we have $K_{s,r} = [0, \infty)$ for every $r \geq 0$ and $r \ominus \rho(s) \cdot x = r$ for every $x \geq 0$. Thus, the reward-bounded reachability probabilities from $s$ are given as \cite{LCPP}
		\begin{align*}
			\probMeasure_s(\reachability_{\leq r}g) &= \int_{0}^{\infty} \sum_{s' \in S} R(s,s') \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx} \\
			&= \int_{0}^{\infty} \sum_{s' \in S \setminus \{s\}} R(s,s') \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx} \\
			& \qquad + \int_{0}^{\infty} R(s,s) \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s}(\reachability_{\leq r} g) \ \mathrm{dx}.
		\end{align*}
		Now we can simplify the second integral via 
		\begin{align*}
			\int_{0}^{\infty} R(s,s) \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s}(\reachability_{\leq r} g) \ \mathrm{dx}
			&= R(s,s) \cdot \probMeasure_{s}(\reachability_{\leq r} g)  \cdot \int_{0}^{\infty} e^{- \rate(s) \cdot x} \ \mathrm{dx} \\
			&= R(s,s) \cdot \probMeasure_{s}(\reachability_{\leq r} g) \cdot \frac{1}{\rate(s)} \\
			&= \prob(s,s) \cdot \probMeasure_{s}(\reachability_{\leq r} g).
		\end{align*}
		Therefore, 
		\begin{align*}
			\probMeasure_s(\reachability_{\leq r}g) = \int_{0}^{\infty} \sum_{s' \in S \setminus \{s\}} R(s,s') \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx} + \prob(s,s) \cdot \probMeasure_{s}(\reachability_{\leq r} g)
		\end{align*}
		which is equivalent to 
		\begin{align*}
			\probMeasure_{s}(\reachability_{\leq r} g) \cdot (1 - \prob(s,s)) = \int_{0}^{\infty} \sum_{s' \in S \setminus \{s\}} R(s,s') \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx}
		\end{align*}
		and hence 
		\begin{align*}
			\probMeasure_{s}(\reachability_{\leq r} g) &= \frac{1}{1-\prob(s,s)} \cdot \int_{0}^{\infty} \sum_{s' \in S \setminus \{s\}} R(s,s') \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx} \\
			&= \int_{0}^{\infty} \sum_{s' \in S \setminus \{s\}} \rate(s) \cdot \frac{\prob(s,s')}{1 - \prob(s,s)} \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx} \\
			&= \int_{0}^{\infty} \sum_{s' \in S \setminus \{s\}} \rate(s) \cdot \prob^{\mathcal{M}^*}(s,s') \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx} \\
			&= \int_{0}^{\infty} \sum_{s' \in S} \rate(s) \cdot \prob^{\mathcal{M}^*}(s,s') \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx} \\
			&= \int_{0}^{\infty} \sum_{s' \in S} R^{\mathcal{M}^*}(s,s') \cdot e^{- \rate(s) \cdot x} \cdot \probMeasure_{s'}(\reachability_{\leq r} g) \ \mathrm{dx} \\
			&= \probMeasure^*_s(\reachability_{\leq r} g)
		\end{align*}
		where the second to last equality follows because $\prob^{\mathcal{M}^*}(s,s) = 0$.
	\end{proof}

	Thanks to \Cref{lem:remove-self-loops-reward-bounded-reach} we can assume w.l.o.g. that no state $s$ in $\mathcal{M}$ with reward $\rho(s) = 0$ has a self-loop when computing reward-bounded reachability probabilities.

	Next, we show that it is possible to safely remove states with reward $0$ from a CTMC without changing the reward-bounded reachability probabilities of any state with positive reward. 
	\PropRemoveRewardZeroStates*
	\begin{proof}
		We show the claim by proving that, for any state $t$ in $\mathcal{M}$ and any successor $t'$ of $t$ with $\rho(t) = 0$ the reward-bounded reachability probabilities in $\mathcal{M}$ are the same as in the chain $\mathcal{M}'$ obtained by removing $t'$ from $\stateSpace$ and setting, for every state $t''$ with $\prob(t'', t') > 0$, the probability distribution as $\prob'(t'', t''') =  \prob(t'',t''') + \prob(t'', t') \cdot \prob(t', t''')$ for all $t''' \neq t'$. By iteratively applying this transformation, we can remove all states with reward $0$ from $\mathcal{M}$, obtaining in the end a CTMC $\mathcal{M}_{> 0}$ of the desired form. 

		By our assumptions it holds for any state $t' $ with $\rho(t') = 0$ that $t' \neq g$. Furthermore, we can assume w.l.o.g. that $\prob(t', t') = 0$ because of \Cref{lem:remove-self-loops-reward-bounded-reach}. Using the latter, we show that $\prob'(t'', \cdot)$ as defined above is a distribution for every $t'' \in \stateSpace \setminus \{t'\}$. If $\prob(t'', t') = 0$, moving from $\mathcal{M}$ to $\mathcal{M}'$ does not change the transition probabilities of $t''$ at all, so nothing is to show. Otherwise, 
		\begin{align*}
			\prob'(t'', \stateSpace \setminus \{t'\}) &= \sum_{t \in \stateSpace \setminus \{t'\}} \prob'(t'', t) \\
				&= \sum_{t \in \stateSpace \setminus \{t'\}} \prob(t'', t) + \prob(t'', t') \cdot \prob(t', t) \\
					&=  \sum_{t \in \stateSpace \setminus \{t'\}} \prob(t'', t) + \sum_{t \in \stateSpace \setminus \{t'\}} \prob(t'', t') \cdot \prob(t', t) \\
					&= \sum_{t \in \stateSpace \setminus \{t'\}} \prob(t'', t) + \prob(t'', t') \cdot \underbrace{\sum_{t \in \stateSpace \setminus \{t'\}} \prob(t', t)}_{= \sum_{t \in \stateSpace} \prob(t', t) = 1 \text{ as} \prob(t', t') = 0} \\
					&= \sum_{t \in \stateSpace \setminus \{t'\}} \prob(t'', t) + \prob(t'', t') = 1.
		\end{align*}

		To show the preservation of reward-bounded reachability probabilities, we first observe that
		\begin{align}
			\probMeasure_{t'}(\reachability_{\leq r} g) &= \int_{0}^{\infty} \sum_{t'' \in S} R(t',t'') \cdot e^{- \rate(t') \cdot x} \cdot \probMeasure_{t''}(\reachability_{\leq r \ominus \rho(t') \cdot x} g) \ \mathrm{dx} \nonumber \\
			&= \int_{0}^{\infty} \sum_{t'' \in S} R(t',t'') \cdot e^{- \rate(t') \cdot x} \cdot \probMeasure_{t''}(\reachability_{\leq r} g) \ \mathrm{dx} \nonumber \\
			&= \sum_{t'' \in \stateSpace} \probMeasure_{t''}(\reachability_{\leq r} g) \cdot R(t', t'') \cdot \int_{0}^{\infty} e^{-\rate(t') \cdot x} \ \mathrm{dx} \nonumber \\
			&= \sum_{t'' \in \stateSpace} \probMeasure_{t''}(\reachability_{\leq r} g) \cdot \prob(t', t'') \cdot \rate(t') \cdot \frac{1}{\rate(t')} \nonumber \\
			&= \sum_{t'' \in \stateSpace} \probMeasure_{t''}(\reachability_{\leq r} g) \cdot \prob(t', t'') \nonumber \\
			&= \sum_{t'' \in \stateSpace \setminus \{t'\}} \probMeasure_{t''}(\reachability_{\leq r} g) \cdot \prob(t', t''). \label{eq:remove-rewards-eq-1}
		\end{align}
		Let now $t \in \stateSpace$ with $\prob(t,t') > 0$. Then 
		\begin{align*}
			&\textcolor{white}{=}\probMeasure^\mathcal{M}_t(\reachability_{\leq r} g) \\&= \int_{0}^{\sup K_{t,r}} \sum_{t''' \in \stateSpace} R(t,t''') \cdot e^{- \rate(t) \cdot x} \cdot \probMeasure_{t'''}(\lozenge_{\leq r\ominus \rho(t) \cdot x} g) \ \mathrm{dx} \\
			&= \int_{0}^{\sup K_{t,r}} \sum_{t''' \in \stateSpace \setminus \{t'\}} R(t,t''') \cdot e^{- \rate(t) \cdot x} \cdot \probMeasure_{t'''}(\lozenge_{\leq r\ominus \rho(t)\cdot x} g) \\
			& \qquad + R(t,t') \cdot e^{- \rate(t) \cdot x} \cdot  \probMeasure_{t'}(\lozenge_{\leq r \ominus \rho(t) \cdot x} g) \ \mathrm{dx} \\
			&= \int_{0}^{\sup K_{t,r}} \sum_{t''' \in \stateSpace \setminus \{t'\}} R(t,t''') \cdot e^{- \rate(t) \cdot x} \cdot \probMeasure_{t'''}(\lozenge_{\leq r\ominus \rho(t)\cdot x} g) \\
			& \qquad + R(t,t') \cdot e^{- \rate(t) \cdot x} \cdot \sum_{t'' \in \stateSpace \setminus \{t'\}} \probMeasure_{t''}(\reachability_{\leq r \ominus \rho(t)\cdot x} g) \cdot \prob(t', t'') \ \mathrm{dx}
			\\ 
			&= \int_{0}^{\sup K_{t,r}} \sum_{t''' \in \stateSpace \setminus \{t'\}} \rate(t) \cdot (\prob(t,t''') + \prob(t,t') \cdot \prob(t', t''')) \cdot e^{- \rate(t) \cdot x} \cdot \probMeasure_{t'''}(\lozenge_{\leq r\ominus \rho(t)\cdot x} g) \ \mathrm{dx} \\
			&= \int_{0}^{\sup K_{t,r}} \sum_{t''' \in \stateSpace \setminus \{t'\}} \rate(t)  \cdot \prob'(t,t''') \cdot e^{- \rate(t) \cdot x} \cdot \probMeasure_{t'''}(\lozenge_{\leq r\ominus \rho(t)\cdot x} g) \ \mathrm{dx} \\
			&= \int_{0}^{\sup K_{t,r}} \sum_{t''' \in \stateSpace \setminus \{t'\}} R^{\mathcal{M}'}(t,t'')  \cdot e^{- \rate(t) \cdot x} \cdot \probMeasure_{t'''}(\lozenge_{\leq r\ominus \rho(t)\cdot x} g) \ \mathrm{dx} \\
			&= \probMeasure^{\mathcal{M}'}_t(\reachability_{\leq r} g),
		\end{align*}
		so removing $t'$ and redistributing the incoming probabilities as described above indeed preserves reward-bounded reachability probabilities. 
	\end{proof}

	\begin{remark}
		Assume that we are given a CTMC $\mathcal{M}$ and a state $s$ with $\rho(s) = 0$, and that we want to compute $\probMeasure_s(\lozenge_{\leq r} g)$. Then, when constructing $\mathcal{M}_{> 0}$ as proposed in (the proof of) \Cref{prop:remove-reward-0-states}, the state $s$ is removed from the chain, making $\probMeasure_s^{\mathcal{M}_{> 0}}$ not well-defined as $s \notin \stateSpace^{\mathcal{M}_{> 0}}$. However, it is obvious that $\probMeasure_s(\lozenge_{\leq r} g) = \sum_{s' \in \Succ(s)} \prob(s,s') \cdot \probMeasure_{s'}(\lozenge_{\leq r} g)$, as $s$ has reward $0$ and since we can safely assume that $\prob(s,s) = 0$ by \Cref{lem:remove-self-loops-reward-bounded-reach}. Hence, we can still construct $\mathcal{M}_{> 0}$, compute the reward bounded reachability probabilities for all $s' \in \Succ(s)$ (potentially applying the above argument multiple times if there is a path starting in $s$ with an initial prefix of states with reward $0$) and taking the weighted sum of these values to obtain the corresponding probability for $s$. 
	\end{remark}
