\textit{Proof of Lemma 2:} Given a wireless communication system including the parameters $\{N,B,C,R\}$, the relationship between $t_c$ and $P_{s}$ follows the formula below~\cite{pa1,ps1,ps2}.
\vspace{-0.3cm}

{\footnotesize
\begin{equation*}
    1-P_{s}=Q\left(\frac{(C-R)BNt_c+0.5\log_{2}(BNt_c)}{\log_{2}e\cdot \sqrt{BNt_c}}\right),
    %\label{eq_tcPs}
\end{equation*}}%
where $Q(\cdot)$ is the $Q$-function.
Let the independent variable part of $Q(\cdot)$ in the above equation as a new function $\Phi(t_c)$ with respect to $t_c$. %Referring to~\cite{2019phi}, $P_s$ has monotonic increasing relationship with $t_c$
Furthermore, from Equaition (4) in \cite{ps2}, $\Phi(t_c)$ is a monotonic increasing function of $t_c$, it must have a unique corresponding inverse function $\Phi^{-1}(t_c)$. Accordingly, $t_c$ can be calculated in~\cref{lem2}.\hfill$\blacksquare$ 
\vspace{-0.1cm}
\section{}
\label{proof_pro1}
\vspace{-0.3em}
\textit{Proof of Proposition 1:} The successful transmission probability $P_{s,l}$ of a link is usually determined by the probability of the received SNR/SINR $\gamma_{l}$ over a minimum threshold $\gamma_{0,l}$ that the receiver can decode the signal, thus, $\mathbb{P}(\gamma_{l}\geq \gamma_{0,l})$. Among the three types of transmission links, some are robust to interference and some are not. Therefore, the calculation of $P_{s}$ includes two cases, i.e., interference-free and interference-involved. For the interference-free case, $\gamma_{l}$ is SNR, and no interference is involved. For the interference case, $\gamma_{l}$ is SINR, and the probability calculation needs to consider the distribution of interferers, i.e., related to the distance distribution $d$ from all other ground nodes to the receiver. To sum up, we have the general formula of $P_{s,l}$ in~\cref{pro0}.
\hfill $\blacksquare$

\vspace{-0.1cm}
\section{}
\label{proof_cro1}
\vspace{-0.3em}
\textit{Proof of Corollary 1:} %Let $f_{\gamma_{\mathrm{g}}}$ be PDF of $\gamma_{\mathrm{g}}$. 
Substituting~\cref{eq_gamma_g,eq_fi} into~\cref{pro0}, we have
\vspace{-0.5cm}

{\footnotesize
\begin{align}
    &P_{s,\mathrm{g}}=
    \mathbb{P}(\gamma_{\mathrm{g}}\geq \gamma_{0,\mathrm{g}})
    \overset{(a)}{=}\mathbb{P}\left(\int_{\gamma_{0,\mathrm{g}}-\varepsilon}^{+\infty}f_{\gamma_{\mathrm{g}}}\mathrm{d}\gamma_{\mathrm{g}}\geq \int_{\gamma_{0,\mathrm{g}}-\varepsilon}^{+\infty}\gamma_{0,\mathrm{g}}'\mathrm{d}\gamma_{\mathrm{g}}\right)\notag \\
    %&=\mathbb{P}(f_{\gamma_{\mathrm{g}}}\geq\gamma_{0,\mathrm{g}}')=\mathbb{P}\left(f_{S_{\mathrm{g}}}\left(\frac{2}{D_{\mathrm{g}}^{2}}\right)^{K}\prod\limits_{k=1}^{K}d_x\geq \gamma_{0,\mathrm{g}}'\right)\notag \\   
    &=\mathbb{P}\left(\prod\limits_{k=1}^{K}d_x\geq \frac{\gamma_{0,\mathrm{g}}'}{f_{S_{\mathrm{g}}}}\left(\frac{D_{\mathrm{g}}^{2}}{2}\right)^{K}\right),
    \label{a1}
\end{align}}%
where $\varepsilon$ is a constant and satisfies $0<\varepsilon<\gamma_{0,\mathrm{g}}$ and $(a)$ comes from the substitution of
\vspace{-0.3cm}

{\footnotesize
\begin{align}
    &\gamma_{0,\mathrm{g}}'=\frac{1-\int_{\gamma_{0,\mathrm{g}}-\varepsilon}^{\gamma_{0,\mathrm{g}}}f_{\gamma_{\mathrm{g}}}\mathrm{d}\gamma_{\mathrm{g}}}{\gamma_{0,\mathrm{g}}-\varepsilon},%\label{aa1}\\
    %&
    \int_{\gamma_{0,\mathrm{g}}-\varepsilon}^{\gamma_{0,\mathrm{g}}}f_{\gamma_{\mathrm{g}}}\mathrm{d}\gamma_{\mathrm{g}}=\int_{\gamma_{0,\mathrm{g}}-\varepsilon}^{+\infty}\gamma_{0,\mathrm{g}}'\mathrm{d}\gamma_{\mathrm{g}}.\label{aa2}
\end{align}}
In~\cref{a1}, each $d_x$ in $\prod_{k=1}^{K}d_x$ is a distance random variable from an interferer node to the desired receiver. Let $d_{\min}$ and $d_{\max}$ be the minimum and maximum value of $d_x$. Due to the homogeneity of ground nodes and the value range of a Cumulative Density Function (CDF) of the random variable $\prod_{k=1}^{K}d_x$,
we have the upper bound $P_{s,\mathrm{g}}^{\mathrm{L}}=\mathbb{P}\left(d_{\min}^{K}\geq \gamma_{0,\mathrm{g}}'/f_{S_{\mathrm{g}}}\cdot\left(D_{\mathrm{g}}^{2}/2\right)^{K}\right)$ and lower bound $P_{s,\mathrm{g}}^{\mathrm{U}}=\mathbb{P}\left(d_{\max}^{K}\geq \gamma_{0,\mathrm{g}}'/f_{S_{\mathrm{g}}}\cdot\left(D_{\mathrm{g}}^{2}/2\right)^{K}\right)$. Let $\gamma_{0,L}'$ and $\gamma_{0,U}'$ be the lower bound and upper bound of $\gamma_{0,\mathrm{g}}$. Referring to~\cref{aa2}, we have $ \gamma_{0,L}'\leq\gamma_{0,\mathrm{g}}'\leq\gamma_{0,U}',\gamma_{0,L}'=(1-\varepsilon)/(\gamma_{0,\mathrm{g}}-\varepsilon),\gamma_{0,U}'=1/(\gamma_{0,\mathrm{g}}-\varepsilon)$. Combining $\gamma_{0,L}',\gamma_{0,U}',P_{s,\mathrm{g}}^{\mathrm{L}},P_{s,\mathrm{g}}^{\mathrm{U}}$, we have
\vspace{-0.3cm}

{\footnotesize
\begin{align*}
    &P_{s,\mathrm{g}}^{\mathrm{L}}
    \geq \mathbb{P}\left(d_{\min}^{K}\geq \frac{\gamma_{0,U}'}{f_{S_{\mathrm{g}}}}\left(\frac{D_{\mathrm{g}}^{2}}{2}\right)^{K}\right)
    =1-\mathbb{P}\left(d_{\min}\leq \left(\frac{\gamma_{0,U}'}{f_{S_{\mathrm{g}}}}\right)^{\frac{1}{K}}\frac{D_{\mathrm{g}}^{2}}{2}\right)\notag\\
    &\overset{(a)}{=}1-\left(1-\left(1-\frac{1}{D_{l}^{2}}\left(\frac{\gamma_{0,U}'}{f_{S_{\mathrm{g}}}}\right)^{\frac{2}{K}}\frac{D_{\mathrm{g}}^{4}}{4}\right)^{K}\right)%\notag\\
    %&
    =\left(1-\frac{D_{\mathrm{g}}^{2}}{4}\left(\frac{\gamma_{0,U}'}{f_{S_{\mathrm{g}}}}\right)^{\frac{2}{K}}\right)^{K},\\&P_{s,\mathrm{g}}^{\mathrm{U}}
    \leq \mathbb{P}\left(d_{\max}^{K}\geq \frac{\gamma_{0,L}'}{f_{S_{\mathrm{g}}}}\left(\frac{D_{\mathrm{g}}^{2}}{2}\right)^{K}\right)
    =1-\mathbb{P}\left(d_{\max}\leq \left(\frac{\gamma_{0,L}'}{f_{S_{\mathrm{g}}}}\right)^{\frac{1}{K}}\frac{D_{\mathrm{g}}^{2}}{2}\right)\notag\\
    &\overset{(b)}{=}1-\left(\frac{1}{D_{\mathrm{g}}^{2}}\left(\frac{\gamma_{0,L}'}{f_{S_{\mathrm{g}}}}\right)^{\frac{2}{K}}\frac{D_{\mathrm{g}}^{4}}{4}\right)^{K}
    =1-\frac{D_{\mathrm{g}}^{2K}}{4^{K}}\left(\frac{\gamma_{0,L}'}{f_{S_{\mathrm{g}}}}\right)^{2},%\label{a3}
\end{align*}
}
where $(a)$ and $(b)$ comes from $\mathbb{P}(X\leq x)=F_{X}(X)$. %\cref{a3,a4} results 
Accordingly, we have the new lower bound and upper bound of $P_{s,\mathrm{g}}$. 
Substituting $f_{S_{\mathrm{g}}}=2\pi\lambda_{\mathrm{g}}d_0e^{-\lambda_{\mathrm{g}}\pi d_0^{2}}$ and $K=\left \lceil \pi \lambda_{\mathrm{g}} D_{\mathrm{g}}^2\right \rceil$ into bound functions, we have~\cref{cro1}.
\hfill$\blacksquare$
\vspace{-0.3em}
\section{}
\label{proof_cro2}
\vspace{-0.3em}
\textit{Proof of Corollary 2:} Substituting~\cref{eq_gamma_sg,eq_fh} into~\cref{pro0}, $P_{s,\mathrm{sg}}$ can be calculated by $P_{s,\mathrm{sg}}=1-\mathbb{P}\left(|h_{\mathrm{sg}}|^{2}\leq \frac{(\sigma_{\mathrm{sg}})^{2}\gamma_{0,\mathrm{sg}}}{p_{\mathrm{sg}}G_{\mathrm{sg}}L_{\mathrm{sg}}(d_0)}\right)$. 
Substituting the CDF of $|h_{\mathrm{sg}}|^{2}$ into the above equation, we have~\cref{cro2}.
\hfill$\blacksquare$
%\vspace{-0.3em}
\section{}
\label{proof_cro3}
%\vspace{-0.3em}
\textit{Proof of Corollary 3:}
Substituting~\cref{eq_gamma_s,eq_fw} into~\cref{pro0}, $P_{s,\mathrm{s}}$ can be calculated as follow. 
%\vspace{-0.3cm}

{\footnotesize
\begin{align}&P_{s,\mathrm{s}}=\mathbb{P}\left(\gamma_{\mathrm{s}}\geq\gamma_{0,\mathrm{s}}\right)\overset{(a)}{=}(1-\varsigma^{2})\left(1-\left(\frac{\gamma_{0,\mathrm{s}}\sigma_{\mathrm{s}}^{2}16\pi^2 c^2d_0^{2}}{A_{0}p_{\mathrm{s}}G_{\mathrm{s}}f_{\mathrm{s}}^{2}}\right)^{\eta_{s}^{2}}\right),\notag%\label{eq_pss}
\end{align}}%
where $(a)$ follows the similar derivation of the Lemma 1 in \cite{ss}. Given any two satellites on the altitudes $h_{i}$ and $h_{j}$, the maximum visible distance is $d_{0}^{\max}=\sqrt{h_{i}(h_{i}+2R_{\mathrm{e}})}+\sqrt{h_{j}(h_{j}+2R_{\mathrm{e}})}$ with $R_{\mathrm{e}}$ being the earth radius. Then %~\cref{eq_pss}
$P_{s,\mathrm{s}}$ has the lower bound and upper bound in~\cref{cro3}.
%This completes the proof.
\hfill$\blacksquare$
%\vspace{-0.3em}
\section{}
\label{proof_the1}
%\vspace{-0.3em}
\textit{Proof of Theorem 1:} In \textbf{Mode 1} ($k=1$), the DID consensus is completed via \textit{inter-ground links} among ground chain nodes. Referring to~\cref{lem2}, given $P_{s,\mathrm{g}}$ of a inter-ground link, the latency $t_{c,\mathrm{g}}$ can be calculated by $t_{c,\mathrm{g}}=\Phi^{-1}\left(Q^{-1}(1{-}P_{s,\mathrm{g}})\right)$
In this equation, $Q^{-1}(\cdot)$ is a monotonic decreasing function, $\Phi^{-1}(\cdot)$ is 
a monotonic increasing function, then $t_{c,\mathrm{g}}$ have monotonic trend relationship with $P_{s,\mathrm{g}}$. Substituting~\cref{cro1} into~\cref{lem2}, we have the lower bound and upper bound of $t_{c,\mathrm{g}},T_{1,\mathrm{overall}}$ as follows.
\vspace{-0.3cm}

{\footnotesize
\begin{align*}
        &4t_{c,\mathrm{g}}^{\mathrm{L}}\leq T_{1,\mathrm{overall}}\leq 4t_{c,\mathrm{g}}^{\mathrm{U}},t_{c,\mathrm{g}}^{\mathrm{L}}\leq t_{c,\mathrm{g}} \leq t_{c,\mathrm{g}}^{\mathrm{U}},\\
        &t_{c,\mathrm{g}}^{\mathrm{L}}=\Phi^{-1}\left(Q^{-1}(1{-}P_{s,\mathrm{g}}^{\mathrm{U}})\right),
        t_{c,\mathrm{g}}^{\mathrm{U}}=\Phi^{-1}\left(Q^{-1}(1{-}P_{s,\mathrm{g}}^{\mathrm{L}})\right).
\end{align*}}%
In \textbf{Mode 2} ($k=2$), the DID consensus is completed via \textit{inter-ground links} among ground chain nodes and \textit{satellite-ground links} between ground chain nodes and satellites. In \textbf{Mode 3} ($k=3$), the DID consensus is completed via \textit{inter-satellite links} among satellite chain nodes. Following the derivation process of $T_{1,\mathrm{overall}}$, we can calculate the lower bound and upper bound of $T_{2,\mathrm{overall}}$ and $T_{3,\mathrm{overall}}$ as follows.
\vspace{-0.3cm}

{\footnotesize
\begin{align*}
        &4\max\{t_{c,\mathrm{g}}^{\mathrm{L}},t_{c,\mathrm{sg}}\}\leq T_{2,\mathrm{overall}}\leq 4\max\{t_{c,\mathrm{g}}^{\mathrm{U}},t_{c,\mathrm{sg}}\},
        \\
        &t_{c,\mathrm{sg}}=\Phi^{-1}\left(Q^{-1}(1{-}P_{s,\mathrm{sg}})\right);\\
        &4t_{c,\mathrm{s}}^{\mathrm{L}}\leq T_{3,\mathrm{overall}}\leq 4t_{c,\mathrm{s}}^{\mathrm{U}},\\
        &t_{c,\mathrm{s}}^{\mathrm{L}}=\Phi^{-1}\left(Q^{-1}(1{-}P_{s,\mathrm{s}}^{\mathrm{U}})\right),
        t_{c,\mathrm{s}}^{\mathrm{U}}=\Phi^{-1}\left(Q^{-1}(1{-}P_{s,\mathrm{s}}^{\mathrm{L}})\right).
\end{align*}}%
The values of $P_{s,\mathrm{sg}},P_{s,\mathrm{s}}^{\mathrm{L}},P_{s,\mathrm{s}}^{\mathrm{U}}$ are given in~\cref{cro2,cro3}. Substituting the value range of $T_{k,\mathrm{overall}}$ into~\cref{lem1}, we can derive the lower bound and upper bound of $\mathsf{TPS}_{k}$ of three modes. Thereby, we have~\cref{the1}.\hfill$\blacksquare$
}

