from typing import Callable
import torch

def quantize(x_tilde: torch.Tensor, w: torch.Tensor, b: %%int%%, f: Callable, eps: %%float%% = 1e-5) -> torch.Tensor:
    # b: precision
    # eps: small floating-point number 
    q = 2 ** (b - 1)
