\kedit{Figure~\ref{fig: proposed} shows the quantization of the TTS model using the proposed method.} 
% As shown in Figure~\ref{fig: proposed}, 
The stored indices are used to quickly reconstruct the quantized weights $\widetilde{\kedit{\bm{W}}}$ from the predefined patterns $\mathcal{P}$. This involves retrieving the corresponding pattern for each index and concatenating the segments to form the complete weight tensor. 
\if 0
\begin{algorithm}
\caption{Weight Indexing After Training Model}
\label{alg:weight_indexing}
\begin{algorithmic}[1]
\State \textbf{Input:} $\widetilde{W}$, kernel size $K$, threshold $K_{\text{threshold}}$
\State \textbf{Output:} Indices into weight patterns $\mathcal{P}$



\If {$K > K_{\text{threshold}}$}
    \State Generate ternary patterns $\mathcal{P}$ for kernel size $K_{\text{threshold}}$
    \State Split $\widetilde{W}$ into segments of size $K_{\text{threshold}}$
    \State Append remaining elements as the final segment
    \State $\mathbf{S} \gets [K_{\text{threshold}}, K_{\text{threshold}}, \ldots, K \bmod K_{\text{threshold}}]$
\Else
    \State Generate ternary patterns $\mathcal{P}$ for kernel size $K$
    \State $\mathbf{S} \gets [K]$
\EndIf
\State Initialize $\mathcal{I} \in \mathbb{R}^{c_{\text{out}} \times c_{\text{in}} \times |\mathbf{S}|}$
\For {each $i$ in $\{1, \ldots, c_{\text{out}}\}$}
    \For {each $j$ in $\{1, \ldots, c_{\text{in}}\}$}
        \State $h \gets 0$
        \For {each $m, s$ in $\mathbf{S}$}
            \State $p \gets \arg \min_{p \in \mathcal{P}} \| \widetilde{W}_{i,j,h:h+s} - p \|$
            \State $\mathcal{I}_{i,j,m} \gets p$
            \State $h \gets h + s$
        \EndFor
    \EndFor
\EndFor
\State \textbf{Return:} Indices $\mathcal{I}$
\end{algorithmic}
\end{algorithm}
\fi


\begin{algorithm}[t]
\caption{Weight Indexing}
\label{alg:generalized_weight_indexing}
\begin{algorithmic}[1]
\State \textbf{Input:} $\widetilde{\bm{v}}=(\widetilde{v}_{1},\ldots,\widetilde{v}_{L})^{\mathsf{T}} \in \{-1, 0, 1\}^{L}$, block size $L^*$
\State \textbf{Output:} List of indices of weight pattern $\mathcal{P}$
\State Initialize $\text{indices} = []$
\For {each block in $\{1, 2, \ldots, \lceil L / L^* \rceil\}$}
    \State Initialize $n = 0$
    \For {each $l$ in $\{ \min(\text{block} \times L^*, L), \ldots, (\text{block} - 1) \times L^* + 1 \}$}
        \State $n \leftarrow n \times 3$
        \If{$\widetilde{v}_{l}=1$}
            \State $n \leftarrow n + 1$
        \ElsIf{$\widetilde{v}_{l}=-1$}
            \State $n \leftarrow n + 2$
        \EndIf
        % \State $n \leftarrow n \times 3$
    \EndFor
    \State Append $n$ to $\text{indices}$
\EndFor
\State \textbf{Return:} List of indices
\end{algorithmic}
\end{algorithm}



