If we set  $p = Z \alpha^k \mu$ and $\alpha^k = \frac{1}{\mu (k+k_0)}$, in which $k_0$ is sufficiently large, we obtain
\begin{align}
    \label{g-11}
    &\frac{1}{N} \sum_{n \in \N}   \E \|\vx_n^{k+1} - \vx_n'^{k+1} \|^2 \\
    \leq &    (1-\frac{1}{k+k_0})  \frac{1}{N}  \sum_{n \in \N}   \E \|\vx_n^{k} - \vx_n'^{k} \|^2 \nonumber \\
    % & +  \frac{2\sqrt{2L} \alpha^k}{NZ}  \E_{\cS,\mathcal{L}} \sqrt{f(\vx^{k}_i; \xi_{i,z})}   \nonumber
     & +  \frac{ 4   \E \| \nabla f(\vx^{k}_i; \xi_{i,z})\|^2 }{\mu^2 N Z (k+k_0)^2} +   \frac{ 4   \E \| \nabla f(\vx^{k}_i; \xi_{i,z})\|^2 }{\mu^2 N Z^2 (k+k_0)}.  \nonumber
\end{align}

Using telescopic cancellation on \eqref{g-11} from time $0$ to $k$, we deduce that
\begin{align}
    \label{g-12}
    &\frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k} - \vx_n'^{k} \|^2  \\
    % \leq & (1-\alpha \mu)^k  \frac{1}{N} \sum_{n \in \N}  \E_{\cS,\mathcal{L}} \|\vx_n^{0} - \vx_n'^{0} \|  \nonumber \\
    \leq & \sum_{k'=0}^{k-1} \lp \prod_{t=k'+1}^{k-1}(1-\frac{1}{t+k_0})  \rp  \cdot \frac{ 4  \E \| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2 }{\mu^2 N Z (k'+k_0)^2} \nonumber  \\
      &   + \sum_{k'=0}^{k-1} \lp \prod_{t=k'+1}^{k-1}(1-\frac{1}{t+k_0})  \rp  \cdot
         \frac{ 4   \E\| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2 }{\mu^2 N Z^2 (k'+k_0)}     \nonumber \\
    \leq & \sum_{k'=0}^{k-1} \frac{k'+k_0}{k+k_0-1}  \cdot  \frac{ 4  \E \| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2 }{\mu^2 N Z (k'+k_0)^2}   \nonumber \\
    & +  \sum_{k'=0}^{k-1} \frac{k'+k_0}{k+k_0-1}  \cdot   \frac{ 4   \E\| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2 }{\mu^2 N Z^2 (k'+k_0)}   \nonumber  \\
    \leq &   \frac{ 4 \sum_{k'=0}^{k-1} \lp \E \| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2  / (k'+k_0) \rp }{\mu^2 N Z (k+k_0-1)} \nonumber \\
    & +   \frac{ 4 \sum_{k'=0}^{k-1}  \E \| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2 }{\mu^2 N Z^2 (k+k_0-1) }.  \nonumber
    % \leq &  \frac{2 M_i }{\mu NZ}. \nonumber
\end{align}


According to \eqref{g-5} and Definition \ref{def-sta},  the on-average stability can be upper bounded by
\begin{align}
    \label{g-12-1}
    & \frac{1}{NZ}\sum_{i \in \N}\sum_{z=1}^{Z}  \|\bar\vx'^{k}_{(i,z)} - \bar\vx^{k} \|^2   \\
    \leq &   \frac{ 4 \sum_{k'=0}^{k-1} \sum_{i \in \N}\sum_{z=1}^{Z} \lp \E \| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2  / (k'+k_0) \rp }{\mu^2 N^2 Z^2 (k+k_0-1)} \nonumber \\
    & +   \frac{ 4 \sum_{k'=0}^{k-1} \sum_{i \in \N}\sum_{z=1}^{Z}  \E \| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2 }{\mu^2 N^2 Z^3 (k+k_0-1) }.   \nonumber
    % \leq &  \frac{2 M_i }{\mu NZ}. \nonumber
\end{align}
This completes the proof.
