\section{Proof of Theorem \ref{the-oe}}
\begin{proof}
Regarding the distance between the algorithm output of attack-free DSGD at time $k+1$ and the optimal solution $\vx_{\cS}^*$ of the global empirical loss, if Assumption \ref{assumption:variance} holds, we have
\begin{align}
    \label{g-22}
    & \E \|\bar\vx^{k+1} - \vx_{\cS}^* \|^2 \\
    = & \E \| \frac{1}{N} \sum_{n \in \N} \sum_{m \in \N} w_{nm} (\vx_m^k - \alpha^k \nabla f(\vx_m^k,\xi_m^k)) - \vx_{\cS}^* \|^2 \nonumber \\
    = & \E \| \frac{1}{N} \sum_{n \in \N} (\vx_n^k - \alpha^k \nabla f(\vx_n^k,\xi_n^k)) - \vx_{\cS}^* \|^2 \nonumber \\
    = & \E \|\bar \vx^k - \frac{\alpha^k}{N} \sum_{n \in \N} \nabla f(\vx_n^k,\xi_n^k) - \vx_{\cS}^* \|^2 \nonumber \\
    \leq & \E \|\bar \vx^k - \frac{\alpha^k}{N} \sum_{n \in \N} \nabla F_{\cS_n}(\vx_n^k) - \vx_{\cS}^* \|^2 + \frac{(\alpha^k)^2 \sigma^2}{N}, \nonumber
    % = & \E \|\bar \vx^k - \frac{\alpha^k}{N} \sum_{n \in \N} f(\bar \vx^k, \xi_n^k) + \frac{\alpha^k}{N} \sum_{n \in \N} [\nabla f(\bar \vx^k, \xi_n^k) -\nabla f(\vx_n^k,\xi_n^k) ]- \vx_{\cS}^* \|^2 \nonumber \\
    % \leq & \E (1+p \alpha^k)\|\bar \vx^k - \frac{\alpha^k}{N} \sum_{n \in \N} \nabla f(\bar \vx^k, \xi_n^k)- \vx_{\cS}^* \|^2  \nonumber \\
    % & + \E \frac{\alpha^k(\alpha^k+p^{-1})}{N} \sum_{n=1}^N \| \nabla f(\bar \vx^k, \xi_n^k) - \nabla f(\vx_n^k,\xi_n^k) \|^2 \nonumber
\end{align}
% where the last inequality holds true because $2 \langle \bm{a},\bm{b} \rangle \leq p\|\bm{a}\|^2 + p^{-1}\|\bm{b}\|^2$.
where $\xi_n^k$ denotes the sample drawn from the local dataset $\cS_n$ at time $k$.

For the first term at the RHS of \eqref{g-22}, we have
\begin{align}
    \label{g-22-1}
    &  \|\bar \vx^k - \frac{\alpha^k}{N} \sum_{n \in \N} \nabla F_{\cS_n}(\vx_n^k) - \vx_{\cS}^* \|^2 \\
    = &   \|\bar \vx^k - \frac{\alpha^k}{N} \sum_{n \in \N} (\nabla F_{\cS_n}(\vx_n^k) -\nabla F_{\cS_n}(\vx_{\cS}^*))- \vx_{\cS}^* \|^2  \nonumber \\
    =&  \|\bar \vx^k - \vx_{\cS}^* \|^2 + (\alpha^k)^2\|\frac{1}{N} \sum_{n \in \N} (\nabla F_{\cS_n}(\vx_n^k) -\nabla F_{\cS_n}(\vx_{\cS}^*)) \|^2 \nonumber \\
    & - \frac{2 \alpha^k}{N} \sum_{n \in \N}  \langle \bar\vx^k - \vx_{\cS}^* , \nabla F_{\cS_n}(\vx_n^k) -\nabla F_{\cS_n}(\vx_{\cS}^*) \rangle. \nonumber
\end{align}
For the second term at the RHS of \eqref{g-22-1}, applying Assumption \ref{assumption:Lip}, we obtain
\begin{align}
    \label{g-22-2}
    &  \|\frac{1}{N} \sum_{n \in \N} (\nabla F_{\cS_n}(\vx_n^k) -\nabla F_{\cS_n}(\vx_{\cS}^*)) \|^2  \\
    % \leq &  \|\frac{1}{N} \sum_{n \in \N} (\nabla F_{\cS_n}(\vx_n^k) - \nabla F_{\cS_n}(\bar\vx^k) +\nabla F_{\cS_n}(\bar\vx^k)- \nabla F_{\cS_n}(\vx_{\cS}^*)) \|^2 \nonumber \\
     \leq & 2 \|\frac{1}{N} \sum_{n \in \N} (\nabla F_{\cS_n}(\vx_n^k) - \nabla F_{\cS_n}(\bar\vx^k) )\|^2 \nonumber \\
     & +2 \|\frac{1}{N} \sum_{n \in \N} ( \nabla F_{\cS_n}(\bar\vx^k)- \nabla F_{\cS_n}(\vx_{\cS}^*)) \|^2 \nonumber \\
     \leq & 2 L^2 H^k  + 4L (F_{\cS}(\bar\vx^k)-F_{\cS}(\vx_{\cS}^*)),  \nonumber
\end{align}
where $H^k = \frac{1}{N} \sum_{n \in \N} \| \vx_n^k -\bar\vx^k\|^2$ represents the consensus error, as defined and analyzed in Lemma \ref{lemma-dm}.
For the third term at the RHS of \eqref{g-22-1}, we have
\begin{align}
    \label{g-22-3}
    &  \frac{2 \alpha^k}{N} \sum_{n \in \N}  \langle\bar\vx^k - \vx_{\cS}^* , \nabla F_{\cS_n}(\vx_n^k) -\nabla F_{\cS_n}(\vx_{\cS}^*) \rangle \\
    = & \frac{2 \alpha^k}{N} \sum_{n \in \N}  \langle\bar\vx^k - \vx_{\cS}^* , \nabla F_{\cS_n}(\vx_n^k)  \rangle  \nonumber \\
    = & \frac{2 \alpha^k}{N} \sum_{n \in \N}  \langle\bar\vx^k - \vx_{n}^k , \nabla F_{\cS_n}(\vx_n^k)  \rangle \nonumber \\
    & + \frac{2 \alpha^k}{N} \sum_{n \in \N}  \langle\vx_n^k - \vx_{\cS}^* , \nabla F_{\cS_n}(\vx_n^k)  \rangle \nonumber \\
    \geq & \frac{2 \alpha^k}{N} \sum_{n \in \N} \lp F_{\cS_n}(\bar\vx^k ) - F_{\cS_n}(\vx_{n}^k) -\frac{L}{2} \|\bar\vx^k  - \vx_{n}^k\|^2  \rp  \nonumber \\
    & + \frac{2 \alpha^k}{N} \sum_{n \in \N} \lp F_{\cS_n}(\vx_{n}^k ) - F_{\cS_n}(\vx_{\cS}^*) + \frac{\mu}{2} \| \vx_{n}^k-\vx_{\cS}^*\|^2  \rp  \nonumber \\
    \geq & \frac{2 \alpha^k}{N} \sum_{n \in \N} \lp F_{\cS_n}(\bar\vx^k ) - F_{\cS_n}(\vx_{\cS}^*) \rp  \nonumber \\
    & - \alpha^k L H^k + \alpha^k \mu \|\bar\vx^k -\vx_{\cS}^* \|^2  \nonumber \\
    \geq & 2 \alpha^k \lp F_{\cS}(\bar\vx^k ) - F_{\cS}(\vx_{\cS}^*) \rp - \alpha^k L H^k + \alpha^k \mu \|\bar\vx^k -\vx_{\cS}^* \|^2 . \nonumber
