\section{Proof of Theorem \ref{the-onsta-b}}

\begin{proof}
Below, following \cite{ye2024ge,ye2024generalization}, we denote the output of Byzantine-resilient DGSD on datasets $\cS$ and $\cS^{(i,z)}$ at time $k$ as  $\mathcal{L}(\cS)= $ $\bar\vx^k =\frac{1}{N}\sum_{n \in \N}\vx_n^k$ and $\cL(\cS^{(i,z)})=\bar\vx'^k_{(i,z)} = \frac{1}{N}\sum_{n \in \N}\vx'^k_n$, respectively. Here, $\vx'^k_n$ denotes the local model of non-Byzantine agent $n$ at time $k$ when trained on the perturbed global dataset $\cS^{(i,z)} = \{\cS_{m} | m \in \mathcal{N},  m \neq i\} \cup \cS_i^{(z)}$, and $\bar\vx'^k_{(i,z)}$ is the average of $\vx'^k_n$.
We analyze the stability of Algorithm \ref{robust-DSGD} under two scenarios, depending on whether the virtual mixing matrix is doubly stochastic or row stochastic.

\subsection{Row Stochastic Virtual Mixing Matrix}
When the virtual mixing matrix is row stochastic, for any $v \in (0,1)$, we decompose the distance between $\bar\vx^{k+1}$ and $\bar\vx'^{k+1}_{(i,z)}$ into three parts as

% As previously mentioned, analyzing the recursion of $\eta^k$ is not suitable when the virtual mixing matrix is row stochastic. In this simulation, we directly analyze the recursion of $\delta^{k}$.
% We decompose $\delta^{k+1}$ into three parts, as
\begin{align}
\label{ger-1}
&  \|\bar\vx^{k+1}-\bar\vx'^{k+1}_{(i,z)}\|^2
% =& \|\frac{1}{N}\sum_{n \in \N}\vx_n^{k+1} - \frac{1}{N}\sum_{n \in \N}\vx'^{k+1}_n\| \nonumber \\
\leq  \frac{2}{v}\|\bar\vx^{k+1} - \bar\vx^{k+\frac{1}{2}} \|^2  \\
&+  \frac{1}{1-v} \|\bar\vx^{k+\frac{1}{2}} - \bar\vx'^{k+\frac{1}{2}}_{(i,z)} \|^2
 + \frac{2}{v} \|\bar\vx'^{k+1}_{(i,z)} - \bar\vx'^{k+\frac{1}{2}}_{(i,z)} \|^2. \nonumber
\end{align}

 For the first term at the RHS of (\ref{ger-1}), we bound it by
\begin{align}
    \label{ger-2}
    &\|\bar\vx^{k+1} - \bar\vx^{k+\frac{1}{2}} \|^2 \\
=& \| \frac{1}{N}\sum_{n \in \N}\vx_n^{k+1} - \frac{1}{N}\sum_{n \in \N}\vx_n^{k+\frac{1}{2}} \|^2 \nonumber\\
\leq& 2\| \frac{1}{N} \sum_{n \in \N}(\vx_n^{k+1} - \hat\vx_n^{k+\frac{1}{2}}) \|^2 \nonumber \\
&+ 2\| \frac{1}{N} \sum_{n \in \N} (\hat\vx_n^{k+\frac{1}{2}} - \vx_n^{k+\frac{1}{2}})\|^2. \nonumber
\end{align}
For the first term at the RHS of \eqref{ger-2}, we use the contraction property of the robust aggregation rules $ \{ \A_n \}_{n \in  \N}$ in Definition \ref{definition:mixing-matrix} to derive
\begin{align}
\label{ger-2-1}
    &\frac{1}{N} \sum_{n \in \N} \| \vx_n^{k+1} - \hat\vx_n^{k+\frac{1}{2}} \|^2 \\
    \leq &  \frac{1}{N} \sum_{n \in \N} \rho^2 \max_{m \in \N_n \cup \{n\}} \| \vx_{m}^{k+\frac{1}{2}} - \hat\vx_n^{k+\frac{1}{2}} \|^2 \nonumber \\
    \leq &  \frac{1}{N} \sum_{n \in \N} \rho^2 \max_{m \in \N} \| \vx_{m}^{k+\frac{1}{2}} - \hat\vx_n^{k+\frac{1}{2}} \|^2 \nonumber \\
    \leq &  \frac{1}{N} \sum_{n \in \N} \rho^2 \lp 2\max_{m \in \N} \| \vx_{m}^{k+\frac{1}{2}} - \bar\vx^{k+\frac{1}{2}} \|^2 + 2\|  \bar\vx^{k+\frac{1}{2}} - \hat\vx_n^{k+\frac{1}{2}}\|^2 \rp \nonumber \\
    \leq & 4\rho^2 \frac{1}{N} \sum_{n \in \N}  \max_{m \in \N} \| \vx_{m}^{k+\frac{1}{2}} - \bar\vx^{k+\frac{1}{2}} \|^2 \nonumber \\
     \leq & 4\rho^2 \sum_{n \in \N}   \| \vx_{n}^{k+\frac{1}{2}} - \bar\vx^{k+\frac{1}{2}} \|^2. \nonumber
\end{align}
For the second term at the RHS of (\ref{ger-2}), it holds that
\begin{align}
    \label{ger-4}
    &\| \frac{1}{N} \sum_{n \in \N} (\hat\vx_n^{k+\frac{1}{2}} - \vx_n^{k+\frac{1}{2}})\|^2 \\
     =&  \lnorm \frac{1}{N} \bm{1}^\top (WX^{k+\frac{1}{2}}-\frac{1}{N}\bm{1}\bm{1}^{\top}X^{k+\frac{1}{2}})
        \rnorm^2
          \nonumber\\
        % ==========================
        =& \frac{1}{N^2}  \lnorm (\bm{1}^\top W-\bm{1}^{\top})
        (X^{k+\frac{1}{2}}-\frac{1}{N}\bm{1}\bm{1}^{\top}X^{k+\frac{1}{2}})
        \rnorm^2
         \nonumber\\
        % ==========================
        \le& \frac{1}{N^2} \lnorm W^\top\bm{1} -\bm{1}
        \rnorm^2
        \lnorm X^{k+\frac{1}{2}}-\frac{1}{N}\bm{1}\bm{1}^{\top}X^{k+\frac{1}{2}}
        \rnorm_F^2
          \nonumber\\
        % ==========================
		=& \frac{\chi^2}{N}\sum_{n\in\N} \|  \vx^{k+\frac{1}{2}}_{n}-\bar\vx^{k+\frac{1}{2}}\|^2,   \nonumber
\end{align}
in which  $X^{k+\frac{1}{2}} = [\vx^{k+\frac{1}{2}}_1, \cdots, \vx^{k+\frac{1}{2}}_{N}]^\top \! \in \mathbb{R}^{N \times d}$.
Substituting \eqref{ger-4} and \eqref{ger-2-1} into \eqref{ger-2}, and applying Lemma 2 in \cite{wu2022byzantine}, we have
\begin{align}
    \label{ger-5}
    &\|\bar\vx^{k+1} - \bar\vx^{k+\frac{1}{2}} \|^2\\
% =& \| \frac{1}{N}\sum_{n \in \N}\vx_n^{k+1} - \frac{1}{N}\sum_{n \in \N}\vx_n^{k+\frac{1}{2}} \| \nonumber\\
% \leq& \| \frac{1}{N} \sum_{n \in \N}(\vx_n^{k+1} - \hat\vx_n^{k+\frac{1}{2}}) \| + \| \frac{1}{N} \sum_{n \in \N} (\hat\vx_n^{k+\frac{1}{2}} - \vx_n^{k+\frac{1}{2}})\|. \nonumber \\
 \leq &  8 \rho^2 \sum_{n \in \N} \|\vx_n^{k+\frac{1}{2}}  - \bar\vx^{k+\frac{1}{2}} \|^2 + \frac{2 \chi^2}{N}\sum_{n\in\N} \|  \vx^{k+\frac{1}{2}}_{n}-\bar\vx^{k+\frac{1}{2}}\|^2\nonumber \\
\leq &  (8\rho^2 N+2 \chi^2)  (2+12(\alpha^k)^2 L^2) H^k \nonumber \\
& + (64 \rho^2 N+16 \chi^2) (\alpha^k)^2 (\sigma^2 + \delta^2).  \nonumber
\end{align}
Note that for the third term at the RHS of (\ref{ger-1}), an inequality similar to (\ref{ger-5}) also holds true.

Now, we analyze the second term at the RHS of (\ref{ger-1}). For the non-Byzantine agent $i$, the probability of Algorithm \ref{robust-DSGD} selecting the same training sample from  $\cS_i$ and $\cS_i^{(z)}$ at time $k$ is $1-\frac{1}{Z}$.  According to Lemma 6 in \cite{sun2021stability}, for any $p>0$, if the loss is strongly convex and Assumption \ref{assumption:Lip} holds, then choosing $\alpha^k \leq \frac{1}{L}$ yields
\begin{align}
    \label{ger-7}
           &   \|\bar\vx^{k+\frac{1}{2}} - \bar\vx'^{k+\frac{1}{2}}_{(i,z)} \|^2  \\
     = &     \|\bar\vx^k -\frac{\alpha^k}{N} \sum_{m \in \N} \nabla f(\vx^{k}_m; \xi_m^{k}) \nonumber  \\
     & \hspace{2em}-\bar\vx'^k_{(i,z)} +\frac{\alpha^k}{N} \sum_{m \in \N} \nabla f(\vx'^{k}_m; \xi_m^{k}) \|^2  \nonumber \\
    \leq& (1+p)  \|\bar\vx^k -\frac{\alpha^k}{N} \sum_{m \in \N} \nabla f(\bar\vx^{k}; \xi_m^{k} ) \nonumber \\
    & \hspace{4em} -\bar\vx'^k_{(i,z)} + \frac{\alpha^k}{N} \sum_{m \in \N} \nabla f(\bar\vx'^{k}_{(i,z)}; \xi_m^{k}) \|^2  \nonumber  \\
    & +  2(1+p^{-1})\frac{(\alpha^k)^2}{N} \sum_{m \in \N}  \|  \nabla f(\bar\vx^{k}; \xi_m^{k}) -  \nabla f(\vx^{k}_m; \xi_m^{k}) \|^2 \nonumber  \\
    & + 2(1+p^{-1}) \frac{(\alpha^k)^2}{N} \sum_{m \in \N} \|  \nabla f(\bar\vx'^{k}_{(i,z)}; \xi_m^{k}) - \nabla f(\vx'^{k}_m; \xi_m^{k}) \|^2   \nonumber  \\
    \leq&    (1-\alpha^k\mu)^2 (1+p) \| \bar\vx^k - \bar\vx'^k_{(i,z)}\|^2
     + 4 (1+p^{-1}) (\alpha^k)^2 L^2 H^k. \nonumber
\end{align}
Substituting \eqref{ger-7} and \eqref{ger-5} into \eqref{ger-1}, in this case we have
\begin{align}
\label{ger-8}
&  \E\|\bar\vx^{k+1}-\bar\vx'^{k+1}_{(i,z)}\|^2 \\
% =& \|\frac{1}{N}\sum_{n \in \N}\vx_n^{k+1} - \frac{1}{N}\sum_{n \in \N}\vx'^{k+1}_n\| \nonumber \\
\leq &  \frac{(1-\alpha^k\mu)^2 (1+p)}{1-v}  \E \| \bar\vx^k - \bar\vx'^k_{(i,z)}\|^2   \nonumber \\
     & + \frac{4 (1+p^{-1}) (\alpha^k)^2 L^2 \E H^k}{1-v} \nonumber \\
    & + \frac{4}{v}(8\rho^2 N+2 \chi^2)  (2+12(\alpha^k)^2 L^2) \E H^k \nonumber \\
& + \frac{4}{v}(64 \rho^2 N+16 \chi^2) (\alpha^k)^2 (\sigma^2 + \delta^2).  \nonumber
\end{align}

For non-Byzantine agent $i$, the probability of Algorithm \ref{robust-DSGD} selecting the different training samples from  $\cS_i$ and $\cS_i^{(z)}$ at time $k$ is $\frac{1}{Z}$. According to Lemma 6 in \cite{sun2021stability}, for any $p>0$, if the loss is strongly convex and Assumption \ref{assumption:Lip} holds, then choosing $\alpha^k \leq \frac{1}{L}$ yields
