\subsection{Doubly Stochastic Virtual Mixing Matrix}
When the virtual mixing matrix becomes doubly stochastic, it is convenient to analyze $ \frac{1}{N} \sum_{n \in \N} \|\vx_n^{k} - \vx'^{k}_n \|^2$ instead of $\|\bar\vx'^{k}_{(i,z)} - \bar\vx^{k} \|^2$, because $\frac{1}{N} \sum_{n \in \N} \|\vx_n^{k} - \vx'^{k}_n \|^2 \geq \|\bar\vx'^{k}_{(i,z)} - \bar\vx^{k} \|^2$. For any $v \in (0,1)$, we decompose $\frac{1}{N} \sum_{n \in \N} \|\vx_n^{k+1} - \vx'^{k+1}_n \|^2$ into three parts, as
\begin{align}
\label{gb-5}
    &  \frac{1}{N} \sum_{n \in \N} \|\vx_n^{k+1} - \vx'^{k+1}_n \|^2 \\
\leq & \frac{2}{v}\frac{1}{N} \sum_{n \in \N}    \|\vx_n^{k+1} - \hat\vx_n^{k+\frac{1}{2}} \|^2 + \frac{2}{v}\frac{1}{N} \sum_{n \in \N}  \|\vx_n'^{k+1} - \hat\vx_n'^{k+\frac{1}{2}} \|^2  \nonumber\\
&+ \frac{1}{1-v} \frac{1}{N} \sum_{n \in \N}  \|\hat\vx_n^{k+\frac{1}{2}} - \hat\vx_n'^{k+\frac{1}{2}} \|^2.  \nonumber
\end{align}

For the first and second terms at the RHS of (\ref{gb-5}), we can bound them similarly to \eqref{ger-5}.

\begin{align}
\label{gb-5-8}
    &\frac{1}{N} \sum_{n \in \N} \| \vx_n^{k+1} - \hat\vx_n^{k+\frac{1}{2}} \|^2 \\
     \leq & 4\rho^2 \sum_{n \in \N}   \| \vx_{n}^{k+\frac{1}{2}} - \bar\vx^{k+\frac{1}{2}} \|^2 \nonumber \\
     \leq &  4\rho^2 N  (2+12(\alpha^k)^2 L^2) H^k + 32 \rho^2 N (\alpha^k)^2 (\sigma^2 + \delta^2).   \nonumber
\end{align}

Now, we analyze the third term at the RHS of (\ref{gb-5}). For the non-Byzantine agent $i$, the probability of Algorithm \ref{robust-DSGD} selecting the same training sample from  $\cS_i$ and $\cS_i^{(z)}$ at time $k$ is $1-\frac{1}{Z}$.  According to Lemma 6 in \cite{sun2021stability}, if the loss is strongly convex and Assumption \ref{assumption:Lip} holds, then choosing $\alpha^k \leq \frac{1}{L}$ yields
\begin{align}
    \label{gb-6}
    % \|\bar\vx^{k+\frac{1}{2}} - \bar\vx'^{k+\frac{1}{2}} \|
    %  \leq   (1-\alpha^k\mu)  \| \bar\vx^k - \bar\vx'^k\|
    & \frac{1}{N} \sum_{n \in \N} \|\hat\vx_n^{k+\frac{1}{2}} - \hat\vx_n'^{k+\frac{1}{2}} \|^2  \\
    = & \frac{1}{N} \sum_{n \in \N} \|\sum_{m \in \N} w_{nm} \lp \vx_m^{k+\frac{1}{2}} - \vx_m'^{k+\frac{1}{2}} \rp\|^2 \nonumber\\
    \leq & \frac{1}{N} \sum_{n \in \N} \sum_{m \in \N} w_{nm}  \| \vx_m^{k+\frac{1}{2}} - \vx_m'^{k+\frac{1}{2}} \|^2 \nonumber\\
    % = & \frac{1}{N} \sum_{n \in \N} \| \vx_n^{k+\frac{1}{2}} - \vx_n'^{k+\frac{1}{2}} \|^2  \nonumber\\
    \leq &   (1-\alpha^k\mu)^2 \frac{1}{N} \sum_{n \in \N} \| \vx_n^{k} - \vx_n'^{k} \|^2. \nonumber
\end{align}
Substituting (\ref{gb-5-8}) and (\ref{gb-6}) into (\ref{gb-5}), in this case we have
\begin{align}
\label{gb-7}
    & \frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k+1} - \vx'^{k+1}_n \|^2 \\
     \leq &  \frac{(1-\alpha^k\mu)^2}{1-v}   \frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k} - \vx'^{k}_n \|^2 \nonumber \\
     & + \frac{16}{v}\rho^2 N  (2+12(\alpha^k)^2 L^2) \E H^k  \nonumber \\
     & + \frac{128}{v} \rho^2 N (\alpha^k)^2 (\sigma^2 + \delta^2).  \nonumber
\end{align}


For non-Byzantine agent $i$, the probability of Algorithm \ref{robust-DSGD} selecting the different training samples from  $\cS_i$ and $\cS_i^{(z)}$ at time $k$ is $\frac{1}{Z}$. According to Lemma 6 in \cite{sun2021stability}, for any $p>0$, if the loss is strongly convex and Assumption \ref{assumption:Lip} holds, then choosing $\alpha^k \leq \frac{1}{L}$ yields
\begin{align}
    \label{gb-8}
    % & \frac{1}{NZ} \sum_{i \in \N}\sum_{z=1}^{Z}\|\bar\vx'^{k}_{(i,z)} - \bar\vx^{k} \|^2 \\
    % \leq
    & \frac{1}{N} \sum_{n \in \N} \|\hat\vx_n^{k+\frac{1}{2}} - \hat\vx_n'^{k+\frac{1}{2}} \|^2 \\
   \leq &  \frac{(1-\alpha^k \mu)^2 (1+p)}{N}  \sum_{n \in \N} \|\vx_n^{k} - \vx_n'^{k} \|^2  \nonumber \\    % + \frac{(1-\alpha^k \mu)^2 p }{N}   \|\vx_i^{k} - \vx_i'^{k} \|^2 \nonumber \\
   & +  \frac{(\alpha^k)^2(1+p^{-1})}{N}  \| \nabla f(\vx^{k}_i; \xi_{i,z}) - \nabla f(\vx^{k}_i; \xi'_{i,z})\|^2.   \nonumber
\end{align}
Substituting (\ref{gb-5-8}) and (\ref{gb-8}) into (\ref{gb-5}), in this case we have
\begin{align}
\label{gb-9}
     & \frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k+1} - \vx'^{k+1}_n \|^2 \\
     \leq &  \frac{(1-\alpha^k\mu)^2(1+p)}{1-v}   \frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k} - \vx'^{k}_n \|^2 \nonumber \\
     & + \frac{16}{v}\rho^2 N  (2+12(\alpha^k)^2 L^2) \E H^k  \nonumber \\
     & + \frac{128}{v} \rho^2 N (\alpha^k)^2 (\sigma^2 + \delta^2)  \nonumber \\
     & +  \frac{4(\alpha^k)^2(1+p^{-1})}{N}  \E  \| \nabla f(\vx^{k}_i; \xi_{i,z}) \|^2. \nonumber
\end{align}


Combining the two cases of (\ref{gb-9}) and (\ref{gb-7}), we can obtain

\begin{align}
\label{gb-10}
    & \frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k+1} - \vx'^{k+1}_n \|^2 \\
    \leq &  \frac{(1-\alpha^k\mu)^2(1+\frac{p}{Z})}{1-v}   \frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k} - \vx'^{k}_n \|^2 \nonumber \\
     & + \frac{16}{v}\rho^2 N  (2+12(\alpha^k)^2 L^2) \E H^k \nonumber \\
     & + \frac{128}{v} \rho^2 N (\alpha^k)^2 (\sigma^2 + \delta^2)  \nonumber \\
     & +  \frac{4(\alpha^k)^2(1+p^{-1})}{NZ}  \E  \| \nabla f(\vx^{k}_i; \xi_{i,z}) \|^2. \nonumber
\end{align}

If we set $v = \frac{\alpha^k\mu}{2}$, $p = Z \alpha^k \mu$ and $\alpha^k = \frac{2}{\mu (k+k_1)}$, according to Lemma \ref{lemma-dm-b}, we have
\begin{align}
\label{gb-10-1}
 & \frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k+1} - \vx'^{k+1}_n \|^2  \\
     \leq &  (1-\frac{1}{k+k_1})  \frac{1}{N} \sum_{n \in \N} \E \|\vx_n^{k} - \vx'^{k}_n \|^2 \nonumber \\
     &+  \frac{2 (16 c_2 +256)  \rho^2 N (\sigma^2 + \delta^2)}{\mu^2 (k+k_1)}
      + \frac{768 c_2 L^2 \rho^2 N (\sigma^2 + \delta^2) }{\mu^4 (k+k_1)^3} \nonumber \\
      &
      + \frac{16 \E  \| \nabla f(\vx^{k}_i; \xi_{i,z}) \|^2  }{\mu^2 NZ (k+k_1)^2}
      + \frac{8 \E  \| \nabla f(\vx^{k}_i; \xi_{i,z}) \|^2  }{\mu^2 N Z^2 (k+k_1)}.  \nonumber
\end{align}


Using telescopic cancellation on \eqref{gb-10-1} from time $0$ to $k$, we deduce that
\begin{align}
    \label{gb-10-2}
    % & \frac{1}{NZ}\sum_{i \in \N}\sum_{z=1}^{Z} \E_{\cS,\mathcal{L}} \|\bar\vx'^{k}_{(i,z)} - \bar\vx^{k} \|^2 \\
     & \frac{1}{N} \sum_{n \in \N}  \|\vx_n^{k} - \vx_n'^{k} \|^2   \\
    % \leq & \sum_{k'=0}^{k-1} \frac{k'+k_1}{k+k_1-1} \bigg[ \frac{(16c_2 +256) \rho^2 N (\sigma^2 + \delta^2)}{\mu^2 (k'+k_1)}    \nonumber  \\
    % & + \frac{384 c_2 L^2 \rho^2 N (\sigma^2 + \delta^2) }{\mu^4 (k'+k_1)^3}
    %  + \frac{16  \E  \| \nabla f(\vx^{k'}_i; \xi_{i,z}) \|^2 }{\mu^2 NZ (k'+k_1)^2}   \nonumber \\
    %  &  + \frac{8  \E  \| \nabla f(\vx^{k'}_i; \xi_{i,z}) \|^2  }{\mu^2 N Z^2 (k'+k_1)}  \bigg]  \nonumber \\
    \leq &   \frac{2 (16c_2 +256) \rho^2 N (\sigma^2 + \delta^2)}{\mu^2} + \frac{768 c_2 L^2 \rho^2 N (\sigma^2 + \delta^2) }{\mu^4 (k+k_1-1)}  \nonumber \\
   & + \frac{16 \sum_{k'=0}^{k-1}  \lp \E  \| \nabla f(\vx^{k'}_i; \xi_{i,z}) \|^2 / (k'+k_1)  \rp}{\mu^2 NZ (k+k_1-1)}  \nonumber \\
    & + \frac{8 \sum_{k'=0}^{k-1} \E  \| \nabla f(\vx^{k'}_i; \xi_{i,z}) \|^2  }{\mu^2 N Z^2  }.  \nonumber
    % \leq &  \frac{2 M_i }{\mu NZ}. \nonumber
\end{align}


According to \eqref{gb-10-2} and Definition \ref{def-sta},  the on-average stability can be upper bounded by
\begin{align}
    \label{gb-10-2-1}
    & \frac{1}{NZ}\sum_{i \in \N}\sum_{z=1}^{Z}  \|\bar\vx'^{k}_{(i,z)} - \bar\vx^{k} \|^2   \\
    \leq &   \frac{ 16 \sum_{k'=0}^{k-1} \sum_{i \in \N}\sum_{z=1}^{Z} \lp \E \| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2  / (k'+k_1) \rp }{\mu^2 N^2 Z^2 (k+k_1-1)} \nonumber \\
    & +   \frac{ 8 \sum_{k'=0}^{k-1} \sum_{i \in \N}\sum_{z=1}^{Z}  \E \| \nabla f(\vx^{k'}_i; \xi_{i,z})\|^2 }{\mu^2 N^2 Z^3 (k+k_1-1) }    \nonumber \\
   &+ \frac{2 (16c_2 +256) \rho^2 N (\sigma^2 + \delta^2)}{\mu^2} + \frac{384 c_2 L^2 2 \rho^2 N (\sigma^2 + \delta^2) }{\mu^4 (k+k_1-1)}.  \nonumber
    % \leq &  \frac{2 M_i }{\mu NZ}. \nonumber
\end{align}
This completes the proof.
\end{proof}

