\section{Proof of Theorem \ref{the-oe-b}}
\begin{proof}
Regarding the distance between the algorithm output of Byzantine-resilient DSGD at time $k+1$ and the optimal solution $\vx_{\cS}^*$ of the global empirical loss, if Assumption \ref{assumption:variance} holds, for any $a \in (0,1)$, we have
\begin{align}
    \label{ger-17}
    & \E \|\bar\vx^{k+1} - \vx_{\cS}^* \|^2  \\
    \leq &  \frac{1}{1-a} \E \|\bar\vx^{k+1} - \bar\vx^{k+\frac{1}{2}} \|^2
    % & + \frac{2}{1-a} \E \|\frac{1}{N} \sum_{n \in \N} \hat \vx_n^{k+\frac{1}{2}} - \bar\vx^{k+\frac{1}{2}}\|^2
     + \frac{1}{a} \E \|\bar\vx^{k+\frac{1}{2}} - \vx_{\cS}^* \|^2.  \nonumber
\end{align}
The first term at the RHS of \eqref{ger-17} can be bounded by \eqref{ger-5}.
For the second term at the RHS of \eqref{ger-17}, if we choose $\alpha^k \leq \frac{1}{2L}$, following \eqref{g-22-5},  we have
\begin{align}
    \label{gb-17-1}
    & \E \| \bar\vx^{k+\frac{1}{2}} - \vx_{\cS}^* \|^2 \\
    \leq & (1-\mu\alpha^k) \E \|\bar \vx^k - \vx_{\cS}^* \|^2  + 2 \alpha^k L \E H^k + \frac{(\alpha^k)^2 \sigma^2}{N}. \nonumber
    % \leq &  (1+p \alpha) [(1-\alpha \mu) \E_{\cS,\mathcal{L}} \|\bar \vx^k - \vx_{\cS}^* \|^2  +  4 \alpha^2 \sigma^2]  \nonumber \\
    % & +  \alpha(\alpha+p^{-1}) \alpha^2 L^2  \Delta_2 (\sigma^2 +\delta^2)  \nonumber
    % \leq &   (1-\alpha^2 \mu^2) \E_{\cS,\mathcal{L}} \|\bar \vx^k - \vx_{\cS}^* \|^2  +  4 (1+\mu \alpha) \alpha^2 \sigma^2  \nonumber \\
    % & +  \alpha(\alpha+\mu^{-1}) \alpha^2 L^2  \Delta_2 (\sigma^2 +\delta^2)  \nonumber
\end{align}

