Substituting \eqref{gb-17-1} and \eqref{ger-5} into \eqref{ger-17}, setting $a=1-\frac{\mu\alpha^k}{2}$, because $1-\mu\alpha^k \leq (1-\frac{\mu\alpha^k}{2})^2$, we have
\begin{align}
    \label{ger-19}
    & \E \|\bar\vx^{k+1} - \vx_{\cS}^* \|^2 \\
    \leq & (1-\frac{\alpha^k \mu}{2})  \E \|\bar \vx^k - \vx_{\cS}^* \|^2  +  \frac{ (\alpha^k)^2 \sigma^2}{\lp 1-\frac{\alpha^k \mu}{2}\rp N}
     +  \frac{2\alpha^k L \E  H^k}{1-\frac{\alpha^k \mu}{2}}  \nonumber\\
     & + \frac{4(4 \rho^2 N+ \chi^2) (2+12 (\alpha^k)^2 L^2) \E H^k}{\alpha^k \mu} \nonumber \\
     & + \frac{ 32(4   \rho^2 N +  \chi^2) \alpha^k (\sigma^2 + \delta^2)}{\mu}.  \nonumber
\end{align}


If we set $\alpha^k = \frac{2}{\mu (k+k_1)}$, then since $\frac{1}{a}=\frac{k+k_1}{k+k_1-1} \in (1,2)$, we have
\begin{align}
    \label{ger-20}
    & \E \|\bar\vx^{k+1} - \vx_{\cS}^* \|^2 \\
    % \leq & (1-\frac{1}{k+k_1})  \E \|\bar \vx^k - \vx_{\cS}^* \|^2  +  2(\alpha^k)^2 \sigma^2
