    %  & + \frac{(64+4c_2)  (4\rho^2 N + \chi^2) (\sigma^2 + \delta^2)}{ \mu^2 (k'+k_1)}  \bigg] \nonumber \\
     \leq & \frac{(k_1-1)  \|\bar \vx^0 - \vx_{\cS}^* \|^2}{k+k_1-1} + \frac{8\sigma^2 ln(k+k_1-1)}{ \mu^2 N (k+k_1-1)} \nonumber \\
     & + \frac{8 c_2 L (\sigma^2 + \delta^2)}{\mu^3 (k+k_1-1) }
      + \frac{96c_2 L^2 (4\rho^2 N+\chi^2)(\sigma^2 + \delta^2)}{ \mu^4 (k+k_1-1)} \nonumber \\
      & + \frac{(64+4c_2)  (4\rho^2 N + \chi^2) (\sigma^2 + \delta^2) }{ \mu^2 }. \nonumber
     % \leq & O\lp \rho^2 N (\sigma^2 + \delta^2) \rp  \nonumber
\end{align}



Finally, combining \eqref{ger-21} with Assumption \ref{assumption:Lip}, we obtain


\begin{align}
\label{ger-22}
&   \E \lp F_{\cS}(\bar\vx^{k})  -  F_{\cS} (\vx_{\cS}^*) \rp \\
\leq & \frac{L}{2} \E \|\bar\vx^{k} - \vx_{\cS}^* \|^2  \nonumber\\
\leq &   \frac{L(k_1-1)  \|\bar \vx^0 - \vx_{\cS}^* \|^2}{2(k+k_1-1)} + \frac{4L\sigma^2 ln(k+k_1-1)}{ \mu^2 N (k+k_1-1)} \nonumber \\
