\section{Useful Lemmas and Their Proofs}
\subsection{Proof of Lemma 2}
The following lemma characterizes the consensus dynamics among the agents of Algorithm \ref{DSGD} during the learning process. The proof builds upon the approach of Theorem 2 in \cite{wu2022byzantine}, as well as Lemma 2 in \cite{ye2024generalization}.
We define the consensus error as $H^k = \frac{1}{N} \sum_{n \in \N} \| \vx^{k}_n - \bar\vx^{k}\|^2 $, where $\bar\vx^k:= \frac{1}{N}\sum_{n \in \N}\vx^k_n$ is the average of all local models at time $k$.
\begin{lemma}[Consensus Error of Attack-free DSGD]
\label{lemma-dm}
    Under Assumptions \ref{assumption:Lip}--\ref{assumption:heterogeneity}, setting the step size $\alpha^k= \frac{1}{\mu(k+k_0)}$, in which $k_0$ is sufficiently large. When all agents share the same initialization, the consensus error of Algorithm \ref{DSGD} can be bounded by
    \begin{align}
        \label{inequality:H-convergence}
        % \E H^k
        % \le & (c_1)^k H^0 + \frac{c_2 M^2+c_3 C^2}{\mu^2} \frac{1}{(k+k_0)^2}.
        \E H^k
        \le &  \frac{c_1(\sigma^2 +\delta^2)}{\mu^2 (k+k_0)^2}.
    \end{align}
    Here  $c_1 > 0$ is a constant, and the expectation is taken over all the random variables.
\end{lemma}

\begin{proof}
For convenience, we define $X^{k} = [\vx^{k}_1, \cdots, \vx^{k}_{N}]^\top \in$ $\mathbb{R}^{N \times d}$ and  $X^{k+\frac{1}{2}} = [\vx^{k+\frac{1}{2}}_1, \cdots, \vx^{k+\frac{1}{2}}_{N}]^\top \! \in \mathbb{R}^{N \times d}$. Because $X^{k+1} = W X^{k+\frac{1}{2}}$, we have

 \begin{align}
        \label{dm-1}
         &\sum_{n \in \N}   \|\vx^{k+1}_{n}-\bar\vx^{k+1}\|^2   \\
        = & \|(I-\frac{1}{N}\bm{1}\bm{1}^\top) X^{k+1}\|_{F}^2  \nonumber\\
%        = \|(I-\frac{1}{N}\bm{1}\bm{1}^\top)  A^{k+\frac{1}{2}}\|_{2,\infty}^2
        % ==========================
         \le & \|(I-\frac{1}{N}\bm{1}\bm{1}^\top)W X^{k+\frac{1}{2}}\|_{F}^2
         \nonumber\\
          =&  \|(I-\frac{1}{N}\bm{1}\bm{1}^\top)W (I-\frac{1}{N}\bm{1}\bm{1}^\top) X^{k+\frac{1}{2}}\|_{F}^2
        \nonumber \\
        % ==========================
        \le&  \|(I-\frac{1}{N}\bm{1}\bm{1}^\top) W\|^2\|(I-\frac{1}{N}\bm{1}\bm{1}^\top) X^{k+\frac{1}{2}}\|_{F}^2
        \nonumber \\
        % ==========================
        =& (1-\lambda)  \| (I-\frac{1}{N}\bm{1}\bm{1}^\top) X^{k+\frac{1}{2}}\|_{F}^2.  \nonumber
    \end{align}


According to Lemma 2 in \cite{wu2022byzantine}, for any $b \in (0,1)$, we have
\begin{align}
\label{g-17}
    \E H^{k+1}
    % \leq & (1-\lambda+a) \lp \frac{1}{1-b}+\frac{6 \alpha^2 L^2}{b} \rp H^k  \\
    %  & +  (1-\lambda+a) \frac{4 \alpha^2 (\sigma^2 + \delta^2)}{b} \nonumber \\
     \leq & (1-\lambda) \lp \frac{1}{1-b}+\frac{6 (\alpha^k)^2 L^2}{b} \rp \E H^k  \\
     & +  (1-\lambda) \frac{4 (\alpha^k)^2 (\sigma^2 + \delta^2)}{b}. \nonumber
\end{align}
If we further set $b =\frac{\lambda}{3}$ and the proper step size satisfying $\alpha^k \leq \frac{1}{3L}\sqrt{(2-\lambda)\lambda^2/(6-2\lambda)}$, we can obtain
\begin{align}
\label{g-18}
    \frac{1}{1-b}+\frac{6 \alpha^2 L^2}{b} \leq 1+\lambda
\end{align}
Substituting \eqref{g-18} into \eqref{g-17}, we have
\begin{align}
    \label{g-19}
    \E H^{k+1} \leq (1-\lambda^2) \E H^k + \frac{12(1-\lambda)}{\lambda} (\alpha^k)^2 (\sigma^2 +\delta^2).
\end{align}

Below we choose the decaying step size  $\alpha^k= \frac{1}{\mu(k+k_0)}$, where $k_0$ is sufficiently large.  By applying telescopic cancellation to \eqref{g-19} from time $0$ to $k$, we deduce that
 \begin{align}
 \label{dm-11}
        &  \E H^{k}
        \le  (1-\lambda^2)^k H^0  \\
         &\hspace{-1em} +\frac{12(1-\lambda)(\sigma^2 +\delta^2)}{\lambda \mu^2} \lp \frac{1}{(k+k_0-1)^2}+\cdot\cdot\cdot+\frac{(1-\lambda^2)^{k-1}}{(k_0)^2} \rp . \nonumber
    \end{align}
When all agents share the same initialization, according to Lemma 5 in \cite{10730755}, if $\frac{(k_0+1)^2}{k_0^2} \leq \frac{2}{2-\lambda^2}$ is satisfied, we have
    \begin{align}
    \label{dm-12}
            &\E H^{k}
        \le   \frac{c_1(\sigma^2 +\delta^2)}{\mu^2(k+k_0)^2}.
    \end{align}
where $c_1 = \frac{24(1-\lambda)}{\lambda^3} $.
\end{proof}

\subsection{Proof of Lemma 3}
The following lemma characterizes the consensus dynamics of Algorithm \ref{robust-DSGD} among the non-Byzantine agents during the learning process. The proof builds upon the approach of Theorem 2 in \cite{wu2022byzantine} and Lemma 2 in \cite{ye2024generalization}.
In this setting, the consensus error is defined as $H^k = \frac{1}{N} \sum_{n \in \N} \| \vx^{k}_n - \bar\vx^{k}\|^2 $, where $\bar\vx^k:= \frac{1}{N}\sum_{n \in \N}\vx^k_n$ is the average of all non-Byzantine models at time $k$.
\begin{lemma}[Consensus of Byzantine-resilient DSGD]
\label{lemma-dm-b}
Suppose that the robust aggregation rules $\{\A_n\}_{n\in \N}$ in Algorithm \ref{robust-DSGD} satisfy Definition \ref{definition:mixing-matrix},  the associated contraction constant satisfies $\rho < \rho^* := \frac{\lambda}{8\sqrt{N}}$ and
Assumptions \ref{assumption:Lip}--\ref{assumption:heterogeneity} hold for all non-Byzantine agents $n \in \N$.
    Set the step size $\alpha^k= \frac{2}{\mu(k+k_1)}$, where $k_1$ is sufficiently large. When all non-Byzantine agents share the same initialization, the consensus error of Algorithm \ref{robust-DSGD} can be bounded by
    \begin{align}
        \label{by-Hk}
        % \E H^k
        % \le & (c_1)^k H^0 + \frac{c_2 M^2+c_3 C^2}{\mu^2} \frac{1}{(k+k_1)^2}.
        \E H^k
        \le &  \frac{c_2(\sigma^2 +\delta^2)}{\mu^2 (k+k_1)^2}.
    \end{align}
    Here  $c_2 > 0$ is a constant, and the expectation is taken over all the random variables.
\end{lemma}
\begin{proof}
In the presence of Byzantine agents, by Theorem 2 in \cite{wu2022byzantine}, if $\rho < \frac{\lambda}{8\sqrt{N}}$ and we define $w = \lambda - 8\rho \sqrt{N}$, then if $\alpha^k \leq \frac{\sqrt{(2-w)w^2/(6-2w)}}{3L}$, we have
\begin{align}
    \label{bdm-1}
    \E H^k \leq (1-w^2) H^k + \frac{12(1-w)}{w}(\alpha^k)^2 (\sigma^2+\delta^2).
\end{align}

We further choose the decaying step size  $\alpha^k= \frac{2}{\mu(k+k_1)}$, use telescopic cancellation on \eqref{bdm-1} from time $0$ to $k$ and deduce that
 \begin{align}
 \label{bdm-2}
        &\E H^{k}
        \le  (1-w^2)^k H^0  \\
         & \hspace{-1em} +\frac{48(1-w)}{w \mu^2}  (\sigma^2 +\delta^2)\lp \frac{1}{(k+k_1-1)^2}+\cdot\cdot\cdot+\frac{(1-w^2)^{k-1}}{(k_1)^2} \rp . \nonumber
    \end{align}
When all agents share the same initialization, by Lemma 5 in \cite{10730755}, if $\frac{(k_1+1)^2}{k_1^2} \leq \frac{2}{2-w^2}$ is satisfied, we have
    \begin{align}
    \label{bdm-3}
            &\E H^{k}
        \le   \frac{c_2(\sigma^2 +\delta^2)}{\mu^2(k+k_1)^2}.
    \end{align}
where $c_2 = \frac{96(1-w)}{w^3} $.
\end{proof}



\section{Additional Numerical Experiments on CIFAR-10}
\label{sec:cifar10}
In addition to the squared $\ell_2$-norm regularized softmax regression task with a strongly convex loss on the MNIST dataset, we investigate the generalization error of ResNet-18 training on the CIFAR-10 dataset with a nonconvex loss. The CIFAR-10 dataset comprises 60,000 color images across 10 classes, with 50,000 training samples and 10,000 test samples. Data heterogeneity is controlled by assigning training samples to each agent according to a Dirichlet distribution,  $Dir(\beta)$, similar to the setup in the softmax regression task. The step size is set as $\alpha^k = \frac{0.015}{0.01k+1}$.  Other experimental settings, including the network topology, remain consistent with those in the softmax regression task.


