In general, mobility can be defined as a network of
interacting communities where the connections and the interrelated intensity represent the movement among them \cite{2525}.
%Model
The model is constructed with the Mobility equation and Monte Carlo simulation  as follows:
\begin{equation}\label{eq111}
 	\begin{cases}
	\begin{split}
		\frac{dS_{i}}{dt}&= \Lambda-\alpha S_{i} Q_{i} -\epsilon(t) S_{i} C_{i}-\Phi S_{i}+\sum_{j}T_{ji}S_{j}-\sum_{j}T_{ij}S_{i},\\
		\frac{dQ_{i}}{dt}&=\alpha S_{i} Q_{i} -\epsilon(t) Q_{i}C_{i}-\Phi Q_{i}+\sum_{j}T_{ji}Q_{j}-\sum_{j}T_{ij}Q_{i},\\
		\frac{dC_{i}}{dt}&= \epsilon(t) S_{i}C_{i}+\epsilon(t) Q_{i}C_{i}-\delta C_{i} I_{i}-\mu C_{i}-\Phi C_{i}+\sum_{j}T_{ji}C_{j}-\sum_{j}T_{ij}C_{i},\\
		\frac{dI_{i}}{dt}&= \delta C_{i} I_{i}-v I_{i}-\Phi I_{i}+\sum_{j} T_{ji} I_{j}-\sum_{j} T_{ij} I_{i},\\
		\frac{dR_{i}}{dt}&= \mu  C_{i} +v I_{i}-\Phi R_{i}+\sum_{j} T_{ji} R_{j}-\sum_{j} T_{ij} R_{i},
	\end{split}
  	\end{cases}
\end{equation}
where $\epsilon(t)$ is the time varying contact rate that can be adjusted by mob dynamics through Monte Carlo simulations, the mobility term $\sum_{j} T_{ji} S_{j}$ represents people entering region $i$, while  $\sum_{j} T_{ij} S_{j}$ represents people leaving region $i$ and $\epsilon(t)=\epsilon(0)\cot (1- M_{t})-M_{t} $ is random factor between $0$ and $1.5.$ 
